INSERT INTO grammar_points (title, structure, jlpt_level, meaning_vi, usage_notes, examples_json, is_active, deleted, created_at, updated_at, version)
VALUES
('〜は', 'N + は', 'N5', 'Thì, là (Trợ từ chỉ chủ đề của câu)', 'Viết は nhưng phát âm là ''wa''. Nó thiết lập nội dung câu nói; thông tin quan trọng sẽ xuất hiện sau nó.', '[{"jp": "私は学生です。", "vi": "Tôi là một sinh viên."}, {"jp": "今日は天気がいいです。", "vi": "Thời tiết hôm nay đẹp."}, {"jp": "この本はおもしろいです。", "vi": "Cuốn sách này rất thú vị."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜が（subject）', 'N + が', 'N5', 'Là (Trợ từ chỉ chủ ngữ, thông tin mới)', 'Các từ để hỏi như だれ và 何 lấy が, không bao giờ lấy は khi chúng là chủ ngữ. が cũng được dùng với 好き, ほしい, 上手 và わかる để chỉ sự việc thích, mong muốn hoặc được hiểu.', '[{"jp": "雨が降っています。", "vi": "Trời đang mưa."}, {"jp": "だれが窓を開けましたか。", "vi": "Ai đã mở cửa sổ?"}, {"jp": "私が行きます。", "vi": "tôi sẽ đi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を', 'N + を', 'N5', 'Chỉ đối tượng trực tiếp của hành động', 'Được viết là を nhưng được phát âm là ''o''. Với các động từ chuyển động như 歩く, 散歩する và 出る nó đánh dấu tuyến đường hoặc địa điểm bị bỏ lại.', '[{"jp": "毎朝パンを食べます。", "vi": "Tôi ăn bánh mì vào mỗi buổi sáng."}, {"jp": "姉は新しいかばんを買いました。", "vi": "Em gái tôi đã mua một chiếc túi mới."}, {"jp": "公園を散歩しました。", "vi": "Tôi đi dạo trong công viên."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に（time）', 'N + に', 'N5', 'Vào lúc (Chỉ thời điểm xác định)', 'Được sử dụng với đồng hồ thời gian, ngày, ngày trong tuần và tháng. Các từ tương đối như 今日, 明日, 毎日 và 来週 không có に.', '[{"jp": "毎朝7時に起きます。", "vi": "Tôi thức dậy lúc 7 giờ mỗi sáng."}, {"jp": "日曜日に友達と会います。", "vi": "Tôi sẽ gặp bạn bè của tôi vào chủ nhật."}, {"jp": "8月に国へ帰ります。", "vi": "Tôi sẽ trở về nước vào tháng 8."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に（destination）', 'N + に + 行く / 来る / 帰る', 'N5', 'Đến, tới (Chỉ đích đến của di chuyển)', 'Gần nghĩa với へ. に đặt trọng tâm vào điểm đến, へ vào hướng đi.', '[{"jp": "毎日バスで学校に行きます。", "vi": "Tôi đi học bằng xe buýt mỗi ngày."}, {"jp": "夜10時に家に帰りました。", "vi": "Tôi về nhà lúc 10 giờ tối."}, {"jp": "来月、姉が日本に来ます。", "vi": "Em gái tôi sẽ đến Nhật Bản vào tháng tới."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に（place of existence）', 'N + に + ある / いる', 'N5', 'Ở, tại (Chỉ nơi tồn tại của người/vật)', 'Dùng với ある, いる và 住む. Đối với nơi xảy ra hành động (ăn, học, chơi), thay vào đó hãy sử dụng で.', '[{"jp": "机の上に辞書があります。", "vi": "Có một cuốn từ điển trên bàn."}, {"jp": "姉は東京に住んでいます。", "vi": "Em gái tôi sống ở Tokyo."}, {"jp": "猫は今どこにいますか。", "vi": "Bây giờ con mèo ở đâu?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に（indirect object）', 'N + に', 'N5', 'tới (người nhận hoặc là mục tiêu của một hành động)', 'Phổ biến với あげる, 貸す, 教える, 見せる, 電話をかける và 会う. Với もらう và 借りる, に đánh dấu người mà bạn nhận được thứ gì đó.', '[{"jp": "母に手紙を書きます。", "vi": "Tôi sẽ viết thư cho mẹ tôi."}, {"jp": "妹に本を貸しました。", "vi": "Tôi cho chị tôi mượn cuốn sách."}, {"jp": "友達に電話をかけました。", "vi": "Tôi đã gọi cho một người bạn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に（frequency）', 'N + に + N', 'N5', 'mỗi; trong (bao nhiêu lần trong một khoảng thời gian)', 'Kinh nguyệt đến trước, sau đó là に, sau đó là số lần: 月に一回 (mỗi tháng một lần).', '[{"jp": "一週間に二回、プールで泳ぎます。", "vi": "Tôi bơi ở hồ bơi hai lần một tuần."}, {"jp": "母は一日に二回、犬の散歩をします。", "vi": "Mẹ tôi dắt chó đi dạo hai lần một ngày."}, {"jp": "一年に一度、家族で旅行します。", "vi": "Tôi đi du lịch cùng gia đình mỗi năm một lần."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜へ', 'N + へ', 'N5', 'đến ; hướng tới (hướng chuyển động)', 'Viết là へ nhưng phát âm là ''e''. Thường có thể hoán đổi với に để chỉ điểm đến; へ nhấn mạnh về hướng hơn một chút.', '[{"jp": "夏休みに北海道へ行きます。", "vi": "Tôi sẽ đến Hokkaido vào kỳ nghỉ hè."}, {"jp": "来週、国へ帰ります。", "vi": "Tôi sẽ trở về đất nước của tôi vào tuần tới."}, {"jp": "どこへ行きますか。", "vi": "Bạn đang đi đâu?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜で（place of action）', 'N + で', 'N5', 'tại; ở (nơi xảy ra hành động)', 'So sánh 教室にいます (ở đâu đó: に) với 教室で勉強します (làm gì đó ở đó: で).', '[{"jp": "図書館で本を読みます。", "vi": "Tôi đọc sách ở thư viện."}, {"jp": "きのう、デパートでくつを買いました。", "vi": "Hôm qua, tôi mua giày ở cửa hàng bách hóa."}, {"jp": "駅の前で友達を待ちました。", "vi": "Tôi đợi bạn tôi ở trước nhà ga."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜で（means）', 'N + で', 'N5', 'Bằng (Chỉ phương tiện, cách thức, công cụ)', 'Để nói ''đi bộ'', hãy sử dụng 歩いて行きます thay vì で.', '[{"jp": "毎日電車で会社へ行きます。", "vi": "Tôi đi làm bằng tàu hỏa hàng ngày."}, {"jp": "はしでご飯を食べます。", "vi": "Tôi ăn cơm bằng đũa."}, {"jp": "日本語で手紙を書きました。", "vi": "Tôi đã viết một lá thư bằng tiếng Nhật."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜と（and）', 'N + と + N', 'N5', 'Và (Liệt kê toàn bộ danh từ)', 'と liệt kê mọi mục; để đưa ra một số ví dụ, hãy sử dụng や. Nó chỉ nối danh từ, không nối động từ hoặc tính từ.', '[{"jp": "かばんの中にペンとノートがあります。", "vi": "Tôi có một cây bút và một cuốn sổ trong túi."}, {"jp": "朝ご飯にパンとたまごを食べました。", "vi": "Tôi đã ăn bánh mì và trứng cho bữa sáng."}, {"jp": "父と母は銀行で働いています。", "vi": "Bố và mẹ tôi làm việc ở ngân hàng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜と（with）', 'N + と', 'N5', 'Cùng với (Chỉ bạn đồng hành)', 'Thường theo sau là いっしょに. Với các động từ như 話す, 会う và 結婚する, と đánh dấu người khác.', '[{"jp": "週末、友達と映画を見ました。", "vi": "Tôi đã xem một bộ phim với bạn bè của tôi vào cuối tuần."}, {"jp": "妹といっしょに買い物に行きます。", "vi": "Tôi đang đi mua sắm với chị tôi."}, {"jp": "だれと昼ご飯を食べましたか。", "vi": "Bạn đã ăn trưa với ai?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜や', 'N + や + N', 'N5', 'và (đưa ra một số ví dụ khác); ... và vân vân', 'Đề nghị danh sách chưa đầy đủ. Thường kết thúc bằng など: 本や雑誌など.', '[{"jp": "机の上に本や雑誌があります。", "vi": "Có sách và tạp chí trên bàn."}, {"jp": "スーパーで肉や野菜を買いました。", "vi": "Tôi mua thịt và rau ở siêu thị."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜か（or）', 'N + か + N', 'N5', 'hoặc (sự lựa chọn giữa các danh từ)', 'Có nghĩa là một trong các mục được chọn. Để liệt kê các mục cùng nhau, hãy sử dụng と hoặc や.', '[{"jp": "飲み物はコーヒーか紅茶がいいです。", "vi": "Đối với đồ uống, cà phê hoặc trà là tốt."}, {"jp": "土曜日か日曜日に買い物に行きます。", "vi": "Tôi sẽ đi mua sắm vào thứ bảy hoặc chủ nhật."}, {"jp": "駅までバスかタクシーで行きます。", "vi": "Đến nhà ga bằng xe buýt hoặc taxi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜も', 'N + も', 'N5', 'Cũng (Chỉ sự đồng nhất)', 'も thay thế は, が và を, nhưng đứng sau các trợ từ khác: 京都にも行きました.', '[{"jp": "私も学生です。", "vi": "Tôi cũng là một sinh viên."}, {"jp": "兄はサッカーも好きです。", "vi": "Anh trai tôi cũng thích bóng đá."}, {"jp": "肉も魚も食べません。", "vi": "Tôi không ăn thịt hoặc cá."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜の（possessive）', 'N + の + N', 'N5', '''s; của (sở hữu, thuộc về hoặc mô tả)', 'Danh từ đầu tiên mô tả danh từ thứ hai: 日本の車 (một chiếc xe hơi Nhật Bản). Danh từ thứ hai có thể lược bỏ khi rõ ràng: それは私のです.', '[{"jp": "これは私のかさです。", "vi": "Đây là chiếc ô của tôi."}, {"jp": "日本語の先生はとてもやさしいです。", "vi": "Giáo viên người Nhật rất tốt bụng."}, {"jp": "駅の近くに新しい店があります。", "vi": "Có một cửa hàng mới gần nhà ga."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜から（from）', 'N + から', 'N5', 'Từ (Chỉ điểm bắt đầu không gian/thời gian)', 'Thường kết hợp với まで: 月曜日から金曜日まで (từ thứ Hai đến thứ Sáu).', '[{"jp": "授業は9時からです。", "vi": "Lớp học bắt đầu lúc 9 giờ."}, {"jp": "学校から駅まで歩きます。", "vi": "Tôi đi bộ từ trường đến ga."}, {"jp": "私はブラジルから来ました。", "vi": "I''m from Brazil."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜まで（until）', 'N + まで', 'N5', 'Đến, tới (Chỉ điểm kết thúc)', 'Đánh dấu điểm kết thúc của một cái gì đó vẫn tiếp tục. Đối với thời hạn (''by''), hãy sử dụng までに (N4).', '[{"jp": "昼休みは1時までです。", "vi": "Giờ nghỉ trưa kéo dài tới 1 giờ chiều."}, {"jp": "駅までいっしょに行きましょう。", "vi": "Chúng ta hãy cùng nhau đến nhà ga nhé."}, {"jp": "きのうは夜11時まで勉強しました。", "vi": "Hôm qua tôi đã học đến 11 giờ đêm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜か（question）', 'Mệnh đề + か', 'N5', '(dấu chấm hỏi) chuyển câu thành câu hỏi', 'Các câu hỏi lịch sự kết thúc bằng か và thường được viết bằng 。. Trong lời nói thông thường, か thường được bỏ đi và thay vào đó sử dụng ngữ điệu lên cao.', '[{"jp": "これはあなたのかばんですか。", "vi": "Đây có phải là túi của bạn?"}, {"jp": "朝ご飯を食べましたか。", "vi": "Bạn đã ăn sáng chưa?"}, {"jp": "トイレはどこですか。", "vi": "Phòng vệ sinh ở đâu."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ね', 'Mệnh đề + ね', 'N5', 'phải không?; Phải? (tìm kiếm sự đồng tình hoặc chia sẻ cảm xúc)', 'Được sử dụng khi người nói mong muốn người nghe chia sẻ cùng quan điểm hoặc kiến ​​thức. So sánh よ, cho người nghe biết điều gì đó mới mẻ.', '[{"jp": "今日は暑いですね。", "vi": "Hôm nay trời nóng quá phải không?"}, {"jp": "このケーキ、おいしいですね。", "vi": "Chiếc bánh này trông có vẻ ngon."}, {"jp": "明日のテストは10時からですね。", "vi": "Bài kiểm tra ngày mai bắt đầu lúc 10 giờ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜よ', 'Mệnh đề + よ', 'N5', 'bạn biết đấy; Tôi nói với bạn (cung cấp thông tin mới hoặc nhấn mạnh)', 'Nói với người nghe điều gì đó mà họ có thể không biết. Việc lạm dụng nó với cấp trên nghe có vẻ tự đề cao.', '[{"jp": "このラーメンはとてもおいしいですよ。", "vi": "Món ramen này rất ngon."}, {"jp": "かさを忘れていますよ。", "vi": "You forgot the umbrella."}, {"jp": "明日はテストがありますよ。", "vi": "Ngày mai tôi có bài kiểm tra."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜より', 'N + より', 'N5', 'hơn (tiêu chuẩn so sánh)', 'Trong X は Y より + tính từ, Y là tiêu chuẩn. Tính từ tiếng Nhật không có dạng ''-er''; より làm công việc đó.', '[{"jp": "今日はきのうより寒いです。", "vi": "Hôm nay trời lạnh hơn hôm qua."}, {"jp": "電車はバスより速いです。", "vi": "Xe lửa nhanh hơn xe buýt."}, {"jp": "兄は父より背が高いです。", "vi": "Anh trai tôi cao hơn bố tôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜の方が〜より', 'N + の方が + N + より', 'N5', 'X nhiều hơn... hơn Y', 'Hai phần có thể đến theo thứ tự. Thường dùng để trả lời câu hỏi どちら.', '[{"jp": "犬の方が猫より好きです。", "vi": "Tôi thích chó hơn mèo."}, {"jp": "東京の方が大阪より人が多いです。", "vi": "Có nhiều người ở Tokyo hơn ở Osaka."}, {"jp": "夏より冬の方が好きです。", "vi": "Tôi thích mùa đông hơn mùa hè."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜と〜とどちらが', 'N + と + N + とどちらが', 'N5', 'cái nào hơn ..., X hay Y?', 'So sánh chính xác hai điều. どっち là dạng thông thường của どちら. Trả lời bằng 〜の方が.', '[{"jp": "コーヒーと紅茶とどちらが好きですか。", "vi": "Bạn thích cái nào hơn, cà phê hay trà?"}, {"jp": "電車とバスとどちらが安いですか。", "vi": "Cái nào rẻ hơn: tàu hay xe buýt?"}, {"jp": "「山と海とどちらがいいですか。」「海の方がいいです。」", "vi": "\"Bạn thích cái nào hơn, núi hay biển?\" \"The sea is better.\""}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜の中で〜が一番', 'N + の中で + N + が一番', 'N5', '... là nhiều nhất ... trong số/của', 'Được sử dụng cho ba mặt hàng trở lên. Trong câu hỏi sử dụng 何, だれ, どこ hoặc いつ trước が一番.', '[{"jp": "果物の中でりんごが一番好きです。", "vi": "Trong số tất cả các loại trái cây, tôi thích nhất là táo."}, {"jp": "クラスの中でだれが一番背が高いですか。", "vi": "Who is the tallest in the class?"}, {"jp": "家族の中で父が一番早く起きます。", "vi": "Bố tôi là người thức dậy đầu tiên trong gia đình."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜です', 'N + です / A-な + です / A-い + です', 'N5', 'Là (Khẳng định lịch sự)', 'Các hình thức: です, ではありません, でした, ではありませんでした. Sau tính từ い, です chỉ thêm tính lịch sự: 高いです.', '[{"jp": "私はマリアです。", "vi": "Tôi là Maria."}, {"jp": "今日は月曜日です。", "vi": "Hôm nay là thứ Hai."}, {"jp": "この部屋はとても静かです。", "vi": "Căn phòng này rất yên tĩnh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜だ', 'N + だ / A-な + だ', 'N5', 'là; là; là (copula đơn giản)', 'Các dạng: だ, じゃない, だった, じゃなかった. Không bao giờ dùng ngay sau tính từ い (高いだ là sai). Thường rơi vào các câu hỏi thông thường: 学生？', '[{"jp": "今日は日曜日だ。", "vi": "Hôm nay là chủ nhật."}, {"jp": "あの人は私の兄だ。", "vi": "Người đó là anh trai tôi."}, {"jp": "明日は休みだから、ゆっくり寝る。", "vi": "Ngày mai là ngày nghỉ của tôi nên tôi sẽ ngủ ngon."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ではありません / 〜じゃない', 'N + ではありません / A-な + ではありません / N + じゃない / A-な + じゃない', 'N5', 'không phải vậy; tôi không; không phải', 'じゃありません và じゃないです là những hình thức đàm thoại lịch sự hơn. Quá khứ: ではありませんでした / じゃなかった. Tính từ い dùng 〜くない thay thế.', '[{"jp": "私は先生ではありません。学生です。", "vi": "Tôi không phải là giáo viên. Tôi là một sinh viên."}, {"jp": "今日は休みじゃない。", "vi": "It''s not a day off today."}, {"jp": "この町はあまりにぎやかではありません。", "vi": "Thị trấn này không sôi động lắm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜でした', 'N + でした / A-な + でした', 'N5', 'đã ; đã (copula quá khứ lịch sự)', 'Quá khứ phủ định: ではありませんでした. Tính từ い không dùng でした: nói 高かったです, không dùng 高いでした.', '[{"jp": "きのうは私の誕生日でした。", "vi": "Hôm qua là sinh nhật của tôi."}, {"jp": "子どものころ、野菜がきらいでした。", "vi": "Hồi nhỏ tôi ghét rau lắm."}, {"jp": "テストはかんたんでした。", "vi": "Bài kiểm tra rất dễ dàng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ます', 'V-ます(bỏ ます) + ます', 'N5', 'Kết thúc động từ không ở quá khứ một cách lịch sự (do; will do)', 'Bao gồm các thói quen và hành động trong tương lai. 飲む→飲みます, 食べる→食べます, する→します, 来る→来ます.', '[{"jp": "毎朝コーヒーを飲みます。", "vi": "Tôi uống cà phê mỗi sáng."}, {"jp": "明日、京都へ行きます。", "vi": "Ngày mai tôi sẽ đi Kyoto."}, {"jp": "弟は毎晩9時に寝ます。", "vi": "Em trai tôi đi ngủ lúc 9 giờ mỗi tối."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ません', 'V-ます(bỏ ます) + ません', 'N5', 'không; sẽ không (lịch sự phủ định)', 'Tương đương đơn giản là dạng ない: 飲みません = 飲まない.', '[{"jp": "私はお酒を飲みません。", "vi": "Tôi không uống rượu."}, {"jp": "日曜日は学校へ行きません。", "vi": "Tôi không đi học vào ngày chủ nhật."}, {"jp": "今晩はテレビを見ません。", "vi": "I won''t watch TV tonight."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ました', 'V-ます(bỏ ます) + ました', 'N5', 'đã làm (quá khứ lịch sự)', 'Tương đương đơn giản là dạng た: 会いました = 会った.', '[{"jp": "きのう、友達に会いました。", "vi": "I met a friend yesterday."}, {"jp": "先週、新しいくつを買いました。", "vi": "Tôi đã mua giày mới vào tuần trước."}, {"jp": "けさ、6時に起きました。", "vi": "À, tôi thức dậy lúc 6 giờ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ませんでした', 'V-ます(bỏ ます) + ませんでした', 'N5', 'đã không (lịch sự quá khứ tiêu cực)', 'Tương đương đơn giản là 〜なかった: 食べませんでした = 食べなかった.', '[{"jp": "けさは朝ご飯を食べませんでした。", "vi": "Kesa chưa ăn sáng."}, {"jp": "週末は宿題をしませんでした。", "vi": "I didn''t do my homework on the weekend."}, {"jp": "きのうは雨でしたから、出かけませんでした。", "vi": "Hôm qua trời mưa nên tôi không đi ra ngoài."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ない', 'V-ない(bỏ ない) + ない', 'N5', 'không; sẽ không (phủ định rõ ràng của động từ)', 'Động từ う đổi âm -u cuối thành -a: 書く→書かない, 買う→買わない. る-động từ thả る: 食べない. する→しない, 来る→こない, ある→ない. Quá khứ: 〜なかった.', '[{"jp": "今日は学校へ行かない。", "vi": "Hôm nay tôi không đi học."}, {"jp": "兄は肉を食べない。", "vi": "Anh trai tôi không ăn thịt."}, {"jp": "「コーヒー、飲む？」「ううん、飲まない。」", "vi": "\"Bạn có muốn cà phê không?\" \"Không, tôi không.\""}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜た', 'V-た', 'N5', 'đã làm (quá khứ đơn giản của động từ)', 'Được làm chính xác như dạng て, với て→た và で→だ: 書いて→書いた, 飲んで→飲んだ, 行って→行った. Tương đương lịch sự: 〜ました.', '[{"jp": "週末は家で映画を見た。", "vi": "Tôi đã xem một bộ phim ở nhà vào cuối tuần."}, {"jp": "駅で先生に会った。", "vi": "Tôi đã gặp giáo viên của tôi ở nhà ga."}, {"jp": "「昼ご飯、食べた？」「うん、もう食べた。」", "vi": "\"Bạn đã ăn trưa chưa?\" \"Ừ, tôi đã ăn rồi.\""}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ましょう', 'V-ます(bỏ ます) + ましょう', 'N5', 'Cùng làm... nào! (Đề nghị)', 'Được sử dụng khi người nói mong đợi người nghe đồng ý. Để mời nhẹ nhàng hơn, hãy sử dụng 〜ませんか.', '[{"jp": "いっしょに行きましょう。", "vi": "Chúng ta hãy đi cùng nhau."}, {"jp": "少し休みましょう。", "vi": "Chúng ta hãy nghỉ ngơi một chút."}, {"jp": "駅の前で会いましょう。", "vi": "Chúng ta hãy gặp nhau trước nhà ga nhé."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ましょうか', 'V-ます(bỏ ます) + ましょうか', 'N5', 'tôi có nên ...?; chúng ta sẽ...?', 'Đề nghị làm điều gì đó cho người nghe (tôi có nên làm không?) hoặc yêu cầu họ cùng nhau quyết định điều gì đó (chúng ta có làm không?).', '[{"jp": "窓を開けましょうか。", "vi": "Chúng ta mở cửa sổ nhé?"}, {"jp": "荷物を持ちましょうか。", "vi": "Tôi có nên mang theo hành lý của mình không?"}, {"jp": "何時に会いましょうか。", "vi": "Chúng ta sẽ gặp nhau lúc mấy giờ?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ませんか', 'V-ます(bỏ ます) + ませんか', 'N5', 'phải không...?; bạn có muốn...? (lời mời lịch sự)', 'Nhẹ nhàng hơn 〜ましょう vì nó khiến không gian người nghe bị suy giảm. Chấp nhận với ええ、〜ましょう.', '[{"jp": "いっしょに昼ご飯を食べませんか。", "vi": "Bạn có muốn ăn trưa cùng nhau không?"}, {"jp": "日曜日にテニスをしませんか。", "vi": "Bạn có muốn chơi quần vợt vào Chủ nhật không?"}, {"jp": "明日、公園を散歩しませんか。", "vi": "Bạn có muốn đi dạo trong công viên vào ngày mai không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たい', 'V-ます(bỏ ます) + たい', 'N5', 'Muốn làm gì', 'Liên hợp như tính từ い: 〜たくない, 〜たかった. Đối tượng có thể lấy が hoặc を. Không dùng để nói trực tiếp mong muốn của người khác.', '[{"jp": "夏休みに沖縄へ行きたいです。", "vi": "Tôi muốn đến Okinawa vào kỳ nghỉ hè."}, {"jp": "冷たい水が飲みたいです。", "vi": "Tôi muốn uống nước lạnh."}, {"jp": "何が食べたいですか。", "vi": "Bạn muốn ăn gì?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜がほしい', 'N + がほしい', 'N5', 'muốn (cái gì đó)', 'Đối với sự vật, không phải hành động (hành động sử dụng 〜たい). Liên hợp như tính từ い: ほしくない, ほしかった.', '[{"jp": "新しいパソコンがほしいです。", "vi": "Tôi muốn một chiếc máy tính mới."}, {"jp": "誕生日に何がほしいですか。", "vi": "Bạn muốn gì cho ngày sinh nhật của mình?"}, {"jp": "今は何もほしくないです。", "vi": "Tôi không muốn bất cứ điều gì ngay bây giờ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をください', 'N + をください', 'N5', 'xin vui lòng cho tôi (cái gì đó); tôi sẽ có', 'Được sử dụng khi mua sắm hoặc đặt hàng. Số lượng theo sau を không có tiểu từ: 切手を二枚ください.', '[{"jp": "すみません、水をください。", "vi": "Xin lỗi, cho tôi xin ít nước."}, {"jp": "このりんごを三つください。", "vi": "Xin vui lòng cho tôi ba quả táo này."}, {"jp": "メニューをください。", "vi": "Xin vui lòng cho tôi thực đơn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てください', 'V-て + ください', 'N5', 'Xin hãy làm gì (Yêu cầu lịch sự)', 'Lịch sự nhưng vẫn là một lời chỉ dẫn mà người nói mong muốn được tuân theo. Yêu cầu nhẹ nhàng hơn sử dụng 〜てくれませんか (N4).', '[{"jp": "もう少しゆっくり話してください。", "vi": "Xin hãy nói chậm lại một chút."}, {"jp": "ここでくつをぬいでください。", "vi": "Hãy cởi giày của bạn ở đây."}, {"jp": "すみません、駅までの道を教えてください。", "vi": "Xin lỗi, bạn có thể chỉ cho tôi đường đến nhà ga được không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ないでください', 'V-ない + でください', 'N5', 'làm ơn đừng (làm)', 'Nhẹ nhàng hơn 〜てはいけません. Trong cách nói thông thường ください được lược bỏ: 見ないで.', '[{"jp": "教室で食べないでください。", "vi": "Vui lòng không ăn trong lớp học."}, {"jp": "この部屋に入らないでください。", "vi": "Xin vui lòng không vào phòng này."}, {"jp": "心配しないでください。", "vi": "Đừng lo lắng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てもいい', 'V-て + もいい', 'N5', 'Được phép làm gì (Cho phép)', 'Thêm ですか để xin phép. Một lời từ chối lịch sự thường chỉ là すみません、ちょっと….', '[{"jp": "この辞書を使ってもいいですか。", "vi": "Tôi có thể sử dụng từ điển này được không?"}, {"jp": "今日は早く帰ってもいいです。", "vi": "Hôm nay bạn có thể về nhà sớm."}, {"jp": "ここにすわってもいいですか。", "vi": "Tôi có thể ngồi đây được không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てはいけない', 'V-て + はいけない', 'N5', 'không được; có thể không', 'Một sự cấm đoán mạnh mẽ, thường dành cho các quy tắc. Hình thức lịch sự: 〜てはいけません. Co rút thông thường: 〜ちゃいけない / 〜じゃいけない.', '[{"jp": "図書館で大きい声で話してはいけません。", "vi": "Đừng nói to trong thư viện."}, {"jp": "子どもはこの川で泳いではいけません。", "vi": "Trẻ em không được phép bơi ở dòng sông này."}, {"jp": "ここでたばこを吸ってはいけません。", "vi": "Bạn không được phép hút thuốc ở đây."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜なければならない / 〜なくてはいけない', 'V-ない(bỏ ない) + なければならない / V-ない(bỏ ない) + なくてはいけない', 'N5', 'phải ; phải', 'Các hình thức lịch sự kết thúc bằng なりません / いけません. Cả hai đều có nghĩa giống nhau; なければならない nghe có vẻ trang trọng hơn một chút.', '[{"jp": "明日は6時に起きなければなりません。", "vi": "Ngày mai tôi phải thức dậy lúc 6 giờ."}, {"jp": "今日は早く家に帰らなくてはいけません。", "vi": "Hôm nay tôi phải về nhà sớm."}, {"jp": "日本では、家に入る前にくつをぬがなければなりません。", "vi": "Ở Nhật Bản, bạn phải cởi giày trước khi vào nhà."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜なくてもいい', 'V-ない(bỏ ない) + なくてもいい', 'N5', 'Không cần phải làm gì cũng được', 'Ngược lại với 〜なければならない. Hỏi với 〜なくてもいいですか (Tôi không hỏi thì có được không?).', '[{"jp": "明日は学校へ来なくてもいいです。", "vi": "Ngày mai bạn không cần phải đến trường."}, {"jp": "名前は書かなくてもいいです。", "vi": "Bạn không cần phải viết tên của bạn."}, {"jp": "今日は料理をしなくてもいいですよ。", "vi": "Hôm nay bạn không cần phải nấu ăn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ている', 'V-て + いる', 'N5', 'đang làm (hành động đang diễn ra); ở trong trạng thái (kết quả của một sự thay đổi); làm thường xuyên', 'Với động từ hành động (食べる, 読む) nó thể hiện một hành động đang diễn ra; với động từ thay đổi (結婚する, 開く, 知る) nó hiển thị trạng thái kết quả. Lịch sự: 〜ています.', '[{"jp": "弟は今、部屋でゲームをしています。", "vi": "Em trai tôi hiện đang chơi game trong phòng."}, {"jp": "姉は結婚しています。", "vi": "Chị tôi đã kết hôn."}, {"jp": "窓が開いています。", "vi": "Cửa sổ đang mở."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜て', 'V-て + Mệnh đề', 'N5', 'và; và sau đó (liên kết các hành động theo thứ tự)', 'Động từ cuối cùng thiết lập thì cho cả câu. 書く→書いて, 飲む→飲んで, 話す→話して, 買う→買って, 行く→行って (không đều).', '[{"jp": "朝起きて、顔を洗います。", "vi": "Tôi thức dậy vào buổi sáng và rửa mặt."}, {"jp": "デパートへ行って、セーターを買いました。", "vi": "Tôi đến cửa hàng bách hóa và mua một chiếc áo len."}, {"jp": "家に帰って、晩ご飯を食べて、寝ました。", "vi": "Tôi về nhà, ăn tối và đi ngủ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てから', 'V-て + から', 'N5', 'sau khi làm; (làm A) rồi đến (B); kể từ khi', 'Nhấn mạnh rằng A kết thúc trước khi B bắt đầu, rõ ràng hơn so với て đơn giản. Với ている trong mệnh đề chính nó thường có nghĩa là ''kể từ''.', '[{"jp": "手を洗ってから、ご飯を食べましょう。", "vi": "Rửa tay trước khi ăn."}, {"jp": "宿題をしてから、テレビを見ます。", "vi": "Tôi làm bài tập về nhà và sau đó xem TV."}, {"jp": "日本に来てから、毎日日本語を勉強しています。", "vi": "Tôi đã học tiếng Nhật hàng ngày kể từ khi tôi đến Nhật Bản."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たり〜たりする', 'V-た + り + V-た + りする', 'N5', 'làm những việc như A và B; đôi khi A, đôi khi B', 'Chọn ra một vài hành động từ nhiều hành động. Căng thẳng và lịch sự diễn ra ở phần cuối cùng する: 〜たりしました.', '[{"jp": "日曜日はそうじをしたり、洗濯をしたりします。", "vi": "Vào Chủ nhật, tôi dọn dẹp nhà cửa và giặt giũ."}, {"jp": "休みの日は本を読んだり、音楽を聞いたりします。", "vi": "Vào những ngày nghỉ, tôi đọc sách và nghe nhạc."}, {"jp": "夏休みは海で泳いだり、山に登ったりしました。", "vi": "Trong kỳ nghỉ hè, tôi bơi dưới biển và leo núi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たことがある', 'V-た + ことがある', 'N5', 'Đã từng làm gì (Kinh nghiệm)', 'Nói về kinh nghiệm sống chứ không phải việc vừa làm: きのう食べたことがある là sai. Phủ định 〜たことがありません có nghĩa là ''chưa bao giờ''.', '[{"jp": "富士山に登ったことがあります。", "vi": "Tôi đã leo núi Phú Sĩ."}, {"jp": "日本の映画を見たことがありますか。", "vi": "Bạn đã từng xem phim Nhật Bản chưa?"}, {"jp": "私は馬に乗ったことがありません。", "vi": "Tôi chưa bao giờ cưỡi ngựa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜前に', 'V-る(thể từ điển) + 前に / N + の + 前に', 'N5', 'trước (làm); trước (một sự kiện); trước đây', 'Động từ trước 前に luôn ở dạng từ điển, ngay cả khi nói về quá khứ. Với khoảng thời gian dài không có の: 3年前に (ba năm trước).', '[{"jp": "寝る前に歯をみがきます。", "vi": "Đánh răng trước khi đi ngủ."}, {"jp": "授業の前にコーヒーを飲みます。", "vi": "Tôi uống cà phê trước giờ học."}, {"jp": "3年前に日本へ来ました。", "vi": "Tôi đến Nhật Bản cách đây ba năm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜後で', 'V-た + 後で / N + の + 後で', 'N5', 'sau (làm); sau (một sự kiện)', 'Động từ trước 後で luôn ở dạng た, ngay cả đối với những kế hoạch trong tương lai. Bản thân 後で có nghĩa là ''sau''.', '[{"jp": "晩ご飯を食べた後で、散歩をします。", "vi": "Ăn tối xong tôi sẽ đi dạo."}, {"jp": "仕事の後で、いっしょに飲みに行きませんか。", "vi": "Bạn có muốn đi uống nước cùng nhau sau giờ làm việc không?"}, {"jp": "テストが終わった後で、友達と遊びました。", "vi": "Sau bài kiểm tra, tôi chơi với bạn bè."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ながら（while）', 'V-ます(bỏ ます) + ながら', 'N5', 'while (làm 2 việc cùng lúc)', 'Cả hai hành động đều được thực hiện bởi cùng một người. Hành động chính diễn ra sau cùng: trong A-ながら B, B là hành động chính.', '[{"jp": "音楽を聞きながら勉強します。", "vi": "Tôi vừa học vừa nghe nhạc."}, {"jp": "父はいつも新聞を読みながら朝ご飯を食べます。", "vi": "Bố tôi luôn ăn sáng trong khi đọc báo."}, {"jp": "コーヒーを飲みながら話しましょう。", "vi": "Hãy nói chuyện bên cà phê."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に行く', 'V-ます(bỏ ます) + に行く / N + に行く', 'N5', 'đi (nơi nào đó) để làm', '来る và 帰る hoạt động giống nhau: 遊びに来る. Với danh từ する, danh từ có thể đi trực tiếp: 買い物に行く, 散歩に行く.', '[{"jp": "デパートへ服を買いに行きます。", "vi": "Tôi đang đi đến cửa hàng bách hóa để mua quần áo."}, {"jp": "週末、海へ泳ぎに行きました。", "vi": "Cuối tuần tôi đi tắm biển."}, {"jp": "友達がうちへ遊びに来ました。", "vi": "Một người bạn đến thăm nhà tôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜が好き / 〜が嫌い', 'N + が好き / N + が嫌い / V-る(thể từ điển) + の + が好き', 'N5', 'thích; không thích', '好き và 嫌い là tính từ な, nên từ thích dùng が, không phải を. 大好き và 大嫌い mạnh hơn. 嫌い nghe có vẻ thẳng thừng; あまり好きじゃない thì nhẹ nhàng hơn.', '[{"jp": "私は甘いものが好きです。", "vi": "Tôi thích những thứ ngọt ngào."}, {"jp": "弟は野菜が嫌いです。", "vi": "Anh trai tôi không thích rau."}, {"jp": "母は料理をするのが好きです。", "vi": "Mẹ tôi thích nấu ăn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜が上手 / 〜が下手', 'N + が上手 / N + が下手', 'N5', 'giỏi ; tệ ở', 'Chủ yếu được sử dụng về người khác; tự gọi mình là 上手 nghe có vẻ giống như khoe khoang. Cả hai đều là tính từ な: 料理が上手な人.', '[{"jp": "姉はピアノが上手です。", "vi": "Em gái tôi chơi piano giỏi."}, {"jp": "私は歌が下手です。", "vi": "Tôi không giỏi hát."}, {"jp": "マイクさんは日本語が上手ですね。", "vi": "Mike giỏi tiếng Nhật."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜がある / 〜がいる', 'N + がある / N + がいる', 'N5', 'có; có; có (ある cho đồ vật, いる cho người và động vật)', 'ある dùng để chỉ đồ vật, thực vật và sự kiện; いる dành cho người và động vật. Phủ định: ない / いない (lịch sự: ありません / いません).', '[{"jp": "公園に大きい木があります。", "vi": "Có một cái cây lớn trong công viên."}, {"jp": "私は妹が一人います。", "vi": "Tôi có một em gái."}, {"jp": "明日、日本語のテストがあります。", "vi": "Ngày mai tôi có bài kiểm tra tiếng Nhật."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜から（reason）', 'Mệnh đề + から', 'N5', 'bởi vì ; từ; vậy', 'Lý do đến trước: A から B (A, vậy B). Trả lời どうして bằng 〜からです. Danh từ và tính từ な cần だ: 雨だから.', '[{"jp": "今日は寒いから、コートを着ます。", "vi": "Hôm nay trời lạnh nên tôi sẽ mặc áo khoác."}, {"jp": "時間がありませんから、タクシーで行きましょう。", "vi": "Chúng ta không có nhiều thời gian nên hãy đi taxi nhé."}, {"jp": "「どうして休みましたか。」「頭が痛かったからです。」", "vi": "``Tại sao bạn lại nghỉ ngày hôm nay?'''' ``Bởi vì đầu tôi đau quá.''''"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜が（but）', 'Mệnh đề + が', 'N5', 'nhưng; mặc dù', 'Cũng được sử dụng chỉ để làm dịu đi một yêu cầu hoặc dẫn dắt vào một chủ đề: すみませんが…. Trang trọng hơn một chút so với けど (N4).', '[{"jp": "この店は安いですが、あまりおいしくないです。", "vi": "Quán này rẻ nhưng đồ ăn không ngon lắm."}, {"jp": "日本語は難しいですが、おもしろいです。", "vi": "Tiếng Nhật khó nhưng thú vị."}, {"jp": "すみませんが、ちょっと静かにしてください。", "vi": "Xin lỗi, nhưng xin hãy im lặng một lát."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜でしょう', 'V(thể thông thường) / A-い / A-な / N + でしょう', 'N5', 'có lẽ; tôi nghĩ; ..., Phải?', 'Điển hình của dự báo thời tiết. Nói với ngữ điệu lên cao, nó yêu cầu người nghe đồng ý. Dạng thông thường: だろう (N4).', '[{"jp": "明日は雨が降るでしょう。", "vi": "Ngày mai trời sẽ mưa."}, {"jp": "山の上は寒いでしょう。", "vi": "Trên núi sẽ lạnh."}, {"jp": "このかばん、かわいいでしょう？", "vi": "Chiếc túi này có dễ thương không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜くなる / 〜になる', 'A-い-ku + なる / A-な + になる / N + になる', 'N5', 'trở nên; lấy; rẽ', 'いい trở thành よくなる. Thường được dùng trong quá khứ để mô tả một sự thay đổi đã xảy ra: 大きくなりました.', '[{"jp": "あたたかくなりましたね。", "vi": "Trời đang ấm dần lên."}, {"jp": "部屋がきれいになりました。", "vi": "Căn phòng bây giờ đã sạch sẽ."}, {"jp": "兄は来年、医者になります。", "vi": "Anh trai tôi sẽ trở thành bác sĩ vào năm tới."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にする（decide）', 'N + にする', 'N5', 'quyết định; chọn; tôi sẽ có', 'Phổ biến khi đặt món ăn hoặc chọn từ các lựa chọn. Quá khứ: 〜にしました (Tôi đã quyết định về...).', '[{"jp": "私はカレーにします。", "vi": "Tôi sẽ làm cà ri."}, {"jp": "飲み物は何にしますか。", "vi": "Bạn muốn uống gì?"}, {"jp": "旅行は来月にしましょう。", "vi": "Hãy thực hiện chuyến đi vào tháng tới."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('まだ〜ていない', 'まだ + V-て + いない / まだ + V-て + いません', 'N5', 'chưa (đã làm)', 'Sử dụng ていない, không phải ませんでした, cho một điều gì đó vẫn có thể xảy ra. Câu trả lời ngắn gọn là いいえ、まだです.', '[{"jp": "まだ昼ご飯を食べていません。", "vi": "Tôi vẫn chưa ăn trưa."}, {"jp": "「宿題はもうしましたか。」「いいえ、まだしていません。」", "vi": "\"Bạn đã làm bài tập về nhà chưa?\" “Không, tôi vẫn chưa làm được việc đó.”"}, {"jp": "電車はまだ来ていません。", "vi": "Tàu vẫn chưa đến."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('もう〜た', 'もう + V-た / もう + V-ます(bỏ ます) + ました', 'N5', 'đã (đã làm); (trong câu hỏi) chưa', 'Trong câu hỏi もう có nghĩa là ''chưa''. Với động từ phủ định, もう có nghĩa là ''không còn nữa'': もう食べません.', '[{"jp": "「もう晩ご飯を食べましたか。」「はい、もう食べました。」", "vi": "“Anh đã ăn tối chưa?” \"Ừ, tôi đã ăn rồi.\""}, {"jp": "妹はもう寝ました。", "vi": "Em gái tôi đã ngủ rồi."}, {"jp": "映画はもう始まりましたよ。", "vi": "Bộ phim đã bắt đầu rồi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('あまり〜ない', 'あまり + V-ない / あまり + A-い-ku + ない / あまり + A-な + じゃない', 'N5', 'không hẳn; không nhiều; không thường xuyên', 'Luôn theo sau là dạng phủ định. あまり好きじゃない là một cách nhẹ nhàng hơn để nói rằng bạn không thích điều gì đó.', '[{"jp": "私はあまりテレビを見ません。", "vi": "Tôi không xem TV nhiều."}, {"jp": "このりんごはあまり甘くないです。", "vi": "Táo này không ngọt lắm."}, {"jp": "今日はあまり忙しくありません。", "vi": "Hôm nay tôi không bận lắm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('全然〜ない', '全然 + V-ない / 全然 + A-い-ku + ない / 全然 + A-な + じゃない', 'N5', 'không hề; không ít nhất', 'Mạnh hơn あまり〜ない. Trong lời nói thông thường, 全然 đôi khi được sử dụng với những từ tích cực (全然大丈夫), nhưng với từ phủ định là cách sử dụng tiêu chuẩn.', '[{"jp": "この問題は全然わかりません。", "vi": "Tôi không hiểu vấn đề này chút nào."}, {"jp": "今日は全然寒くないです。", "vi": "Hôm nay trời không lạnh chút nào."}, {"jp": "弟は全然勉強しません。", "vi": "Em trai tôi không học gì cả."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜だけ', 'N + だけ / V-る(thể từ điển) + だけ', 'N5', 'chỉ một; chỉ', 'Giọng điệu trung tính. So sánh しか〜ない (N4), nhấn mạnh rằng số lượng là nhỏ.', '[{"jp": "財布に100円だけあります。", "vi": "Tôi chỉ có 100 yên trong ví."}, {"jp": "朝はコーヒーだけ飲みます。", "vi": "Tôi chỉ uống cà phê vào buổi sáng."}, {"jp": "日曜日だけ休みです。", "vi": "Chỉ đóng cửa vào Chủ nhật."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜くらい / 〜ぐらい（approximately）', 'N + くらい / N + ぐらい', 'N5', 'về ; khoảng (một lượng hoặc một khoảng thời gian)', 'Được sử dụng với số lượng và thời lượng. Đối với một thời điểm (khoảng ba giờ), hãy sử dụng ごろ: 3時ごろ.', '[{"jp": "駅まで歩いて10分ぐらいです。", "vi": "Mất khoảng 10 phút đi bộ đến ga."}, {"jp": "毎日2時間くらい勉強します。", "vi": "Tôi học khoảng 2 giờ mỗi ngày."}, {"jp": "このかばんは5000円ぐらいでした。", "vi": "Chiếc túi này có giá khoảng 5000 yên."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ごろ', 'N + ごろ', 'N5', 'xung quanh; về (một thời điểm)', 'Gắn vào đồng hồ thời gian, ngày tháng. に sau ごろ là tùy chọn: 7時ごろ(に)起きます.', '[{"jp": "毎晩11時ごろ寝ます。", "vi": "Tôi đi ngủ vào khoảng 11 giờ tối mỗi đêm."}, {"jp": "4月ごろ、桜が咲きます。", "vi": "Hoa anh đào nở vào khoảng tháng 4."}, {"jp": "夕方6時ごろに家に帰ります。", "vi": "Tôi về nhà vào khoảng 6 giờ chiều."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('何も〜ない / 誰も〜ない', '何も + V-ない / 誰も + V-ない', 'N5', 'không có gì; không ai; không phải bất cứ điều gì; không phải ai cả', 'Với địa điểm, trợ từ đứng trước も: どこにも / どこへも行きません (không đi đến đâu). 誰 thường được viết bằng hiragana: だれ.', '[{"jp": "けさは何も食べませんでした。", "vi": "Kesa chưa ăn gì cả."}, {"jp": "教室にはだれもいません。", "vi": "Không có ai trong lớp học."}, {"jp": "冷蔵庫の中には何もありません。", "vi": "Chẳng có gì trong tủ lạnh cả."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('何か / 誰か / どこか', 'Question word + か', 'N5', 'cái gì đó; người nào đó; ở đâu đó', 'Từ để hỏi + か cho từ ''some-''; từ để hỏi + も + phủ định cho từ ''không-''. が và を sau 何か / だれか thường bị lược bỏ.', '[{"jp": "何か飲みますか。", "vi": "bạn có muốn uống gì không?"}, {"jp": "だれか来ましたよ。", "vi": "Ai đó đã đến."}, {"jp": "夏休みにどこかへ行きましたか。", "vi": "Bạn có đi đâu trong kỳ nghỉ hè không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('これ / それ / あれ / どれ', 'これ / それ / あれ / どれ', 'N5', 'cái này; cái đó (gần bạn); cái đó (ở đằng kia); cái nào', 'こ = ở gần người nói, そ = ở gần người nghe, あ = ở xa cả hai, ど = câu hỏi. Họ đứng một mình; làm chủ ngữ どれ lấy が, không phải は.', '[{"jp": "これは私の辞書です。", "vi": "Đây là từ điển của tôi."}, {"jp": "それは何ですか。", "vi": "Nó là gì vậy?"}, {"jp": "「あなたのかさはどれですか。」「あれです。」", "vi": "\"Chiếc ô nào của bạn?\" \"Cái đó.\""}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('この / その / あの / どの', 'この / その / あの / どの + N', 'N5', 'cái này; cái đó (gần bạn); cái đó... đằng kia; cái nào (trước danh từ)', 'Luôn theo sau bởi một danh từ: この本, không bao giờ この đứng một mình. これ / それ / あれ / どれ được sử dụng khi không có danh từ.', '[{"jp": "このケーキはおいしいです。", "vi": "Bánh này ngon lắm."}, {"jp": "その本はだれのですか。", "vi": "Cuốn sách đó là của ai?"}, {"jp": "「どの人が先生ですか。」「あの人です。」", "vi": "\"Người nào là giáo viên của bạn?\" \"Người đó.\""}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('ここ / そこ / あそこ / どこ', 'ここ / そこ / あそこ / どこ', 'N5', 'ở đây; ở đó (gần bạn); ở đằng kia; ở đâu', 'こちら / そちら / あちら / どちら là phiên bản lịch sự hơn: お国はどちらですか (Bạn đến từ đâu?).', '[{"jp": "ここは私の学校です。", "vi": "Đây là trường học của tôi."}, {"jp": "トイレはあそこです。", "vi": "Nhà vệ sinh ở đằng kia."}, {"jp": "すみません、駅はどこですか。", "vi": "Xin lỗi, nhà ga ở đâu?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜くない / 〜かった / 〜くなかった', 'A-い(bỏ い) + くない / A-い(bỏ い) + かった / A-い(bỏ い) + くなかった', 'N5', 'Các dạng phủ định và quá khứ của tính từ i (is not; was; was not)', '高い→高くない, 高かった, 高くなかった. Thêm です để lịch sự. いい là không đều: よくない, よかった, よくなかった.', '[{"jp": "この部屋はあまり広くないです。", "vi": "Căn phòng này không lớn lắm."}, {"jp": "きのうのテストは難しかったです。", "vi": "Bài kiểm tra ngày hôm qua thật khó khăn."}, {"jp": "先週見た映画はおもしろくなかったです。", "vi": "Bộ phim tôi xem tuần trước không thú vị."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜な（na-adjective）', 'A-な + な + N / A-な + です / A-な + ではありません / A-な + でした', 'N5', 'tính từ na: đặt な trước danh từ và です hoặc だ ở cuối câu', 'Trước danh từ, thêm な: 静かな部屋. Ở cuối câu chúng thay đổi như danh từ. きれい và きらい kết thúc bằng い nhưng là tính từ な.', '[{"jp": "京都は有名な町です。", "vi": "Kyoto là một thị trấn nổi tiếng."}, {"jp": "きのうは暇でした。", "vi": "Hôm qua tôi có thời gian rảnh."}, {"jp": "この部屋はあまり静かではありません。", "vi": "Căn phòng này không yên tĩnh lắm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜くて / 〜で', 'A-い-ku + て / A-な + で / N + で', 'N5', 'và (nối tính từ hoặc danh từ)', 'いい trở thành よくて. Kết hợp những phẩm chất chỉ ra cùng một hướng (cả tốt hoặc cả xấu); để tương phản, hãy sử dụng が thay thế.', '[{"jp": "この店は安くておいしいです。", "vi": "Quán này rẻ và ngon."}, {"jp": "私の町は静かできれいです。", "vi": "Thị trấn của tôi yên tĩnh và sạch sẽ."}, {"jp": "兄は大学生で、妹は高校生です。", "vi": "Anh trai tôi là sinh viên đại học và chị gái tôi là học sinh trung học."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜という（named）', 'N + という + N', 'N5', 'được gọi là; đặt tên', 'Giới thiệu một cái tên mà người nghe có thể không biết.', '[{"jp": "これは「すきやき」という料理です。", "vi": "Đây là món ăn có tên \"Sukiyaki\"."}, {"jp": "「さくら」という店でアルバイトをしています。", "vi": "Tôi làm việc bán thời gian tại một cửa hàng tên là \"Sakura\"."}, {"jp": "山田さんという人から電話がありました。", "vi": "Tôi nhận được một cuộc điện thoại từ một người tên là ông Yamada."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('あげる / くれる / もらう', 'N (receiver) + に + N + を + あげる / N (giver) + が + N + を + くれる / N (giver) + に + N + を + もらう', 'N4', 'đưa (cho người khác); đưa (cho tôi hoặc nhóm của tôi); nhận được', 'くれる chỉ được sử dụng khi người nhận là người nói hoặc ai đó trong nhóm người nói. Với もらう người tặng có thể được đánh dấu bằng に hoặc から.', '[{"jp": "私は弟に古いゲームをあげた。", "vi": "Tôi đã tặng anh trai tôi một trò chơi cũ."}, {"jp": "姉が誕生日にかわいいかばんをくれました。", "vi": "Em gái tôi đã tặng tôi một chiếc túi dễ thương nhân dịp sinh nhật."}, {"jp": "友達から旅行のおみやげをもらった。", "vi": "Tôi nhận được một món quà lưu niệm từ chuyến đi của tôi từ một người bạn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てあげる', 'V-て + あげる', 'N4', 'Làm giúp cho ai', 'Nói thẳng với cấp trên nghe có vẻ trịch thượng; thay vào đó hãy sử dụng お〜しましょうか (お持ちしましょうか) khiêm tốn.', '[{"jp": "妹の宿題を手伝ってあげました。", "vi": "Tôi đã giúp em gái tôi làm bài tập về nhà."}, {"jp": "道に迷っている人に、駅までの行き方を教えてあげた。", "vi": "Tôi đã chỉ cho một người bị lạc đường đến nhà ga."}, {"jp": "重そうだね。持ってあげようか。", "vi": "Nó có vẻ nặng nề. Tôi mang nó đến cho bạn nhé?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てくれる', 'V-て + くれる', 'N4', 'Ai làm giúp cho mình', 'Chủ ngữ là người làm việc giúp đỡ; người được lợi là người nói hoặc người thân thiết với họ.', '[{"jp": "友達が引っ越しを手伝ってくれた。", "vi": "Một người bạn đã giúp tôi di chuyển."}, {"jp": "父が駅まで車で送ってくれました。", "vi": "Bố tôi chở tôi đến nhà ga."}, {"jp": "母が毎朝お弁当を作ってくれます。", "vi": "Mẹ tôi làm hộp cơm trưa mỗi sáng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てもらう', 'V-て + もらう', 'N4', 'Được ai làm giúp cho', 'Người nhận sự giúp đỡ là chủ ngữ và người thực hiện hành động được đánh dấu bằng に.', '[{"jp": "先輩にレポートを見てもらった。", "vi": "Tôi yêu cầu cấp trên của tôi xem báo cáo."}, {"jp": "友達に写真を撮ってもらった。", "vi": "Tôi nhờ một người bạn chụp ảnh cho tôi."}, {"jp": "分からないところを先生に説明してもらいました。", "vi": "Tôi xin thầy giải thích chỗ tôi chưa hiểu."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てくださる / 〜ていただく', 'V-て + くださる / V-て + いただく', 'N4', '(kính trọng) ai đó tử tế làm cho tôi; (khiêm tốn) Tôi nhận được sự ưu ái của ai đó làm', 'くださる là phiên bản kính ngữ của くれる (ます-dạng: くださいます); いただく là phiên bản khiêm tốn của もらう.', '[{"jp": "先生が私の作文を直してくださいました。", "vi": "Giáo viên đã sửa bài viết của tôi."}, {"jp": "ホテルの方に、おいしい店を教えていただきました。", "vi": "Nhân viên khách sạn giới thiệu với chúng tôi về một số nhà hàng ngon."}, {"jp": "今日は来ていただいて、ありがとうございました。", "vi": "Cảm ơn bạn đã đến ngày hôm nay."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ていく', 'V-て + いく', 'N4', 'làm điều gì đó rồi đi; tiếp tục làm (từ bây giờ đến tương lai)', 'Chuyển động hoặc thay đổi khỏi người nói, hoặc từ hiện tại hướng tới tương lai. So sánh 〜てくる.', '[{"jp": "雨が降りそうだから、傘を持っていきます。", "vi": "Có vẻ như trời sắp mưa nên tôi sẽ mang theo ô."}, {"jp": "これからもっと寒くなっていくでしょう。", "vi": "Từ giờ trở đi trời sẽ lạnh hơn."}, {"jp": "時間があるなら、お茶を飲んでいきませんか。", "vi": "Nếu có thời gian, tại sao không đi uống trà?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てくる', 'V-て + くる', 'N4', 'làm điều gì đó và quay lại; đến làm ; (thay đổi) cho đến nay; bắt đầu', 'Sự chuyển động hoặc thay đổi hướng về phía người nói, hoặc từ quá khứ đến hiện tại. 行ってきます nghĩa đen là ''Tôi sẽ đi và quay lại.''', '[{"jp": "ちょっとコンビニに行ってきます。", "vi": "Tôi sẽ đến cửa hàng tiện lợi một lúc."}, {"jp": "日本語が少しずつ分かってきた。", "vi": "Tôi bắt đầu hiểu tiếng Nhật từng chút một."}, {"jp": "おなかがすいてきた。", "vi": "Tôi đang đói."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てしまう / 〜ちゃう', 'V-て + しまう', 'N4', 'kết thúc hoàn toàn; làm một cách tình cờ; kết thúc việc làm (với sự hối tiếc)', 'Trong lời nói, 〜てしまう hợp âm thành 〜ちゃう, và 〜でしまう thành 〜じゃう (飲んじゃう).', '[{"jp": "電車に傘を忘れてしまいました。", "vi": "Tôi quên ô trên tàu."}, {"jp": "この本はおもしろくて、一晩で読んでしまった。", "vi": "Cuốn sách này rất thú vị và tôi đã đọc nó trong một đêm."}, {"jp": "あ、ケーキを全部食べちゃった。", "vi": "Ồ, tôi đã ăn hết cái bánh rồi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ておく', 'V-て + おく', 'N4', 'Làm sẵn, chuẩn bị trước', 'Trong cách nói thông thường 〜ておく thường trở thành 〜とく (買っとく), và 〜でおく trở thành 〜どく (読んどく).', '[{"jp": "旅行の前に、ホテルを予約しておきます。", "vi": "Đặt khách sạn trước chuyến đi của bạn."}, {"jp": "パーティーのために、飲み物を冷やしておいた。", "vi": "Tôi đã giữ lạnh đồ uống cho bữa tiệc."}, {"jp": "エアコンはつけておいてください。", "vi": "Vui lòng để máy điều hòa bật."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てみる', 'V-て + みる', 'N4', 'Làm thử xem sao', 'Có nghĩa là thử làm việc gì đó để xem kết quả, không nỗ lực làm việc gì khó khăn.', '[{"jp": "このシャツ、着てみてもいいですか。", "vi": "Tôi có thể thử chiếc áo này được không?"}, {"jp": "新しくできたラーメン屋に行ってみた。", "vi": "Tôi đến một cửa hàng ramen mới."}, {"jp": "日本の料理を自分で作ってみたいです。", "vi": "Tôi muốn thử tự mình làm món ăn Nhật Bản."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てある', 'V-て + ある', 'N4', 'đã được thực hiện (và vẫn như vậy); trạng thái kết quả của một hành động có chủ ý', 'Được sử dụng với động từ chuyển tiếp và tân ngữ thường dùng が. Nó ngụ ý ai đó đã cố tình làm điều đó, không giống như 〜ている với nội động từ (窓が開いている).', '[{"jp": "入り口に地図がはってあります。", "vi": "Có một bản đồ ở lối vào."}, {"jp": "テーブルの上にお皿が並べてあった。", "vi": "Trên bàn đã bày sẵn những chiếc đĩa."}, {"jp": "ビールなら冷蔵庫に入れてあるよ。", "vi": "Tôi có bia trong tủ lạnh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とき', 'V(thể thông thường) / A-い / A-な + な / N + の + とき', 'N4', 'Khi, lúc...', 'Thì của động từ thể hiện thứ tự: 行くとき nghĩa là trước hoặc trên đường (việc đi vẫn chưa kết thúc); 行ったとき có nghĩa là sau khi đến nơi. Thường được viết 時 bằng chữ Hán.', '[{"jp": "子どものとき、よく川で泳ぎました。", "vi": "Khi tôi còn nhỏ, tôi thường bơi ở sông."}, {"jp": "日本へ行くとき、新しいかばんを買いました。", "vi": "Khi tôi đến Nhật Bản, tôi đã mua một chiếc túi mới."}, {"jp": "日本へ行ったとき、友達にお土産を買いました。", "vi": "Khi tôi đến Nhật Bản, tôi đã mua một món quà lưu niệm cho bạn tôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜間 / 〜間に', 'V-て + いる / V-る(thể từ điển) / N + の + 間（に）', 'N4', 'trong khi ; trong suốt (toàn bộ thời gian); tại một thời điểm nào đó trong thời gian', '間 có nghĩa là hành động tiếp tục trong suốt thời gian; 間に có nghĩa là nó xảy ra vào một thời điểm nào đó trong một khoảng thời gian.', '[{"jp": "夏休みの間、祖父の家にいました。", "vi": "Tôi ở nhà ông nội trong kỳ nghỉ hè."}, {"jp": "母が寝ている間に、部屋を掃除した。", "vi": "Tôi dọn phòng trong khi mẹ tôi đang ngủ."}, {"jp": "電車を待っている間、ずっと本を読んでいた。", "vi": "Tôi đã đọc sách trong suốt thời gian chờ tàu."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜そうだ（appearance）', 'V-ます(bỏ ます) / A-い(bỏ い) / A-な + そうだ', 'N4', 'trông giống như; có vẻ ; có vẻ sắp', 'Một sự phán xét từ những gì bạn nhìn thấy. いい → よさそう, ない → なさそう. Không dùng với tính từ chỉ những đặc điểm rõ ràng (赤い, かわいい); かわいそう có nghĩa là ''đáng thương''.', '[{"jp": "そのカレー、辛そうだね。", "vi": "Món cà ri đó có vẻ cay."}, {"jp": "空が暗いですね。雨が降りそうです。", "vi": "Bầu trời tối sầm. Có vẻ như trời sắp mưa."}, {"jp": "久しぶりに会った祖父は元気そうだった。", "vi": "Ông tôi, người mà tôi gặp lần đầu sau một thời gian, có vẻ đang rất vui vẻ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜そうだ（hearsay）', 'V(thể thông thường) / A-い + そうだ / A-な + だ + そうだ / N + だ + そうだ', 'N4', 'Tôi đã nghe điều đó; họ nói thế', 'Gắn vào các dạng đơn giản hoàn toàn, không giống như ''trông giống'' そうだ, gắn vào thân cây. Nó không có hình thức quá khứ hoặc tiêu cực.', '[{"jp": "天気予報では、明日は雪が降るそうです。", "vi": "Theo dự báo thời tiết, ngày mai trời sẽ có tuyết."}, {"jp": "駅前の本屋は来月なくなるそうだ。", "vi": "Có vẻ như hiệu sách trước nhà ga sẽ đóng cửa vào tháng tới."}, {"jp": "リンさんのお兄さんは医者だそうです。", "vi": "Có vẻ như anh trai của Rin là bác sĩ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜らしい（hearsay/conjecture）', 'V(thể thông thường) / A-い / A-な / N + らしい', 'N4', 'rõ ràng; có vẻ như; tôi nghe thấy', 'Dựa vào nội dung đã nghe hoặc đọc nên loa phát ra âm thanh hơi tách biệt. ''Điển hình'' らしい (男らしい) là một điểm N3 riêng biệt.', '[{"jp": "駅の近くに新しいカフェができたらしい。", "vi": "Có vẻ như một quán cà phê mới đã mở gần nhà ga."}, {"jp": "部屋の電気が消えている。もう寝たらしい。", "vi": "Đèn trong phòng tắt. Có vẻ như anh ấy đã ngủ rồi."}, {"jp": "あの店のラーメンはとても有名らしいです。", "vi": "Món ramen ở nhà hàng đó có vẻ rất nổi tiếng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ようだ', 'V(thể thông thường) / A-い + ようだ / A-な + な + ようだ / N + の + ようだ', 'N4', 'Dường như, hình như là...', 'Một cách hơi trang trọng để đưa ra đánh giá dựa trên những gì bạn quan sát hoặc cảm nhận; みたいだ là từ tương đương thông thường. Việc sử dụng ''like, as if'' được đề cập ở N3.', '[{"jp": "誰もいないようですね。", "vi": "Có vẻ như không có ai ở đó."}, {"jp": "かぜをひいたようで、朝からのどが痛い。", "vi": "Tôi cảm thấy như bị cảm lạnh và cổ họng đau rát từ sáng."}, {"jp": "外は寒いようだ。みんなコートを着ている。", "vi": "Bên ngoài có vẻ lạnh. Mọi người đều mặc áo khoác."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜みたい', 'V(thể thông thường) / A-い / A-な / N + みたい', 'N4', 'có vẻ như; trông giống như; thích (thông thường)', 'Thông thường tương đương với ようだ. Nó gắn trực tiếp vào danh từ và tính từ na (静かみたい) mà không cần な hoặc の. Trước danh từ nó trở thành みたいな.', '[{"jp": "隣の部屋に誰か来たみたい。", "vi": "Hình như có ai đó ở phòng bên cạnh."}, {"jp": "今日の彼女は元気がないみたいだね。", "vi": "Hôm nay cô ấy có vẻ không được khỏe."}, {"jp": "このケーキ、お店のケーキみたい！", "vi": "Chiếc bánh này trông giống như một chiếc bánh mua ở cửa hàng!"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜すぎる', 'V-ます(bỏ ます) / A-い(bỏ い) / A-な + すぎる', 'N4', 'Quá... (Vượt mức bình thường, tiêu cực)', 'Liên hợp như động từ Nhóm 2 (すぎた, すぎて). いい → よすぎる và tính từ ない → なさすぎる.', '[{"jp": "ゆうべ飲みすぎて、頭が痛い。", "vi": "Tôi đã uống quá nhiều và đầu tôi đau nhức."}, {"jp": "この靴は私には大きすぎます。", "vi": "Chiếc giày này quá lớn đối với tôi."}, {"jp": "この問題は簡単すぎて、つまらない。", "vi": "Vấn đề này quá dễ và nhàm chán."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜方', 'V-ます(bỏ ます) + 方', 'N4', 'làm thế nào để; cách làm', 'Kết quả là một danh từ nên tân ngữ lấy の thay vì を (日本語の話し方). Với động từ する: 勉強のしかた.', '[{"jp": "この機械の使い方を教えてください。", "vi": "Xin vui lòng cho tôi biết cách sử dụng máy này."}, {"jp": "この漢字の読み方が分かりません。", "vi": "Tôi không biết đọc chữ kanji này như thế nào."}, {"jp": "祖母においしいみそ汁の作り方を習った。", "vi": "Tôi đã học cách nấu súp miso ngon từ bà tôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜中', 'N + 中', 'N4', 'ở giữa; trong thời gian (ちゅう); khắp; khắp nơi (じゅう)', 'ちゅう đánh dấu một hoạt động đang diễn ra hoặc một khoảng thời gian (会議中, 午前中, 今週中); じゅう có nghĩa là ''xuyên suốt'' một thời gian hoặc địa điểm (一日中, 世界中).', '[{"jp": "父は今、電話中です。", "vi": "Bây giờ bố tôi đang nói chuyện điện thoại."}, {"jp": "昨日は一日中雨が降っていた。", "vi": "Hôm qua trời mưa cả ngày."}, {"jp": "この歌は世界中で知られている。", "vi": "Bài hát này được biết đến trên toàn thế giới."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜つもり', 'V-る(thể từ điển) / V-ない + つもり', 'N4', 'Dự định làm gì', 'Nêu rõ ý định cá nhân chắc chắn. 〜つもりはない có nghĩa là ''không có ý định''. Hỏi cấp trên 〜つもりですか nghe có vẻ thẳng thừng.', '[{"jp": "夏休みは北海道を旅行するつもりです。", "vi": "Tôi đang có kế hoạch đi du lịch đến Hokkaido vào kỳ nghỉ hè."}, {"jp": "今日はお酒を飲まないつもりです。", "vi": "Hôm nay tôi sẽ không uống rượu."}, {"jp": "大学を出たら、どうするつもりですか。", "vi": "Bạn dự định làm gì sau khi tốt nghiệp đại học?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜予定', 'V-る(thể từ điển) + 予定 / N + の + 予定', 'N4', 'Theo kế hoạch là...', 'Đề cập đến một lịch trình hoặc sự sắp xếp cố định, thường có sự tham gia của người khác; khách quan hơn つもり.', '[{"jp": "来月、大阪に引っ越す予定です。", "vi": "Tôi đang có kế hoạch chuyển đến Osaka vào tháng tới."}, {"jp": "会議は三時に終わる予定です。", "vi": "Cuộc họp dự kiến ​​kết thúc lúc ba giờ."}, {"jp": "出発は朝八時の予定です。", "vi": "Dự kiến ​​khởi hành lúc 8 giờ sáng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことにする', 'V-る(thể từ điển) / V-ない + ことにする', 'N4', 'quyết định', 'Một quyết định của người nói; so sánh 〜ことになる. 〜ことにしている (N3) có nghĩa là ''đặt nó thành quy tắc''.', '[{"jp": "健康のために、毎朝歩くことにした。", "vi": "Tôi quyết định đi bộ mỗi sáng vì sức khỏe của mình."}, {"jp": "高かったので、買わないことにしました。", "vi": "Nó đắt nên tôi quyết định không mua."}, {"jp": "もう遅いから、タクシーで帰ることにしよう。", "vi": "Giờ cũng muộn rồi nên tôi sẽ bắt taxi về nhà."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことになる', 'V-る(thể từ điển) / V-ない + ことになる', 'N4', 'điều đó đã được quyết định; hóa ra là thế', 'Trình bày một quyết định được đưa ra bởi người khác hoặc bởi hoàn cảnh. Mọi người cũng sử dụng nó cho các quyết định của riêng họ để có vẻ ít quyết đoán hơn.', '[{"jp": "来年の春から、名古屋の店で働くことになりました。", "vi": "Bắt đầu từ mùa xuân tới, tôi sẽ làm việc tại một cửa hàng ở Nagoya."}, {"jp": "今度の日曜日、クラスのみんなでバーベキューをすることになった。", "vi": "Chủ nhật tuần này, tôi quyết định tổ chức tiệc nướng với lớp của mình."}, {"jp": "友達の結婚式で、私がスピーチをすることになりました。", "vi": "Tôi dự kiến ​​sẽ phát biểu tại đám cưới của một người bạn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことができる', 'V-る(thể từ điển) + ことができる', 'N4', 'Có thể làm gì (Khả năng)', 'Trang trọng hơn một chút so với hình thức tiềm năng. Cũng được dùng cho những việc có thể hoặc được phép (ここでたばこを吸うことはできません).', '[{"jp": "この図書館では、本を二週間借りることができます。", "vi": "Bạn có thể mượn sách trong hai tuần tại thư viện này."}, {"jp": "妹はピアノを弾くことができる。", "vi": "Em gái tôi có thể chơi piano."}, {"jp": "ここからは富士山を見ることができません。", "vi": "Bạn không thể nhìn thấy Núi Phú Sĩ từ đây."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜える / 〜られる（potential）', 'V-る(thể từ điển) (Group 1: final u → e) + る / V-ない(bỏ ない) + られる (Group 2)', 'N4', 'có thể; có thể (dạng tiềm năng)', 'Bất quy tắc: する → できる, 来る → 来られる. Tân ngữ thường dùng が thay vì を. Trong lời nói thông thường, động từ Nhóm 2 thường bỏ ら (見れる).', '[{"jp": "私は漢字が二百ぐらい読めます。", "vi": "Tôi có thể đọc được khoảng 200 chữ kanji."}, {"jp": "兄は辛い料理が食べられない。", "vi": "Anh trai tôi không ăn được đồ cay."}, {"jp": "明日のパーティーに来られますか。", "vi": "Bạn có thể đến dự bữa tiệc ngày mai được không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜れる / 〜られる（passive）', 'V-ない(bỏ ない) + れる (Group 1) / V-ない(bỏ ない) + られる (Group 2)', 'N4', 'được thực hiện (bởi ai đó); giọng nói thụ động', 'Bất quy tắc: する → される, 来る → 来られる. Người thực hiện được đánh dấu bằng に. Thường thể hiện rằng đối tượng gặp rắc rối trước hành động của ai đó (雨に降られた).', '[{"jp": "先生に作文をほめられました。", "vi": "Giáo viên của tôi đã khen ngợi bài luận của tôi."}, {"jp": "電車の中で足を踏まれた。", "vi": "Chân tôi đã bị giẫm lên tàu."}, {"jp": "この寺は六百年前に建てられました。", "vi": "Ngôi chùa này được xây dựng cách đây 600 năm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜せる / 〜させる', 'V-ない(bỏ ない) + せる (Group 1) / V-ない(bỏ ない) + させる (Group 2)', 'N4', 'bắt ai đó làm gì; để ai đó làm (nguyên nhân)', 'Bất quy tắc: する → させる, 来る → 来させる. Với nội động từ người ta dùng を; với động từ chuyển tiếp, に. Bối cảnh quyết định ''làm'' hoặc ''cho phép''.', '[{"jp": "母は毎日弟に野菜を食べさせる。", "vi": "Mẹ tôi bắt em trai tôi ăn rau mỗi ngày."}, {"jp": "コーチは毎日、選手たちを走らせた。", "vi": "Huấn luyện viên bắt các cầu thủ chạy mỗi ngày."}, {"jp": "息子が行きたいと言ったので、一人で旅行に行かせました。", "vi": "Con trai tôi muốn đi nên tôi để cháu tự đi du lịch."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜せられる / 〜させられる', 'V-ない(bỏ ない) + せられる (Group 1; short form される) / V-ない(bỏ ない) + させられる (Group 2)', 'N4', 'bị buộc phải làm (trái với ý muốn của ai đó)', 'Bất quy tắc: する → させられる, 来る → 来させられる. Dạng ngắn Nhóm 1 (待たされる) phổ biến trong lời nói, nhưng không phổ biến với các động từ kết thúc bằng す (話させられる).', '[{"jp": "子どものころ、母に毎日ピアノを練習させられた。", "vi": "Khi tôi còn nhỏ, mẹ tôi bắt tôi tập piano hàng ngày."}, {"jp": "駅で三十分も待たされました。", "vi": "Tôi phải đợi ba mươi phút ở nhà ga."}, {"jp": "会社の飲み会で歌を歌わされた。", "vi": "Tôi bị bắt phải hát một bài hát trong bữa tiệc rượu của công ty."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜おう / 〜よう', 'V-る(thể từ điển) (Group 1: final u → o) + う / V-ます(bỏ ます) + よう (Group 2)', 'N4', 'hãy (thông thường); Tôi sẽ (dạng ý chí)', 'Bất quy tắc: する → しよう, 来る → 来よう. Tương đương với 〜ましょう.', '[{"jp": "疲れたね。少し休もう。", "vi": "Tôi mệt rồi. Chúng ta hãy nghỉ ngơi một chút."}, {"jp": "週末、一緒に映画を見ようよ。", "vi": "Cuối tuần này chúng ta cùng nhau xem phim nhé."}, {"jp": "よし、今日から毎日日記を書こう。", "vi": "Được rồi, bắt đầu từ hôm nay, tôi sẽ viết nhật ký hàng ngày."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜(よ)うと思う', 'V(thể ý chí) + と思う', 'N4', 'đang nghĩ đến việc làm; lên kế hoạch', '〜と思う thường báo cáo một quyết định vừa được đưa ra; 〜と思っている thể hiện một kế hoạch được thực hiện trong một thời gian. Nhẹ nhàng hơn つもり.', '[{"jp": "今年の夏は海に行こうと思っています。", "vi": "Tôi đang nghĩ đến việc đi biển vào mùa hè này."}, {"jp": "明日は早く起きて、公園を走ろうと思う。", "vi": "Tôi nghĩ ngày mai tôi sẽ dậy sớm và chạy trong công viên."}, {"jp": "新しいパソコンを買おうと思ったけど、やめました。", "vi": "Tôi đã nghĩ đến việc mua một chiếc máy tính mới nhưng lại quyết định từ chối."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜え / 〜ろ', 'V-る(thể từ điển) (Group 1: final u → e) / V-ます(bỏ ます) + ろ (Group 2)', 'N4', 'làm điều đó! (dạng mệnh lệnh; mệnh lệnh thẳng thừng)', 'Bất quy tắc: する → しろ, 来る → 来い, くれる → くれ. Rất thẳng thừng; chủ yếu được nghe từ nam giới, trên các biển báo, trong trường hợp khẩn cấp và trong tiếng cổ vũ (がんばれ).', '[{"jp": "早く起きろ！遅刻するぞ。", "vi": "Dậy sớm! Tôi sẽ bị trễ mất."}, {"jp": "危ない！止まれ！", "vi": "nguy hiểm! dừng lại!"}, {"jp": "がんばれ！あと少しだ！", "vi": "giữ nó lên! Chỉ một chút nữa thôi!"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜な（prohibition）', 'V-る(thể từ điển) + な', 'N4', 'đừng! (cấm mạnh)', 'Rất mạnh mẽ và thẳng thừng. Đừng nhầm lẫn nó với đuôi câu な diễn tả cảm xúc (いいな).', '[{"jp": "危ないから、この川では泳ぐな。", "vi": "Đừng bơi ở con sông này, nó nguy hiểm."}, {"jp": "もう泣くな。大丈夫だよ。", "vi": "Đừng khóc nữa. Không sao đâu."}, {"jp": "壁に「ここにごみを捨てるな」と書いてある。", "vi": "Có một tấm biển trên tường ghi rằng, ``Đừng vứt rác ở đây.''''"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜なさい', 'V-ます(bỏ ます) + なさい', 'N4', 'làm (sự hướng dẫn của phụ huynh, giáo viên, v.v.)', 'Nhẹ nhàng hơn dạng mệnh lệnh nhưng vẫn mang tính chỉ dẫn chắc chắn; được phụ huynh, giáo viên và trong các buổi hướng dẫn thi cử, không bao giờ hướng tới cấp trên.', '[{"jp": "もう九時よ。早く寝なさい。", "vi": "Đã chín giờ rồi. Đi ngủ sớm đi."}, {"jp": "次の文を読んで、質問に答えなさい。", "vi": "Đọc đoạn văn sau và trả lời các câu hỏi."}, {"jp": "ご飯の前に手を洗いなさい。", "vi": "Rửa tay trước khi ăn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ば', 'V-ば / A-い(bỏ い) + ければ / A-な + なら / N + なら', 'N4', 'Nếu... thì... (Điều kiện)', 'Tập trung vào điều kiện cần thiết để đạt được kết quả. Khi mệnh đề chính là một yêu cầu hoặc lời mời, たら thường tự nhiên hơn trừ khi mệnh đề ば là một trạng thái (ある, いる, tính từ).', '[{"jp": "この道をまっすぐ行けば、駅に着きます。", "vi": "Nếu đi thẳng theo con đường này sẽ tới nhà ga."}, {"jp": "安ければ、買いたいです。", "vi": "Nếu nó rẻ thì tôi muốn mua nó."}, {"jp": "分からないことがあれば、いつでも聞いてください。", "vi": "Nếu bạn không hiểu điều gì đó, xin vui lòng hỏi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たら', 'V-た + ら / A-い(bỏ い) + かったら / A-な + だったら / N + だったら', 'N4', 'Nếu, sau khi...', 'Câu điều kiện linh hoạt nhất và rất phổ biến trong lời nói. Với những sự kiện chắc chắn sẽ xảy ra, nó có nghĩa là ''khi/sau''.', '[{"jp": "駅に着いたら、電話してください。", "vi": "Hãy gọi cho tôi khi bạn đến nhà ga."}, {"jp": "もし明日雨だったら、家で映画を見よう。", "vi": "Nếu ngày mai trời mưa thì chúng ta hãy xem phim ở nhà nhé."}, {"jp": "暑かったら、窓を開けてもいいですよ。", "vi": "Nếu trời nóng, bạn có thể mở cửa sổ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜なら', 'V(thể thông thường) / A-い / A-な / N + なら', 'N4', 'Nếu là... thì...', 'Tiếp thu những gì người nghe đã nói hoặc một tình huống được cho là đúng, sau đó đưa ra lời khuyên hoặc ý kiến. Không giống như たら, hành động chính có thể xảy ra trước mệnh đề なら.', '[{"jp": "京都へ行くなら、秋がいいですよ。", "vi": "Mùa thu là thời điểm lý tưởng nhất để đến Kyoto."}, {"jp": "パソコンのことなら、兄に聞くといいよ。", "vi": "Về vấn đề máy tính, bạn có thể hỏi anh trai mình."}, {"jp": "そんなに眠いなら、今日は早く寝たら？", "vi": "Nếu buồn ngủ quá thì sao hôm nay bạn không đi ngủ sớm nhỉ?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜と（conditional）', 'V-る(thể từ điển) / V-ない / A-い + と / A-な + だ + と / N + だ + と', 'N4', 'khi nào; nếu như; bất cứ khi nào (kết quả tự nhiên hoặc tự động)', 'Để có kết quả tự nhiên, cách máy móc hoạt động, hướng dẫn và thói quen. Mệnh đề chính không thể là một yêu cầu, mong muốn hay lời mời.', '[{"jp": "このボタンを押すと、お茶が出ます。", "vi": "Nhấn nút này và trà sẽ được phục vụ."}, {"jp": "春になると、桜が咲きます。", "vi": "Vào mùa xuân, hoa anh đào nở rộ."}, {"jp": "この道を右に曲がると、左に郵便局があります。", "vi": "Rẽ phải trên con đường này và bưu điện sẽ ở bên trái của bạn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ても / 〜でも', 'V-て + も / A-い-ku + ても / A-な + でも / N + でも', 'N4', 'ngay cả khi; mặc dù', 'Với từ để hỏi hoặc いくら nó có nghĩa là ''không có vấn đề gì ...'' (何を食べても, いくら待っても).', '[{"jp": "雨が降っても、試合はあります。", "vi": "Ngay cả khi trời mưa, vẫn sẽ có một trò chơi."}, {"jp": "いくら練習しても、なかなか上手になりません。", "vi": "Dù bạn có luyện tập bao nhiêu đi nữa thì bạn cũng sẽ không bao giờ giỏi được."}, {"jp": "日曜日でも、この店は開いています。", "vi": "Cửa hàng này mở cửa cả ngày chủ nhật."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜のに（although）', 'V(thể thông thường) / A-い + のに / A-な + な + のに / N + な + のに', 'N4', 'mặc dù ; mặc dù (với sự ngạc nhiên hoặc không hài lòng)', 'Mang đến sự ngạc nhiên, thất vọng hoặc phàn nàn. Mệnh đề chính không thể là một yêu cầu hay ý định; sử dụng けど hoặc ても ở đó.', '[{"jp": "一生懸命勉強したのに、試験に落ちてしまった。", "vi": "Mặc dù tôi học hành chăm chỉ nhưng tôi đã trượt kỳ thi."}, {"jp": "日曜日なのに、会社に行かなければならない。", "vi": "Dù là chủ nhật nhưng tôi vẫn phải đi làm."}, {"jp": "約束したのに、彼は来なかった。", "vi": "Anh ấy đã không đến dù đã hứa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜のに（purpose）', 'V-る(thể từ điển) + のに / N + に', 'N4', 'vì ; để (với việc sử dụng, thời gian hoặc chi phí)', 'Thường theo sau là các từ như 使う, いい, 便利, 必要 hoặc かかる. Với danh từ, chỉ dùng に (旅行に便利).', '[{"jp": "このかばんは旅行に行くのに便利です。", "vi": "Túi này tiện lợi khi đi du lịch."}, {"jp": "家から駅まで歩くのに二十分かかります。", "vi": "Phải mất hai mươi phút đi bộ từ nhà tôi đến ga."}, {"jp": "引っ越しするのに十万円ぐらいかかった。", "vi": "Tôi tốn khoảng 100.000 yên để di chuyển."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ので', 'V(thể thông thường) / A-い + ので / A-な + な + ので / N + な + ので', 'N4', 'Vì... nên... (Lý do khách quan, lịch sự)', 'Nghe nhẹ nhàng và khách quan hơn から nên nó được ưa chuộng hơn khi đưa ra lý do một cách lịch sự hoặc khi xin lỗi.', '[{"jp": "頭が痛いので、今日は早く帰ります。", "vi": "Hôm nay tôi bị đau đầu nên về nhà sớm."}, {"jp": "明日はテストなので、今夜は勉強します。", "vi": "Ngày mai tôi có bài kiểm tra nên tối nay tôi sẽ học."}, {"jp": "道がこんでいたので、少し遅れました。", "vi": "Đường đông đúc nên tôi đến hơi muộn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜て（reason）', 'V-て / A-い(bỏ い) + くて / A-な + で / N + で', 'N4', 'bởi vì ; vì vậy (gây ra một cảm giác hoặc trạng thái)', 'Phần thứ hai thường là cảm giác, hình thức tiềm ẩn hoặc kết quả, không phải là yêu cầu hay ý định (dùng から hoặc ので cho những điều đó). Phủ định: 〜なくて (会えなくて寂しい).', '[{"jp": "ニュースを聞いて、びっくりしました。", "vi": "Tôi rất ngạc nhiên khi nghe tin này."}, {"jp": "このスープは熱くて、飲めません。", "vi": "Món súp này quá nóng để uống."}, {"jp": "かぜで学校を休みました。", "vi": "Tôi nghỉ học vì cảm lạnh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜し', 'V(thể thông thường) / A-い + し / A-な + だ + し / N + だ + し', 'N4', 'và hơn thế nữa; và bên cạnh đó (liệt kê lý do)', 'Liệt kê một số lý do hoặc điểm. Một chữ し gợi ý rằng còn có những lý do khác.', '[{"jp": "この部屋は広いし、駅から近いし、とても気に入っています。", "vi": "Phòng này rộng rãi, gần ga, mình rất thích."}, {"jp": "今日は雨だし、疲れているし、どこにも行きたくない。", "vi": "Hôm nay trời mưa, tôi mệt, không muốn đi đâu cả."}, {"jp": "もう遅いし、そろそろ帰ろうか。", "vi": "Bây giờ cũng đã muộn rồi nên chúng ta hãy về nhà thôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜けど / 〜けれども', 'Mệnh đề + けど / けれども', 'N4', 'nhưng; mặc dù; (đầu vào mềm)', 'Mang tính trò chuyện nhiều hơn が; けれども trang trọng hơn けど một chút. Thường được sử dụng như một lời mở đầu nhẹ nhàng trước một câu hỏi hoặc yêu cầu.', '[{"jp": "この店は高いけど、おいしい。", "vi": "Nhà hàng này đắt tiền nhưng ngon."}, {"jp": "すみません、駅に行きたいんですけど、どう行けばいいですか。", "vi": "Xin lỗi, tôi muốn đến nhà ga, nhưng tôi nên đi bằng cách nào?"}, {"jp": "何度も電話したけれども、誰も出なかった。", "vi": "Tôi gọi nhiều lần nhưng không ai trả lời."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ために', 'V-る(thể từ điển) / V-た / N + の + ために', 'N4', 'để ; vì (vì lợi ích của); bởi vì', 'Vì mục đích, động từ phải là thứ mà chủ ngữ có thể kiểm soát được (so sánh 〜ように). Việc sử dụng ''vì'' nghe có vẻ khá trang trọng.', '[{"jp": "日本の大学に入るために、毎日勉強しています。", "vi": "Tôi đang học hàng ngày để vào được một trường đại học Nhật Bản."}, {"jp": "家族のために、一生懸命働いている。", "vi": "Anh ấy làm việc chăm chỉ vì gia đình."}, {"jp": "大雪のために、電車が止まりました。", "vi": "Tàu dừng lại vì tuyết dày."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ように（purpose）', 'V-る(thể từ điển) / V-ない + ように', 'N4', 'vậy đó ; theo thứ tự đó', 'Dùng với các động từ mà chủ ngữ không thể trực tiếp điều khiển: dạng tiềm năng, 分かる, 見える, phủ định. Với những hành động có chủ ý, hãy sử dụng ために.', '[{"jp": "後ろの人にも聞こえるように、大きな声で話してください。", "vi": "Hãy nói to để người đứng sau có thể nghe thấy."}, {"jp": "忘れないように、手にメモを書いた。", "vi": "Tôi đã viết một ghi chú trên tay để tôi không quên."}, {"jp": "かぜをひかないように、暖かくして寝てください。", "vi": "Hãy ngủ ấm áp để tránh bị cảm lạnh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ようにする', 'V-る(thể từ điển) / V-ない + ようにする', 'N4', 'Cố gắng làm / không làm gì', '〜ようにしている mô tả một thói quen mà bạn duy trì. So sánh 〜ようになる, một sự thay đổi xảy ra.', '[{"jp": "毎日野菜を食べるようにしています。", "vi": "Tôi cố gắng ăn rau mỗi ngày."}, {"jp": "これからは遅刻しないようにします。", "vi": "Từ giờ trở đi tôi sẽ cố gắng không đến muộn."}, {"jp": "寝る前にスマホを見ないようにしている。", "vi": "Tôi cố gắng không nhìn vào điện thoại thông minh của mình trước khi đi ngủ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ようになる', 'V-る(thể từ điển) / V-ない + ようになる', 'N4', 'Trở nên có thể làm gì', 'Thường được sử dụng với các động từ tiềm năng. Đối với ''không còn nữa'', 〜なくなる thường tự nhiên hơn 〜ないようになる.', '[{"jp": "練習して、自転車に乗れるようになりました。", "vi": "Sau khi tập luyện, tôi đã có thể đi xe đạp."}, {"jp": "日本に来てから、朝ご飯を食べるようになった。", "vi": "Sau khi đến Nhật Bản, tôi bắt đầu ăn sáng."}, {"jp": "赤ちゃんが少しずつ話せるようになってきた。", "vi": "Bé bắt đầu biết nói từng chút một."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てほしい', 'V-て + ほしい / V-ない + で + ほしい', 'N4', 'muốn ai đó làm gì', 'Người bạn muốn hành động được đánh dấu bằng に. Nói với cấp trên điều đó nghe có vẻ khắt khe; 〜ていただきたいです lịch sự hơn.', '[{"jp": "もう少しゆっくり話してほしいです。", "vi": "Tôi muốn bạn nói chậm lại một chút."}, {"jp": "この話は誰にも言わないでほしい。", "vi": "Xin đừng kể cho ai biết về câu chuyện này."}, {"jp": "早く春が来てほしいなあ。", "vi": "Tôi mong mùa xuân đến sớm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たがる', 'V-ます(bỏ ます) + たがる', 'N4', '(người khác) muốn', 'Dùng cho người khác, vì bạn không thể trực tiếp biết được mong muốn của họ. Mong muốn hiện tại thường được thể hiện bằng 〜たがっている.', '[{"jp": "子どもたちは外で遊びたがっている。", "vi": "Trẻ em muốn chơi bên ngoài."}, {"jp": "弟はいつも私のゲームをやりたがる。", "vi": "Anh trai tôi luôn muốn chơi trò chơi của tôi."}, {"jp": "犬が散歩に行きたがっています。", "vi": "Con chó muốn đi dạo."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜がる', 'A-い(bỏ い) / A-な + がる', 'N4', '(người khác) cảm thấy; có dấu hiệu cảm giác', 'Chuyển các tính từ cảm giác (怖い, 寂しい, ほしい) thành động từ mô tả cảm giác của người khác. Đối tượng của cảm giác lấy を.', '[{"jp": "妹は暗い所を怖がる。", "vi": "Em gái tôi sợ những nơi tối tăm."}, {"jp": "祖母は孫に会えなくて寂しがっている。", "vi": "Người bà nhớ việc gặp cháu trai của mình."}, {"jp": "息子は新しい自転車をほしがっている。", "vi": "Con trai tôi muốn một chiếc xe đạp mới."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かもしれない', 'V(thể thông thường) / A-い / A-な / N + かもしれない', 'N4', 'có thể; có thể; có thể', 'Chắc chắn khoảng 50% hoặc ít hơn. Trong cách nói thông thường, nó thường được rút ngắn thành かも.', '[{"jp": "午後から雨が降るかもしれません。", "vi": "Trời có thể mưa vào buổi chiều."}, {"jp": "かぎがない。電車の中で落としたかもしれない。", "vi": "Không có chìa khóa. Có lẽ tôi đã đánh rơi nó trên tàu."}, {"jp": "その話は本当かもしれない。", "vi": "Câu chuyện đó có thể là sự thật."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜だろう', 'V(thể thông thường) / A-い / A-な / N + だろう', 'N4', 'có lẽ; Tôi cho rằng (dạng đơn giản của でしょう)', 'Phổ biến trong văn viết và lời nói thông thường của nam giới; でしょう là hình thức lịch sự. Thường dùng với たぶん hoặc きっと, hoặc như 〜だろうと思う.', '[{"jp": "明日はたぶん晴れるだろう。", "vi": "Có lẽ ngày mai trời sẽ nắng."}, {"jp": "彼女はもう家に着いただろう。", "vi": "Bây giờ chắc cô ấy đã về tới nhà rồi."}, {"jp": "この問題は子どもには難しいだろうと思います。", "vi": "Tôi nghĩ vấn đề này sẽ khó khăn đối với trẻ em."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜はずだ', 'V(thể thông thường) / A-い + はずだ / A-な + な + はずだ / N + の + はずだ', 'N4', 'nên thế; dự kiến (dựa trên lý luận)', 'Một kỳ vọng tự tin dựa trên sự thật hoặc logic, không phải là phỏng đoán. Nó không có nghĩa là ''nên'' như một nghĩa vụ.', '[{"jp": "荷物は明日届くはずです。", "vi": "Gói hàng sẽ đến vào ngày mai."}, {"jp": "彼は十年もアメリカに住んでいたから、英語が上手なはずだ。", "vi": "Anh ấy sống ở Mỹ được mười năm nên chắc hẳn anh ấy giỏi tiếng Anh."}, {"jp": "おかしいな。かぎはここに置いたはずなのに。", "vi": "Điều đó thật kỳ lạ. Lẽ ra tôi nên để chìa khóa ở đây."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜はずがない', 'V(thể thông thường) / A-い + はずがない / A-な + な + はずがない / N + の + はずがない', 'N4', 'không thể được; không có cách nào đó', 'Phủ nhận mạnh mẽ dựa trên lý luận. 〜ないはずだ (''không nên'') là một sự mong đợi nhẹ nhàng hơn.', '[{"jp": "あんなにまじめな人がうそをつくはずがない。", "vi": "Không đời nào một người nghiêm túc như vậy lại nói dối được."}, {"jp": "今日は日曜日だから、銀行が開いているはずがない。", "vi": "Hôm nay là chủ nhật nên ngân hàng không mở cửa được."}, {"jp": "かぎはちゃんとかけたから、ドアが開いているはずがない。", "vi": "Cửa đã được khóa cẩn thận nên không có cách nào cửa mở được."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜んです / 〜のです', 'V(thể thông thường) / A-い + んです / A-な + な + んです / N + な + んです', 'N4', 'chính là...; (giải thích hoặc yêu cầu giải thích)', 'Thêm ý nghĩa giải thích một tình huống hoặc hỏi thông tin cơ bản. Các hình thức thông thường là 〜んだ và 〜の. Việc sử dụng quá mức nó có thể nghe có vẻ tự đề cao.', '[{"jp": "どうしたんですか。顔色が悪いですよ。", "vi": "Chuyện gì đã xảy ra thế? Bạn trông nhợt nhạt."}, {"jp": "すみません、遅れました。電車が止まっていたんです。", "vi": "Xin lỗi, tôi đến muộn. Tàu đã dừng lại."}, {"jp": "日本語で手紙を書きたいんですが、手伝ってくれませんか。", "vi": "Tôi muốn viết một lá thư bằng tiếng Nhật, bạn có thể giúp tôi được không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かどうか', 'V(thể thông thường) / A-い / A-な / N + かどうか', 'N4', 'có hay không', 'Nhúng câu hỏi có-không vào câu. Đối với các câu hỏi có từ để hỏi, chỉ sử dụng 〜か (何時に来るか).', '[{"jp": "明日行けるかどうか、まだ分かりません。", "vi": "Tôi vẫn không biết liệu ngày mai tôi có thể đi được không."}, {"jp": "この服が似合うかどうか、ちょっと着てみます。", "vi": "Tôi sẽ thử bộ trang phục này xem nó có hợp với tôi không."}, {"jp": "そのレストランがおいしいかどうか、友達に聞いてみよう。", "vi": "Hỏi bạn bè xem nhà hàng có ngon không."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜か（embedded question）', 'Question word + ... + V(thể thông thường) / A-い / A-な / N + か', 'N4', 'câu hỏi nhúng (cái gì, ở đâu, ai, v.v.)', 'Sau danh từ hoặc tính từ na, だ bị lược bỏ (誰の傘か知らない).', '[{"jp": "会議が何時に始まるか、教えてください。", "vi": "Xin vui lòng cho tôi biết cuộc họp bắt đầu lúc mấy giờ."}, {"jp": "どこで財布をなくしたか、覚えていません。", "vi": "Tôi không nhớ mình đã đánh rơi ví ở đâu."}, {"jp": "誰が窓を割ったか、知っていますか。", "vi": "Bạn có biết ai đã phá vỡ cửa sổ không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜と思う', 'V(thể thông thường) / A-い + と思う / A-な + だ + と思う / N + だ + と思う', 'N4', 'tôi nghĩ rằng', 'Người Nhật thường phủ định mệnh đề trích dẫn (来ないと思う) hơn là 思う. Đối với ý kiến ​​của người khác, hãy sử dụng 〜と思っている.', '[{"jp": "この映画はきっと人気が出ると思う。", "vi": "Tôi nghĩ bộ phim này chắc chắn sẽ nổi tiếng."}, {"jp": "彼女は今日は来ないと思います。", "vi": "Tôi không nghĩ cô ấy sẽ đến hôm nay."}, {"jp": "日本の電車はとても便利だと思います。", "vi": "Tôi nghĩ tàu Nhật rất tiện lợi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜と言う', '「Mệnh đề」 + と言う / Mệnh đề (plain) + と言う', 'N4', 'nói điều đó; kể (trích dẫn)', 'Trích dẫn trực tiếp đi vào bên trong 「」; trích dẫn gián tiếp sử dụng các hình thức đơn giản. 〜と言っていた được dùng phổ biến khi truyền lại điều ai đó đã nói.', '[{"jp": "先生は「明日はテストがあります」と言いました。", "vi": "Giáo viên nói, “Ngày mai có bài kiểm tra.”"}, {"jp": "兄は今晩、帰りが遅くなると言っていた。", "vi": "Anh trai tôi nói tối nay anh ấy sẽ về nhà muộn."}, {"jp": "日本では食べる前に「いただきます」と言います。", "vi": "Ở Nhật Bản, chúng tôi nói “itadakimasu” trước khi ăn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜しか〜ない', 'N + しか + V-ない', 'N4', 'chỉ; không có gì ngoài', 'Luôn đi đôi với động từ phủ định. So với だけ, nó nhấn mạnh số lượng ít hoặc không đủ.', '[{"jp": "財布に五百円しかない。", "vi": "Tôi chỉ có 500 yên trong ví."}, {"jp": "このことは、あなたにしか話していません。", "vi": "Tôi chỉ nói chuyện với bạn về điều này."}, {"jp": "朝はコーヒーしか飲みません。", "vi": "Tôi chỉ uống cà phê vào buổi sáng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ばかり', 'N + ばかり', 'N4', 'không có gì ngoài; chỉ một; tất cả', 'Thường ngụ ý có quá nhiều thứ. 〜てばかりいる (N3) và 〜たばかり (''vừa làm'') là những điểm riêng biệt.', '[{"jp": "弟は肉ばかり食べて、野菜を食べない。", "vi": "Em trai tôi chỉ ăn thịt và không ăn rau."}, {"jp": "このクラスは女の子ばかりだ。", "vi": "Lớp này chỉ có con gái thôi."}, {"jp": "最近は雨の日ばかりで、洗濯ができない。", "vi": "Gần đây trời mưa nhiều quá nên tôi không thể giặt đồ được."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たばかり', 'V-た + ばかり', 'N4', 'vừa làm xong', 'Cho thấy người nói cảm thấy thời gian đã trôi qua rất ít, ngay cả khi đó là vài tuần trước. 〜たところ chỉ đề cập đến khoảnh khắc trước đây.', '[{"jp": "日本に来たばかりなので、まだ日本語がよく分かりません。", "vi": "Mình mới sang Nhật nên chưa hiểu tiếng Nhật lắm."}, {"jp": "さっき昼ご飯を食べたばかりだから、おなかがいっぱいだ。", "vi": "Tôi vừa mới ăn trưa nên đã no rồi."}, {"jp": "買ったばかりの傘をなくしてしまった。", "vi": "Tôi làm mất chiếc ô vừa mới mua."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ところだ', 'V-る(thể từ điển) / V-て + いる / V-た + ところだ', 'N4', 'sắp ; ở giữa; vừa làm xong', 'Dạng từ điển: sắp. 〜ているところ: ở giữa. 〜たところ: vừa xong. Nó xác định chính xác giai đoạn của một hành động.', '[{"jp": "今から出かけるところです。", "vi": "Tôi sắp rời đi."}, {"jp": "今、晩ご飯を作っているところだから、後で電話するね。", "vi": "Bây giờ tôi đang nấu bữa tối nên sẽ gọi cho bạn sau."}, {"jp": "ちょうど今、駅に着いたところです。", "vi": "Tôi vừa mới đến nhà ga."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜やすい / 〜にくい', 'V-ます(bỏ ます) + やすい / V-ます(bỏ ます) + にくい', 'N4', 'dễ dàng; khó để', 'Cả hai liên hợp như tính từ i. やすい cũng có thể có nghĩa là ''có xu hướng'' (この服は汚れやすい).', '[{"jp": "このペンは書きやすいです。", "vi": "Cây bút này rất dễ viết."}, {"jp": "先生の説明は分かりやすい。", "vi": "Lời giải của thầy rất dễ hiểu."}, {"jp": "この魚は骨が多くて食べにくい。", "vi": "Loại cá này có nhiều xương nên rất khó ăn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜始める / 〜終わる / 〜続ける', 'V-ます(bỏ ます) + 始める / V-ます(bỏ ます) + 終わる / V-ます(bỏ ます) + 続ける', 'N4', 'bắt đầu làm; làm xong; tiếp tục làm', '〜終わる được dùng với những hành động có kết thúc rõ ràng (読む, 食べる, 書く). 〜終える là một cách thay thế trang trọng hơn.', '[{"jp": "去年からギターを習い始めました。", "vi": "Tôi bắt đầu học guitar vào năm ngoái."}, {"jp": "その本、読み終わったら貸してくれない？", "vi": "Bạn có thể cho tôi mượn cuốn sách đó sau khi bạn đọc xong nó được không?"}, {"jp": "三時間も歩き続けて、足が痛くなった。", "vi": "Sau khi đi bộ được ba giờ, chân tôi đau nhức."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜出す', 'V-ます(bỏ ます) + 出す', 'N4', 'đột nhiên bắt đầu làm; bùng nổ', 'Ngụ ý sự khởi đầu đột ngột, thường không kiểm soát được. Không giống như 〜始める, nó không được sử dụng cho các hành động đã được lên kế hoạch hoặc trong các yêu cầu.', '[{"jp": "赤ちゃんが急に泣き出した。", "vi": "Đứa bé đột nhiên bắt đầu khóc."}, {"jp": "さっきまで晴れていたのに、急に雨が降り出した。", "vi": "Vừa rồi trời đang nắng, nhưng đột nhiên trời bắt đầu mưa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ほど〜ない', 'N / V(thể thông thường) + ほど + A-い-ku + ない / A-な + ではない', 'N4', 'không phải như ... như', 'Mệnh đề trước ほど là tiêu chuẩn so sánh. Luôn luôn theo sau là một tiêu cực.', '[{"jp": "今年の夏は去年ほど暑くない。", "vi": "Mùa hè năm nay không nóng như năm ngoái."}, {"jp": "私の町は東京ほどにぎやかではありません。", "vi": "Thị trấn của tôi không sôi động như Tokyo."}, {"jp": "テストは思ったほど難しくなかった。", "vi": "Bài kiểm tra không khó như tôi mong đợi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('なかなか〜ない', 'なかなか + V-ない', 'N4', 'không dễ dàng; sẽ không; không dễ dàng', 'Cho thấy điều gì đó không xảy ra nhanh chóng và dễ dàng như mong đợi. Với dạng khẳng định, なかなか có nghĩa là ''khá'' (なかなかおいしい).', '[{"jp": "バスがなかなか来ない。", "vi": "Xe buýt không đến dễ dàng."}, {"jp": "漢字がなかなか覚えられません。", "vi": "Tôi gặp khó khăn khi nhớ chữ kanji."}, {"jp": "子どもがなかなか寝てくれない。", "vi": "Con tôi khó ngủ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ずつ', 'N (quantity) + ずつ', 'N4', 'mỗi; tại một thời điểm; từng chút một', '', '[{"jp": "りんごを一人に二つずつ配った。", "vi": "Tôi đưa cho mỗi người hai quả táo."}, {"jp": "毎日少しずつ漢字を覚えています。", "vi": "Tôi ghi nhớ chữ Hán từng chút một mỗi ngày."}, {"jp": "一人ずつ部屋に入ってください。", "vi": "Hãy vào phòng từng người một."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜も（emphasis）', 'N (number + counter) + も', 'N4', 'nhiều như vậy; nhiều như ; (với một phủ định) thậm chí không một', 'Cho thấy người nói cảm thấy số lượng lớn. Với 一 + counter và động từ phủ định, nó có nghĩa là ''thậm chí không một''.', '[{"jp": "昨日は十時間も寝てしまった。", "vi": "Hôm qua tôi đã ngủ được mười tiếng."}, {"jp": "このかばんは五万円もするんですか。", "vi": "Cái túi này có giá 50.000 yên phải không?"}, {"jp": "財布の中に一円もない。", "vi": "Tôi không còn một xu nào trong ví."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜までに', 'N / V-る(thể từ điển) + までに', 'N4', 'bởi (một thời hạn); trước đây', 'までに đánh dấu thời hạn cho một hành động diễn ra một lần; まで đánh dấu khoảng thời gian một sự việc tiếp tục diễn ra (六時まで働く).', '[{"jp": "レポートは金曜日までに出してください。", "vi": "Vui lòng gửi báo cáo của bạn trước thứ Sáu."}, {"jp": "六時までに家に帰らなければならない。", "vi": "Tôi phải về nhà trước sáu giờ."}, {"jp": "暗くなるまでに山を下りよう。", "vi": "Hãy xuống núi trước khi trời tối."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことがある', 'V-る(thể từ điển) / V-ない + ことがある', 'N4', 'đôi khi; có những lúc', 'Sử dụng từ điển hoặc dạng ない. Với dạng quá khứ (〜たことがある) nó có nghĩa là ''đã từng làm trước đây''.', '[{"jp": "忙しいときは、朝ご飯を食べないことがあります。", "vi": "Khi tôi bận, đôi khi tôi không ăn sáng."}, {"jp": "この道は冬になると、雪で通れなくなることがある。", "vi": "Vào mùa đông, con đường này có thể trở nên tắc nghẽn do tuyết."}, {"jp": "週末は家族で料理をすることがある。", "vi": "Vào cuối tuần, thỉnh thoảng tôi nấu ăn cùng gia đình."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ないといけない / 〜なくちゃ', 'V-ない + といけない / V-ない(bỏ ない) + なくちゃ', 'N4', 'phải ; phải (đàm thoại)', 'Các lựa chọn thay thế hàng ngày cho なければならない. なくちゃ xuất phát từ なくては; なきゃ (từ なければ) cũng rất phổ biến.', '[{"jp": "明日は早いから、もう寝ないといけない。", "vi": "Ngày mai trời còn sớm nên tôi phải đi ngủ rồi."}, {"jp": "あ、もうこんな時間！帰らなくちゃ。", "vi": "A, đã lâu như vậy rồi! Tôi phải về nhà."}, {"jp": "この薬は毎日飲まないといけません。", "vi": "Thuốc này phải được uống mỗi ngày."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜させてください', 'V-ない(bỏ ない) + せてください (Group 1) / V-ない(bỏ ない) + させてください (Group 2)', 'N4', 'xin vui lòng cho tôi (làm)', 'Được xây dựng trên thể nguyên nhân て (する → させて). 〜させていただけませんか thì lịch sự hơn.', '[{"jp": "少し考えさせてください。", "vi": "Hãy để tôi suy nghĩ về nó một lát."}, {"jp": "今日は私に払わせてください。", "vi": "Hãy để tôi trả tiền ngay hôm nay."}, {"jp": "体の調子が悪いので、今日は早く帰らせてください。", "vi": "Hôm nay tôi thấy không khỏe nên xin hãy cho tôi về nhà sớm hôm nay."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('尊敬語', 'いらっしゃる（行く・来る・いる） / 召し上がる（食べる・飲む） / おっしゃる（言う） / なさる（する） / ご覧になる（見る） / くださる（くれる）', 'N4', 'động từ kính ngữ; ngôn ngữ tôn trọng hành động của người khác', 'Nâng cao hành động của những người bạn tôn trọng, chẳng hạn như khách hàng, giáo viên và cấp trên. Đừng bao giờ sử dụng nó cho hành động của riêng bạn.', '[{"jp": "社長は何時ごろいらっしゃいますか。", "vi": "Mấy giờ tổng thống sẽ đến?"}, {"jp": "先生、どうぞ召し上がってください。", "vi": "Mời thầy thưởng thức."}, {"jp": "部長は会議でそうおっしゃいました。", "vi": "Người quản lý đã nói như vậy tại cuộc họp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('謙譲語', '参る（行く・来る） / おる（いる） / いただく（食べる・飲む・もらう） / 申す（言う） / いたす（する） / 拝見する（見る） / 伺う（聞く・訪ねる）', 'N4', 'động từ khiêm tốn; ngôn ngữ khiêm tốn cho hành động của chính mình', 'Giảm bớt hành động của chính bạn hoặc của nhóm bạn đối với người mà bạn tôn trọng. 参る, おる, 申す và いたす cũng làm cho lời nói nói chung có vẻ trang trọng.', '[{"jp": "明日の午後、そちらに伺います。", "vi": "Tôi sẽ đến thăm bạn vào chiều mai."}, {"jp": "初めまして。リンと申します。", "vi": "Rất vui được gặp bạn. Tên tôi là Rin."}, {"jp": "お手紙、拝見しました。", "vi": "Tôi đã thấy thư của bạn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('お〜になる', 'お + V-ます(bỏ ます) + になる', 'N4', '(kính trọng) ai đó được kính trọng làm', 'Không dùng với gốc một âm tiết (見る, 寝る) hoặc động từ có dạng đặc biệt (行く → いらっしゃる). する-danh từ lấy ご + Danh từ + になる (ご利用になる).', '[{"jp": "先生はもうお帰りになりました。", "vi": "Thầy đã về nhà rồi."}, {"jp": "この本をお読みになりましたか。", "vi": "Bạn đã đọc cuốn sách này chưa?"}, {"jp": "社長はいつもこのホテルにお泊まりになります。", "vi": "Tổng thống luôn ở khách sạn này."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('お〜する', 'お + V-ます(bỏ ます) + する / ご + N + する', 'N4', '(khiêm tốn) Tôi làm (đối với một người được kính trọng)', 'Chỉ dành cho những hành động có ảnh hưởng hoặc có lợi cho người khác. お〜いたします thậm chí còn trang trọng hơn.', '[{"jp": "重そうですね。お持ちしましょうか。", "vi": "Nó có vẻ nặng nề. Tôi mang nó đến cho bạn nhé?"}, {"jp": "後で詳しくご説明します。", "vi": "Tôi sẽ giải thích chi tiết sau."}, {"jp": "駅までお送りします。", "vi": "Tôi sẽ thả bạn ở nhà ga."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜でございます', 'N / A-な + でございます', 'N4', 'là; là; là (copula rất lịch sự)', 'Phiên bản rất lịch sự của です, điển hình của nhân viên cửa hàng và khách sạn nói chuyện với khách hàng. ございます bản thân nó là hình thức lịch sự của あります.', '[{"jp": "お手洗いはあちらでございます。", "vi": "Nhà vệ sinh ở đằng kia."}, {"jp": "こちらが、お部屋のかぎでございます。", "vi": "Đây là chìa khóa phòng của bạn."}, {"jp": "はい、山田商店でございます。", "vi": "Vâng, đây là Yamada Shoten."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ても構わない', 'V-て + も構わない / A-い-ku + ても構わない / A-な + でも構わない / N + でも構わない', 'N4', 'đừng bận tâm nếu; sẽ ổn thôi nếu', 'Trang trọng hơn 〜てもいい một chút. 〜なくても構わない có nghĩa là ''không sao đâu''.', '[{"jp": "ここに荷物を置いても構いませんか。", "vi": "Có ổn không nếu tôi để hành lý của mình ở đây?"}, {"jp": "少しぐらい高くても構わないから、いい辞書を買いたい。", "vi": "Tôi không phiền nếu nó đắt một chút nhưng tôi muốn mua một cuốn từ điển tốt."}, {"jp": "返事は明日でも構いませんよ。", "vi": "Bạn có thể trả lời vào ngày mai."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜の / 〜こと（nominalizer）', 'V(thể thông thường) + の / V(thể thông thường) + こと', 'N4', 'hành động làm (chuyển cụm động từ thành danh từ)', 'の được ưa chuộng hơn với các động từ nhận thức (見る, 聞こえる) và trong lời nói thông thường; こと cần được dùng trước です/だ và trong các mẫu cố định như 〜ことができる.', '[{"jp": "私は写真を撮るのが好きです。", "vi": "Tôi thích chụp ảnh."}, {"jp": "趣味は古い映画を見ることです。", "vi": "Sở thích của tôi là xem phim cũ."}, {"jp": "かぎをかけるのを忘れました。", "vi": "Tôi quên khóa nó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ばよかった', 'V-ば + よかった / V-ない(bỏ ない) + なければよかった', 'N4', 'nên có (thực hiện); Tôi ước tôi có', 'Thể hiện sự tiếc nuối về quá khứ. 〜たらよかった là một từ thay thế trong hội thoại phổ biến.', '[{"jp": "もっと早く家を出ればよかった。", "vi": "Lẽ ra tôi nên rời nhà sớm hơn."}, {"jp": "あんなこと、言わなければよかった。", "vi": "Đáng lẽ tôi không nên nói điều đó."}, {"jp": "傘を持ってくればよかったなあ。", "vi": "Tôi ước gì tôi đã mang theo một chiếc ô."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たらどう', 'V-た + らどう', 'N4', 'tại sao bạn không ...?; bạn nghĩ thế nào về ...?', 'Thường được rút gọn thành 〜たら？. Có thể tỏ ra tự đề cao cấp trên; 〜たらいかがですか là phiên bản lịch sự.', '[{"jp": "疲れているなら、少し休んだらどう？", "vi": "Nếu mệt thì tại sao bạn không nghỉ ngơi?"}, {"jp": "分からなければ、先生に聞いてみたらどうですか。", "vi": "Nếu không hiểu sao không hỏi thầy cô?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ほうがいい', 'V-た / V-ない + ほうがいい', 'N4', 'Nên / Không nên làm gì (Lời khuyên)', 'Để được tư vấn, dạng quá khứ (行ったほうがいい) là lựa chọn thông thường và nghe mạnh mẽ hơn. Thể phủ định sử dụng dạng ない, không phải quá khứ.', '[{"jp": "熱があるなら、病院に行ったほうがいいですよ。", "vi": "Nếu sốt thì nên đến bệnh viện."}, {"jp": "夜遅くに一人で歩かないほうがいい。", "vi": "Tốt hơn hết là đừng đi bộ một mình vào đêm khuya."}, {"jp": "大事な書類は、コピーしておいたほうがいいですよ。", "vi": "Tốt nhất là nên sao chép các tài liệu quan trọng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とか〜とか', 'N + とか + N + とか / V-る(thể từ điển) + とか + V-る(thể từ điển) + とか', 'N4', 'những thứ như A và B; A, B, v.v. (thông thường)', 'Bình thường hơn 〜や〜など, và nó cũng có thể liệt kê các động từ hoặc cả cụm từ.', '[{"jp": "冷蔵庫に卵とか牛乳とかが入っています。", "vi": "Có trứng và sữa trong tủ lạnh."}, {"jp": "休みの日は、映画とか買い物とかに行きます。", "vi": "Vào những ngày nghỉ, tôi đi xem phim hoặc đi mua sắm."}, {"jp": "健康のために、野菜を食べるとか運動するとか、何かしたほうがいい。", "vi": "Bạn nên làm điều gì đó cho sức khỏe của mình, như ăn rau và tập thể dục."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜など', 'N + など', 'N4', 'v.v.; vân vân; chẳng hạn như', 'Thường kết hợp với や (AやBなど). Sau một danh từ, nó làm dịu đi một gợi ý.', '[{"jp": "机の上に本やノートなどがあります。", "vi": "Trên bàn có sách và vở."}, {"jp": "夏休みに京都や奈良などに行きました。", "vi": "Trong kỳ nghỉ hè, tôi đã đến những nơi như Kyoto và Nara."}, {"jp": "お茶など、いかがですか。", "vi": "Bạn có muốn uống trà không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜でも（suggestion）', 'N + でも', 'N4', 'hoặc cái gì đó (làm dịu đi một lời đề nghị)', 'Đưa ra một ví dụ trong khi vẫn để ngỏ các tùy chọn khác, điều này làm cho lời mời và lời khuyên nghe có vẻ ít thuyết phục hơn.', '[{"jp": "ちょっと休んで、コーヒーでも飲みませんか。", "vi": "Bạn có muốn nghỉ ngơi và uống chút cà phê không?"}, {"jp": "雨だから、家でゲームでもしよう。", "vi": "Trời mưa nên ở nhà chơi vài trò chơi nhé."}, {"jp": "暇なら、本でも読んだら？", "vi": "Nếu bạn có thời gian rảnh, tại sao không đọc sách?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜さ', 'A-い(bỏ い) + さ / A-な + さ', 'N4', '-ness (chuyển tính từ thành danh từ chỉ mức độ)', 'いい trở thành よさ. Thường dùng cho các phép đo (高さ, 重さ, 大きさ, 長さ).', '[{"jp": "この橋の長さはどのくらいですか。", "vi": "Cây cầu này dài bao nhiêu?"}, {"jp": "山の上の寒さにびっくりした。", "vi": "Tôi ngạc nhiên vì trời trên núi lạnh đến thế nào."}, {"jp": "この仕事の大変さは、やってみないと分からない。", "vi": "Bạn sẽ không hiểu công việc này khó khăn như thế nào cho đến khi bạn thử nó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜目', 'N (number + counter) + 目', 'N4', '-th (thứ tự: thứ nhất, thứ hai, thứ ba...)', '', '[{"jp": "右から三つ目の建物が図書館です。", "vi": "Tòa nhà thứ ba từ phải sang là thư viện."}, {"jp": "日本に来るのは今回で二回目です。", "vi": "Đây là lần thứ hai tôi đến Nhật Bản."}, {"jp": "二つ目の角を左に曲がってください。", "vi": "Rẽ trái ở góc thứ hai."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜おきに', 'N (number + counter) + おきに', 'N4', 'nhau; trong khoảng thời gian', 'Với ngày (一日おき) nó bỏ qua một đơn vị, nghĩa là ''cách ngày''. Với số phút hoặc khoảng cách, nó thường chỉ có nghĩa là ''mọi X''.', '[{"jp": "このバスは十五分おきに来ます。", "vi": "Xe buýt này đến cứ sau mười lăm phút."}, {"jp": "一日おきにジョギングをしています。", "vi": "Tôi chạy bộ mỗi ngày."}, {"jp": "道の両側に、木が五メートルおきに植えてある。", "vi": "Hai bên đường cứ năm mét lại trồng cây xanh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜くする / 〜にする（make）', 'A-い-ku + する / A-な + に + する / N + に + する', 'N4', 'làm (cái gì)...; thay đổi cái gì đó sang trạng thái', 'Ai đó cố tình thay đổi một cái gì đó. So sánh 〜くなる / 〜になる, nơi mà sự thay đổi tự nó xảy ra.', '[{"jp": "テレビの音を小さくしてください。", "vi": "Vui lòng giảm âm thanh TV."}, {"jp": "お客さんが来るから、部屋をきれいにしよう。", "vi": "Chúng ta có khách đến nên hãy dọn phòng đi."}, {"jp": "暑いので、髪を短くしました。", "vi": "Trời nóng nên tôi cắt tóc ngắn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜がする', 'N + がする', 'N4', '(mùi, âm thanh, vị hoặc cảm giác) được cảm nhận', 'Được sử dụng với におい, 音, 声, 味 và 気 (〜気がする: ''có cảm giác như vậy'').', '[{"jp": "台所からいいにおいがする。", "vi": "Có một mùi thơm dễ chịu tỏa ra từ nhà bếp."}, {"jp": "外で変な音がしました。", "vi": "Tôi nghe thấy một tiếng động lạ ở bên ngoài."}, {"jp": "このお茶は少し甘い味がする。", "vi": "Trà này có vị hơi ngọt."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かな / 〜かしら', 'V(thể thông thường) / A-い / A-な / N + かな / かしら', 'N4', 'tôi tự hỏi', 'Một câu hỏi nhẹ nhàng, thường tự nói với chính mình. かしら nghe có vẻ nữ tính và hơi lỗi thời. 〜ないかな có thể diễn tả một điều ước (早く来ないかな).', '[{"jp": "明日は晴れるかな。", "vi": "Tôi tự hỏi liệu ngày mai trời có nắng không."}, {"jp": "このお菓子、誰が買ってきたのかな。", "vi": "Tôi tự hỏi ai đã mua chiếc kẹo này?"}, {"jp": "この服、私に似合うかしら。", "vi": "Chiếc váy này có hợp với tôi không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てくれませんか / 〜ていただけませんか', 'V-て + くれませんか / V-て + いただけませんか', 'N4', 'bạn có thể làm ơn...? (yêu cầu lịch sự)', 'Nhẹ nhàng hơn 〜てください. Sự lịch sự tăng từ 〜てくれませんか lên 〜てもらえませんか đến 〜ていただけませんか.', '[{"jp": "すみません、写真を撮ってくれませんか。", "vi": "Xin lỗi, bạn có thể chụp một bức ảnh được không?"}, {"jp": "この書類の書き方を教えていただけませんか。", "vi": "Bạn có thể vui lòng cho tôi biết cách viết tài liệu này?"}, {"jp": "もう少し大きい声で話していただけませんか。", "vi": "Bạn có thể vui lòng nói to hơn một chút được không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ないで', 'V-ない + で', 'N4', 'không làm gì; thay vì làm', '〜ずに (N3) có nghĩa tương tự nhưng trang trọng hơn. Khác với 〜なくて, nó đưa ra lý do.', '[{"jp": "今朝は朝ご飯を食べないで学校に行った。", "vi": "Sáng nay tôi đi học mà không ăn sáng."}, {"jp": "傘を持たないで出かけて、雨にぬれてしまった。", "vi": "Tôi ra ngoài mà không mang ô và bị ướt sũng dưới mưa."}, {"jp": "エレベーターを使わないで、階段で上がりましょう。", "vi": "Thay vì sử dụng thang máy, hãy đi lên cầu thang bộ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜わけだ', 'V(thể thông thường) / A-い / A-な + な / N + という + わけだ', 'N3', 'Thảo nào... / Hóa ra là vậy...', 'Đưa ra kết luận một cách tự nhiên dựa trên những sự kiện đã biết, thường với cảm giác ''bây giờ tôi đã hiểu''. Thường đứng trước だから, それで hoặc どうりで.', '[{"jp": "三年も中国に住んでいたんですか。だから中国語が上手なわけですね。", "vi": "Bạn sống ở Trung Quốc được ba năm? Đó là lý do tại sao tôi giỏi tiếng Trung."}, {"jp": "窓が全部開いている。どうりで寒いわけだ。", "vi": "Tất cả các cửa sổ đều mở. Không có gì ngạc nhiên khi trời lạnh."}, {"jp": "この本は三百ページだから、一日に二十ページ読めば、十五日で読み終わるわけだ。", "vi": "Cuốn sách này có 300 trang, vì vậy nếu bạn đọc 20 trang mỗi ngày, bạn có thể đọc xong trong 15 ngày."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜わけではない', 'V(thể thông thường) / A-い / A-な + な / N + という + わけではない', 'N3', 'nó không có nghĩa như vậy; nó không phải vậy; không nhất thiết', 'Sự phủ nhận một phần hoặc nhẹ nhàng những gì người nghe có thể giả định. Thường đi kèm với いつも, 全部 hoặc 必ずしも. Không giống như 〜わけがない, loại trừ một cách thẳng thừng điều gì đó.', '[{"jp": "料理が嫌いなわけではないが、毎日作る時間がない。", "vi": "Không phải tôi không thích nấu ăn mà là tôi không có thời gian để nấu nướng hàng ngày."}, {"jp": "値段が高ければおいしいというわけではない。", "vi": "Chỉ vì thứ gì đó đắt tiền không có nghĩa là nó ngon."}, {"jp": "全然分からないわけではありませんが、もう少しゆっくり話していただけますか。", "vi": "Không phải là tôi không hiểu gì cả, nhưng bạn có thể nói chậm hơn một chút được không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜わけがない', 'V(thể thông thường) / A-い / A-な + な / N + の + わけがない', 'N3', 'Chắc chắn không thể... / Lẽ nào lại...', 'Niềm tin chắc chắn của người nói rằng điều gì đó là không thể. Bình thường: 〜わけない. Gần giống với 〜はずがない, nhưng nghe có vẻ cảm xúc hơn và ít dựa trên lý lẽ hơn.', '[{"jp": "こんなに練習したんだから、負けるわけがない。", "vi": "Tôi đã luyện tập rất nhiều, không đời nào tôi sẽ thua được."}, {"jp": "あんなにまじめな人が、約束を忘れるわけがありません。", "vi": "Không đời nào một người nghiêm túc như vậy lại quên lời hứa của mình."}, {"jp": "一日で漢字を百個覚えるなんて、できるわけがないよ。", "vi": "Không có cách nào bạn có thể ghi nhớ 100 chữ Hán trong một ngày."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜わけにはいかない', 'V-る(thể từ điển) / V-ない + わけにはいかない', 'N3', 'Không thể... (Vì đạo đức, quy tắc xã hội)', 'Hành động này có thể thực hiện được nhưng bị loại trừ bởi nghĩa vụ, hoàn cảnh hoặc lẽ thường. 〜ないわけにはいかない có nghĩa là ''phải; không thể tránh khỏi việc làm''.', '[{"jp": "明日は大事な会議があるから、休むわけにはいかない。", "vi": "Ngày mai tôi có cuộc họp quan trọng nên không thể nghỉ được."}, {"jp": "友達に頼まれたことだから、断るわけにはいかなかった。", "vi": "Đó là lời mời của một người bạn nên tôi không thể từ chối."}, {"jp": "招待されたのだから、パーティーに行かないわけにはいかない。", "vi": "Tôi được mời đến bữa tiệc nên tôi không còn cách nào khác là phải đi dự bữa tiệc."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ものだ', 'V-る(thể từ điển) / V-た / A-い / A-な + な + ものだ', 'N3', 'đó là điều tự nhiên; người ta nên; đã từng (nỗi nhớ); Làm sao ...! (cảm xúc sâu sắc)', 'Công dụng chính: sự thật chung hoặc xu hướng tự nhiên, chuẩn mực xã hội (nên), thói quen hoài niệm về quá khứ với 〜たものだ, và cảm giác sâu sắc (時間がたつのは早いものだ). Bình thường: 〜もんだ.', '[{"jp": "子どものころは、この川でよく泳いだものだ。", "vi": "Khi tôi còn nhỏ, tôi thường bơi ở dòng sông này."}, {"jp": "新しい環境に慣れるには、時間がかかるものだ。", "vi": "Cần có thời gian để làm quen với môi trường mới."}, {"jp": "目上の人には敬語を使うものだ。", "vi": "Ngôn ngữ kính trọng được sử dụng cho cấp trên."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ものではない', 'V-る(thể từ điển) + ものではない', 'N3', 'người ta không nên; điều đó không đúng', 'Lời khuyên dựa trên lẽ thường hoặc chuẩn mực xã hội, thường là từ người lớn tuổi. Bình thường: 〜もんじゃない. Nghe có vẻ giống sự hiểu biết thông thường hơn là 〜べきではない.', '[{"jp": "人の失敗を笑うものではない。", "vi": "Đừng cười nhạo lỗi lầm của người khác."}, {"jp": "出された食べ物を残すものじゃないよ。", "vi": "Đừng bỏ lại thức ăn bạn đã được phục vụ."}, {"jp": "夜遅くに人の家に電話をかけるものではありません。", "vi": "Đây không phải là việc gọi điện đến nhà ai đó vào đêm khuya."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜もの / 〜もん', 'Mệnh đề + もの / もん', 'N3', 'bởi vì (lý do thông thường hoặc tự biện minh)', 'Nghe có vẻ bĩu môi hoặc tự biện minh; thường bắt đầu bằng だって. もん thông tục hơn. Được sử dụng bởi trẻ em và giữa những người bạn thân; tránh ở nơi làm việc.', '[{"jp": "「どうして食べないの？」「だって、ピーマン嫌いなんだもん。」", "vi": "\"Tại sao bạn không ăn nó?\" “Bởi vì tôi không thích ớt xanh.”"}, {"jp": "一人で行けるよ。もう子どもじゃないもん。", "vi": "Tôi có thể đi một mình. Tôi không còn là một đứa trẻ nữa."}, {"jp": "ケーキ、全部食べちゃった。だって、すごくおいしかったんだもん。", "vi": "Tôi đã ăn hết cái bánh. Bởi vì nó thực sự rất ngon."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ものだから / 〜もので', 'V(thể thông thường) / A-い / A-な + な / N + な + ものだから / もので', 'N3', 'bởi vì ; vì (giải thích hoặc bào chữa cho một tình huống)', 'Giải thích hoặc bào chữa cho điều gì đó không hoàn toàn nằm trong tầm kiểm soát của người nói. Mệnh đề chính không thể là một mệnh lệnh hoặc yêu cầu. もので thường dùng trong lời xin lỗi lịch sự.', '[{"jp": "道がすごく混んでいたものだから、約束の時間に間に合わなかった。", "vi": "Đường đông đúc đến mức tôi không thể đến đúng giờ được."}, {"jp": "すみません、急いでいたもので、書類を持ってくるのを忘れてしまいました。", "vi": "Xin lỗi, tôi vội quá quên mang theo tài liệu."}, {"jp": "初めての海外旅行だったものだから、見るものすべてが珍しかった。", "vi": "Đó là chuyến đi nước ngoài đầu tiên của tôi nên mọi thứ tôi thấy đều khác thường."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことだ', 'V-る(thể từ điển) / V-ない + ことだ', 'N3', 'nên ; điều tốt nhất là (lời khuyên)', 'Lời khuyên cá nhân từ một người ở vị trí có thể đưa ra lời khuyên đó (giáo viên, phụ huynh, cấp trên). Không dùng với cấp trên. So sánh 〜ものだ, cái nào phù hợp với những chuẩn mực chung.', '[{"jp": "日本語が上手になりたいなら、毎日少しずつでも話すことだ。", "vi": "Nếu bạn muốn giỏi tiếng Nhật hơn, hãy nói một chút mỗi ngày."}, {"jp": "風邪を早く治したければ、無理をしないでゆっくり休むことです。", "vi": "Nếu bạn muốn nhanh chóng thoát khỏi cảm lạnh, đừng cố gắng quá sức và hãy nghỉ ngơi một chút."}, {"jp": "人の話は最後までよく聞くことだ。", "vi": "Hãy lắng nghe cẩn thận đến cuối những gì mọi người nói."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことはない', 'V-る(thể từ điển) + ことはない', 'N3', 'không cần phải làm vậy; không cần phải làm vậy', 'Trấn an hoặc khuyên nhủ rằng điều gì đó là không cần thiết. Đừng nhầm lẫn với 〜たことはない (''chưa bao giờ làm'').', '[{"jp": "簡単な手術ですから、そんなに心配することはありませんよ。", "vi": "Đây là một phẫu thuật đơn giản nên không có gì phải lo lắng."}, {"jp": "駅までは歩いて五分だから、タクシーを使うことはない。", "vi": "Cách ga năm phút đi bộ nên tôi không phải đi taxi."}, {"jp": "一回失敗したくらいで、あきらめることはないよ。", "vi": "Tôi sẽ không bỏ cuộc chỉ vì tôi đã thất bại một lần."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことにしている', 'V-る(thể từ điển) / V-ない + ことにしている', 'N3', 'biến nó thành một quy tắc; đưa ra quan điểm', 'Một quy tắc cá nhân mà người nói (hoặc chủ đề) đã quyết định và tuân theo. So sánh 〜ことになっている, một quy tắc hoặc kế hoạch do người khác đặt ra.', '[{"jp": "健康のために、週に三回はジムに通うことにしている。", "vi": "Vì sức khỏe của mình, tôi cố gắng đến phòng tập thể dục ba lần một tuần."}, {"jp": "夜十時以降は、スマホを見ないことにしています。", "vi": "Tôi cố gắng không nhìn vào điện thoại thông minh của mình sau 10 giờ tối."}, {"jp": "父は、給料日には家族を外食に連れていくことにしている。", "vi": "Cha tôi luôn đưa gia đình đi ăn vào ngày lãnh lương."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことになっている', 'V-る(thể từ điển) / V-ない + ことになっている', 'N3', 'chuyện đó đã được sắp xếp rồi; đó là quy luật; được cho là', 'Các quy tắc, phong tục hay kế hoạch do người khác (công ty, trường học, xã hội) quyết định chứ không phải là sự lựa chọn cá nhân. So sánh 〜ことにしている.', '[{"jp": "この寮では、夜十一時までに戻ることになっている。", "vi": "Ở ký túc xá này, bạn phải trở về lúc 11 giờ đêm."}, {"jp": "来月から大阪の支社で働くことになっています。", "vi": "Tôi sẽ làm việc tại văn phòng chi nhánh ở Osaka bắt đầu từ tháng tới."}, {"jp": "図書館の中では、飲み物を飲んではいけないことになっている。", "vi": "Đồ uống không được phép vào trong thư viện."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜こと（instruction）', 'V-る(thể từ điển) / V-ない + こと', 'N3', 'phải ; làm (quy tắc hoặc hướng dẫn bằng văn bản)', 'Kết thúc câu bằng こと để nêu một quy tắc. Được tìm thấy trong các thông báo, quy định và hướng dẫn giữa giáo viên với học sinh. Vô tư; không được sử dụng đối với cấp trên.', '[{"jp": "レポートは、来週の金曜日までに提出すること。", "vi": "Các báo cáo phải được nộp trước thứ Sáu tới."}, {"jp": "図書館の本に、線を引かないこと。", "vi": "Không gạch chân những cuốn sách trong thư viện."}, {"jp": "試験中は、スマホの電源を切っておくこと。", "vi": "Vui lòng tắt điện thoại thông minh của bạn trong khi thi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ように言う / 〜ように頼む', 'V-る(thể từ điển) / V-ない + ように言う / ように頼む', 'N3', 'bảo ai đó làm gì; nhờ ai làm gì (báo cáo lệnh hoặc yêu cầu)', 'Báo cáo một hướng dẫn hoặc yêu cầu một cách gián tiếp. Cũng có tác dụng với các động từ khác: 伝える, 注意する, お願いする. Phiên bản trích dẫn trực tiếp: 「〜てください」と言う.', '[{"jp": "医者に、お酒を飲みすぎないように言われた。", "vi": "Bác sĩ bảo tôi không nên uống quá nhiều rượu."}, {"jp": "隣の部屋の人に、夜は音楽の音を小さくするように頼んだ。", "vi": "Tôi nhờ người ở phòng bên cạnh tắt nhạc vào ban đêm."}, {"jp": "山下さんに、明日の会議に遅れないように伝えてください。", "vi": "Hãy nói với ông Yamashita đừng đến muộn trong cuộc họp ngày mai."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ようとする', 'V(thể ý chí) + とする', 'N3', 'cố gắng ; cố gắng ; sắp sửa', 'Thường thì một nỗ lực không thành công hoặc bị gián đoạn. 〜ようとしない = ''thậm chí sẽ không thử'' (không sẵn lòng). So sánh 〜てみる, có nghĩa là thực sự làm một việc gì đó để xem nó diễn ra như thế nào.', '[{"jp": "ドアを開けようとしたが、鍵がかかっていて開かなかった。", "vi": "Tôi cố mở cửa nhưng nó bị khóa và không mở được."}, {"jp": "家を出ようとしたとき、急に雨が降り出した。", "vi": "Khi tôi chuẩn bị ra khỏi nhà thì trời bỗng đổ mưa."}, {"jp": "弟は何度注意しても、部屋を片付けようとしない。", "vi": "Em trai tôi không chịu dọn phòng dù tôi có cảnh báo bao nhiêu lần đi chăng nữa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜そうにない / 〜そうもない', 'V-ます(bỏ ます) + そうにない / そうもない', 'N3', 'không thể ; không có vẻ như nó sẽ', 'Bề ngoài phủ định 〜そうだ với động từ, dựa trên những gì người nói quan sát được. Nhấn mạnh hơn: 〜そうにもない. Với tính từ dùng 〜なさそうだ thay thế.', '[{"jp": "この雨は、夕方までやみそうにない。", "vi": "Cơn mưa này dường như không tạnh cho đến tận tối."}, {"jp": "仕事が多すぎて、今日中には終わりそうもない。", "vi": "Tôi có quá nhiều việc nên tôi không nghĩ mình sẽ hoàn thành nó trong ngày hôm nay."}, {"jp": "こんなにたくさんの料理、二人では食べきれそうにないね。", "vi": "Nhiều đồ ăn quá, tôi không nghĩ hai chúng ta có thể ăn hết."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜一方だ', 'V-る(thể từ điển) + 一方だ', 'N3', 'Có xu hướng ngày càng...', 'Thay đổi ổn định theo một hướng, thường (không phải luôn luôn) theo chiều hướng xấu hơn. Dùng với các động từ thay đổi như 増える, 減る, 上がる, 悪くなる.', '[{"jp": "この町の人口は、減る一方だ。", "vi": "Dân số của thị trấn này đang giảm."}, {"jp": "物価は上がる一方なのに、給料は全然上がらない。", "vi": "Giá cả tăng nhưng tiền lương không tăng chút nào."}, {"jp": "勉強をさぼっていたら、成績は下がる一方だった。", "vi": "Nếu tôi bỏ học, điểm số của tôi sẽ chỉ đi xuống."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜一方で', 'V(thể thông thường) / A-い / A-な + な / N + である + 一方で', 'N3', 'trong khi ; mặt khác; cùng lúc', 'Trình bày hai mặt của một sự vật hoặc hai hoạt động song song. So sánh 〜に対して, sự tương phản giữa hai chủ đề khác nhau.', '[{"jp": "インターネットは便利な一方で、危険な面もある。", "vi": "Mặc dù Internet thuận tiện nhưng nó cũng có thể nguy hiểm."}, {"jp": "この会社は給料が高い一方で、休みがとても少ない。", "vi": "Công ty này tuy lương cao nhưng ngày nghỉ lại rất ít."}, {"jp": "彼女は会社で働く一方で、夜は大学院に通っている。", "vi": "Trong khi làm việc tại một công ty, cô ấy đi học cao học vào ban đêm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に対して', 'N + に対して / N + に対する + N / V(thể thông thường) / A-い / A-な + な + のに対して', 'N3', 'Đối với... / Trái ngược với...', 'Đánh dấu mục tiêu của một hành động, thái độ hoặc cảm giác, hoặc đối chiếu hai sự vật. So sánh 〜について, đánh dấu chủ đề đang được thảo luận hơn là mục tiêu.', '[{"jp": "お客様に対して、そんな言い方をしてはいけない。", "vi": "Đừng nói những điều như vậy với khách hàng của bạn."}, {"jp": "新しい税金に対する反対の声が高まっている。", "vi": "Sự phản đối thuế mới ngày càng tăng."}, {"jp": "東京は晴れているのに対して、大阪は朝から大雨だ。", "vi": "Trong khi ở Tokyo trời nắng thì ở Osaka lại mưa to từ sáng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜について', 'N + について / N + についての + N', 'N3', 'Về vấn đề gì đó', 'Đánh dấu chủ đề nói, suy nghĩ hoặc nghiên cứu. Trang trọng hơn: 〜に関して. So sánh 〜に対して (mục tiêu của thái độ hoặc hành động).', '[{"jp": "今日の授業では、日本の食文化について話し合いました。", "vi": "Trong lớp học hôm nay chúng ta đã thảo luận về văn hóa ẩm thực Nhật Bản."}, {"jp": "新しい商品についての質問は、こちらのメールアドレスまでお送りください。", "vi": "Nếu bạn có bất kỳ câu hỏi nào về sản phẩm mới, vui lòng gửi chúng đến địa chỉ email này."}, {"jp": "その事件について、警察はまだ何も発表していない。", "vi": "Cảnh sát vẫn chưa công bố bất cứ điều gì về vụ việc."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜によって / 〜による', 'N + によって / N + による + N', 'N3', 'bởi (đại lý); bằng cách; bởi vì; tùy thuộc vào', 'Công dụng: tác nhân của thể bị động (trang trọng, để tạo ra hoặc khám phá), nguyên nhân, phương tiện và ''thay đổi tùy theo''. 〜によっては = ''trong một số trường hợp, tùy thuộc vào''.', '[{"jp": "この橋は、有名な建築家によって設計された。", "vi": "Cây cầu này được thiết kế bởi một kiến ​​trúc sư nổi tiếng."}, {"jp": "台風による被害は、まだ正確には分かっていない。", "vi": "Hiện chưa rõ thiệt hại chính xác do cơn bão gây ra."}, {"jp": "国によって、食事のマナーはずいぶん違う。", "vi": "Nghi thức ăn uống thay đổi đáng kể tùy theo quốc gia."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜によると / 〜によれば', 'N + によると / N + によれば', 'N3', 'theo', 'Nêu tên nguồn thông tin. Câu thường kết thúc bằng cách diễn đạt tin đồn như 〜そうだ, 〜らしい hoặc 〜ということだ.', '[{"jp": "天気予報によると、週末は大雪になるそうだ。", "vi": "Theo dự báo thời tiết, cuối tuần sẽ có tuyết rơi dày đặc."}, {"jp": "ニュースによれば、事故の原因はまだ分かっていないらしい。", "vi": "Theo báo cáo tin tức, nguyên nhân của vụ tai nạn vẫn chưa được biết."}, {"jp": "姉の話によると、あのレストランは予約がないと入れないということだ。", "vi": "Theo chị tôi, bạn không thể vào nhà hàng đó nếu không đặt trước."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ばかりでなく', 'V(thể thông thường) / A-い / A-な + な / N + ばかりでなく', 'N3', 'không chỉ ... mà còn', 'Ý nghĩa tương tự như 〜だけでなく nhưng trang trọng hơn một chút. Phần thứ hai thường chứa も hoặc まで.', '[{"jp": "この映画は子どもばかりでなく、大人も楽しめる。", "vi": "Bộ phim này không chỉ trẻ em mà cả người lớn cũng có thể yêu thích."}, {"jp": "新しいスマホは画面が大きいばかりでなく、電池も長持ちする。", "vi": "Những chiếc smartphone mới không chỉ có màn hình lớn hơn mà còn có pin lâu hơn."}, {"jp": "運動は体にいいばかりでなく、ストレスを減らす効果もある。", "vi": "Tập thể dục không chỉ tốt cho cơ thể mà còn có thể làm giảm căng thẳng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜だけでなく', 'V(thể thông thường) / A-い / A-な + な / N + だけでなく', 'N3', 'không chỉ ... mà còn', 'Phổ biến trong cả lời nói và văn viết. Bình thường: 〜だけじゃなくて. Ít trang trọng hơn 〜ばかりでなく.', '[{"jp": "この店は料理がおいしいだけでなく、値段も安い。", "vi": "Đồ ăn ở nhà hàng này không chỉ ngon mà giá cả cũng rẻ."}, {"jp": "地震の後、水だけでなく電気も止まってしまった。", "vi": "Sau trận động đất, không chỉ nước mà cả điện cũng bị cắt."}, {"jp": "彼女は歌が上手なだけでなく、自分で曲も作っている。", "vi": "Cô ấy không chỉ là một ca sĩ giỏi, cô ấy còn viết những bài hát của riêng mình."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜も〜ば〜も', 'N + も + V-ば + N + も / N + も + A-い(bỏ い) + ければ + N + も', 'N3', 'cả ... và ...; không chỉ ... mà còn', 'Liệt kê hai sự kiện cùng loại để nhấn mạnh; các cặp tương phản (いいときも悪いときも) rất phổ biến. So sánh 〜し, trong đó liệt kê lý do.', '[{"jp": "彼女は歌も歌えば、ピアノも弾く。", "vi": "Cô ấy hát và cũng chơi piano."}, {"jp": "この町には、海もあれば山もある。", "vi": "Thị trấn này có cả biển và núi."}, {"jp": "人生には、いいときもあれば悪いときもある。", "vi": "Trong cuộc sống có những lúc tốt và những lúc tồi tệ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜らしい（typical of）', 'N + らしい', 'N3', 'điển hình của; phù hợp; thực sự thích', 'Có những phẩm chất mà bạn mong đợi ở danh từ. Phủ định: 〜らしくない (''không thích''). Khác với tin đồn 〜らしい (N4) và 〜っぽい (trông giống X nhưng không phải).', '[{"jp": "今日は春らしい暖かい一日だった。", "vi": "Hôm nay là một ngày xuân ấm áp."}, {"jp": "文句ばかり言うなんて、君らしくないね。", "vi": "Không phải lúc nào bạn cũng phàn nàn."}, {"jp": "もっと学生らしい服装で来てください。", "vi": "Hãy ăn mặc giống sinh viên hơn nhé."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜っぽい', 'N / V-ます(bỏ ます) / A-い(bỏ い) + っぽい', 'N3', 'Có vẻ... / Hơi có tính chất...', 'Danh từ + っぽい: trông giống X nhưng thực ra không phải (大人っぽい). Thân động từ + っぽい: có xu hướng (怒りっぽい). So sánh 〜らしい, có nghĩa là thực sự điển hình của X.', '[{"jp": "この服はちょっと子どもっぽいから、別のにしよう。", "vi": "Bộ trang phục này hơi trẻ con nên tôi sẽ chọn thứ khác."}, {"jp": "最近忘れっぽくなって、困っている。", "vi": "Gần đây tôi hay quên, điều này làm tôi khó chịu."}, {"jp": "あの白っぽいビルが、新しい市役所です。", "vi": "Tòa nhà màu trắng đó là tòa thị chính mới."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜的', 'N + 的な + N / N + 的に', 'N3', '-ic; -al; về mặt', 'Biến một danh từ (thường là chữ kanji) thành tính từ na: 的な trước danh từ, 的に trước động từ và tính từ. Nhiều từ được học tốt nhất dưới dạng từ: 具体的, 基本的, 積極的.', '[{"jp": "日本の伝統的な料理を食べてみたい。", "vi": "Tôi muốn thử ẩm thực truyền thống của Nhật Bản."}, {"jp": "この問題は、経済的な理由で解決が難しい。", "vi": "Vấn đề này khó giải quyết vì lý do kinh tế."}, {"jp": "個人的には、この案に賛成です。", "vi": "Cá nhân tôi đồng ý với ý kiến ​​này."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ような / 〜ように（like）', 'V(thể thông thường) / N + の + ような / ように', 'N3', 'thích; BẰNG; chẳng hạn như', 'ような đứng trước danh từ, ように đứng trước động từ và tính từ. AのようなB cũng có thể có nghĩa là ''B chẳng hạn như A''. Bình thường: 〜みたいな / 〜みたいに.', '[{"jp": "私も、あなたのような優しい看護師になりたいです。", "vi": "Tôi cũng muốn trở thành một y tá tốt bụng như bạn."}, {"jp": "先生が言ったように、この文法はテストによく出る。", "vi": "Như thầy đã nói, ngữ pháp này thường xuất hiện trong các bài kiểm tra."}, {"jp": "東京のような大きな都市では、家賃がとても高い。", "vi": "Ở những thành phố lớn như Tokyo, giá thuê nhà rất cao."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('まるで〜ようだ', 'まるで + V(thể thông thường) / N + の + ようだ', 'N3', 'giống như; như thể', 'まるで báo hiệu một sự so sánh mang tính biểu tượng: nó chỉ có vẻ như vậy thôi. Bình thường: まるで〜みたいだ. So sánh N2 〜かのようだ.', '[{"jp": "この部屋は広くて明るくて、まるでホテルのようだ。", "vi": "Căn phòng này rộng và sáng sủa, gần giống như một khách sạn."}, {"jp": "久しぶりに会った友達は、まるで別人のように変わっていた。", "vi": "Khi tôi gặp người bạn của mình lần đầu tiên sau một thời gian dài, anh ấy dường như như một người hoàn toàn khác."}, {"jp": "三月なのに、今日はまるで真夏のように暑い。", "vi": "Dù đang là tháng ba nhưng hôm nay trời vẫn nóng như giữa hè."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に違いない', 'V(thể thông thường) / A-い / A-な / N + に違いない', 'N3', 'phải thế; chắc chắn ; không còn nghi ngờ gì nữa', 'Niềm tin mạnh mẽ dựa trên bằng chứng hoặc trực giác; một giọng điệu hơi viết. So sánh 〜に決まっている, cái nào mang tính chủ quan và mang tính đối thoại hơn.', '[{"jp": "隣の家は何日も電気が消えている。家族で旅行に出かけたに違いない。", "vi": "Nhà bên cạnh cúp điện mấy ngày nay. Chắc hẳn gia đình đã đi du lịch."}, {"jp": "こんなに人が並んでいるんだから、この店のラーメンはおいしいに違いない。", "vi": "Ramen ở quán này chắc ngon lắm vì có rất nhiều người xếp hàng."}, {"jp": "この手紙の字は、父の字に違いない。", "vi": "Chữ viết trong lá thư này chắc chắn là chữ viết tay của bố tôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に決まっている', 'V(thể thông thường) / A-い / A-な / N + に決まっている', 'N3', 'chắc chắn; bị ràng buộc; tất nhiên', 'Một phán đoán rất tự tin, chủ quan, thường gặp trong hội thoại (〜に決まってる). Quyết đoán hơn 〜に違いない và không phù hợp với cách viết trang trọng.', '[{"jp": "練習もしないで試合に出たら、負けるに決まっている。", "vi": "Nếu bạn tham gia một trò chơi mà không luyện tập, bạn chắc chắn sẽ thua."}, {"jp": "一人で富士山に登るなんて、お母さんが心配するに決まってるでしょう。", "vi": "Tôi chắc chắn mẹ bạn sẽ lo lắng nếu bạn leo núi Phú Sĩ một mình."}, {"jp": "そんなうまい話、うそに決まっているよ。", "vi": "Đó là một câu chuyện hay, nhưng nó chắc chắn là một lời nói dối."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜気がする', 'V(thể thông thường) / A-い / A-な + な + 気がする / V(thể thông thường) / N + の + ような + 気がする', 'N3', 'có cảm giác rằng; cảm thấy như', 'Một ấn tượng trực quan, mơ hồ hơn là một phán đoán chắc chắn; ような気がする thậm chí còn nhẹ nhàng hơn. Khác với N4 〜がする (mùi, âm thanh hoặc vị).', '[{"jp": "この人とは、どこかで会ったことがある気がする。", "vi": "Tôi có cảm giác như đã gặp người này ở đâu rồi."}, {"jp": "今日は何か、いいことがありそうな気がする。", "vi": "Tôi cảm thấy hôm nay sẽ có điều gì đó tốt đẹp xảy ra."}, {"jp": "ドアの鍵をかけ忘れたような気がして、家に戻った。", "vi": "Tôi cảm thấy như quên khóa cửa nên quay vào nhà."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ずに', 'V-ない(bỏ ない) + ずに', 'N3', 'không làm', 'Trang trọng hơn, viết theo phong cách tương đương với 〜ないで. Bất quy tắc: する → せずに (không phải しずに), 来る → 来ずに (こずに).', '[{"jp": "けさは朝ご飯を食べずに家を出た。", "vi": "Kesa rời nhà mà không ăn sáng."}, {"jp": "辞書を使わずに、この新聞記事が読めますか。", "vi": "Bạn có thể đọc bài báo này mà không cần sử dụng từ điển không?"}, {"jp": "彼は誰にも相談せずに、会社を辞めてしまった。", "vi": "Anh ấy rời công ty mà không hỏi ý kiến ​​ai."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜まま', 'V-た / V-ない / A-い / A-な + な / N + の + まま', 'N3', 'như nó vốn có; không thay đổi; trong khi vẫn còn (trong trạng thái)', 'Một thay đổi dự kiến ​​đã không xảy ra và trạng thái vẫn tiếp tục. Thường gợi ý điều gì đó bất thường hoặc không mong muốn (để đèn sáng, mang giày vào trong nhà).', '[{"jp": "エアコンをつけたまま寝てしまい、風邪をひいた。", "vi": "Tôi ngủ quên khi bật điều hòa và bị cảm lạnh."}, {"jp": "この町は、私が子どもだったころのままだ。", "vi": "Thị trấn này vẫn giống như khi tôi còn nhỏ."}, {"jp": "靴のまま部屋に入らないでください。", "vi": "Vui lòng không vào phòng khi đang mang giày."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜うちに', 'V-る(thể từ điển) / V-て + いる / V-ない / A-い / A-な + な / N + の + うちに', 'N3', 'Trong lúc còn... / Tranh thủ khi...', 'Hãy làm điều gì đó khi điều kiện còn tồn tại, trước khi nó thay đổi; hoặc một sự thay đổi xảy ra mà không được chú ý trong một hoạt động. So sánh 〜間に, đánh dấu một khoảng thời gian cố định mà không có tính khẩn cấp.', '[{"jp": "若いうちに、いろいろな国を旅行したほうがいい。", "vi": "Sẽ tốt hơn nếu bạn đi du lịch đến nhiều quốc gia khác nhau khi bạn còn trẻ."}, {"jp": "スープが冷めないうちに、どうぞ召し上がってください。", "vi": "Hãy thưởng thức món súp trước khi nó nguội."}, {"jp": "音楽を聞いているうちに、いつの間にか眠ってしまった。", "vi": "Trong khi nghe nhạc, tôi ngủ thiếp đi trước khi biết điều đó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ところに / 〜ところへ / 〜ところを', 'V-る(thể từ điển) / V-て + いる / V-た + ところに / ところへ / ところを', 'N3', 'đúng lúc; vào lúc này (ai đó đến hoặc có gì đó làm gián đoạn)', 'ところに/へ: có chuyện gì đó xảy ra hoặc có người đến đúng lúc, thường làm gián đoạn. ところを: cảnh là tân ngữ của động từ như 見る, 見つかる, 助ける. Đặt cụm từ: お忙しいところを.', '[{"jp": "出かけようとしているところに、友達から電話がかかってきた。", "vi": "Ngay khi tôi chuẩn bị rời đi, tôi nhận được điện thoại từ một người bạn."}, {"jp": "みんなで君の話をしているところへ、ちょうど君が来た。", "vi": "Bạn vừa bước vào trong lúc mọi người đang bàn tán về bạn."}, {"jp": "授業中にスマホを見ているところを、先生に見られてしまった。", "vi": "Giáo viên của tôi bắt gặp tôi đang nhìn vào điện thoại thông minh của mình trong giờ học."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ば〜ほど', 'V-ば + V-る(thể từ điển) + ほど / A-い(bỏ い) + ければ + A-い + ほど / A-な + なら + A-な + な + ほど', 'N3', 'càng...càng nhiều', 'Từ đó được lặp lại, đầu tiên ở dạng ば/なら, sau đó ở dạng thông thường. Phần đầu tiên có thể bỏ đi: 考えるほど分からなくなる.', '[{"jp": "日本語は、勉強すればするほど面白くなる。", "vi": "Càng học tiếng Nhật càng thấy thú vị."}, {"jp": "スマホの画面は大きければ大きいほど見やすいが、持ち歩くのは大変だ。", "vi": "Màn hình smartphone càng lớn thì càng dễ nhìn nhưng lại khó mang theo."}, {"jp": "部屋が静かなら静かなほど、よく眠れる。", "vi": "Phòng của bạn càng yên tĩnh thì bạn sẽ càng ngủ ngon hơn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ほど', 'V(thể thông thường) / A-い / A-な + な / N + ほど', 'N3', 'đến mức đó; vậy... cái đó', 'Hiển thị mức độ với một ví dụ hoặc so sánh. Thường có thể hoán đổi với 〜くらい, nhưng ほど nghe trang trọng hơn và phù hợp với mức độ cao hơn; nó không thể đánh dấu một cái gì đó là tối thiểu.', '[{"jp": "昨日は、立っていられないほど疲れていた。", "vi": "Hôm qua tôi mệt đến mức không thể đứng nổi."}, {"jp": "試験に合格したと聞いて、涙が出るほどうれしかった。", "vi": "Khi biết tin mình đã đỗ kỳ thi, tôi vui mừng đến phát khóc."}, {"jp": "このあたりは、夜になると怖いほど静かだ。", "vi": "Khu vực này yên tĩnh đến đáng sợ vào ban đêm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜くらい / 〜ぐらい（extent）', 'V(thể thông thường) / A-い / A-な + な / N + くらい', 'N3', 'đến mức đó; để có thể; ít nhất (điều gì đó tối thiểu)', 'Giống như 〜ほど, thể hiện mức độ. くらい cũng có thể đánh dấu một việc gì đó nhỏ nhặt hoặc dễ dàng (''ít nhất; một việc đơn giản như vậy''), cách sử dụng ほど không có.', '[{"jp": "おなかが痛くて、歩けないくらいだった。", "vi": "Bụng tôi đau đến nỗi tôi không thể đi lại được."}, {"jp": "隣の部屋の音楽がうるさくて、自分の声も聞こえないぐらいだ。", "vi": "Âm nhạc ở phòng bên cạnh to đến mức tôi không thể nghe thấy giọng nói của chính mình."}, {"jp": "自分の部屋ぐらい、自分で掃除しなさい。", "vi": "Tự mình dọn dẹp phòng riêng của mình."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜さえ', 'N + さえ / N + でさえ / N + にさえ', 'N3', 'thậm chí', 'Đưa ra một ví dụ cực đoan, ngụ ý ''tất nhiên những người khác cũng vậy''. Trang trọng hơn 〜も hoặc 〜でも theo nghĩa này. Là chủ ngữ: 〜でさえ. So sánh N1 〜すら.', '[{"jp": "忙しくて、昼ご飯を食べる時間さえなかった。", "vi": "Tôi bận đến nỗi thậm chí không có thời gian để ăn trưa."}, {"jp": "こんな簡単な問題は、小学生でさえ解ける。", "vi": "Ngay cả một học sinh tiểu học cũng có thể giải được một bài toán đơn giản như vậy."}, {"jp": "彼女は親友にさえ本当のことを話さなかった。", "vi": "Cô thậm chí còn không nói sự thật với người bạn thân nhất của mình."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜さえ〜ば', 'N + さえ + V-ば / V-ます(bỏ ます) + さえ + すれば / V-て + さえ + いれば', 'N3', 'Chỉ cần... là đủ...', 'Nhấn mạnh rằng chỉ riêng điều kiện này là đủ hoặc là điều kiện duy nhất còn thiếu.', '[{"jp": "このアプリさえあれば、どこでも日本語の勉強ができる。", "vi": "Với ứng dụng này, bạn có thể học tiếng Nhật ở bất cứ đâu."}, {"jp": "時間さえあれば、もっと旅行に行きたいんですが。", "vi": "Nếu có thời gian, tôi muốn đi du lịch nhiều hơn."}, {"jp": "薬を飲んで寝てさえいれば、すぐに治りますよ。", "vi": "Chỉ cần uống thuốc và ngủ một giấc là sẽ hồi phục nhanh chóng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜こそ', 'N + こそ', 'N3', 'chính xác ; nó là... cái đó; (nhấn mạnh mạnh)', 'Chọn ra một điều là điều quan trọng nhất. こちらこそ là một câu trả lời cố định: ''cảm ơn/niềm vui là của tôi''. Các dạng N2 liên quan: 〜からこそ, 〜てこそ.', '[{"jp": "「いつもありがとう。」「いえ、こちらこそ。」", "vi": "\"Cảm ơn bạn vì tất cả mọi thứ.\" \"Không, cảm ơn.\""}, {"jp": "今年こそ、たばこをやめるつもりだ。", "vi": "Tôi đang có ý định bỏ thuốc lá trong năm nay."}, {"jp": "毎日の小さな努力こそが、大きな成功につながる。", "vi": "Những nỗ lực nhỏ hàng ngày sẽ dẫn đến thành công lớn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜として', 'N + として / N + としての + N', 'N3', 'như ; trong vai trò hoặc năng lực của', 'Nêu rõ vai trò, trạng thái hoặc danh mục. So sánh 〜にとって, thể hiện sự phán xét được đưa ra từ quan điểm của ai.', '[{"jp": "兄は、エンジニアとしてアメリカの会社で働いている。", "vi": "Anh trai tôi làm kỹ sư ở một công ty Mỹ."}, {"jp": "この町は、温泉地として有名です。", "vi": "Thị trấn này nổi tiếng với suối nước nóng."}, {"jp": "社会人としての責任を持って行動してください。", "vi": "Hãy hành động có trách nhiệm với tư cách là một thành viên của xã hội."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にとって', 'N + にとって / N + にとっての + N', 'N3', 'Đối với ai đó mà nói thì...', 'Tiếp theo là sự đánh giá (大切だ, 難しい, 便利だ). Không dùng cho hành động hay thái độ đối với ai đó; sử dụng 〜に対して cho những điều đó.', '[{"jp": "私にとって、家族は何よりも大切なものです。", "vi": "Đối với tôi, gia đình quan trọng hơn bất cứ điều gì."}, {"jp": "このあたりの坂道は、お年寄りにとってはかなり大変だ。", "vi": "Những con dốc quanh đây khá khó khăn với người già."}, {"jp": "留学は、彼にとっていい経験になったようだ。", "vi": "Có vẻ như việc đi du học là một trải nghiệm tốt đối với anh ấy."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にしては', 'V(thể thông thường) / N + にしては', 'N3', 'cho (xem xét nó); bất ngờ cho', 'Kết quả khác với những gì bạn mong đợi ở X. Không theo sau tính từ; so sánh 〜わりに, có thể và tập trung vào mức độ (giá cả, độ tuổi, nỗ lực).', '[{"jp": "初めて作ったにしては、このケーキはよくできている。", "vi": "Chiếc bánh này hóa ra rất ngon vì đây là lần đầu tiên tôi làm nó."}, {"jp": "彼は小学生にしては、ずいぶん難しい言葉を知っている。", "vi": "Anh ấy biết những từ khá khó đối với một học sinh tiểu học."}, {"jp": "十月にしては、今日はずいぶん暑いね。", "vi": "Hôm nay trời khá nóng trong tháng 10."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にしても', 'V(thể thông thường) / N + にしても', 'N3', 'ngay cả khi; thậm chí còn xem xét; cấp điều đó', 'Chấp nhận một quan điểm và nói rằng điều đó không làm thay đổi quan điểm của người nói. Thường chấp nhận một sự thật; so sánh 〜としても, nó thuần túy mang tính giả thuyết hơn.', '[{"jp": "忙しかったにしても、電話一本ぐらいできたでしょう。", "vi": "Ngay cả khi tôi bận, tôi cũng có thể gọi ít nhất một cuộc điện thoại."}, {"jp": "冗談にしても、そんな言い方はひどいよ。", "vi": "Kể cả là một trò đùa, thì đó cũng là một điều khủng khiếp để nói ra."}, {"jp": "引っ越すにしても、来年の春以降になると思います。", "vi": "Kể cả nếu tôi có chuyển đi thì tôi nghĩ cũng phải sau mùa xuân năm sau."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に関して / 〜に関する', 'N + に関して / N + に関する + N', 'N3', 'về ; liên quan đến; liên quan đến', 'Trang trọng hơn 〜について; phổ biến trong kinh doanh, tin tức và văn bản. Trước danh từ, dùng に関する (hoặc に関しての).', '[{"jp": "新しいサービスに関してご質問がある方は、受付までどうぞ。", "vi": "Nếu bạn có bất kỳ câu hỏi nào về các dịch vụ mới, vui lòng liên hệ với lễ tân."}, {"jp": "彼は日本の歴史に関する本をたくさん持っている。", "vi": "Anh ấy có nhiều sách về lịch sử Nhật Bản."}, {"jp": "事故の原因に関しては、現在調査中です。", "vi": "Nguyên nhân vụ tai nạn hiện đang được điều tra."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に比べて', 'N + に比べて / V-る(thể từ điển) + のに比べて', 'N3', 'so sánh với ; so với', 'Ngoài ra còn có 〜と比べて, 〜に比べると và 〜に比べれば. Đặt hai thứ cạnh nhau rõ ràng hơn 〜より.', '[{"jp": "今年の夏は、去年に比べてずいぶん涼しい。", "vi": "Mùa hè năm nay mát mẻ hơn nhiều so với năm ngoái."}, {"jp": "都会に比べて、田舎は家賃が安い。", "vi": "Giá thuê nhà ở nông thôn rẻ hơn ở thành phố."}, {"jp": "電車で行くのに比べて、車で行くと三十分ほど長くかかる。", "vi": "Đi bằng ô tô mất nhiều thời gian hơn khoảng 30 phút so với đi tàu."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に代わって', 'N + に代わって / N + に代わり', 'N3', 'thay vì ; thay mặt cho; thay thế', 'Ai đó hành động vì người khác, hoặc một cái gì đó mới thay thế một cái gì đó cũ. Dạng viết: 〜に代わり. So sánh 〜代わりに (thay vì làm; đổi lấy).', '[{"jp": "入院中の社長に代わって、副社長があいさつをした。", "vi": "Phó chủ tịch thay mặt tổng thống gửi lời chào khi nhập viện."}, {"jp": "最近は、紙の新聞に代わって、スマホでニュースを読む人が増えている。", "vi": "Gần đây, ngày càng có nhiều người đọc tin tức trên điện thoại thông minh thay vì đọc báo giấy."}, {"jp": "父に代わって、私が町内会の会議に出席しました。", "vi": "Tôi đã thay mặt bố tôi tham dự cuộc họp hội khu phố."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜代わりに', 'V(thể thông thường) / A-い / A-な + な / N + の + 代わりに', 'N3', 'thay vì ; để đổi lấy; để bù đắp cho', 'Ba cách sử dụng: thay thế (thay vì), trao đổi (đổi lại) và bù đắp (một nhược điểm được cân bằng bởi một nhược điểm).', '[{"jp": "今日は外で食べる代わりに、家でカレーを作った。", "vi": "Hôm nay thay vì đi ăn ngoài, tôi lại nấu cà ri ở nhà."}, {"jp": "友達に英語を教える代わりに、ギターを教えてもらっている。", "vi": "Thay vì dạy tiếng Anh cho bạn bè, tôi nhờ họ dạy tôi chơi ghi-ta."}, {"jp": "このアパートは駅から遠い代わりに、家賃が安い。", "vi": "Căn hộ này tuy cách xa nhà ga nhưng giá thuê lại rẻ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に従って', 'N + に従って / V-る(thể từ điển) + に従って', 'N3', 'phù hợp với; tiếp theo; như ... (vì vậy ...)', 'Với những danh từ như quy tắc hay chỉ dẫn: ''theo sau, tuân theo''. Với V-る(thể từ điển): thay đổi tỷ lệ như 〜につれて, với giọng trang trọng hơn.', '[{"jp": "係の人の指示に従って、落ち着いて避難してください。", "vi": "Hãy làm theo hướng dẫn của người phụ trách và sơ tán một cách bình tĩnh."}, {"jp": "高く登るに従って、気温が下がっていった。", "vi": "Khi chúng tôi leo lên cao hơn, nhiệt độ giảm xuống."}, {"jp": "町が大きくなるに従って、交通の問題も増えてきた。", "vi": "Khi thị trấn ngày càng lớn hơn, các vấn đề về giao thông cũng tăng lên."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜につれて', 'V-る(thể từ điển) / N + につれて', 'N3', 'như (một điều thay đổi, một điều khác cũng thay đổi)', 'Cả hai nửa đều mô tả sự thay đổi dần dần. Mệnh đề chính không thể là một yêu cầu hoặc ý định của người nói. Gần với 〜に従って và 〜とともに.', '[{"jp": "年をとるにつれて、朝早く目が覚めるようになった。", "vi": "Khi tôi lớn hơn, tôi bắt đầu thức dậy sớm hơn vào buổi sáng."}, {"jp": "日本での生活に慣れるにつれて、友達も増えていった。", "vi": "Khi đã quen với cuộc sống ở Nhật Bản, tôi bắt đầu kết bạn nhiều hơn."}, {"jp": "時間がたつにつれて、その事故のことは忘れられていった。", "vi": "Thời gian trôi qua, vụ tai nạn cũng bị lãng quên."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とともに', 'N + とともに / V-る(thể từ điển) + とともに', 'N3', 'cùng với ; cùng với ; BẰNG; cùng lúc với', 'Phiên bản chính thức của 〜と一緒に. Đồng thời đánh dấu các sự kiện xảy ra cùng lúc hoặc thay đổi tỷ lệ như 〜につれて.', '[{"jp": "社長は、社員とともに新しい工場の完成を喜んだ。", "vi": "Chủ tịch cùng với các nhân viên của mình rất vui mừng với việc hoàn thành nhà máy mới."}, {"jp": "経済の発展とともに、人々の生活も大きく変わった。", "vi": "Cùng với sự phát triển kinh tế, đời sống người dân cũng có sự thay đổi đáng kể."}, {"jp": "ベルが鳴るとともに、学生たちは教室を飛び出した。", "vi": "Chuông vừa reo, học sinh đã chạy ra khỏi lớp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たびに', 'V-る(thể từ điển) / N + の + たびに', 'N3', 'Mỗi lần... lại...', 'Mỗi lần A xảy ra thì B cũng xảy ra. Nhấn mạnh hơn 〜と hoặc 〜ときはいつも.', '[{"jp": "この写真を見るたびに、大学時代を思い出す。", "vi": "Mỗi lần nhìn bức ảnh này, tôi lại nhớ về thời đại học của mình."}, {"jp": "姉は出張のたびに、お土産を買ってきてくれる。", "vi": "Chị tôi mua quà lưu niệm cho tôi mỗi khi tôi đi công tác."}, {"jp": "この川は、大雨が降るたびにあふれて、道が通れなくなる。", "vi": "Mỗi khi có mưa lớn, dòng sông này tràn bờ và không thể đi qua được."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ごとに', 'N + ごとに / V-る(thể từ điển) + ごとに', 'N3', 'mỗi; mỗi; trong khoảng thời gian', 'Lặp lại đều đặn hoặc lần lượt từng đơn vị. Với V-る(thể từ điển) nó gần với 〜たびに. Cẩn thận: 一日ごとに = hàng ngày, nhưng 一日おきに (N4) = cách ngày.', '[{"jp": "このバスは十五分ごとに出ています。", "vi": "Xe buýt này khởi hành cứ sau mười lăm phút."}, {"jp": "季節ごとに、店の飾りが変わる。", "vi": "Trang trí của cửa hàng thay đổi tùy theo mùa."}, {"jp": "一回使うごとにポイントがたまるカードです。", "vi": "Thẻ này giúp bạn kiếm được điểm mỗi khi bạn sử dụng nó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜最中に', 'V-て + いる / N + の + 最中に', 'N3', 'Đúng lúc đang... thì...', 'Nhấn mạnh mức độ cao của một hoạt động, thường là khi có điều gì đó bất ngờ làm gián đoạn hoạt động đó. Mạnh hơn 〜中に hoặc 〜ている間に. Ngoài ra 〜最中だ.', '[{"jp": "大事な会議の最中に、携帯電話が鳴ってしまった。", "vi": "Giữa một cuộc họp quan trọng, điện thoại di động của tôi reo lên."}, {"jp": "料理をしている最中に、停電になった。", "vi": "Đang nấu ăn thì mất điện."}, {"jp": "今、試験の最中だから、廊下では静かにしてください。", "vi": "Chúng ta hiện đang ở giữa kỳ thi, vì vậy xin hãy im lặng ở hành lang."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ついでに', 'V-る(thể từ điển) / V-た / N + の + ついでに', 'N3', 'Tiện thể, nhân tiện làm gì', 'Hành động chính vẫn xảy ra; cái thứ hai được thêm vào vì nó thuận tiện. So sánh N1 〜がてら.', '[{"jp": "郵便局へ行くついでに、この手紙も出してきてくれる？", "vi": "Bạn có thể vui lòng gửi cho tôi lá thư này trong khi bạn đến bưu điện được không?"}, {"jp": "京都へ出張したついでに、昔の友達に会ってきた。", "vi": "Khi đang đi công tác ở Kyoto, tôi gặp lại một người bạn cũ."}, {"jp": "買い物のついでに、図書館に本を返した。", "vi": "Trong khi đi mua sắm, tôi đã trả cuốn sách cho thư viện."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜おかげで', 'V(thể thông thường) / A-い / A-な + な / N + の + おかげで', 'N3', 'Nhờ có... (Kết quả tốt đẹp)', 'Nguyên nhân của một kết quả tốt đẹp, với một cảm giác biết ơn. Đôi khi được sử dụng một cách mỉa mai khi mang lại kết quả xấu (君のおかげで遅刻したよ). So sánh 〜せいで (đổ lỗi).', '[{"jp": "先輩が手伝ってくれたおかげで、仕事が早く終わった。", "vi": "Nhờ sự giúp đỡ của tiền bối nên tôi đã có thể hoàn thành công việc của mình một cách nhanh chóng."}, {"jp": "薬が効いたおかげで、熱が下がった。", "vi": "Nhờ có thuốc mà cơn sốt của tôi đã giảm."}, {"jp": "駅が近いおかげで、雨の日も楽に通勤できる。", "vi": "Gần ga nên việc đi lại dễ dàng ngay cả trong những ngày mưa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜せいで', 'V(thể thông thường) / A-い / A-な + な / N + の + せいで', 'N3', 'Tại vì... / Do... (Kết quả xấu, đổ lỗi)', 'Nguyên nhân dẫn đến kết quả xấu, đổ lỗi. 〜のせいにする = ''đổ lỗi cho điều gì đó''. Cảm giác trái ngược với 〜おかげで.', '[{"jp": "電車が遅れたせいで、面接に遅刻してしまった。", "vi": "Tôi đến trễ buổi phỏng vấn vì tàu bị trễ."}, {"jp": "夜中に犬がうるさかったせいで、ほとんど眠れなかった。", "vi": "Tôi hầu như không thể ngủ được vì con chó gây ra quá nhiều tiếng ồn trong đêm."}, {"jp": "私が道を間違えたせいで、みんなを待たせてしまった。", "vi": "Tôi rẽ nhầm và bắt mọi người phải chờ đợi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たとたん / 〜たとたんに', 'V-た + とたん / とたんに', 'N3', 'khoảnh khắc; giống như (điều gì đó bất ngờ xảy ra)', 'Sự kiện thứ hai xảy ra đột ngột và nằm ngoài tầm kiểm soát của người nói. Không được sử dụng cho các hành động, yêu cầu hoặc ý định đã được lên kế hoạch của chính người nói.', '[{"jp": "立ち上がったとたんに、めまいがした。", "vi": "Vừa đứng dậy tôi đã cảm thấy choáng váng."}, {"jp": "家を出たとたん、雨が降り出した。", "vi": "Vừa ra khỏi nhà thì trời bắt đầu mưa."}, {"jp": "その歌手がステージに現れたとたん、会場から大きな拍手が起こった。", "vi": "Ngay khi ca sĩ xuất hiện trên sân khấu, đã có một tràng pháo tay lớn từ khán phòng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たら〜た', 'V-た + ら ... V-た', 'N3', 'khi tôi làm A, (tôi đã tìm thấy) B; khi làm, tôi phát hiện ra', 'Sau một hành động, người nói nhận thấy hoặc phát hiện ra điều gì đó. Mệnh đề thứ hai là quá khứ và nằm ngoài tầm kiểm soát của người nói. 〜と〜た là từ viết tương đương hơn.', '[{"jp": "窓を開けたら、外は一面の雪だった。", "vi": "Khi tôi mở cửa sổ, bên ngoài đã có một lớp tuyết dày đặc."}, {"jp": "久しぶりに実家に帰ったら、近所に大きなマンションが建っていた。", "vi": "Khi tôi trở về nhà lần đầu tiên sau một thời gian dài, một tòa nhà chung cư lớn đã được xây dựng ở khu vực tôi ở."}, {"jp": "かばんの中を探してみたら、なくしたと思っていた鍵が出てきた。", "vi": "Khi lục túi, tôi tìm thấy chiếc chìa khóa mà tôi tưởng đã đánh mất."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たって / 〜だって', 'V-た + って / A-い-ku + たって / A-な / N + だって', 'N3', 'ngay cả khi; không sao cả (thông thường)', 'Dạng thông tục của 〜ても / 〜でも, thường đi kèm với いくら hoặc từ để hỏi. だって cũng có nghĩa là ''vì'' ở đầu câu và ''thậm chí'' sau danh từ.', '[{"jp": "今から急いだって、もう間に合わないよ。", "vi": "Cho dù bây giờ bạn có vội vàng, bạn cũng sẽ không đến kịp."}, {"jp": "高くたって、欲しいものは欲しい。", "vi": "Tôi muốn những gì tôi muốn, ngay cả khi nó đắt tiền."}, {"jp": "いくら便利だって、使い方が分からなければ意味がない。", "vi": "Dù tiện lợi đến đâu thì cũng sẽ vô nghĩa nếu bạn không biết cách sử dụng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ないことはない', 'V-ない / A-い-ku + ない / A-な + でない + ことはない', 'N3', 'không phải thế... không phải; có thể nếu cần thiết; không phải là không thể', 'Một sự phủ định kép đưa ra một tiếng ''có'' do dự. Ngoài ra 〜ないこともない. Đừng nhầm lẫn với Động từ-dict + ことはない (''không cần đâu'').', '[{"jp": "辛い料理は食べられないことはないけど、あまり好きじゃない。", "vi": "Không phải là tôi không ăn được cay mà là tôi không thích lắm."}, {"jp": "今から急げば、間に合わないことはないと思う。", "vi": "Tôi không nghĩ bạn sẽ bỏ lỡ nó nếu bạn nhanh lên bây giờ."}, {"jp": "この服、少し派手だけど、似合わないことはないよ。", "vi": "Bộ trang phục này hơi lòe loẹt nhưng tôi thấy nó không đẹp chút nào."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てしょうがない / 〜てしかたがない', 'V-て / A-い-ku + て / A-な + で + しょうがない / しかたがない', 'N3', 'vô cùng; không thể giúp được (cảm giác); không thể chịu nổi', 'Đối với những cảm giác và cảm giác mà người nói không thể kiểm soát được. しょうがない thì bình thường hơn. Không giống như 〜てたまらない, nó cũng có tác dụng với các động từ tự phát như 気になる hoặc 涙が出る.', '[{"jp": "昨日あまり寝ていないので、眠くてしょうがない。", "vi": "Đêm qua tôi không ngủ được nhiều nên không thể không cảm thấy buồn ngủ."}, {"jp": "来週の旅行が楽しみでしかたがない。", "vi": "Tôi không thể không mong đợi chuyến đi vào tuần tới."}, {"jp": "一人暮らしを始めたばかりのころは、家族のことが気になってしかたがなかった。", "vi": "Khi mới bắt đầu sống một mình, tôi không thể không lo lắng cho gia đình mình."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てたまらない', 'V-て / A-い-ku + て / A-な + で + たまらない', 'N3', 'không thể chịu nổi ; sắp chết ; vô cùng (cảm giác)', 'Cảm giác mạnh mẽ, trực tiếp hoặc cảm giác cơ thể; rất phổ biến với ham muốn (〜たくてたまらない). Không được sử dụng cho sự thật khách quan. So sánh 〜てしかたがない.', '[{"jp": "この部屋はエアコンがなくて、暑くてたまらない。", "vi": "Căn phòng này không có máy điều hòa và nóng không chịu nổi."}, {"jp": "三年ぶりに国の家族に会えるので、うれしくてたまらない。", "vi": "Tôi rất hạnh phúc vì có thể gặp gia đình mình ở đất nước mình lần đầu tiên sau ba năm."}, {"jp": "試合に負けたのが悔しくてたまらなかった。", "vi": "Tôi rất thất vọng vì chúng tôi đã thua trận đấu."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てはじめて', 'V-て + はじめて', 'N3', 'chỉ sau đó; không cho đến khi', 'Điều gì đó chỉ được nhận ra hoặc trở thành khả thi sau một trải nghiệm; thường theo sau là 分かる, 気づく hoặc 知る. Cũng được viết là 〜て初めて.', '[{"jp": "病気になってはじめて、健康のありがたさが分かった。", "vi": "Phải đến khi bị bệnh tôi mới nhận ra giá trị của sức khỏe tốt."}, {"jp": "一人で暮らしてはじめて、親の苦労が分かった。", "vi": "Phải đến khi sống một mình, tôi mới hiểu được những khó khăn mà bố mẹ tôi đã phải trải qua."}, {"jp": "実際に使ってみてはじめて、この機械の便利さに気づいた。", "vi": "Phải đến khi thực sự sử dụng tôi mới nhận ra chiếc máy này tiện lợi đến nhường nào."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てばかりいる', 'V-て + ばかりいる', 'N3', 'không làm gì khác ngoài; tiếp tục làm (quan trọng)', 'Một hành động lặp đi lặp lại hoặc liên tục, thường kèm theo sự chỉ trích hoặc không hài lòng. So sánh Danh từ N4 + ばかり (甘い物ばかり食べる).', '[{"jp": "弟は休みの日、ゲームをしてばかりいる。", "vi": "Em trai tôi suốt ngày nghỉ chơi game."}, {"jp": "泣いてばかりいないで、どうしたのか話してごらん。", "vi": "Đừng chỉ khóc, hãy kể cho tôi nghe chuyện gì đã xảy ra."}, {"jp": "休みの間、寝てばかりいたら、かえって疲れてしまった。", "vi": "Tôi đã ngủ suốt trong kỳ nghỉ nhưng cuối cùng lại cảm thấy mệt mỏi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ばいい', 'V-ば + いい / A-い(bỏ い) + ければ + いい', 'N3', 'nên ; tất cả những gì bạn cần làm là; Tôi hy vọng (với のに/けど: Tôi ước gì)', 'Yêu cầu hoặc đưa ra lời khuyên (〜ばいいですか = ''tôi nên làm gì?''). 〜ばいいのに = ''Tôi ước gì''. 〜たらいい là từ gần đồng nghĩa; 〜ほうがいい nghe có vẻ kiên quyết hơn.', '[{"jp": "「この書類、どこに出せばいいですか。」「二階の受付に出してください。」", "vi": "\"Tôi nên nộp tài liệu này ở đâu?\" \"Xin vui lòng nộp cho quầy tiếp tân ở tầng hai.\""}, {"jp": "分からないことがあったら、遠慮しないで私に聞けばいいよ。", "vi": "Nếu có gì không hiểu, đừng ngần ngại hỏi tôi."}, {"jp": "明日、雨が降らなければいいんだけど。", "vi": "Tôi hy vọng ngày mai trời không mưa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜場合（は）', 'V(thể thông thường) / A-い / A-な + な / N + の + 場合（は）', 'N3', 'trong trường hợp; nếu như; trong trường hợp đó', 'Điển hình của các hướng dẫn, quy tắc và thông báo về các tình huống có thể xảy ra. Không giống như 〜たら, nó không được sử dụng để kể lại một sự kiện xảy ra một lần trong quá khứ.', '[{"jp": "雨の場合は、試合は中止になります。", "vi": "Trong trường hợp trời mưa, trận đấu sẽ bị hủy."}, {"jp": "カードをなくした場合は、すぐに銀行に連絡してください。", "vi": "Nếu bạn bị mất thẻ, hãy liên hệ ngay với ngân hàng của bạn."}, {"jp": "予約の時間に遅れる場合は、お電話でお知らせください。", "vi": "Nếu bạn đến trễ cuộc hẹn, vui lòng thông báo cho chúng tôi qua điện thoại."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とすれば / 〜としたら', 'V(thể thông thường) / A-い / A-な + だ / N + だ + とすれば / としたら', 'N3', 'nếu; giả sử điều đó ; giả sử', 'Đặt ra một giả thuyết và xem xét những gì tiếp theo. Thường dùng với もし hoặc 仮に. としたら mang tính đàm thoại nhiều hơn; とすれば nghe giống lý luận logic hơn.', '[{"jp": "もし宝くじで一億円当たったとしたら、何に使いますか。", "vi": "Nếu bạn trúng xổ số 100 triệu yên, bạn sẽ tiêu số tiền đó vào việc gì?"}, {"jp": "今から出発するとすれば、向こうに着くのは夜の九時ごろになる。", "vi": "Nếu chúng tôi rời đi bây giờ, chúng tôi sẽ đến đó vào khoảng chín giờ tối."}, {"jp": "彼の話が本当だとしたら、大変なことになる。", "vi": "Nếu câu chuyện của anh ấy là sự thật thì đó sẽ là một vấn đề lớn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜としても', 'V(thể thông thường) / A-い / A-な + だ / N + だ + としても', 'N3', 'ngay cả khi; thậm chí giả sử', 'Nhượng bộ giả định: ngay cả khi giả sử A, B vẫn đúng. Nhiều giả thuyết hơn 〜ても; so sánh 〜にしても, thường chấp nhận một sự thật.', '[{"jp": "親に反対されたとしても、私は留学するつもりだ。", "vi": "Dù bố mẹ có phản đối thì tôi vẫn có ý định đi du học."}, {"jp": "今からタクシーに乗ったとしても、九時の飛行機には間に合わないだろう。", "vi": "Kể cả bây giờ có bắt taxi đi chăng nữa, tôi cũng không thể kịp chuyến bay lúc chín giờ."}, {"jp": "それが本当だとしても、ほかの人に話すべきではない。", "vi": "Cho dù đó là sự thật thì bạn cũng không nên nói cho người khác biết."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とか（hearsay）', 'Mệnh đề + とか', 'N3', 'Tôi nghe thấy điều gì đó như; rõ ràng', 'Tin đồn mơ hồ; nhẹ nhàng hơn và ít chắc chắn hơn 〜そうだ. Thường là 〜とかいう話だ, 〜とか聞いた, hoặc 〜とかで (đưa ra lý do được báo cáo). Khác với việc liệt kê 〜とか〜とか.', '[{"jp": "駅前の本屋、今月で閉店するとか。寂しくなりますね。", "vi": "Hiệu sách trước nhà ga sẽ đóng cửa trong tháng này. Tôi sẽ nhớ bạn."}, {"jp": "今年の冬は、例年より寒くなるとかいう話だよ。", "vi": "Mùa đông năm nay được cho là lạnh hơn thường lệ."}, {"jp": "部長は今日、熱があるとかで休んでいます。", "vi": "Hôm nay người quản lý xin nghỉ vì bị sốt."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜って', 'Mệnh đề + って / N + って', 'N3', '(trích dẫn thông thường) nói rằng; Tôi đã nghe; như ; cái gì là', 'Thay thế ngẫu nhiên cho と (trích dẫn), そうだ (tin đồn, thường là 〜んだって) và は (chủ đề, đặc biệt là ''X là gì?''). Phổ biến trong lời nói; tránh trong văn bản chính thức.', '[{"jp": "彼女、今日は来られないって。", "vi": "Hôm nay cô ấy không thể đến được."}, {"jp": "駅前に新しいカフェができたんだって。行ってみない？", "vi": "Một quán cà phê mới đã mở trước nhà ga. Bạn có muốn đi không?"}, {"jp": "「ふろしき」って何ですか。", "vi": "\"furoshiki\" là gì?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ということだ', 'Mệnh đề + ということだ', 'N3', 'Tôi đã nghe điều đó; nó có nghĩa là; nói cách khác', 'Hai cách sử dụng: báo cáo thông tin (trang trọng hơn 〜そうだ) và đưa ra kết luận (''vậy điều đó có nghĩa là ...''). Việc sử dụng kết thúc thường kết thúc bằng ということですね.', '[{"jp": "駅員さんの話では、事故のため電車は一時間ほど止まるということです。", "vi": "Theo nhân viên nhà ga, tàu sẽ phải dừng khoảng 1 giờ do tai nạn."}, {"jp": "「申し込みは明日までです。」「じゃあ、今日中に書類を準備しなければならないということですね。」", "vi": "``Hạn nộp đơn là ngày mai.'''' ``Vậy, điều đó có nghĩa là chúng ta phải chuẩn bị tài liệu ngay hôm nay.''''"}, {"jp": "全員が賛成したということは、この計画で進めてもいいということだ。", "vi": "Việc mọi người đều đồng ý có nghĩa là chúng ta có thể tiến hành kế hoạch này."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜というのは', 'N / Mệnh đề + というのは', 'N3', 'ý nghĩa của ... là; ... có nghĩa; lý do là', 'Giới thiệu một từ để định nghĩa hoặc một tình huống để nhận xét. Bình thường: 〜って. Khi bắt đầu câu, というのは giới thiệu lý do kết thúc bằng 〜からだ. Được viết: 〜とは.', '[{"jp": "「割り勘」というのは、食事代などをみんなで同じ金額ずつ払うことです。", "vi": "``Chia hóa đơn'''' có nghĩa là mọi người đều trả số tiền như nhau cho các bữa ăn, v.v."}, {"jp": "一人で海外に住むというのは、思ったより大変なことだ。", "vi": "Sống một mình ở nước ngoài khó khăn hơn tôi tưởng."}, {"jp": "来週の旅行には行けなくなった。というのは、急に出張が入ったからだ。", "vi": "Tôi sẽ không thể đi du lịch vào tuần tới. Đó là bởi vì tôi đột nhiên phải đi công tác."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜というより', 'V(thể thông thường) / A-い / A-な / N + というより', 'N3', 'chứ không phải ; không nhiều A như B', 'Sửa hoặc tinh chỉnh mô tả: mô tả thứ hai phù hợp hơn. Thường theo sau là むしろ.', '[{"jp": "今日は涼しいというより、寒いくらいだ。", "vi": "Hôm nay trời có vẻ lạnh hơn là mát."}, {"jp": "彼女は友達というより、家族のような存在だ。", "vi": "Cô ấy giống gia đình hơn là một người bạn."}, {"jp": "それは意見というより、ただの文句だよ。", "vi": "Đó là một lời phàn nàn hơn là một ý kiến."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜わりに / 〜わりには', 'V(thể thông thường) / A-い / A-な + な / N + の + わりに', 'N3', 'xem xét; vì (bất ngờ)', 'Kết quả không khớp với mức độ bạn mong đợi từ A (giá, tuổi, nỗ lực). Có thể theo sau tính từ, không giống như 〜にしては.', '[{"jp": "この店は値段のわりに、量が多くておいしい。", "vi": "Nhà hàng này có một lượng lớn đồ ăn với mức giá của nó và rất ngon."}, {"jp": "兄はよく食べるわりには、全然太らない。", "vi": "Mặc dù anh trai tôi ăn rất nhiều nhưng anh ấy không bao giờ tăng cân."}, {"jp": "このホテルは駅から近いわりに、静かでよく眠れた。", "vi": "Mặc dù khách sạn này gần ga nhưng lại yên tĩnh và tôi ngủ rất ngon."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜くせに', 'V(thể thông thường) / A-い / A-な + な / N + の + くせに', 'N3', 'mặc dù ; bất chấp (chỉ trích, khiển trách)', 'Giống như 〜のに, nhưng với sự khinh miệt hoặc trách móc đối với chủ ngữ. Cả hai mệnh đề đều có cùng một chủ đề; hiếm khi được sử dụng về bản thân. Bình thường.', '[{"jp": "自分では何もしないくせに、人の仕事には文句ばかり言う。", "vi": "Mặc dù bản thân anh ấy không làm gì cả nhưng anh ấy luôn phàn nàn về việc làm của người khác."}, {"jp": "知っているくせに、どうして教えてくれなかったの？", "vi": "Nếu biết sao cậu không nói cho tôi biết?"}, {"jp": "弟は体が大きいくせに、小さな虫をこわがる。", "vi": "Em trai tôi tuy lớn nhưng lại sợ côn trùng nhỏ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜から〜にかけて', 'N + から + N + にかけて', 'N3', 'từ... qua; trên (một khoảng thời gian hoặc khu vực)', 'Một khoảng thời gian hoặc không gian gồ ghề có các cạnh không chính xác; phổ biến trong các bản tin thời tiết. So sánh 〜から〜まで, đánh dấu điểm bắt đầu và điểm kết thúc rõ ràng.', '[{"jp": "今夜から明日の朝にかけて、強い雨が降るでしょう。", "vi": "Dự kiến ​​đêm nay đến sáng mai sẽ có mưa lớn."}, {"jp": "関東から東北にかけての広い地域で、強い揺れが観測された。", "vi": "Rung lắc mạnh được quan sát thấy trên một khu vực rộng lớn từ Kanto đến Tohoku."}, {"jp": "この花は、三月から四月にかけてきれいに咲く。", "vi": "Loài hoa này nở đẹp từ tháng 3 đến tháng 4."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ぶり', 'N + ぶり / V-ます(bỏ ます) + ぶり', 'N3', 'lần đầu tiên trong (một khoảng thời gian); cách thức, cách làm', 'Khoảng thời gian + ぶり: lần đầu tiên trong thời gian dài như vậy (〜ぶりに / 〜ぶりの). Danh từ hoặc Thân động từ + ぶり: cách ai đó làm việc gì đó (仕事ぶり, 話しぶり).', '[{"jp": "五年ぶりに高校の友達に会って、話が止まらなかった。", "vi": "Tôi gặp lại những người bạn cấp ba của mình lần đầu tiên sau 5 năm và không thể ngừng nói chuyện."}, {"jp": "久しぶりですね。お元気でしたか。", "vi": "Đã được một thời gian rồi. Bạn thế nào rồi?"}, {"jp": "新入社員の仕事ぶりを見て、部長は安心したようだ。", "vi": "Người quản lý có vẻ nhẹ nhõm sau khi thấy hiệu suất làm việc của nhân viên mới."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜っけ', 'V-た / N + だ / N + だった + っけ', 'N3', 'phải không?; tôi phải không?; (cố nhớ lại)', 'Kiểm tra điều gì đó bạn đã quên hoặc nhớ lại quá khứ một cách trìu mến (〜たっけ). Hình thức lịch sự: 〜でしたっけ, 〜ましたっけ.', '[{"jp": "あれ、会議って何時からだっけ？", "vi": "Này, cuộc họp bắt đầu lúc mấy giờ?"}, {"jp": "すみません、お名前、何とおっしゃいましたっけ。", "vi": "Xin lỗi, tên bạn là gì?"}, {"jp": "子どものころ、よくこの公園で遊んだっけ。", "vi": "Khi tôi còn nhỏ, tôi thường chơi ở công viên này."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ますように', 'V-ます(bỏ ます) + ますように / V-ます(bỏ ます) + ませんように', 'N3', 'tôi hy vọng; tháng năm (mong muốn, cầu nguyện)', 'Được sử dụng cho những lời chúc và lời cầu nguyện, ví dụ: tại một ngôi đền hoặc trên dải tanabata, và ở cuối bức thư chúc ai đó mọi điều tốt lành.', '[{"jp": "試験に合格できますように。", "vi": "Tôi hy vọng bạn có thể vượt qua kỳ thi."}, {"jp": "明日の遠足、雨が降りませんように。", "vi": "Tôi hy vọng trời không mưa trong chuyến du ngoạn ngày mai."}, {"jp": "家族みんなが元気で過ごせますように。", "vi": "Tôi hy vọng mọi người trong gia đình bạn luôn khỏe mạnh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ふりをする', 'V(thể thông thường) / A-い / A-な + な / N + の + ふりをする', 'N3', 'giả vờ ; hành động như thể', 'Cố tình tạo ấn tượng sai. Động từ-ta phổ biến: 寝たふり, 死んだふり.', '[{"jp": "母に呼ばれたが、聞こえないふりをしてゲームを続けた。", "vi": "Mẹ gọi điện cho tôi nhưng tôi giả vờ như không nghe thấy và tiếp tục chơi game."}, {"jp": "彼は本当は知っているのに、知らないふりをしている。", "vi": "Anh giả vờ như không biết mặc dù anh thực sự biết."}, {"jp": "電車の中で、寝たふりをして席を譲らない人がいる。", "vi": "Trên tàu có những người giả vờ ngủ không chịu nhường ghế."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜向き / 〜向け', 'N + 向き / N + 向け', 'N3', 'phù hợp với/nhắm tới; dành cho', '向き: rất hợp với X. 向け: được làm nhằm mục đích dành cho X. 向き cũng có nghĩa là ''đối diện'' (南向きの部屋).', '[{"jp": "この料理は作り方が簡単なので、初心者向きだ。", "vi": "Món ăn này rất dễ làm nên thích hợp cho người mới bắt đầu."}, {"jp": "この雑誌は、若い女性向けに作られている。", "vi": "Tạp chí này được thực hiện cho phụ nữ trẻ."}, {"jp": "子ども向けの番組だが、大人が見ても十分楽しめる。", "vi": "Mặc dù chương trình hướng đến trẻ em nhưng người lớn cũng có thể thưởng thức."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜がち', 'V-ます(bỏ ます) / N + がち', 'N3', 'Thường hay, dễ bị... (Thói quen xấu)', 'Có xu hướng thường xuyên hướng tới điều gì đó không mong muốn. So sánh 〜やすい (dễ xảy ra, có thể bình thường) và 〜気味 (dấu hiệu nhẹ của tình trạng hiện tại).', '[{"jp": "冬になると、つい家にこもりがちになる。", "vi": "Khi mùa đông đến, chúng ta có xu hướng ở nhà."}, {"jp": "娘は小さいころ病気がちだったが、今はとても元気だ。", "vi": "Con gái tôi khi còn nhỏ thường hay ốm đau nhưng hiện tại cháu đã khỏe lại rất nhiều."}, {"jp": "一人暮らしだと、野菜が不足しがちです。", "vi": "Nếu bạn sống một mình, bạn có xu hướng hết rau."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜気味', 'N / V-ます(bỏ ます) + 気味', 'N3', 'Hơi có cảm giác... / Có triệu chứng...', 'Một dấu hiệu nhẹ của tình trạng (thường là tiêu cực) hiện tại. So sánh 〜がち, có nghĩa là việc gì đó xảy ra thường xuyên.', '[{"jp": "少し風邪気味なので、今日は早めに帰ります。", "vi": "Hôm nay tôi cảm thấy hơi lạnh nên sẽ về nhà sớm."}, {"jp": "最近、仕事が忙しくて疲れ気味だ。", "vi": "Gần đây tôi bận rộn với công việc và tôi cảm thấy mệt mỏi."}, {"jp": "人手が足りず、工事は予定より遅れ気味だ。", "vi": "Do thiếu nhân lực nên việc thi công chậm tiến độ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜だらけ', 'N + だらけ', 'N3', 'đầy ; được bao phủ bởi; đánh đố với', 'Một lượng lớn thứ gì đó che phủ hoặc lấp đầy một nơi; thường tiêu cực. So sánh N1 〜まみれ (được bao phủ bởi thứ gì đó dính hoặc bẩn).', '[{"jp": "子どもたちは、泥だらけになって帰ってきた。", "vi": "Bọn trẻ trở về nhà với thân hình đầy bùn."}, {"jp": "急いで書いたレポートは、間違いだらけだった。", "vi": "Bản báo cáo viết vội vàng và đầy sai sót."}, {"jp": "引っ越したばかりで、部屋はまだ段ボールだらけだ。", "vi": "Tôi mới chuyển đến và phòng tôi vẫn còn đầy bìa cứng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜切る / 〜切れない', 'V-ます(bỏ ます) + 切る / V-ます(bỏ ます) + 切れない', 'N3', 'làm hoàn toàn; kết thúc/không thể kết thúc; quá nhiều để', 'Làm một việc gì đó cho đến tận cùng. Cũng mô tả một trạng thái hoàn toàn: 疲れ切る (''hoàn toàn kiệt sức''). Thường được viết bằng kana: 〜きる / 〜きれない.', '[{"jp": "三時間かけて、長い小説を最後まで読み切った。", "vi": "Tôi phải mất ba giờ để đọc xong một cuốn tiểu thuyết dài."}, {"jp": "注文しすぎて、料理を食べ切れなかった。", "vi": "Tôi gọi quá nhiều và không thể ăn hết."}, {"jp": "山の上では、数え切れないほどの星が見えた。", "vi": "Trên đỉnh núi, tôi có thể nhìn thấy vô số ngôi sao."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かける', 'V-ます(bỏ ます) + かける / V-ます(bỏ ます) + かけの + N', 'N3', 'hoàn thành một nửa; bắt đầu ; sắp sửa', 'Một hành động đã bắt đầu nhưng chưa kết thúc, hoặc một việc gì đó sắp xảy ra (死にかける). Thân động từ + かけの + danh từ mô tả sự việc chưa hoàn thành.', '[{"jp": "読みかけの本が、机の上に置いてある。", "vi": "Có một cuốn sách mà tôi chưa đọc trên bàn."}, {"jp": "彼女は何か言いかけたが、そのまま黙ってしまった。", "vi": "Cô bắt đầu nói điều gì đó nhưng lại im lặng."}, {"jp": "この花は枯れかけていたが、水をやったら元気になった。", "vi": "Bông hoa này đã chết, nhưng sau khi tôi tưới nước cho nó, nó đã sống lại."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜合う', 'V-ます(bỏ ます) + 合う', 'N3', 'làm với nhau; làm cùng nhau', 'Hành động tương hỗ hoặc chia sẻ. Nhiều từ ghép được tạo thành từ: 話し合う, 知り合う, 付き合う, 助け合う.', '[{"jp": "困ったときは、お互いに助け合いましょう。", "vi": "Hãy giúp đỡ nhau khi chúng ta gặp khó khăn."}, {"jp": "旅行の計画について、家族で話し合った。", "vi": "Gia đình bàn bạc kế hoạch du lịch."}, {"jp": "優勝が決まると、選手たちは抱き合って喜んだ。", "vi": "Khi đã xác định được người chiến thắng, các cầu thủ ôm nhau trong niềm vui sướng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜直す', 'V-ます(bỏ ます) + 直す', 'N3', 'làm lại; làm lại (để sửa chữa hoặc cải thiện)', 'Làm lại điều gì đó để sửa chữa hoặc cải thiện nó. Sự lặp lại đơn giản (もう一度〜する) không mang lại cảm giác sửa chữa.', '[{"jp": "名前を間違えたので、書類を書き直した。", "vi": "Tôi đã viết sai tên nên đã viết lại tài liệu."}, {"jp": "すみません、電波が悪いので、あとでかけ直します。", "vi": "Xin lỗi, tín hiệu kém nên tôi sẽ gọi lại sau."}, {"jp": "一度はあきらめた夢だが、もう一度考え直してみることにした。", "vi": "Đó là giấc mơ mà tôi đã từng từ bỏ nhưng tôi quyết định nghĩ lại về nó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜づらい', 'V-ます(bỏ ます) + づらい', 'N3', 'khó ; khó khăn hoặc không thoải mái để', 'Nhấn mạnh sự khó chịu về thể chất hoặc tâm lý của người thực hiện. 〜にくい (N4) khách quan hơn, mô tả bản chất của sự vật. N2 trang trọng: 〜がたい.', '[{"jp": "この靴は少し小さくて、歩きづらい。", "vi": "Đôi giày này hơi nhỏ và khó mang vào."}, {"jp": "先輩にお金を貸してほしいとは、ちょっと言いづらい。", "vi": "Có một chút khó khăn khi yêu cầu tiền bối cho bạn vay tiền."}, {"jp": "字が小さくて読みづらいので、もう少し大きくしてもらえますか。", "vi": "Font chữ hơi nhỏ và khó đọc, bạn có thể làm cho nó to hơn một chút được không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜べきだ / 〜べきではない', 'V-る(thể từ điển) + べきだ / V-る(thể từ điển) + べきではない', 'N3', 'nên ; nên/không nên', 'Có quan điểm mạnh mẽ về điều gì là đúng hoặc nghĩa vụ của một người; quá thẳng thừng để sử dụng đối với cấp trên. する → すべき hoặc するべき. So sánh 〜ほうがいい (lời khuyên) và 〜ものだ (chuẩn mực xã hội).', '[{"jp": "自分が悪いと思ったら、すぐに謝るべきだ。", "vi": "Nếu bạn cho rằng đó là lỗi của mình thì bạn nên xin lỗi ngay lập tức."}, {"jp": "環境のために、私たちはもっとエネルギーを大切に使うべきだ。", "vi": "Vì lợi ích của môi trường, chúng ta nên sử dụng năng lượng cẩn thận hơn."}, {"jp": "病院の中では、大きな声で話すべきではない。", "vi": "Bạn không nên nói chuyện lớn tiếng trong bệnh viện."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ほど〜はない', 'N + ほど + A-い / A-な + な + N + はない', 'N3', 'không có gì là ... như; không có ... như', 'Nói X là ... nhiều nhất, thường là từ kinh nghiệm hoặc cảm nhận cá nhân. Ngoài ra 〜くらい〜はない.', '[{"jp": "仕事の後に飲む冷たいビールほどおいしいものはない。", "vi": "Không có gì tốt hơn một ly bia lạnh sau giờ làm việc."}, {"jp": "この町で、あの店ほど安くておいしいラーメン屋はない。", "vi": "Không có cửa hàng ramen nào ở thị trấn này rẻ và ngon như cửa hàng đó."}, {"jp": "健康ほど大切なものはないと、病気になって気づいた。", "vi": "Khi bị bệnh tôi mới nhận ra rằng không có gì quan trọng hơn sức khỏe."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜しかない', 'V-る(thể từ điển) + しかない', 'N3', 'không có lựa chọn nào khác ngoài việc; chỉ có thể', 'Không có lựa chọn nào khác nên người nói chấp nhận lựa chọn này. Khác với Danh từ + しか〜ない (''chỉ''). Tương đương N2 trang trọng: 〜ほかない.', '[{"jp": "終電に乗り遅れたから、タクシーで帰るしかない。", "vi": "Tôi đã lỡ chuyến tàu cuối cùng nên không còn cách nào khác là bắt taxi về nhà."}, {"jp": "誰も手伝ってくれないなら、一人でやるしかない。", "vi": "Nếu không ai có thể giúp bạn, bạn sẽ phải làm điều đó một mình."}, {"jp": "ここまで来たら、もう最後まで頑張るしかないね。", "vi": "Nếu đã đi xa đến mức này, bạn không còn cách nào khác ngoài việc cố gắng hết sức cho đến cuối cùng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜まで（even）', 'N + まで / N + にまで', 'N3', 'thậm chí (một trường hợp cực đoan)', 'Thêm một mục cực đoan lên trên những mục khác, thường gây ngạc nhiên hoặc mất tinh thần. So sánh 〜さえ, tự nó chọn ra một ví dụ cực đoan.', '[{"jp": "最近は、小学生までスマホを持っている。", "vi": "Ngày nay, ngay cả học sinh tiểu học cũng có điện thoại thông minh."}, {"jp": "親友にまでうそをつかれて、とてもショックだった。", "vi": "Tôi bị sốc khi ngay cả người bạn thân nhất của tôi cũng nói dối tôi."}, {"jp": "雨だけでなく、風まで強くなってきた。", "vi": "Không chỉ mưa mà gió càng lúc càng mạnh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ところだった', 'V-る(thể từ điển) + ところだった', 'N3', 'gần như; gần như (nhưng không)', 'Một điều gì đó (thường là tồi tệ) đã suýt xảy ra nhưng đã không xảy ra. Thường đi kèm với mệnh đề もう少しで, 危うく hoặc mệnh đề 〜たら. So sánh 〜そうになった.', '[{"jp": "考え事をしていて、もう少しで車にひかれるところだった。", "vi": "Tôi đang suy nghĩ điều gì đó và suýt bị ô tô đâm."}, {"jp": "目覚ましが鳴らなくて、危うく飛行機に乗り遅れるところだった。", "vi": "Chuông báo thức của tôi không kêu và tôi suýt bị lỡ chuyến bay."}, {"jp": "君が教えてくれなかったら、大事な書類を出し忘れるところだったよ。", "vi": "Nếu bạn không nói với tôi, tôi sẽ quên đưa một tài liệu quan trọng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜からといって', 'Mệnh đề + からといって', 'N3', 'chỉ vì (... không có nghĩa); đơn giản vì', 'Phủ nhận rằng một lý do sẽ tự động dẫn đến một kết luận. Thường theo sau là phủ định như 〜わけではない hoặc 〜とは限らない. Bình thường: 〜からって.', '[{"jp": "日本人だからといって、みんなが敬語を正しく使えるわけではない。", "vi": "Chỉ vì bạn là người Nhật không có nghĩa là mọi người đều có thể sử dụng kính ngữ một cách chính xác."}, {"jp": "忙しいからといって、朝ご飯を食べないのは体によくない。", "vi": "Bỏ bữa sáng chỉ vì bận rộn sẽ không tốt cho sức khỏe của bạn."}, {"jp": "一回負けたからといって、あきらめる必要はない。", "vi": "Không cần thiết phải bỏ cuộc chỉ vì bạn đã thua một lần."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とおりに / 〜どおりに', 'V-る(thể từ điển) / V-た / N + の + とおりに / N + どおりに', 'N3', 'như ; theo cách đó; chính xác như', 'Làm điều gì đó giống hệt như một mô hình, hướng dẫn hoặc dự đoán. Ngay sau danh từ nó trở thành どおり (予定どおり, 思いどおり). に thường bị bỏ đi. そのとおりだ = ''chính xác''.', '[{"jp": "説明書に書いてあるとおりに組み立てたのに、うまく動かない。", "vi": "Mình đã lắp ráp theo hướng dẫn nhưng không được."}, {"jp": "先生が言ったとおり、試験には去年と似た問題が出た。", "vi": "Đúng như giáo viên nói, đề thi có câu hỏi tương tự như năm ngoái."}, {"jp": "工事は予定どおりに進んでいる。", "vi": "Việc xây dựng đang tiến triển theo đúng kế hoạch."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜なんか / 〜なんて', 'N + なんか / N + なんて / Mệnh đề + なんて', 'N3', 'những thứ như; thích (bác bỏ hoặc khiêm tốn); Làm sao ...! (ngạc nhiên)', 'Phiên bản thông thường của など với giọng điệu khinh miệt, khiêm tốn hoặc ngạc nhiên. なんか cũng làm dịu đi những gợi ý (お茶なんかどう？). Câu + なんて thể hiện sự ngạc nhiên hoặc không tin tưởng.', '[{"jp": "私なんか、まだまだ初心者です。", "vi": "Tôi vẫn là người mới bắt đầu."}, {"jp": "幽霊なんて、いるわけがないよ。", "vi": "Không có thứ gì gọi là ma cả."}, {"jp": "あの二人が結婚するなんて、びっくりした。", "vi": "Tôi rất ngạc nhiên khi hai người đó kết hôn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に際して', 'N + に際して / V-る(thể từ điển) + に際して / N + に際しての + N', 'N2', 'nhân dịp; khi; tại thời điểm', 'Chính thức; cho những dịp đặc biệt, chỉ diễn ra một lần (nghi lễ, khởi hành, hợp đồng). Gần đồng nghĩa với 〜にあたって, mang lại cảm giác chuẩn bị hoặc đối mặt với sự kiện; に際して chỉ đơn giản là đánh dấu sự kiện.', '[{"jp": "新製品の発売に際して、記者会見が開かれた。", "vi": "Một cuộc họp báo đã được tổ chức để chào mừng sự ra mắt của sản phẩm mới."}, {"jp": "海外へ渡航するに際しては、現地の安全情報を必ず確認してください。", "vi": "Khi đi du lịch nước ngoài, hãy nhớ kiểm tra thông tin an toàn tại địa phương."}, {"jp": "契約の更新に際しての注意事項をまとめました。", "vi": "Chúng tôi đã tổng hợp những điểm cần lưu ý khi gia hạn hợp đồng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に伴って', 'N + に伴って / V-る(thể từ điển) + の + に伴って / N + に伴う + N', 'N2', 'cùng với ; BẰNG; đi kèm', '〜に伴い là dạng viết nhiều hơn. Giống như 〜につれて nó có thể mô tả sự thay đổi dần dần, nhưng nó cũng bao gồm các sự kiện xảy ra một lần dẫn đến một sự kiện khác (ví dụ: chuyển địa điểm).', '[{"jp": "高齢化に伴って、医療費は年々増加している。", "vi": "Chi phí y tế đang tăng lên hàng năm khi dân số già đi."}, {"jp": "工場の移転に伴い、約二百人の従業員が転勤することになった。", "vi": "Khoảng 200 nhân viên sẽ phải di dời do việc di dời nhà máy."}, {"jp": "台風の接近に伴う大雨に注意してください。", "vi": "Hãy cẩn thận với mưa lớn khi cơn bão đến gần."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に応じて', 'N + に応じて / N + に応じた + N', 'N2', 'theo ; tùy thuộc vào ; để đáp lại', 'B được điều chỉnh để phù hợp với A (khả năng, ngân sách, mùa giải, yêu cầu). So sánh 〜次第で, nhấn mạnh rằng kết quả hoàn toàn do A quyết định.', '[{"jp": "この奨学金は、家庭の収入に応じて支給額が変わる。", "vi": "Số tiền học bổng này thay đổi tùy thuộc vào thu nhập của gia đình."}, {"jp": "お客様のご予算に応じたプランをご提案いたします。", "vi": "Chúng tôi sẽ đề xuất một kế hoạch phù hợp với ngân sách của bạn."}, {"jp": "会社は社員の要望に応じて、在宅勤務の制度を導入した。", "vi": "Công ty đã giới thiệu hệ thống làm việc tại nhà để đáp ứng yêu cầu của nhân viên."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に反して', 'N + に反して / N + に反する + N / N + に反した + N', 'N2', 'trái ngược với ; chống lại; vi phạm', 'Dùng với các danh từ như 予想, 期待, 意思, 規則. Với một quy tắc hoặc luật là danh từ, nó có nghĩa là ''vi phạm''.', '[{"jp": "大方の予想に反して、無名の新人が優勝した。", "vi": "Trái ngược với hầu hết sự mong đợi, một người mới vô danh đã giành chiến thắng."}, {"jp": "本人の意思に反して、彼は地方の支店に異動させられた。", "vi": "Chống lại ý muốn của mình, anh ta đã được chuyển đến một chi nhánh địa phương."}, {"jp": "たとえ上司の指示であっても、法律に反することはすべきではない。", "vi": "Bạn không nên làm bất cứ điều gì trái pháp luật, ngay cả khi sếp bảo bạn làm như vậy."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に基づいて', 'N + に基づいて / N + に基づく + N / N + に基づいた + N', 'N2', 'dựa vào; trên cơ sở', 'Cơ sở là một tiêu chuẩn vững chắc như dữ liệu, luật, sự kiện hoặc kinh nghiệm và B tuân thủ chặt chẽ các tiêu chuẩn đó. So sánh 〜をもとに, được sử dụng cho vật liệu mà từ đó một cái gì đó mới được tạo ra.', '[{"jp": "この映画は実際に起きた事件に基づいて制作された。", "vi": "Bộ phim này được thực hiện dựa trên một sự việc có thật."}, {"jp": "アンケートの結果に基づき、来年度の計画を見直すことにした。", "vi": "Dựa trên kết quả của bảng câu hỏi, chúng tôi quyết định xem lại kế hoạch của mình cho năm tới."}, {"jp": "科学的な根拠に基づいた判断が求められている。", "vi": "Cần phải có những phán đoán dựa trên bằng chứng khoa học."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にわたって', 'N + にわたって / N + にわたる + N', 'N2', 'qua ; khắp; trải dài (cả một thời kỳ hoặc một khu vực)', 'Nhấn mạnh toàn bộ khoảng thời gian dài, một khu vực rộng hoặc nhiều đồ vật (多岐にわたる). Không được sử dụng cho nhịp ngắn hoặc nhỏ.', '[{"jp": "工事は三か月にわたって行われる予定だ。", "vi": "Việc xây dựng dự kiến ​​sẽ diễn ra trong ba tháng."}, {"jp": "昨夜の大雪で、関東地方の広い範囲にわたって交通が乱れた。", "vi": "Tuyết dày đêm qua đã làm gián đoạn giao thông trên một khu vực rộng lớn của vùng Kanto."}, {"jp": "両国の首脳は、二日間にわたる会談を終えた。", "vi": "Lãnh đạo hai nước kết thúc hai ngày hội đàm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に沿って', 'N + に沿って / N + に沿った + N', 'N2', 'Men theo / Dựa theo, bám sát theo...', 'Nghĩa đen: dọc theo một con đường, con sông hoặc bờ biển. Cách sử dụng trừu tượng: tuân theo một kế hoạch, chính sách hoặc mong muốn của ai đó.', '[{"jp": "川に沿って桜並木が二キロほど続いている。", "vi": "Hàng cây hoa anh đào trải dài khoảng hai cây số dọc theo bờ sông."}, {"jp": "マニュアルに沿って作業を進めてください。", "vi": "Hãy tiến hành theo hướng dẫn."}, {"jp": "お客様のご要望に沿ったデザインを考えます。", "vi": "Chúng tôi sẽ đưa ra một thiết kế đáp ứng nhu cầu của bạn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に加えて', 'N + に加えて', 'N2', 'ngoài ra; trên đầu trang', 'Hơi trang trọng; 〜に加え là dạng viết. Mục được thêm vào thường được đánh dấu bằng も.', '[{"jp": "今年は猛暑に加えて雨不足が続き、野菜の価格が高騰している。", "vi": "Năm nay, ngoài nắng nóng gay gắt, tiếp tục thiếu mưa, giá rau tăng vọt."}, {"jp": "この仕事には、語学力に加えて交渉力も必要だ。", "vi": "Công việc này không chỉ đòi hỏi kỹ năng ngôn ngữ mà còn cả kỹ năng đàm phán."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をめぐって', 'N + をめぐって / N + をめぐる + N', 'N2', 'qua ; liên quan đến; xung quanh (vấn đề tranh chấp)', 'Động từ theo sau là về tranh luận, xung đột hoặc cạnh tranh (議論する, 対立する, 争う). Không giống như 〜について, nó không được sử dụng để giải thích một chủ đề đơn giản.', '[{"jp": "新しい空港の建設をめぐって、住民の意見が二つに分かれている。", "vi": "Người dân chia thành hai luồng ý kiến ​​liên quan đến việc xây dựng sân bay mới."}, {"jp": "父の遺産をめぐって、兄弟の間でもめごとが起きた。", "vi": "Giữa hai anh em nảy sinh tranh chấp về quyền thừa kế của cha họ."}, {"jp": "首相の発言をめぐる議論は、今も続いている。", "vi": "Cuộc tranh luận xung quanh phát biểu của Thủ tướng vẫn tiếp tục cho đến ngày nay."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を通じて / 〜を通して', 'N + を通じて / N + を通して', 'N2', 'qua ; thông qua; bằng cách ; trong suốt (một khoảng thời gian)', 'Có thể hoán đổi cho nhau. 〜を通して có xu hướng nhấn mạnh một quá trình hoặc trải nghiệm có chủ ý; 〜を通じて trang trọng hơn một chút và phổ biến hơn với phương tiện truyền thông, địa chỉ liên lạc và thời gian (一年を通じて).', '[{"jp": "共通の友人を通じて、今の妻と知り合った。", "vi": "Tôi gặp người vợ hiện tại của mình thông qua một người bạn chung."}, {"jp": "ボランティア活動を通して、地域の人々とのつながりが深まった。", "vi": "Thông qua các hoạt động tình nguyện, tôi đã kết nối sâu sắc hơn với người dân địa phương."}, {"jp": "この地域は一年を通じて雨が少ない。", "vi": "Vùng này có lượng mưa ít quanh năm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をきっかけに', 'N + をきっかけに / N + をきっかけとして / V(thể thông thường) + の + をきっかけに', 'N2', 'Nhân dịp... / Bắt nguồn từ cơ hội...', 'Đánh dấu một sự kiện dẫn đến một sự khởi đầu hoặc thay đổi mới. Từ tương đương chính thức 〜を契機に thường được sử dụng trong văn viết.', '[{"jp": "大学時代の留学をきっかけに、国際協力の仕事に興味を持つようになった。", "vi": "Sau thời gian du học ở nước ngoài, anh bắt đầu quan tâm đến công việc hợp tác quốc tế."}, {"jp": "引っ越したのをきっかけに、家具をすべて買い替えた。", "vi": "Sau khi chuyển đi, tôi đã thay thế toàn bộ đồ đạc của mình."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を除いて', 'N + を除いて / N + を除き / N + を除く + N', 'N2', 'ngoại trừ; loại trừ; ngoài', 'Trang trọng hơn 〜以外. 〜を除き là dạng viết.', '[{"jp": "年末年始を除いて、図書館は毎日開いている。", "vi": "Thư viện mở cửa hàng ngày trừ những ngày lễ cuối năm và năm mới."}, {"jp": "一部の地域を除き、明日は全国的に晴れるでしょう。", "vi": "Ngày mai trời sẽ nắng trên khắp đất nước, ngoại trừ một số khu vực."}, {"jp": "この件について知っているのは、私を除いて三人しかいない。", "vi": "Ngoài tôi chỉ có ba người biết về vấn đề này."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かのようだ', 'V(thể thông thường) / A-い + かのようだ / A-な + である + かのようだ / N + である + かのようだ', 'N2', 'như thể ; như thể (trong khi thực tế không phải vậy)', 'Mang tính văn học hơn 〜ようだ và báo hiệu rõ ràng rằng sự so sánh này không đúng theo nghĩa đen. Thường kết hợp với まるで. Ngoài ra 〜かのように / 〜かのような.', '[{"jp": "彼はまるで何も知らないかのような顔をしていた。", "vi": "Anh ấy trông như không biết gì cả."}, {"jp": "三月なのに、真冬に戻ったかのような寒さだ。", "vi": "Dù đang là tháng 3 nhưng trời lạnh đến mức khiến chúng ta có cảm giác như đang quay về giữa mùa đông."}, {"jp": "その記者は、うわさをまるで事実であるかのように報じた。", "vi": "Phóng viên đã tường thuật tin đồn như thể nó là sự thật."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かねない', 'V-ます(bỏ ます) + かねない', 'N2', 'Có nguy cơ... / E rằng sẽ... (Kết quả xấu)', 'Chỉ cho kết quả không mong muốn. Mặc dù có ない nhưng ý nghĩa vẫn tích cực: ''có nguy cơ thực sự là ...''. Đừng nhầm lẫn với 〜かねる (không thể).', '[{"jp": "そんな無理な運転をしていたら、大事故を起こしかねない。", "vi": "Nếu bạn lái xe như vậy, bạn có thể gây ra tai nạn nghiêm trọng."}, {"jp": "不用意な一言が、会社の信用を失うことにつながりかねない。", "vi": "Một lời nói bất cẩn có thể dẫn đến mất niềm tin vào công ty."}, {"jp": "あの人なら、平気でうそをつきかねない。", "vi": "Người đó có thể dễ dàng nói dối."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かねる', 'V-ます(bỏ ます) + かねる', 'N2', 'Khó lòng... / Không thể... (Từ chối lịch sự)', 'Một cách từ chối nhẹ nhàng, trang trọng, rất phổ biến trong dịch vụ khách hàng. Nó thể hiện sự miễn cưỡng hoặc khó khăn của người nói chứ không phải sự bất lực về thể chất.', '[{"jp": "申し訳ございませんが、そのご質問にはお答えしかねます。", "vi": "Chúng tôi xin lỗi, nhưng chúng tôi không thể trả lời câu hỏi của bạn."}, {"jp": "個人情報に関するお問い合わせには、お電話では対応いたしかねます。", "vi": "Chúng tôi không thể trả lời các câu hỏi liên quan đến thông tin cá nhân qua điện thoại."}, {"jp": "彼のやり方には、どうしても賛成しかねる。", "vi": "Tôi chỉ không thể đồng ý với cách tiếp cận của anh ấy."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ずにはいられない', 'V-ない(bỏ ない) + ずにはいられない', 'N2', 'không thể không làm; không thể cưỡng lại việc làm', 'する trở thành せずにはいられない. 〜ないではいられない là một từ tương đương mang tính đàm thoại hơn một chút. Sự thôi thúc bên trong, không giống như 〜ざるを得ない (do hoàn cảnh ép buộc).', '[{"jp": "あまりにひどいニュースに、怒りを感じずにはいられなかった。", "vi": "Tin tức khủng khiếp đến mức tôi không khỏi tức giận."}, {"jp": "彼女の苦労話を聞いて、泣かずにはいられなかった。", "vi": "Tôi không cầm được nước mắt khi nghe câu chuyện khó khăn của chị."}, {"jp": "このシリーズは、一度読み始めたら最後まで読まずにはいられない。", "vi": "Khi bạn bắt đầu đọc bộ truyện này, bạn không thể không đọc nó cho đến cuối."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ざるを得ない', 'V-ない(bỏ ない) + ざるを得ない', 'N2', 'Đành phải... / Buộc lòng phải...', 'Hoàn cảnh buộc người nói phải thực hiện một hành động không thực sự muốn thực hiện. する trở thành せざるを得ない. Trang trọng hơn 〜しかない.', '[{"jp": "予算が足りないので、計画を縮小せざるを得ない。", "vi": "Do thiếu ngân sách, chúng tôi không có lựa chọn nào khác ngoài việc thu nhỏ lại kế hoạch của mình."}, {"jp": "上司の命令だったので、気が進まなくても行かざるを得なかった。", "vi": "Đó là lệnh của sếp nên tôi không còn cách nào khác là phải đi, ngay cả khi tôi không thấy thích."}, {"jp": "彼の努力だけは認めざるを得ない。", "vi": "Tôi phải thừa nhận nỗ lực của anh ấy."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てはいられない', 'V-て + はいられない', 'N2', 'không đủ khả năng để (tiếp tục) làm; không thể chỉ', 'Hoàn cảnh không cho phép người ta ở trạng thái A nên người ta cảm thấy bị thúc đẩy phải hành động. Bình thường: 〜ちゃいられない / 〜てらんない.', '[{"jp": "締め切りが迫っているので、のんびりしてはいられない。", "vi": "Thời hạn đang đến gần nên tôi không thể dễ dàng được."}, {"jp": "困っている人を見ると、黙ってはいられない性格だ。", "vi": "Khi thấy ai đó gặp khó khăn, anh ấy là kiểu người không thể giữ im lặng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ものか', 'V-る(thể từ điển) / A-い / A-な + な + ものか', 'N2', 'không thể nào (tôi sẽ); như thể ; tôi sẽ không bao giờ', 'Từ chối hoặc từ chối cảm xúc mạnh mẽ; không phải là một câu hỏi thực sự Dạng hội thoại: 〜もんか; lịch sự/nữ tính: 〜ものですか.', '[{"jp": "あんな失礼な店には、二度と行くものか。", "vi": "Liệu tôi có bao giờ đến một cửa hàng thô lỗ như vậy nữa không?"}, {"jp": "一度や二度失敗したくらいで、諦めるもんか。", "vi": "Bạn không bỏ cuộc sau khi thất bại một hoặc hai lần sao?"}, {"jp": "あの人の気持ちなんて、君に分かるものか。", "vi": "Bạn có biết người đó cảm thấy thế nào không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ものの', 'V(thể thông thường) / A-い / A-な + な / A-な + である / N + である + ものの', 'N2', 'mặc dù ; mặc dù (nhưng kết quả mong đợi không theo sau)', 'Thừa nhận sự thật đầu tiên, sau đó nói rằng mọi thứ không diễn ra như nó tưởng. Được viết nhiều hơn 〜けれども.', '[{"jp": "免許は取ったものの、怖くてまだ一度も運転していない。", "vi": "Mặc dù tôi đã có bằng nhưng tôi chưa bao giờ lái xe ô tô vì tôi rất sợ."}, {"jp": "新しい制度は導入されたものの、十分に活用されていないのが現状だ。", "vi": "Mặc dù một hệ thống mới đã được giới thiệu nhưng tình hình hiện tại là nó chưa được sử dụng đầy đủ."}, {"jp": "この部屋は駅から近いものの、日当たりが悪いのが難点だ。", "vi": "Căn phòng này tuy gần ga nhưng có vấn đề là không nhận được nhiều ánh nắng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ものなら', 'V-る(thể từ điển) (potential form) + ものなら', 'N2', 'nếu (có thể); nếu chỉ có một người có thể', 'Đối với một việc gì đó khó hoặc không thể làm được; mệnh đề chính thường là 〜たい hoặc một lời thách thức. Đừng nhầm lẫn với N1 〜(よ)うものなら (''nếu ai dám..., sẽ có chuyện không hay xảy ra'').', '[{"jp": "できるものなら、学生時代に戻ってもう一度やり直したい。", "vi": "Nếu có thể, tôi muốn quay lại thời sinh viên của mình và thử lại."}, {"jp": "行けるものなら行きたいが、その日はどうしても仕事を休めない。", "vi": "Tôi muốn đi nếu có thể, nhưng tôi không đủ khả năng để nghỉ làm vào ngày hôm đó."}, {"jp": "止められるものなら止めてみろ。", "vi": "Nếu bạn có thể ngăn chặn nó, hãy cố gắng ngăn chặn nó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜くらいなら / 〜ぐらいなら', 'V-る(thể từ điển) + くらいなら / V-る(thể từ điển) + ぐらいなら', 'N2', 'chứ không phải ; nếu phải làm (làm việc đó), tôi thà', 'A là điều mà người nói cực kỳ không thích; B là lựa chọn ít xấu xa hơn hoặc tốt hơn, thường đi kèm với 〜ほうがいい / 〜ほうがましだ.', '[{"jp": "あんな人に頭を下げるくらいなら、会社を辞めたほうがましだ。", "vi": "Tôi thà rời bỏ công ty còn hơn cúi đầu trước một người như vậy."}, {"jp": "途中で投げ出すぐらいなら、最初から引き受けないほうがいい。", "vi": "Thà không chấp nhận lời đề nghị ngay từ đầu còn hơn là bỏ cuộc giữa chừng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ものがある', 'V-る(thể từ điển) / A-い / A-な + な + ものがある', 'N2', 'có cái gì đó (về nó là vậy) ...; nó thực sự là', 'Diễn tả ấn tượng mạnh mẽ của người nói về chất lượng cảm nhận được ở điều gì đó. Đó là một sự đánh giá, không phải là một tuyên bố về sự tồn tại theo nghĩa đen.', '[{"jp": "この画家の初期の作品には、見る人の心を強く打つものがある。", "vi": "Những tác phẩm đầu tay của nghệ sĩ này có tác động mạnh mẽ đến người xem."}, {"jp": "毎日二時間かけて通勤するのは、正直つらいものがある。", "vi": "Thành thật mà nói, việc đi lại hai giờ mỗi ngày có thể là một điều khó khăn."}, {"jp": "若い選手たちの成長ぶりには、目を見張るものがある。", "vi": "Sự trưởng thành của các cầu thủ trẻ là điều đáng chú ý."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことか', 'Question word + … + V(thể thông thường) / A-い / A-な + な + ことか', 'N2', 'làm thế nào ...!; bao nhiêu ...!', 'Thường đi kèm với どんなに, どれほど, 何度, v.v. Không phải là một câu hỏi thực sự; nó truyền tải cảm xúc sâu sắc. Giọng điệu nhẹ nhàng hoặc kịch tính.', '[{"jp": "この日が来るのを、どれほど待ち望んだことか。", "vi": "Tôi đã chờ đợi ngày này đến bao lâu rồi?"}, {"jp": "一人暮らしを始めて、家族のありがたさを何度感じたことか。", "vi": "Đã bao nhiêu lần bạn cảm thấy biết ơn gia đình mình kể từ khi bắt đầu sống một mình?"}, {"jp": "無事だと聞いて、どんなに安心したことか。", "vi": "Tôi nhẹ nhõm biết bao khi biết rằng anh ấy vẫn an toàn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことに（は）', 'V-た / A-い / A-な + な + ことに（は）', 'N2', '(cảm xúc)-ly; cái gì (ngạc nhiên, buồn, v.v.) là cái gì', 'Một từ cảm xúc (驚いた, 残念な, うれしい, 不思議な) thể hiện cảm xúc của người nói trước khi đưa ra sự thật. Viết khá.', '[{"jp": "驚いたことに、彼は会社を辞めてパン屋を開いたそうだ。", "vi": "Trước sự ngạc nhiên của tôi, có vẻ như anh ấy đã bỏ việc và mở một tiệm bánh."}, {"jp": "残念なことに、その美しい建物は来月取り壊されることになった。", "vi": "Thật không may, tòa nhà đẹp đẽ này sẽ bị phá bỏ vào tháng tới."}, {"jp": "うれしいことには、応募作品が予想の倍以上も集まった。", "vi": "Thật vui mừng, chúng tôi đã nhận được số lượng bài dự thi nhiều hơn gấp đôi so với mong đợi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことだから', 'N + の + ことだから', 'N2', 'biết (ai đó); vì đó là (ai đó), chắc chắn', 'Từ những gì người nói biết về tính cách của một người, nó sẽ dẫn đến phỏng đoán về hành vi của họ. Thường theo sau là だろう, きっと hoặc に違いない.', '[{"jp": "几帳面な彼のことだから、書類はもう準備してあるだろう。", "vi": "Anh ấy là người tỉ mỉ nên tôi chắc chắn rằng anh ấy đã chuẩn bị sẵn giấy tờ."}, {"jp": "あの子のことだから、きっとどこかで寄り道をしているんだよ。", "vi": "Vì là về thằng nhóc đó nên tôi chắc chắn nó đang đi đường vòng đâu đó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことなく', 'V-る(thể từ điển) + ことなく', 'N2', 'không có (làm); không bao giờ', 'Một cách viết tương đương với 〜ないで / 〜ずに, thường ngụ ý rằng điều gì đó mà người ta mong đợi sẽ không xảy ra.', '[{"jp": "彼は三十年間、一日も休むことなく店を開け続けた。", "vi": "Ông đã mở cửa hàng suốt 30 năm không bỏ sót một ngày nào."}, {"jp": "失敗を恐れることなく、新しいことに挑戦してほしい。", "vi": "Tôi muốn bạn thử những điều mới mà không sợ thất bại."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことから', 'V(thể thông thường) / A-い / A-な + な / A-な + である / N + である + ことから', 'N2', 'từ thực tế đó; bởi vì; đánh giá từ', 'Đưa ra bằng chứng hoặc nguồn gốc đằng sau một cái tên, phán đoán hoặc kết luận. Phổ biến trong việc giải thích tên địa danh và trong các báo cáo.', '[{"jp": "この坂は、昔から桜の名所であることから「桜坂」と呼ばれている。", "vi": "Con dốc này được gọi là ``Sakurazaka'''' vì từ lâu nó đã là địa điểm nổi tiếng để ngắm hoa anh đào."}, {"jp": "現場に靴の跡が残っていたことから、犯人は外から侵入したと考えられる。", "vi": "Thủ phạm được cho là đã vào từ bên ngoài nên có dấu giày để lại tại hiện trường."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ないことには', 'V-ない / A-い-ku + ない / A-な + でない / N + でない + ことには', 'N2', 'trừ khi; nếu ... không (thì điều đó không thể xảy ra)', 'Mệnh đề chính phủ định (分からない, できない, 始まらない): không có A thì B không thể xảy ra. Nhấn mạnh hơn 〜なければ.', '[{"jp": "実際に会って話してみないことには、どんな人か分からない。", "vi": "Bạn sẽ không biết ai đó là người như thế nào cho đến khi bạn thực sự gặp họ và nói chuyện với họ."}, {"jp": "社長の許可が出ないことには、このプロジェクトは始められない。", "vi": "Dự án này không thể bắt đầu nếu không có sự cho phép của tổng thống."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことは〜が', 'V(thể thông thường) + ことは + V(thể thông thường) + が / A-い + ことは + A-い + が / A-な + な + ことは + A-な + だ + が', 'N2', 'đúng là ..., nhưng; (Tôi) làm ..., nhưng', 'Từ tương tự được lặp lại để thừa nhận điều gì đó chỉ một phần trước khi thêm sự bảo lưu. けど thay thế が trong lời nói.', '[{"jp": "あの映画、見たことは見たけど、途中で寝てしまった。", "vi": "Tôi đã xem bộ phim đó nhưng tôi đã ngủ quên giữa chừng."}, {"jp": "この部屋は広いことは広いが、駅からかなり遠い。", "vi": "Căn phòng này rộng rãi nhưng lại khá xa nhà ga."}, {"jp": "彼の説明は、分かることは分かるが、納得はできない。", "vi": "Tôi hiểu lời giải thích của anh ấy, nhưng tôi không hiểu nó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜あげく', 'V-た + あげく / N + の + あげく', 'N2', 'sau (một quá trình lâu dài và rắc rối); cuối cùng', 'Kết quả thường là tiêu cực hoặc đáng thất vọng. 〜末(に) mang tính trung lập và có thể kết thúc tốt đẹp; あげく nhấn mạnh sự thất vọng. あげくの果てに là dạng tăng cường.', '[{"jp": "さんざん迷ったあげく、結局どちらも買わなかった。", "vi": "Sau nhiều đắn đo, cuối cùng tôi cũng không mua."}, {"jp": "長時間の話し合いのあげく、計画は白紙に戻された。", "vi": "Sau một thời gian dài thảo luận, kế hoạch đã bị hủy bỏ."}, {"jp": "彼は無理を重ねたあげく、体を壊して入院してしまった。", "vi": "Sau khi cố gắng quá sức, anh ấy suy sụp và phải nhập viện."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜あまり（に）', 'V-る(thể từ điển) / V-た / A-な + な / N + の + あまり（に）', 'N2', 'nhiều đến thế; quá mức; vì quá nhiều', 'Cảm giác hoặc trạng thái ở mức độ cực đoan sẽ dẫn đến một kết quả bất thường, thường không mong muốn. Chủ yếu là với các danh từ chỉ cảm xúc (緊張, 心配, 驚き, 悲しみ).', '[{"jp": "彼女は緊張のあまり、スピーチの内容を忘れてしまった。", "vi": "Cô lo lắng đến mức quên mất nội dung bài phát biểu của mình."}, {"jp": "子どもの将来を心配するあまり、親が口を出しすぎることがある。", "vi": "Cha mẹ có thể trở nên quá quan tâm đến tương lai của con cái họ và trở nên quá quan tâm."}, {"jp": "うれしさのあまり、思わず涙が出た。", "vi": "Tôi hạnh phúc đến mức bật khóc."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜上（に）', 'V(thể thông thường) / A-い / A-な + な / N + である + 上（に）', 'N2', 'ngoài ra ; ở trên ; ngoài ra còn có', 'Thêm điểm thứ hai cùng loại (tốt + tốt, xấu + xấu). に có thể được viết ra bằng văn bản. Nó thường không được theo sau bởi một mệnh lệnh hoặc yêu cầu.', '[{"jp": "あのレストランは料理がおいしい上に、値段も手頃だ。", "vi": "Đồ ăn ở nhà hàng đó ngon và giá cả hợp lý."}, {"jp": "道に迷った上に、雨まで降ってきた。", "vi": "Tôi không chỉ bị lạc mà trời còn bắt đầu mưa."}, {"jp": "彼女は仕事が速い上、ミスもほとんどない。", "vi": "Cô ấy làm việc nhanh chóng và ít mắc lỗi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜上で', 'V-た + 上で / N + の + 上で / V-る(thể từ điển) + 上で', 'N2', 'sau (làm), trên; trong (làm), khi nói đến', 'Động từ-ta + 上で: làm A trước, sau đó làm B. Động từ-dict + 上で: ''trong quá trình / vì mục đích của A''. Văn bản kinh doanh thường rút ngắn nó thành ご確認の上.', '[{"jp": "家族とよく相談した上で、お返事いたします。", "vi": "Chúng tôi sẽ phản hồi sau khi tham khảo ý kiến ​​của gia đình bạn."}, {"jp": "内容を確認した上で、契約書に署名してください。", "vi": "Vui lòng kiểm tra nội dung và ký hợp đồng."}, {"jp": "外国語を学ぶ上で大切なのは、間違いを恐れないことだ。", "vi": "Điều quan trọng khi học ngoại ngữ là không sợ mắc lỗi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜以上（は）', 'V(thể thông thường) / A-な + である / N + である + 以上（は）', 'N2', 'kể từ ; bây giờ đó; miễn là', 'Từ một tình huống nhất định, rút ​​ra một nghĩa vụ, quyết tâm hoặc phán đoán chắc chắn. Gần đồng nghĩa với 〜からには; 以上は nghe trang trọng và logic hơn, からには giống quyết tâm cá nhân hơn.', '[{"jp": "引き受けた以上は、最後まで責任を持ってやり遂げるつもりだ。", "vi": "Bây giờ tôi đã nhận công việc, tôi dự định sẽ chịu trách nhiệm và theo đuổi nó đến cùng."}, {"jp": "プロである以上、言い訳は許されない。", "vi": "Là một người chuyên nghiệp, không có lời bào chữa nào."}, {"jp": "証拠がない以上、彼を犯人と決めつけることはできない。", "vi": "Vì không có bằng chứng nên không thể kết luận anh ta là thủ phạm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜からには', 'V(thể thông thường) / N + である + からには', 'N2', 'bây giờ đó; vì (đã làm/đang…, người ta phải)', 'Thể hiện quyết tâm: đã đạt đến tình huống này, người ta nên nhìn thấu nó. Thường kết thúc bằng 〜たい, 〜つもりだ, 〜なければならない. So sánh 〜以上(は), trang trọng và trung lập hơn.', '[{"jp": "オリンピックに出るからには、メダルを狙いたい。", "vi": "Khi tham dự Thế vận hội, tôi muốn giành huy chương."}, {"jp": "自分で決めたからには、途中で投げ出すわけにはいかない。", "vi": "Vì tôi đã tự mình đưa ra quyết định nên tôi không thể bỏ nó giữa chừng được."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜からこそ', 'V(thể thông thường) / A-い / A-な + だ / N + だ + からこそ', 'N2', 'chính xác là vì; đó là bởi vì... đó', 'Nhấn mạnh rằng lý do này chứ không phải lý do nào khác là lý do thực sự, thường là lý do mà người nghe không mong đợi. Thường kết thúc bằng 〜のだ.', '[{"jp": "君のことを思っているからこそ、厳しいことを言うんだ。", "vi": "Tôi nói những điều khắc nghiệt vì tôi quan tâm đến bạn."}, {"jp": "苦しい時期があったからこそ、今の成功があるのだと思う。", "vi": "Tôi tin rằng thành công hiện tại của tôi là nhờ những khoảng thời gian khó khăn mà tôi đã trải qua."}, {"jp": "小さな会社だからこそできるサービスもある。", "vi": "Có một số dịch vụ mà chỉ một công ty nhỏ mới có thể cung cấp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜からして', 'N + からして', 'N2', 'đánh giá từ ; (bắt đầu) ngay cả với; để bắt đầu với', 'Hai cách sử dụng: ''đánh giá từ X'' (cơ sở để phỏng đoán) và ''kể cả X, chứ đừng nói đến phần còn lại'', trong đó một ví dụ đại diện cho tổng thể, thường mang tính phê phán.', '[{"jp": "空の様子からして、午後は雨になりそうだ。", "vi": "Đánh giá từ bầu trời, có vẻ như trời sẽ mưa vào buổi chiều."}, {"jp": "あの店は、店員の態度からして感じが悪い。", "vi": "Cửa hàng đó có cảm giác không tốt vì thái độ của nhân viên."}, {"jp": "彼の話は、最初の前提からして間違っている。", "vi": "Câu chuyện của anh ấy đã sai ngay từ đầu."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜からすると / 〜からすれば', 'N + からすると / N + からすれば', 'N2', 'đánh giá từ ; từ quan điểm của', 'Đưa ra bằng chứng cho một phán đoán hoặc quan điểm của một người. Gần 〜から見ると; không giống như 〜からいうと, nó có thể cần một người.', '[{"jp": "あの話し方からすると、彼は関西の出身だろう。", "vi": "Dựa theo cách nói chuyện thì chắc hẳn anh ta đến từ Kansai."}, {"jp": "親からすれば、子どもはいくつになっても子どもだ。", "vi": "Đối với cha mẹ, con cái dù có bao nhiêu tuổi vẫn là trẻ con."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜から見ると / 〜から見れば', 'N + から見ると / N + から見れば', 'N2', 'từ quan điểm của; đánh giá từ ; nhìn thấy từ', 'Nhìn vào điều gì đó từ vị trí của một người hoặc từ bằng chứng nhất định. 〜から見て và 〜から見ても cũng rất phổ biến.', '[{"jp": "外国人から見ると、日本の習慣には不思議なものが多いらしい。", "vi": "Từ góc nhìn của người nước ngoài, nhiều phong tục của người Nhật có vẻ kỳ lạ."}, {"jp": "今の成績から見れば、第一志望の合格は十分可能だ。", "vi": "Xét theo điểm số hiện tại của tôi, tôi hoàn toàn có khả năng đậu được lựa chọn đầu tiên."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜からいうと / 〜からいって', 'N + からいうと / N + からいって', 'N2', 'về mặt ; từ quan điểm của; đánh giá bằng', 'Danh từ là tiêu chí hay quan điểm (立場, 経験, 値段), không phải là người: nói 親からすると, không phải ×親からいうと. 〜からいえば cũng được sử dụng.', '[{"jp": "立地からいうと、駅前のマンションのほうが便利だ。", "vi": "Xét về vị trí thì những căn hộ phía trước ga thuận tiện hơn."}, {"jp": "これまでの経験からいって、この計画はうまくいかないと思う。", "vi": "Dựa trên kinh nghiệm của tôi cho đến nay, tôi không nghĩ kế hoạch này sẽ thành công."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜際（に）', 'V-る(thể từ điển) / V-た / N + の + 際（に）', 'N2', 'khi nào; vào thời điểm đó; nhân dịp', 'Phiên bản trang trọng của 〜とき, phổ biến trong các thông báo và hướng dẫn. Không giống như 〜に際して, nó phù hợp cho những dịp hàng ngày.', '[{"jp": "お降りの際は、お忘れ物のないようご注意ください。", "vi": "Khi xuống tàu, hãy cẩn thận đừng để lại bất cứ thứ gì."}, {"jp": "以前京都を訪れた際に、この寺にも立ち寄った。", "vi": "Tôi cũng đã ghé qua ngôi chùa này khi đến thăm Kyoto trước đây."}, {"jp": "パスポートを申請する際には、写真と本人確認書類が必要です。", "vi": "Khi xin hộ chiếu, bạn sẽ cần có ảnh và giấy tờ tùy thân."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜次第', 'V-ます(bỏ ます) + 次第 / N + 次第', 'N2', 'ngay khi (rồi ngay lập tức)', 'Trang trọng, dùng để chỉ một hành động được lên kế hoạch trong tương lai ngay sau A (liên hệ, bắt đầu). Không dùng khi mệnh đề chính ở quá khứ. So sánh 〜次第で (tùy theo).', '[{"jp": "詳しい日程が決まり次第、皆様にご連絡いたします。", "vi": "Chúng tôi sẽ liên hệ với mọi người ngay khi lịch trình chi tiết được quyết định."}, {"jp": "資料が届き次第、内容を確認してお返事します。", "vi": "Sau khi nhận được tài liệu, chúng tôi sẽ kiểm tra nội dung và trả lời bạn."}, {"jp": "定員になり次第、受付を締め切らせていただきます。", "vi": "Việc đăng ký sẽ kết thúc ngay khi đủ số lượng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜次第だ / 〜次第で', 'N + 次第だ / N + 次第で / N + 次第では', 'N2', 'tùy thuộc vào ; nó phụ thuộc vào', 'Kết quả được quyết định bởi A. 〜次第では chỉ ra một kết quả có thể xảy ra trong số nhiều kết quả.', '[{"jp": "合格できるかどうかは、これからの努力次第だ。", "vi": "Việc bạn có thể vượt qua hay không phụ thuộc vào sự nỗ lực của bạn từ bây giờ."}, {"jp": "天気次第で、明日の予定を変えるかもしれない。", "vi": "Tùy thuộc vào thời tiết, lịch trình ngày mai có thể thay đổi."}, {"jp": "考え方次第では、失敗も貴重な経験になる。", "vi": "Tùy thuộc vào suy nghĩ của bạn, ngay cả thất bại cũng có thể là một trải nghiệm quý giá."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜末（に）', 'V-た + 末（に） / N + の + 末（に）', 'N2', 'sau (một quá trình dài); cuối cùng, vào cuối', 'Trung lập: kết quả có thể tốt hoặc xấu và thường là một quyết định hoặc kết luận. Sử dụng 〜あげく khi kết quả không tốt hoặc gây khó chịu.', '[{"jp": "半年にわたる交渉の末、両社はようやく合意に達した。", "vi": "Sau sáu tháng đàm phán, cuối cùng hai công ty đã đạt được thỏa thuận."}, {"jp": "散々悩んだ末に、彼は留学をあきらめることにした。", "vi": "Sau nhiều suy nghĩ, anh quyết định từ bỏ việc đi du học."}, {"jp": "試行錯誤の末に完成したのが、この新しいエンジンだ。", "vi": "Động cơ mới này đã được hoàn thiện sau nhiều thử nghiệm và sai sót."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たところで', 'V-た + ところで', 'N2', 'ngay cả khi (nó sẽ không có ích gì); dù có bao nhiêu', 'Mệnh đề chính nói rằng nỗ lực đó là vô ích hoặc kết quả sẽ không quan trọng lắm. Thường đi kèm với いくら, どんなに, 今さら. Khác với 〜たところ (khi tôi làm thì tôi đã tìm thấy).', '[{"jp": "今から急いだところで、終電には間に合わないだろう。", "vi": "Ngay cả khi tôi vội vàng, tôi sẽ không thể bắt kịp chuyến tàu cuối cùng."}, {"jp": "いくら説明したところで、あの人は聞く耳を持たない。", "vi": "Dù bạn có giải thích thế nào thì người đó cũng không nghe."}, {"jp": "失敗したところで、失うものは何もない。", "vi": "Bạn không có gì để mất nếu bạn thất bại."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たところ', 'V-た + ところ', 'N2', 'khi (tôi) đã làm ..., (tôi tìm thấy điều đó); khi làm', 'Báo cáo những gì xảy ra sau một hành động, thường là một khám phá. Kết quả là một sự kiện trong quá khứ nằm ngoài tầm kiểm soát của người nói. Trang trọng hơn 〜たら.', '[{"jp": "駅の窓口で問い合わせたところ、その電車は運休しているとのことだった。", "vi": "Khi tôi hỏi tại quầy ga thì được biết tàu đã bị đình chỉ."}, {"jp": "試しに新しい肥料を使ってみたところ、トマトがよく育った。", "vi": "Khi tôi thử sử dụng loại phân bón mới, cà chua của tôi phát triển tốt."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ばかりか', 'V(thể thông thường) / A-い / A-な + な / N + ばかりか', 'N2', 'Không chỉ... mà ngay cả...', 'Mạnh hơn 〜だけでなく; mục thứ hai thường gây ngạc nhiên hơn và được đánh dấu bằng も, まで hoặc さえ. Không giống như 〜だけでなく, nó không được theo sau bởi mệnh lệnh hoặc yêu cầu.', '[{"jp": "彼は約束の時間に遅れたばかりか、謝りもしなかった。", "vi": "Anh ta không chỉ đến trễ cuộc hẹn mà thậm chí còn không xin lỗi."}, {"jp": "この薬は効果がないばかりか、副作用まであるそうだ。", "vi": "Thuốc này không những không có tác dụng mà còn có tác dụng phụ."}, {"jp": "その歌手は国内ばかりか、アジア各国でも人気がある。", "vi": "Nữ ca sĩ nổi tiếng không chỉ ở Nhật Bản mà còn ở nhiều nước châu Á."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ばかりに', 'V(thể thông thường) / A-い / A-な + な / A-な + である / N + である + ばかりに', 'N2', 'đơn giản là vì; chỉ vì (với một kết quả tồi tệ)', 'Mệnh đề chính là một kết quả không mong muốn, thường kèm theo sự tiếc nuối. Dạng cố định 〜たいばかりに (''chỉ vì ai đó muốn'') giải thích một động cơ mạnh mẽ.', '[{"jp": "確認を一つ怠ったばかりに、大きな損害を出してしまった。", "vi": "Vì sơ suất kiểm tra một điều, tôi đã gây ra tổn thất lớn."}, {"jp": "正直に話したばかりに、かえって彼女を傷つけてしまった。", "vi": "Dù tôi đã nói với cô ấy sự thật nhưng cuối cùng tôi lại khiến cô ấy tổn thương nhiều hơn."}, {"jp": "英語ができないばかりに、せっかくのチャンスを逃した。", "vi": "Tôi đã bỏ lỡ cơ hội tuyệt vời này vì tôi không thể nói được tiếng Anh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ばかりだ', 'V-る(thể từ điển) + ばかりだ', 'N2', 'giữ (trở nên tồi tệ hơn); chỉ tiếp tục', 'Thay đổi liên tục theo một hướng, hầu như luôn luôn theo hướng tồi tệ hơn. 〜一方だ (N3) cũng tương tự nhưng cũng có thể diễn tả xu hướng trung tính hoặc tốt.', '[{"jp": "駅前の商店街は、客が減るばかりだ。", "vi": "Lượng khách hàng ở khu mua sắm trước nhà ga ngày càng giảm."}, {"jp": "薬を飲んでいるのに、症状は悪くなるばかりだ。", "vi": "Mặc dù tôi đang dùng thuốc nhưng các triệu chứng của tôi vẫn ngày càng nặng hơn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜はもちろん / 〜はもとより', 'N + はもちろん / N + はもとより', 'N2', 'chưa kể; tất nhiên ... và cả', 'A là trường hợp hiển nhiên; B được thêm bằng も hoặc まで. 〜はもとより trang trọng và được viết hơn 〜はもちろん.', '[{"jp": "この公園は、週末はもちろん平日も家族連れでにぎわう。", "vi": "Công viên này đông đúc các gia đình không chỉ vào cuối tuần mà cả các ngày trong tuần."}, {"jp": "この料理教室では、基本の調理法はもとより、盛り付けのコツまで教えてもらえる。", "vi": "Trong lớp học nấu ăn này, bạn không chỉ học các phương pháp nấu ăn cơ bản mà còn học các mẹo bày biện."}, {"jp": "地震の後、電気はもちろん、水道もガスも止まってしまった。", "vi": "Sau trận động đất, không chỉ điện mà cả nước và khí đốt cũng bị cắt."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜はともかく', 'N + はともかく / N + はともかくとして', 'N2', 'đặt sang một bên; bất kể ; bất cứ điều gì về', 'Đặt A sang một bên để tập trung vào B, điều mà người nói cho là quan trọng hơn. So sánh 〜はさておき, được sử dụng nhiều hơn để tạm gác một chủ đề và tiếp tục.', '[{"jp": "見た目はともかく、味はなかなかいい。", "vi": "Bất kể hình thức bên ngoài, hương vị khá ngon."}, {"jp": "結果はともかくとして、最後まで諦めなかったことは評価したい。", "vi": "Bất kể kết quả thế nào, tôi cũng muốn khen ngợi anh ấy vì đã không bỏ cuộc cho đến phút cuối cùng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜はさておき', 'N + はさておき', 'N2', 'bỏ qua một bên; gạt sang một bên (bây giờ)', 'Thường được dùng để chuyển sang ý chính, như trong 冗談はさておき hoặc それはさておき. Trang trọng hơn 〜はともかく một chút.', '[{"jp": "冗談はさておき、そろそろ本題に入りましょう。", "vi": "Đùa giỡn sang một bên, hãy bắt tay vào công việc."}, {"jp": "費用の問題はさておき、まずは実現可能かどうかを検討すべきだ。", "vi": "Gạt vấn đề chi phí sang một bên, trước tiên chúng ta nên xem xét liệu điều đó có khả thi hay không."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜反面 / 〜半面', 'V(thể thông thường) / A-い / A-な + な / A-な + である / N + である + 反面', 'N2', 'mặt khác; trong khi (nó là...)', 'Trình bày hai mặt đối lập của cùng một sự việc. 〜一方で (N3) rộng hơn và cũng có thể tương phản hai thứ khác nhau.', '[{"jp": "都会の暮らしは便利な反面、ストレスも多い。", "vi": "Sống ở thành phố rất thuận tiện nhưng cũng có thể rất căng thẳng."}, {"jp": "インターネットは情報を手軽に得られる反面、誤った情報も広まりやすい。", "vi": "Mặc dù Internet giúp việc lấy thông tin trở nên dễ dàng nhưng nó cũng khiến thông tin sai lệch dễ dàng lan truyền."}, {"jp": "彼は仕事には厳しい反面、部下思いの一面もある。", "vi": "Dù nghiêm khắc trong công việc nhưng anh cũng rất quan tâm đến cấp dưới."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ながら（も）', 'V-ます(bỏ ます) / V-ない / A-い / A-な / N + ながら（も）', 'N2', 'mặc dù ; cho dù; trong khi (trái với mong đợi)', 'Không phải ''trong khi làm'' ながら: chủ ngữ ở trạng thái A, nhưng B lại đúng. Đặt các cụm từ: 残念ながら, 知りながら, 及ばずながら.', '[{"jp": "狭いながらも、日当たりのいい快適な部屋だ。", "vi": "Đó là một căn phòng nhỏ nhưng thoải mái, có nhiều ánh sáng mặt trời."}, {"jp": "悪いと知りながら、つい嘘をついてしまった。", "vi": "Tôi đã nói dối dù tôi biết điều đó là sai."}, {"jp": "彼女は若いながらも、しっかりした考えを持っている。", "vi": "Tuy còn trẻ nhưng cô ấy có những ý tưởng mạnh mẽ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜つつ / 〜つつも', 'V-ます(bỏ ます) + つつ / V-ます(bỏ ます) + つつも', 'N2', 'trong khi (làm); mặc dù, ngay cả khi', 'riêng つつ là viết 〜ながら (hai hành động cùng một lúc). つつも có nghĩa là ''mặc dù'', thường đi kèm với các động từ chỉ biết hoặc suy nghĩ (思いつつ, 知りつつ).', '[{"jp": "今年の業績を振り返りつつ、来年の目標を考えたい。", "vi": "Tôi muốn nhìn lại những thành tựu đã đạt được trong năm nay và nghĩ về những mục tiêu của năm tới."}, {"jp": "体に悪いと分かりつつも、夜更かしがやめられない。", "vi": "Dù biết điều đó có hại cho sức khỏe nhưng tôi không thể ngừng thức khuya."}, {"jp": "早く返事をしなければと思いつつ、もう一週間もたってしまった。", "vi": "Tôi nghĩ mình nên trả lời nhanh nhưng đã một tuần rồi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜つつある', 'V-ます(bỏ ます) + つつある', 'N2', 'Đang dần dần... (Xu hướng biến đổi)', 'Phong cách viết dành cho sự thay đổi đang được tiến hành hướng tới một kết quả nào đó. Được sử dụng với các động từ thay đổi (増える, 回復する, 変わる), không phải với các hành động đơn giản đang diễn ra như 食べる.', '[{"jp": "地球の平均気温は、年々上昇しつつある。", "vi": "Nhiệt độ trung bình của trái đất đang tăng lên hàng năm."}, {"jp": "この地域の伝統的な祭りは、若者の減少とともに失われつつある。", "vi": "Các lễ hội truyền thống ở vùng này đang dần biến mất khi số lượng người trẻ ngày càng giảm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜っぱなし', 'V-ます(bỏ ます) + っぱなし', 'N2', 'để lại (cái gì đó) như cũ; tiếp tục (làm) không nghỉ ngơi', 'Hoặc là có việc gì đó chưa được làm xong mà lẽ ra phải được giải quyết (thường là lời phàn nàn) hoặc là một trạng thái tiếp diễn không ngừng nghỉ. Đàm thoại.', '[{"jp": "部屋の電気をつけっぱなしにして出かけてしまった。", "vi": "Tôi để đèn trong phòng sáng rồi đi ra ngoài."}, {"jp": "今日は朝から立ちっぱなしで、足が痛い。", "vi": "Tôi đã đứng từ sáng nay và chân tôi bị đau."}, {"jp": "窓を開けっぱなしにしないでください。", "vi": "Đừng để cửa sổ mở."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜抜く', 'V-ます(bỏ ます) + 抜く', 'N2', 'làm đến cùng; nhìn xuyên qua; làm kỹ lưỡng', 'Nhấn mạnh việc hoàn thành một việc gì đó dù khó khăn hay khó khăn, hoặc làm nó một cách trọn vẹn (考え抜く, 生き抜く).', '[{"jp": "足を痛めていたが、彼は最後まで走り抜いた。", "vi": "Dù bị thương ở chân nhưng anh vẫn chạy đến cuối cùng."}, {"jp": "悩み抜いた末に出した結論なので、後悔はない。", "vi": "Tôi không hề hối hận vì đã đi đến kết luận này sau nhiều suy nghĩ."}, {"jp": "チームは苦しい試合で一点のリードを守り抜いた。", "vi": "Đội đã dẫn trước một điểm trong một trận đấu khó khăn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜得る / 〜得ない', 'V-ます(bỏ ます) + 得る / V-ます(bỏ ます) + 得ない', 'N2', 'có thể; có thể/không thể; là không thể', 'Khả năng logic, không phải kỹ năng cá nhân (không phải ×泳ぎ得る nghĩa là ''có thể bơi''). Tích cực được đọc là うる hoặc える; các dạng khác sử dụng え- (えない, えた).', '[{"jp": "どんなに注意していても、事故は起こり得る。", "vi": "Dù bạn có cẩn thận đến đâu thì tai nạn vẫn có thể xảy ra."}, {"jp": "あの真面目な彼が犯人だなんて、あり得ない。", "vi": "Không thể nào một kẻ nghiêm túc như vậy lại là thủ phạm được."}, {"jp": "今回の調査で、これまで知り得なかった事実が明らかになった。", "vi": "Cuộc điều tra này đã tiết lộ những sự thật mà trước đây chưa được biết đến."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜がたい', 'V-ます(bỏ ます) + がたい', 'N2', 'khó ; gần như không thể (về mặt cảm xúc)', 'Dùng với động từ chỉ sự suy nghĩ và cảm xúc (信じる, 理解する, 許す, 離れる). Không giống như 〜にくい, không phải vì khó khăn về thể chất (×この肉は食べがたい).', '[{"jp": "あの誠実な人が不正をしたとは、信じがたい。", "vi": "Thật khó để tin rằng một người trung thực như vậy lại có thể lừa dối."}, {"jp": "彼の失礼な態度は、どうにも許しがたい。", "vi": "Hành vi thô lỗ của anh ta là không thể chấp nhận được."}, {"jp": "生まれ育った町は、やはり離れがたいものだ。", "vi": "Thật khó để rời khỏi thị trấn nơi bạn sinh ra và lớn lên."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ようがない', 'V-ます(bỏ ます) + ようがない / N + の + しようがない', 'N2', 'không có cách nào để; không thể (không có phương tiện nào có sẵn)', 'Không có phương pháp nào cả, ngay cả khi người ta muốn. 〜ようもない được nhấn mạnh hơn. Với danh từ suru: 説明のしようがない.', '[{"jp": "連絡先が分からないので、知らせようがない。", "vi": "Tôi không biết thông tin liên lạc của bạn nên không thể cho bạn biết."}, {"jp": "これだけ証拠がそろっていては、言い訳のしようがない。", "vi": "Với rất nhiều bằng chứng, không có lời bào chữa nào cả."}, {"jp": "壊れた部品がもう生産されていないので、直しようがない。", "vi": "Vì bộ phận bị hỏng không còn được sản xuất nên không có cách nào khắc phục được."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ようでは', 'V(thể thông thường) + ようでは', 'N2', 'nếu (bạn cứ thế này/cứ làm thế này), (không ổn đâu)', 'Chỉ trích một trạng thái không mong muốn và dự đoán một kết quả xấu; mệnh đề chính là phủ định (〜ない, 困る, だめだ).', '[{"jp": "こんな簡単なミスをするようでは、大きな仕事は任せられない。", "vi": "Nếu mắc phải một sai lầm đơn giản như vậy, bạn sẽ không được giao phó một công việc lớn lao nào."}, {"jp": "毎朝遅刻しているようでは、信頼を得られないよ。", "vi": "Bạn sẽ không có được sự tin tưởng nếu bạn đến muộn vào mỗi buổi sáng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てならない', 'V-て + ならない / A-い-ku + てならない / A-な + でならない', 'N2', 'không thể giúp được (cảm giác); cảm thấy khủng khiếp; cực kỳ', 'Dành cho những cảm xúc hoặc ấn tượng tự nảy sinh (気がする, 思われる, 心配だ, 残念だ). Trang trọng và được viết hơn 〜てたまらない / 〜てしょうがない.', '[{"jp": "故郷の母のことが心配でならない。", "vi": "Tôi không khỏi lo lắng cho mẹ ở quê nhà."}, {"jp": "あのとき本当のことを言わなかったのが、悔やまれてならない。", "vi": "Tôi rất tiếc đã không nói sự thật vào thời điểm đó."}, {"jp": "この計画には何か裏があるような気がしてならない。", "vi": "Tôi không thể không cảm thấy như có điều gì đó đằng sau kế hoạch này."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てこそ', 'V-て + こそ', 'N2', 'chỉ bằng (làm); chỉ khi', 'Nhấn mạnh rằng A là điều kiện thiết yếu cho giá trị thực hoặc kết quả tạo ra B. 〜てはじめて (N3) trung tính hơn, tập trung vào thời điểm.', '[{"jp": "自分で経験してこそ、本当の意味で理解できるのだ。", "vi": "Chỉ bằng cách tự mình trải nghiệm, bạn mới có thể thực sự hiểu được nó."}, {"jp": "お互いに協力し合ってこそ、チームは強くなる。", "vi": "Một đội trở nên mạnh mẽ hơn khi chúng ta hợp tác với nhau."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てからでないと', 'V-て + からでないと / V-て + からでなければ', 'N2', 'không cho đến khi (sau khi làm); chỉ sau', 'Mệnh đề chính mang tính phủ định hoặc thể hiện sự khó khăn: B không thể xảy ra trừ khi A được thực hiện trước.', '[{"jp": "実物を見てからでないと、買うかどうか決められない。", "vi": "Tôi không thể quyết định có nên mua nó hay không cho đến khi tôi nhìn thấy nó trực tiếp."}, {"jp": "この薬は、医師に相談してからでなければ服用しないでください。", "vi": "Không dùng thuốc này mà không hỏi ý kiến ​​​​bác sĩ trước."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜て以来', 'V-て + 以来 / N + 以来', 'N2', 'kể từ đó', 'Mệnh đề chính là một trạng thái hoặc một thói quen tiếp diễn từ thời điểm quá khứ đó đến nay, không một sự kiện nào sau đó. Trang trọng hơn 〜てから.', '[{"jp": "大学を卒業して以来、彼とは一度も会っていない。", "vi": "Tôi đã không gặp anh ấy một lần kể từ khi tôi tốt nghiệp đại học."}, {"jp": "この町に越してきて以来、毎朝川沿いを散歩するのが日課になっている。", "vi": "Kể từ khi tôi chuyển đến thị trấn này, việc đi dạo dọc bờ sông mỗi sáng đã trở thành thói quen hàng ngày của tôi."}, {"jp": "創業以来、この店は同じ味を守り続けている。", "vi": "Kể từ khi thành lập đến nay, nhà hàng này vẫn giữ nguyên hương vị đó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に過ぎない', 'V(thể thông thường) / N + に過ぎない', 'N2', 'Chỉ đơn thuần là... / Không hơn không kém', 'Hạ thấp một cái gì đó nhỏ hoặc không quan trọng. Thường đi kèm với ただ hoặc 単なる.', '[{"jp": "それは単なるうわさに過ぎない。", "vi": "Đó chỉ là tin đồn thôi."}, {"jp": "私は自分の仕事をしたに過ぎません。", "vi": "Tôi chỉ đang làm công việc của mình thôi."}, {"jp": "今回明らかになった問題は、氷山の一角に過ぎない。", "vi": "Những vấn đề được bộc lộ lần này chỉ là phần nổi của tảng băng chìm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に限る', 'V-る(thể từ điển) / V-ない / N + に限る', 'N2', 'không có gì nhịp đập; điều tốt nhất là', 'Niềm tin cá nhân của người nói rằng điều gì đó là sự lựa chọn tốt nhất; đàm thoại. Để nói ''tốt nhất là'' tổng quát hơn, hãy sử dụng 〜に越したことはない.', '[{"jp": "疲れたときは、早く寝るに限る。", "vi": "Khi nào mệt thì hãy đi ngủ sớm."}, {"jp": "夏の暑い日は、冷たいビールに限る。", "vi": "Vào những ngày hè nóng bức, một ly bia lạnh là tất cả những gì bạn cần."}, {"jp": "面倒なことには関わらないに限る。", "vi": "Miễn là bạn không dính vào những chuyện rắc rối."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に限らず', 'N + に限らず', 'N2', 'không chỉ; không giới hạn ở', 'Mở rộng phạm vi ra ngoài A; phần thứ hai thường có も. Gần giống với 〜だけでなく nhưng trang trọng hơn một chút.', '[{"jp": "この遊園地は、子どもに限らず大人にも人気がある。", "vi": "Công viên giải trí này được yêu thích không chỉ với trẻ em mà cả người lớn."}, {"jp": "日本に限らず、多くの先進国が少子化の問題を抱えている。", "vi": "Nhiều nước phát triển, không chỉ Nhật Bản, đang phải đối mặt với vấn đề tỷ lệ sinh giảm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に限って', 'N + に限って', 'N2', 'của tất cả (lần/người); chính xác là khi nào; (ai đó) trong số tất cả mọi người sẽ không', 'Hai cách sử dụng: (1) ''đúng lúc'', phàn nàn rằng vận rủi ập đến vào thời điểm tồi tệ nhất; (2) với はずがない / ない, tin tưởng chắc chắn rằng một người cụ thể sẽ không làm điều gì đó.', '[{"jp": "傘を持っていない日に限って、雨が降るんだよね。", "vi": "Trời chỉ mưa vào những ngày không có ô."}, {"jp": "急いでいるときに限って、電車が遅れる。", "vi": "Xe lửa chỉ bị trễ khi bạn đang vội."}, {"jp": "うちの子に限って、そんなことをするはずがない。", "vi": "Không đời nào con tôi lại làm những việc như vậy."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に限り', 'N + に限り', 'N2', 'giới hạn ở ; chỉ (cho)', 'Chính thức; điển hình của các thông báo, quảng cáo và quy tắc để nêu rõ điều kiện áp dụng cho ai hoặc cái gì.', '[{"jp": "本日ご来店のお客様に限り、全商品を二割引きいたします。", "vi": "Chúng tôi đang giảm giá 20% cho tất cả các sản phẩm cho khách hàng ghé thăm cửa hàng của chúng tôi ngay hôm nay."}, {"jp": "先着百名様に限り、記念品を差し上げます。", "vi": "100 người đầu tiên sẽ nhận được quà lưu niệm."}, {"jp": "この駐車場は、住民に限り無料で利用できる。", "vi": "Bãi đậu xe này chỉ miễn phí cho cư dân."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かぎり', 'V-る(thể từ điển) / V-て + いる / A-い / A-な + である / N + である + かぎり', 'N2', 'chừng nào ; đến mức (đến giới hạn của)', '''Miễn là'' có điều kiện, hoặc ''trong chừng mực'' giới hạn của kiến ​​thức hoặc khả năng (私の知るかぎり, できるかぎり). Cũng được viết là 限り. Khác với 〜に限り (giới hạn).', '[{"jp": "私の知るかぎり、彼が約束を破ったことは一度もない。", "vi": "Theo tôi biết thì anh ấy chưa bao giờ thất hứa."}, {"jp": "体が動くかぎり、この仕事を続けたい。", "vi": "Tôi muốn tiếp tục làm công việc này miễn là cơ thể tôi còn cử động được."}, {"jp": "できるかぎりのことはやったので、結果がどうなっても悔いはない。", "vi": "Tôi đã làm tất cả những gì có thể, nên tôi không hề hối tiếc dù kết quả có thế nào đi chăng nữa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ないかぎり', 'V-ない + かぎり', 'N2', 'trừ khi; miễn là ... không', 'B giữ được chừng nào A không xảy ra. Nhấn mạnh và trang trọng hơn 〜なければ.', '[{"jp": "よほどのことがないかぎり、明日の会議には出席します。", "vi": "Tôi sẽ tham dự cuộc họp ngày mai trừ khi có vấn đề đặc biệt."}, {"jp": "本人が反省しないかぎり、同じ問題は何度でも起こるだろう。", "vi": "Trừ khi bản thân người đó ăn năn, vấn đề tương tự sẽ xảy ra nhiều lần."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にかけては', 'N + にかけては / N + にかけても', 'N2', 'khi nói đến; về mặt (kỹ năng)', 'Khen ngợi khả năng của ai đó trong một lĩnh vực cụ thể; thường được theo sau bởi 誰にも負けない, 一番だ, 自信がある.', '[{"jp": "料理の腕にかけては、うちの父は誰にも負けない。", "vi": "Tài nấu ăn của bố tôi không ai sánh bằng."}, {"jp": "彼女は数字の分析にかけては、社内で右に出る者がいない。", "vi": "Cô ấy là người không ai sánh kịp trong công ty về khả năng phân tích các con số."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にこたえて', 'N + にこたえて / N + にこたえる + N', 'N2', 'để đáp lại; cuộc họp (mong đợi, yêu cầu)', 'Dùng với các danh từ như 期待, 要望, 声援, 要求. Cũng được viết là 〜に応えて. So sánh 〜に応じて, có nghĩa là điều chỉnh theo một điều kiện.', '[{"jp": "ファンの声援にこたえて、選手たちは手を振った。", "vi": "Các cầu thủ vẫy tay chào lại sự cổ vũ của người hâm mộ."}, {"jp": "利用者の要望にこたえて、図書館の開館時間が延長された。", "vi": "Để đáp ứng yêu cầu của người dùng, giờ mở cửa thư viện đã được kéo dài."}, {"jp": "彼は周囲の期待にこたえる結果を出した。", "vi": "Anh ấy đã đạt được những kết quả đáp ứng được sự mong đợi của những người xung quanh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に先立って', 'N + に先立って / V-る(thể từ điển) + に先立って / N + に先立つ + N', 'N2', 'trước ; trước đây', 'Chính thức; để chuẩn bị hoặc sự kiện xảy ra trước một dịp quan trọng. 〜に先立ち là dạng viết.', '[{"jp": "新作映画の公開に先立って、完成披露試写会が開かれた。", "vi": "Trước khi phát hành bộ phim mới, một buổi chiếu xem trước đã được tổ chức để giới thiệu thành phẩm."}, {"jp": "試合開始に先立ち、全員で黙とうをささげた。", "vi": "Trước khi trận đấu bắt đầu, mọi người đều giữ im lặng một lúc."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にしろ / 〜にせよ', 'V(thể thông thường) / A-い / A-な / N + にしろ・にせよ', 'N2', 'ngay cả khi; liệu ... hay ...; trong mọi trường hợp', 'Cùng nghĩa với 〜にしても (N3) nhưng trang trọng hơn; にせよ được viết nhiều nhất. Dạng ghép AにしろBにしろ có nghĩa là ''A hay B''.', '[{"jp": "たとえ冗談にしろ、そんなことを言うべきではない。", "vi": "Dù là đùa cũng không nên nói như vậy."}, {"jp": "参加するにせよしないにせよ、今週中に返事をください。", "vi": "Dù bạn có quyết định tham gia hay không, vui lòng phản hồi trước cuối tuần này."}, {"jp": "いずれにせよ、もう一度話し合う必要がある。", "vi": "Dù thế nào đi nữa, chúng ta cần nói chuyện lại."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にすれば / 〜にしたら', 'N + にすれば / N + にしたら', 'N2', 'từ quan điểm của; cho (ai đó), (có vẻ như vậy)', 'Tưởng tượng mọi thứ sẽ như thế nào từ vị trí của người khác (thường không phải của người nói). Không giống như 〜にとって, nó tập trung vào cảm xúc hoặc quan điểm của người đó.', '[{"jp": "子どもにすれば、親の小言はうるさいだけなのだろう。", "vi": "Đối với trẻ em, sự cằn nhằn của cha mẹ có lẽ chỉ khiến chúng khó chịu."}, {"jp": "毎日遅くまで残業させられる社員にしたら、たまったものではない。", "vi": "Nếu bạn có những nhân viên bị buộc phải làm thêm giờ đến khuya mỗi ngày thì thật không thể chịu nổi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に相違ない', 'V(thể thông thường) / A-い / A-な / N + に相違ない', 'N2', 'không nghi ngờ gì nữa; phải thế; chắc chắn', 'Một dạng viết, trang trọng tương đương với 〜に違いない (N3). Cũng thấy trên các biểu mẫu: 上記の通り相違ありません (''điều trên là chính xác'').', '[{"jp": "この筆跡は、父のものに相違ない。", "vi": "Chữ viết này chắc chắn là của bố tôi."}, {"jp": "彼の証言が事実なら、事件の背後には別の人物がいるに相違ない。", "vi": "Nếu lời khai của anh ta là đúng thì chắc chắn phải có người khác đứng sau vụ việc."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に越したことはない', 'V-る(thể từ điển) / V-ない / A-い / A-な / N + に越したことはない', 'N2', 'tốt nhất là nên; không có gì tốt hơn', 'Thể hiện sự ưa thích thông thường, thường theo sau là が / けれど và một sự dè dặt thực tế. So sánh 〜に限る, đó là sự lựa chọn cá nhân hơn.', '[{"jp": "どんなに健康でも、定期的に検診を受けるに越したことはない。", "vi": "Dù bạn có khỏe mạnh đến đâu thì việc kiểm tra sức khỏe định kỳ luôn là điều nên làm."}, {"jp": "旅行の荷物は、軽いに越したことはない。", "vi": "Khi đi du lịch, tốt hơn hết bạn nên mang theo hành lý nhẹ nhàng."}, {"jp": "住まいは駅に近いに越したことはないが、その分家賃が高くなる。", "vi": "Tốt hơn là sống gần nhà ga hơn, nhưng giá thuê nhà cũng sẽ cao hơn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にほかならない', 'N + にほかならない / V(thể thông thường) + から + にほかならない', 'N2', 'không có gì khác hơn; không ai khác hơn là; chính xác', 'Khẳng định mạnh mẽ rằng điều này và không có gì khác là trường hợp. 〜からにほかならない nhấn mạnh một lý do. Chính thức/bằng văn bản.', '[{"jp": "今回の成功は、社員一人ひとりの努力の結果にほかならない。", "vi": "Thành công này là kết quả của sự nỗ lực của mỗi nhân viên."}, {"jp": "彼が厳しく指導するのは、選手の才能を信じているからにほかならない。", "vi": "Lý do ông huấn luyện các cầu thủ một cách nghiêm khắc là vì ông tin vào tài năng của các cầu thủ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にもかかわらず', 'V(thể thông thường) / A-い / A-な + である / N + にもかかわらず', 'N2', 'Mặc dù... bất chấp...', 'Một dạng tương đương trang trọng của 〜のに, phổ biến trong tin tức và văn viết; nhấn mạnh rằng kết quả đi ngược lại với những gì A mong đợi. Đừng nhầm lẫn với 〜にかかわらず (bất kể cái nào).', '[{"jp": "悪天候にもかかわらず、大勢の観客が会場に集まった。", "vi": "Bất chấp thời tiết xấu, rất đông khán giả vẫn tập trung tại địa điểm thi đấu."}, {"jp": "何度も注意されたにもかかわらず、彼は同じミスを繰り返した。", "vi": "Mặc dù đã được cảnh cáo nhiều lần nhưng anh vẫn mắc lỗi tương tự."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にあたって', 'N + にあたって / V-る(thể từ điển) + にあたって / N + にあたっての + N', 'N2', 'khi; vào thời điểm đó; nhân dịp (bắt đầu một việc gì đó quan trọng)', 'Chính thức; được sử dụng khi phải đối mặt với một công việc quan trọng, thường với ý thức chuẩn bị hoặc quyết tâm. 〜に際して cũng tương tự nhưng chỉ đơn giản là đánh dấu sự kiện. Dạng viết: 〜にあたり.', '[{"jp": "新生活を始めるにあたって、必要な物をリストにまとめた。", "vi": "Tôi đã soạn ra một danh sách những thứ tôi cần để bắt đầu cuộc sống mới của mình."}, {"jp": "開会にあたり、主催者を代表して一言ご挨拶申し上げます。", "vi": "Nhân dịp khai mạc sự kiện, tôi xin thay mặt ban tổ chức gửi vài lời chúc mừng."}, {"jp": "論文を書くにあたっては、引用のルールを守らなければならない。", "vi": "Khi viết một bài báo, bạn phải tuân theo các quy tắc trích dẫn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜において / 〜における', 'N + において / N + における + N', 'N2', 'ở ; Tại; trong lĩnh vực (chính thức)', 'Phiên bản trang trọng của で dùng để chỉ địa điểm, thời gian, lĩnh vực hoặc tình huống. Trước một danh từ, có dạng 〜における.', '[{"jp": "卒業式は大講堂において行われます。", "vi": "Lễ tốt nghiệp sẽ được tổ chức tại hội trường lớn."}, {"jp": "現代社会における家族の役割について考えてみたい。", "vi": "Tôi muốn nghĩ về vai trò của gia đình trong xã hội hiện đại."}, {"jp": "彼女はデザインの分野において高く評価されている。", "vi": "Cô được đánh giá cao trong lĩnh vực thiết kế."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にかかわらず', 'N + にかかわらず / V-る(thể từ điển) + V-ない + にかかわらず', 'N2', 'bất kể ; bất kể', 'Dùng với các danh từ ám chỉ một phạm vi hoặc một cặp đối lập (年齢, 天候, 有無, 男女). Rất gần với 〜を問わず. Đừng nhầm lẫn với 〜にもかかわらず (mặc dù).', '[{"jp": "このセミナーは、経験の有無にかかわらず、どなたでも参加できます。", "vi": "Hội thảo này dành cho tất cả mọi người, bất kể kinh nghiệm."}, {"jp": "天候にかかわらず、試合は予定通り行います。", "vi": "Trận đấu sẽ diễn ra theo lịch trình bất kể thời tiết."}, {"jp": "出席するしないにかかわらず、必ず返信してください。", "vi": "Hãy chắc chắn trả lời dù bạn có tham dự hay không."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にかかわる', 'N + にかかわる', 'N2', 'ảnh hưởng; liên quan (điều gì đó quan trọng); liên quan đến', 'Dùng cho những việc gây hậu quả nghiêm trọng: 命, 名誉, 信用, 将来. Cũng được viết 〜に関わる.', '[{"jp": "これは人の命にかかわる問題だから、慎重に判断しなければならない。", "vi": "Đây là vấn đề ảnh hưởng tới đời sống người dân nên chúng ta phải đưa ra các quyết định thận trọng."}, {"jp": "会社の信用にかかわるようなミスは、絶対に避けたい。", "vi": "Bạn chắc chắn muốn tránh mắc phải những sai lầm ảnh hưởng đến uy tín của công ty."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜につき', 'N + につき', 'N2', 'mỗi; cho mỗi người; do (trong thông báo chính thức)', 'Hai cách sử dụng riêng biệt: ''per'' với số lượng và ''vì'' trên các thông báo và biển hiệu (工事中につき). Lý do sử dụng là rất trang trọng.', '[{"jp": "駐車料金は、一時間につき三百円です。", "vi": "Phí đỗ xe là 300 yên mỗi giờ."}, {"jp": "本日は定休日につき、お休みさせていただきます。", "vi": "Hôm nay chúng tôi sẽ đóng cửa vì đây là ngày nghỉ lễ bình thường."}, {"jp": "工事中につき、この先は通行止めです。", "vi": "Con đường hiện đang bị đóng cửa không cho xe cộ qua lại do đang thi công."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に向けて', 'N + に向けて / N + に向けた + N', 'N2', 'về phía ; nhằm vào; đang chuẩn bị cho; gửi tới', 'Đánh dấu một mục tiêu hoặc sự kiện đang được hướng tới hoặc khán giả có điều gì đó hướng tới. Khác với 〜向け (N3), ''được thiết kế cho''.', '[{"jp": "来年の全国大会に向けて、毎日練習に励んでいる。", "vi": "Anh ấy đang luyện tập chăm chỉ mỗi ngày để chuẩn bị cho giải đấu quốc gia vào năm tới."}, {"jp": "政府は、温室効果ガス削減に向けた新しい計画を発表した。", "vi": "Chính phủ đã công bố một kế hoạch mới để giảm lượng khí thải nhà kính."}, {"jp": "大統領は国民に向けてメッセージを発表した。", "vi": "Tổng thống đã gửi thông điệp tới toàn dân."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜のもとで / 〜のもとに', 'N + のもとで / N + のもとに', 'N2', 'dưới (hướng dẫn, ảnh hưởng, một quy tắc); với', 'Dưới sự hướng dẫn, bảo vệ hoặc ảnh hưởng của ai đó, hoặc dưới một quy tắc hoặc điều kiện. Thường được viết là 〜の下で / 〜の下に.', '[{"jp": "私は大学院で、有名な教授のもとで研究を続けた。", "vi": "Tôi tiếp tục nghiên cứu ở trường cao học dưới sự hướng dẫn của một giáo sư nổi tiếng."}, {"jp": "明るい太陽のもとで、子どもたちが元気に遊んでいる。", "vi": "Trẻ em vui đùa vui vẻ dưới ánh nắng tươi sáng."}, {"jp": "すべての国民は、法のもとに平等である。", "vi": "Mọi công dân đều bình đẳng trước pháp luật."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜抜きで / 〜抜きに', 'N + 抜きで / N + 抜きに / N + 抜きの + N', 'N2', 'không có; bỏ đi', 'Bỏ đi một số thứ thường được đưa vào. 〜抜きには〜ない / 〜を抜きにしては〜ない có nghĩa là ''không thể... không có''.', '[{"jp": "今日は仕事の話抜きで、ゆっくり楽しみましょう。", "vi": "Hôm nay hãy thư giãn và tận hưởng mà không nói về công việc."}, {"jp": "彼の協力抜きには、このプロジェクトは成功しなかっただろう。", "vi": "Nếu không có sự hợp tác của anh ấy, dự án này sẽ không thể thành công."}, {"jp": "朝食抜きで出勤する人が増えている。", "vi": "Ngày càng có nhiều người đi làm mà không ăn sáng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をこめて', 'N + をこめて', 'N2', 'với (cảm giác); đầy ; đưa ... vào', 'Dùng với cảm xúc hoặc ý định (愛, 感謝, 願い, 心). Cũng được viết là 〜を込めて.', '[{"jp": "母の誕生日に、感謝の気持ちをこめて手紙を書いた。", "vi": "Vào ngày sinh nhật của mẹ tôi, tôi đã viết một lá thư để bày tỏ lòng biết ơn của mình."}, {"jp": "職人が一つ一つ心をこめて作った器です。", "vi": "Mỗi tác phẩm đều được thực hiện bởi một nghệ nhân với sự cẩn thận tuyệt vời."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を中心に', 'N + を中心に / N + を中心として / N + を中心とした + N', 'N2', 'Lấy... làm trung tâm, chủ yếu là...', 'A là phần cốt lõi hoặc phần chính của một khu vực, nhóm hoặc hoạt động rộng hơn.', '[{"jp": "今回の地震では、沿岸部を中心に大きな被害が出た。", "vi": "Trận động đất này gây ra thiệt hại lớn chủ yếu ở các khu vực ven biển."}, {"jp": "この講座では、会話を中心に実践的な日本語を学びます。", "vi": "Trong khóa học này, bạn sẽ học tiếng Nhật thực tế, tập trung vào hội thoại."}, {"jp": "若者を中心とした新しいファッションが広がっている。", "vi": "Thời trang mới đang lan rộng, đặc biệt là trong giới trẻ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をもとに', 'N + をもとに / N + をもとにして / N + をもとにした + N', 'N2', 'dựa vào; sử dụng ... làm cơ sở hoặc nguồn', 'A là chất liệu hoặc gợi ý để từ đó tạo ra một điều gì đó mới mẻ. 〜に基づいて được sử dụng khi tuân thủ nghiêm ngặt một quy tắc hoặc thực tế nào đó như một tiêu chuẩn.', '[{"jp": "この小説は、作者自身の体験をもとに書かれている。", "vi": "Cuốn tiểu thuyết này được viết dựa trên kinh nghiệm của chính tác giả."}, {"jp": "集めたデータをもとにして、グラフを作成した。", "vi": "Một biểu đồ được tạo ra dựa trên dữ liệu được thu thập."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を問わず', 'N + を問わず', 'N2', 'Không phân biệt... / Bất kể...', 'Dùng với các danh từ hàm ý một phạm vi hoặc một cặp đối lập (男女, 昼夜, 国内外). Rất gần với 〜にかかわらず; を問わず là điển hình của các quảng cáo và thông báo việc làm.', '[{"jp": "この仕事は、年齢や経験を問わず応募できます。", "vi": "Công việc này dành cho mọi lứa tuổi và kinh nghiệm."}, {"jp": "この曲は国内外を問わず、多くの人々に愛されている。", "vi": "Bài hát này được nhiều người yêu thích cả ở Nhật Bản và nước ngoài."}, {"jp": "救急隊員は、昼夜を問わず出動に備えている。", "vi": "Lực lượng cứu hộ sẵn sàng ứng phó cả ngày lẫn đêm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をはじめ', 'N + をはじめ / N + をはじめとして / N + をはじめとする + N', 'N2', 'Trước tiên phải kể đến là...', 'Nêu tên thành viên tiêu biểu nhất của nhóm, sau đó đề cập đến cả nhóm. Mệnh đề chính bao gồm nhiều mục, không chỉ A.', '[{"jp": "京都には、金閣寺をはじめ、多くの有名な寺がある。", "vi": "Kyoto có nhiều ngôi chùa nổi tiếng, trong đó có Kinkaku-ji."}, {"jp": "社長をはじめとして、社員全員がこの計画に賛成した。", "vi": "Tất cả nhân viên, kể cả chủ tịch, đều tán thành kế hoạch này."}, {"jp": "米をはじめとする農産物の価格が上昇している。", "vi": "Giá nông sản, trong đó có gạo, đang tăng cao."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を〜として', 'N + を + N + として / N + を + N + とする', 'N2', 'xử lý (A) như (B); với A là B', 'Đặt A vào vai trò hoặc chức năng của B; Các danh từ B phổ biến là 目的, 目標, 中心, 対象, 条件. 〜を〜にして là một biến thể thông thường hơn.', '[{"jp": "この大会は、地域の活性化を目的として開かれている。", "vi": "Giải đấu này được tổ chức với mục đích hồi sinh khu vực."}, {"jp": "私たちのチームは、営業部の山口さんをリーダーとして新しい企画に取り組んでいる。", "vi": "Nhóm của chúng tôi đang thực hiện một dự án mới với ông Yamaguchi từ bộ phận bán hàng là trưởng nhóm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かというと', 'V(thể thông thường) / A-い / A-な / N + かというと / Question word + … + かというと', 'N2', 'nếu bạn hỏi liệu (thực ra là không); lý do tại sao... là', 'Với từ để hỏi (なぜ, どうして) nó đưa ra lời giải thích. Không có ai, nó chỉ đặt ra một câu hỏi để phủ nhận giả định dễ dàng (〜かというと、そうではない). Ngoài ra 〜かといえば.', '[{"jp": "高い料理ならおいしいかというと、必ずしもそうではない。", "vi": "Đồ ăn đắt tiền không nhất thiết có nghĩa là nó ngon."}, {"jp": "なぜこの仕事を選んだかというと、人の役に立ちたかったからです。", "vi": "Lý do tôi chọn công việc này là vì tôi muốn giúp đỡ mọi người."}, {"jp": "では、彼の意見に全面的に賛成かというと、そういうわけでもない。", "vi": "Bây giờ, điều đó không có nghĩa là tôi hoàn toàn đồng ý với ý kiến ​​của anh ấy."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かと思ったら / 〜かと思うと', 'V-た + かと思ったら / V-た + かと思うと', 'N2', 'đúng lúc; không sớm hơn; khoảnh khắc', 'B đi theo A ngay lập tức và bất ngờ. Nó mô tả những gì người nói quan sát được, vì vậy nó không được sử dụng cho hành động của chính người nói.', '[{"jp": "空が急に暗くなったかと思ったら、激しい雨が降り出した。", "vi": "Bầu trời đột nhiên tối sầm lại, sau đó bắt đầu mưa to."}, {"jp": "息子は帰ってきたかと思うと、すぐにまた遊びに出かけた。", "vi": "Vừa lúc tôi tưởng con trai đã về đến nhà thì nó lại ra ngoài chơi ngay."}, {"jp": "やっと静かになったかと思ったら、また隣の工事が始まった。", "vi": "Ngay khi tôi nghĩ mọi chuyện cuối cùng đã yên tĩnh lại thì công việc xây dựng ở nhà bên cạnh lại bắt đầu."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜か〜ないかのうちに', 'V-る(thể từ điển) + か + V-ない + かのうちに / V-た + か + V-ない + かのうちに', 'N2', 'ngay khi ; hầu như không ... khi', 'Động từ tương tự được lặp lại ở dạng tích cực và tiêu cực: không rõ liệu A có hoàn thành trước khi B xảy ra hay không. Mô tả các sự kiện được quan sát.', '[{"jp": "ベルが鳴るか鳴らないかのうちに、生徒たちは教室を飛び出した。", "vi": "Học sinh có chạy ra khỏi lớp trước khi chuông reo hay không."}, {"jp": "彼は布団に入ったか入らないかのうちに、いびきをかき始めた。", "vi": "Anh ấy bắt đầu ngáy khi đang ở dưới chăn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜きり', 'V-た + きり / N + きり', 'N2', 'kể từ (và không có gì sau đó); chỉ một; chỉ', 'Động từ-ta + きり: điều gì đó đã xảy ra và điều tiếp theo được mong đợi không bao giờ đến (thường đi kèm với ない). Danh từ + きり: ''chỉ'' (一度きり, 二人きり). Bình thường: 〜っきり.', '[{"jp": "兄は十年前に家を出たきり、一度も連絡をよこさない。", "vi": "Anh trai tôi đã rời nhà mười năm trước và chưa bao giờ liên lạc với tôi."}, {"jp": "今度の休みは、久しぶりに二人きりで旅行したい。", "vi": "Kỳ nghỉ sắp tới này, lần đầu tiên tôi muốn đi du lịch một mình."}, {"jp": "チャンスは一度きりだから、絶対に失敗できない。", "vi": "Bạn chỉ có một cơ hội, vì vậy bạn không thể thất bại."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜げ', 'A-い(bỏ い) + げ / A-な + げ / V-ます(bỏ ます) + たげ', 'N2', 'dường như ; nhìn (như thể); với một không khí', 'Mô tả cảm giác hiện rõ trên khuôn mặt hoặc thái độ của ai đó; liên hợp giống như tính từ na (〜げな, 〜げに). Đúng hơn là văn học.', '[{"jp": "彼女は窓の外を寂しげに見つめていた。", "vi": "Cô buồn bã nhìn ra ngoài cửa sổ."}, {"jp": "少年は得意げな顔で、描いた絵を見せてくれた。", "vi": "Cậu bé cho tôi xem bức tranh cậu đã vẽ với vẻ mặt đầy tự hào."}, {"jp": "何か言いたげな様子だったが、彼は黙って帰っていった。", "vi": "Anh ấy dường như muốn nói điều gì đó nhưng lại về nhà mà không nói một lời."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜っこない', 'V-ます(bỏ ます) + っこない', 'N2', 'Tuyệt đối không thể... / Làm sao mà... được', 'Chỉ lời nói thông thường; thường đi kèm với động từ tiềm năng (できっこない, 分かりっこない). Một cách thông thường tương đương với 〜わけがない.', '[{"jp": "こんな量の仕事、一日で終わりっこないよ。", "vi": "Khối lượng công việc này không thể hoàn thành trong một ngày."}, {"jp": "宝くじなんて当たりっこないと思いながら、毎年買っている。", "vi": "Tôi mua xổ số hàng năm và nghĩ rằng mình sẽ không bao giờ thắng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜どころか', 'V(thể thông thường) / A-い / A-な / N + どころか', 'N2', 'xa ; huống chi ; ngược lại', 'Hoặc thực tế đối lập với A, hoặc thậm chí không thể có thứ gì nhỏ hơn A (AどころかBも〜ない).', '[{"jp": "薬を飲んだが、熱は下がるどころか、ますます高くなった。", "vi": "Tôi đã uống thuốc nhưng thay vì hạ sốt thì cơn sốt lại càng tăng cao."}, {"jp": "忙しくて、旅行どころか週末に休むこともできない。", "vi": "Tôi bận đến mức không thể nghỉ cuối tuần chứ đừng nói đến việc đi du lịch."}, {"jp": "彼は謝るどころか、逆に私を責めてきた。", "vi": "Thay vì xin lỗi, anh lại đổ lỗi cho tôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜どころではない', 'V-る(thể từ điển) / N + どころではない', 'N2', 'đây không phải là lúc; không còn nghi ngờ gì nữa', 'Hoàn cảnh khiến A không thể hoặc không thể tưởng tượng được vào lúc này. Bình thường: 〜どころじゃない.', '[{"jp": "来週は試験なので、遊びに行くどころではない。", "vi": "Tuần sau tôi có bài kiểm tra nên không thể ra ngoài chơi được."}, {"jp": "引っ越しの準備に追われて、花見どころではなかった。", "vi": "Tôi không thể ngắm hoa anh đào vì bận chuẩn bị chuyển nhà."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とは限らない', 'V(thể thông thường) / A-い / A-な / N + とは限らない', 'N2', 'không nhất thiết; không phải lúc nào cũng vậy', 'Phủ nhận rằng điều gì đó luôn đúng; thường đi kèm với 必ずしも hoặc 〜からといって.', '[{"jp": "値段が高いからといって、品質がいいとは限らない。", "vi": "Chỉ vì giá cao không có nghĩa là chất lượng tốt."}, {"jp": "専門家の意見がいつも正しいとは限らない。", "vi": "Ý kiến ​​của chuyên gia không phải lúc nào cũng đúng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜というものだ', 'V(thể thông thường) / A-い / A-な / N + というものだ', 'N2', 'đó là những gì (A) là; nó vốn là vậy đó; đó thực sự là', 'Một quan điểm chắc chắn về cái gì đó thực sự là gì hoặc mọi thứ diễn ra một cách tự nhiên như thế nào. Thường dùng để chỉ trích một thái độ.', '[{"jp": "困っている人がいたら助ける。それが人情というものだ。", "vi": "Nếu ai đó gặp khó khăn, tôi sẽ giúp đỡ họ. Đó là nhân loại."}, {"jp": "何の準備もせずに合格しようなんて、虫がよすぎるというものだ。", "vi": "Sẽ là quá ngu ngốc nếu cố gắng vượt qua kỳ thi mà không có sự chuẩn bị nào."}, {"jp": "一人で全部やろうとするのは無理というものだ。", "vi": "Không thể cố gắng làm mọi việc một mình."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜というものではない', 'V(thể thông thường) / A-い / A-な / N + というものではない', 'N2', 'không phải (nhất thiết) như vậy; nó không tuân theo điều đó', 'Từ chối một niềm tin đơn giản hóa quá mức; thường đi kèm với 〜ばいい hoặc 〜さえ〜ば. 〜というものでもない là một biến thể nhẹ nhàng hơn.', '[{"jp": "練習は長くやればいいというものではない。", "vi": "Thực hành không cần phải lâu."}, {"jp": "お金さえあれば幸せになれるというものではない。", "vi": "Tiền không nhất thiết làm bạn hạnh phúc."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜といっても', 'V(thể thông thường) / A-い / A-な / N + といっても', 'N2', 'mặc dù tôi nói; mặc dù (nó được gọi là)', 'Sửa hoặc giới hạn những gì người nghe có thể thừa nhận từ câu nói đầu tiên. Thường theo sau là たった, ただ hoặc 〜しか〜ない.', '[{"jp": "料理ができるといっても、簡単なものしか作れません。", "vi": "Mặc dù tôi có thể nấu ăn nhưng tôi chỉ có thể làm những món đơn giản."}, {"jp": "海外に住んでいたといっても、たった半年のことだ。", "vi": "Mặc dù tôi sống ở nước ngoài nhưng cũng chỉ được nửa năm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜といえば / 〜というと', 'N + といえば / N + というと', 'N2', 'nói về ; khi bạn nghĩ đến; nếu bạn đề cập đến', 'Giới thiệu điều gì đó liên quan chặt chẽ đến một chủ đề hoặc chọn một từ vừa được đề cập để chuyển cuộc trò chuyện. 〜といったら là một biến thể giàu cảm xúc hơn.', '[{"jp": "日本の夏の風物詩といえば、やはり花火大会だろう。", "vi": "Khi nói đến truyền thống mùa hè của Nhật Bản, chắc chắn đó là màn bắn pháo hoa."}, {"jp": "北海道というと、広い大地とおいしい海産物を思い浮かべる人が多い。", "vi": "Khi nhắc đến Hokkaido, nhiều người nghĩ đến vùng đất rộng lớn và hải sản tươi ngon."}, {"jp": "旅行といえば、来月の出張の件はどうなりましたか。", "vi": "Nói về du lịch, chuyện gì đã xảy ra với chuyến công tác của bạn vào tháng tới?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ほかない', 'V-る(thể từ điển) + ほかない / V-る(thể từ điển) + よりほかない', 'N2', 'không có lựa chọn nào khác ngoài việc; không có gì để làm nhưng', 'Tương đương một cách trang trọng với 〜しかない (N3). Các biến thể: 〜ほかはない, 〜よりほかない, 〜ほかしかたがない.', '[{"jp": "終電を逃してしまったので、タクシーで帰るほかない。", "vi": "Tôi đã lỡ chuyến tàu cuối cùng nên không còn cách nào khác là bắt taxi về nhà."}, {"jp": "自分で決めた道なのだから、前に進むよりほかない。", "vi": "Đây là con đường tôi đã chọn cho mình nên tôi không còn cách nào khác là phải tiến về phía trước."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜まい', 'V-る(thể từ điển) + まい / V-ます(bỏ ます) (ichidan verbs) + まい', 'N2', 'sẽ không (giải quyết); có lẽ sẽ không (phỏng đoán)', 'Viết/chính thức. Ngôi thứ nhất: kiên quyết không làm (〜ないつもりだ). Khác: đoán tiêu cực (〜ないだろう). する → するまい / すまい. Thường là 〜まいと思う / 〜まいと決心する.', '[{"jp": "あんな恥ずかしい思いは、二度とするまいと心に誓った。", "vi": "Tôi tự thề với mình rằng tôi sẽ không bao giờ trải qua trải nghiệm đáng xấu hổ như vậy nữa."}, {"jp": "この大雨では、今日はもう誰も来るまい。", "vi": "Với cơn mưa lớn này, hôm nay sẽ không có ai đến."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜（よ）うではないか', 'V(thể ý chí) + ではないか / V(thể ý chí) + ではありませんか', 'N2', 'hãy (lời kêu gọi hành động chính thức); tại sao chúng ta không', 'Lời kêu gọi mạnh mẽ, trang trọng đối với một nhóm, điển hình trong các bài phát biểu và bài xã luận. Phiên bản thông thường là 〜(よ)うじゃないか.', '[{"jp": "この町の未来のために、皆で力を合わせようではないか。", "vi": "Tất cả chúng ta hãy cùng nhau làm việc vì tương lai của thị trấn này."}, {"jp": "失敗を恐れず、新しいことに挑戦してみようではありませんか。", "vi": "Đừng sợ thất bại và thử những điều mới."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜もかまわず', 'N + もかまわず / V(thể thông thường) + の + もかまわず', 'N2', 'không quan tâm đến; bất kể ; không chú ý đến', 'Làm việc gì đó mà không quan tâm đến điều mọi người thường quan tâm (人目, 周囲, 雨). Thường hàm ý không tán thành.', '[{"jp": "彼女は人目もかまわず、駅のホームで大声で泣いた。", "vi": "Cô khóc lớn trên sân ga mà không lo có ai nhìn thấy mình."}, {"jp": "服が汚れるのもかまわず、子どもたちは泥の中で遊び続けた。", "vi": "Bọn trẻ vẫn tiếp tục chơi đùa trong bùn, không thèm quan tâm đến việc quần áo chúng có bị bẩn hay không."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜上', 'N + 上 / N + 上の + N', 'N2', 'từ quan điểm của; về mặt ; vì lý do', 'Gắn với các danh từ Hán-Nhật (歴史上, 経験上, 健康上, 表面上). Đọc じょう, không phải うえ.', '[{"jp": "この映画には、教育上好ましくない場面が多い。", "vi": "Có nhiều cảnh trong phim này phản cảm về mặt giáo dục."}, {"jp": "安全上の理由から、この先には立ち入らないでください。", "vi": "Vì lý do an toàn, vui lòng không vượt quá điểm này."}, {"jp": "法律上は問題がなくても、道徳的に許されないこともある。", "vi": "Ngay cả khi không có vấn đề gì về mặt pháp lý, nó có thể không được chấp nhận về mặt đạo đức."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜おそれがある', 'V-る(thể từ điển) + おそれがある / N + の + おそれがある', 'N2', 'có nguy cơ đó; có thể (kết quả xấu)', 'Đối với những khả năng không mong muốn; điển hình của tin tức, báo cáo thời tiết và cảnh báo chính thức. Cũng được viết là 〜恐れがある. 〜かねない nghe giống sự đánh giá của chính người nói hơn.', '[{"jp": "台風の影響で、今夜から大雨になるおそれがあります。", "vi": "Do ảnh hưởng của bão nên có nguy cơ sẽ có mưa lớn bắt đầu từ tối nay."}, {"jp": "この薬は眠くなるおそれがあるので、服用後の運転は避けてください。", "vi": "Thuốc này có thể làm bạn buồn ngủ, vì vậy hãy tránh lái xe sau khi dùng thuốc."}, {"jp": "沿岸部には津波のおそれがあるため、避難指示が出された。", "vi": "Lệnh sơ tán đã được ban hành tại các khu vực ven biển do nguy cơ xảy ra sóng thần."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜せいか', 'V(thể thông thường) / A-い / A-な + な / N + の + せいか', 'N2', 'có lẽ vì; có lẽ do', 'Người nói không chắc chắn về nguyên nhân. Chủ yếu là cho kết quả xấu hoặc trung tính; để có kết quả tốt, おかげか cũng được sử dụng.', '[{"jp": "年のせいか、最近疲れが取れにくくなった。", "vi": "Có lẽ là do tuổi tác của tôi mà gần đây thật khó để tôi thoát khỏi sự mệt mỏi."}, {"jp": "昨夜遅くまで起きていたせいか、今日は頭がぼんやりしている。", "vi": "Hôm nay đầu óc tôi có chút sương mù, có lẽ là do tối qua tôi thức khuya."}, {"jp": "気のせいか、彼女は少し元気がないように見えた。", "vi": "Có lẽ đó chỉ là trí tưởng tượng của tôi, nhưng cô ấy có vẻ hơi khác thường."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜だけあって / 〜だけに', 'V(thể thông thường) / A-い / A-な + な / N + だけあって・だけに', 'N2', 'như có thể được mong đợi (vì); chính xác là vì; hơn thế nữa bởi vì', 'だけあって khen ngợi một kết quả phù hợp với mong đợi (thường đi kèm với さすが). だけに còn có nghĩa là ''thêm vì'' và có thể dẫn đến những kết quả tiêu cực.', '[{"jp": "さすが一流ホテルだけあって、サービスが行き届いている。", "vi": "Đúng như mong đợi từ một khách sạn hạng nhất, dịch vụ rất chu đáo."}, {"jp": "十年も日本に住んでいただけあって、彼の日本語はとても自然だ。", "vi": "Sống ở Nhật được 10 năm nên tiếng Nhật của anh ấy rất tự nhiên."}, {"jp": "期待していただけに、落選の知らせはショックだった。", "vi": "Đúng như tôi đã mong chờ, tin tôi bị từ chối đến như một cú sốc."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜だけのことはある', 'V(thể thông thường) / A-い / A-な + な / N + だけのことはある', 'N2', 'không có gì lạ; nó sống theo; như mong đợi của', 'Đánh giá một kết quả được chứng minh hoàn toàn bằng công sức, giá cả hoặc danh tiếng; thường đi kèm với さすが. Giống như 〜だけあって nhưng đặt ở cuối câu.', '[{"jp": "この料理は本当においしい。人気店だけのことはある。", "vi": "Món ăn này thực sự rất ngon. Có một số thứ chỉ có ở các cửa hàng bình dân."}, {"jp": "素晴らしい演奏だった。さすが毎日練習しているだけのことはある。", "vi": "Đó là một màn trình diễn tuyệt vời. Đúng như dự đoán, vấn đề chỉ là luyện tập hàng ngày mà thôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('たとえ〜ても', 'たとえ + V-て + も / たとえ + A-い-ku + ても / たとえ + A-な + でも / たとえ + N + でも', 'N2', 'ngay cả khi; không vấn đề gì', 'たとえ báo hiệu trước một giả thuyết ''ngay cả khi'' và củng cố nó. Một biến thể được viết nhiều hơn là たとえ〜としても.', '[{"jp": "たとえ反対されても、自分の夢を諦めるつもりはない。", "vi": "Ngay cả khi có sự phản đối, tôi cũng không có ý định từ bỏ ước mơ của mình."}, {"jp": "たとえ小さな会社でも、やりがいのある仕事がしたい。", "vi": "Ngay cả khi đó là một công ty nhỏ, tôi vẫn muốn làm một công việc xứng đáng."}, {"jp": "たとえ給料が安くても、好きな仕事なら続けられる。", "vi": "Ngay cả khi mức lương thấp, bạn vẫn có thể tiếp tục làm công việc mình thích."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜やら〜やら', 'N + やら + N + やら / V-る(thể từ điển) + やら + V-る(thể từ điển) + やら / A-い + やら + A-い + やら', 'N2', 'chuyện gì xảy ra với ... và ...; và ... và (trong số những thứ khác)', 'Liệt kê một vài ví dụ trong số rất nhiều ví dụ, thường gợi ý sự hỗn loạn hoặc cảm xúc lẫn lộn. Thường được theo sau bởi で + 大変だ / 忙しい.', '[{"jp": "引っ越しの前は、荷造りやら手続きやらで目が回るほど忙しかった。", "vi": "Trước khi chuyển đi, tôi rất bận rộn với việc đóng gói và các thủ tục."}, {"jp": "財布をなくして、情けないやら腹が立つやらで、泣きたくなった。", "vi": "Tôi bị mất ví, tôi cảm thấy thật thảm hại và tức giận đến mức muốn khóc."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ずに済む / 〜ないで済む', 'V-ない(bỏ ない) + ずに済む / V-ない + で済む', 'N2', 'vượt qua mà không có; không cần phải làm vậy; được tha khỏi', 'Một cái gì đó khó chịu hoặc tốn kém hóa ra lại không cần thiết. する → せずに済む. So sánh Danh từ + で済む, ''chỉ cần ...''.', '[{"jp": "友人が車で送ってくれたので、タクシーを使わずに済んだ。", "vi": "Bạn tôi đã chở tôi đi nên tôi không phải đi taxi."}, {"jp": "早めに治療を始めたおかげで、手術しないで済んだ。", "vi": "Nhờ điều trị sớm nên tôi tránh được phải phẫu thuật."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ようによっては', 'V-ます(bỏ ます) + ようによっては', 'N2', 'tùy thuộc vào cách (người ta làm điều đó)', 'Chủ yếu với 考え, 見, 言い, 使い: kết quả thay đổi tùy theo cách thực hiện A. Thường đưa ra cách giải thích tích cực.', '[{"jp": "考えようによっては、今回の失敗はいい教訓になったとも言える。", "vi": "Tùy thuộc vào cách bạn nghĩ về nó, bạn có thể nói rằng thất bại này đã dạy cho chúng ta một bài học hay."}, {"jp": "古い家具も、使いようによってはおしゃれなインテリアになる。", "vi": "Đồ nội thất cũ cũng có thể trở thành nội thất đầy phong cách tùy thuộc vào cách bạn sử dụng nó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜がてら', 'V-ます(bỏ ます) / N + がてら', 'N1', 'trong khi ; trên đường đi; tận dụng cơ hội của', 'Một chuyến đi chơi phục vụ hai mục đích; mệnh đề chính thường là chuyển động (行く, 寄る, 歩く). So sánh 〜かたがた (trang trọng, chào hỏi và thăm hỏi) và 〜かたわら (hai hoạt động dài hạn).', '[{"jp": "散歩がてら、駅前の本屋に寄って新刊をのぞいてきた。", "vi": "Khi đang đi dạo, tôi ghé vào hiệu sách trước nhà ga để mua sách mới."}, {"jp": "お客さんを駅まで送りがてら、郵便局で小包を出してきた。", "vi": "Sau khi thả khách hàng ở ga, tôi gửi một gói hàng ở bưu điện."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かたわら', 'V-る(thể từ điển) / N + の + かたわら', 'N1', 'đồng thời cũng ; bên cạnh (nghề nghiệp chính của một người)', 'Hai hoạt động được theo đuổi song song trong một thời gian dài (một công việc và một việc theo đuổi bên lề), không phải là hành động chỉ thực hiện một lần. Là một danh từ đơn giản, かたわら cũng có nghĩa là ''bên cạnh''.', '[{"jp": "彼女は会社勤めのかたわら、週末は日本語教室でボランティアをしている。", "vi": "Khi đang làm việc tại một công ty, cô tình nguyện tham gia lớp học tiếng Nhật vào cuối tuần."}, {"jp": "祖父は農業を営むかたわら、地元の歴史を研究して三冊の本にまとめた。", "vi": "Khi làm nông dân, ông tôi đã nghiên cứu lịch sử địa phương và biên soạn thành ba cuốn sách."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜が早いか', 'V-る(thể từ điển) + が早いか', 'N1', 'khoảnh khắc; không sớm hơn ... hơn', 'Hành động thứ hai diễn ra gần như ngay lập tức; nó nêu lên một sự kiện trong quá khứ, không bao giờ là một yêu cầu hay ý định. Từ gần đồng nghĩa: 〜や否や (trang trọng nhất), 〜なり (cùng chủ đề, thường gây ngạc nhiên), 〜そばから (lặp lại).', '[{"jp": "子どもたちは玄関を開けるが早いか、ランドセルを放り出して遊びに行ってしまった。", "vi": "Các em quá vội vàng mở cửa trước, hoặc vứt cặp đi học và ra ngoài chơi."}, {"jp": "開店のベルが鳴るが早いか、客たちは目当ての売り場へ駆け出した。", "vi": "Ngay khi tiếng chuông khai trương vang lên, khách hàng đã đổ xô đến tầng bán hàng mà mình mong muốn."}, {"jp": "彼は給料をもらうが早いか、全部競馬につぎ込んでしまった。", "vi": "Dù nhận được tiền lương nhưng anh ấy lại tiêu hết vào việc đua ngựa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜すら', 'N (+ particle) + すら', 'N1', 'thậm chí ; thậm chí không (một ví dụ cực đoan)', 'Một 〜さえ mang tính văn học hơn. Không giống như さえ, nó không được sử dụng trong cấu trúc 〜さえ〜ば (''giá như'').', '[{"jp": "高熱が三日も続き、水を飲むことすらつらかった。", "vi": "Tôi bị sốt cao trong ba ngày và thậm chí rất khó uống nước."}, {"jp": "この漢字は、専門家ですら読み間違えることがある。", "vi": "Ngay cả các chuyên gia đôi khi cũng có thể đọc sai chữ Hán này."}, {"jp": "彼は長年連れ添った妻にすら、病気のことを打ち明けなかった。", "vi": "Ông không tiết lộ bệnh tình của mình, kể cả với người vợ đã chung sống nhiều năm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ずくめ', 'N + ずくめ', 'N1', 'không có gì ngoài; toàn bộ; cái này... nối tiếp cái khác', 'Hoạt động với một số danh từ hạn chế (黒, いいこと, 規則, ごちそう, 結構). Không giống như だらけ hay まみれ nó có thể mang nghĩa tích cực và không có nghĩa là được che chắn về mặt vật lý.', '[{"jp": "昇進に結婚、新居の購入と、今年はいいことずくめの一年だった。", "vi": "Năm nay đầy những điều tốt đẹp: Tôi được thăng chức, kết hôn và mua một căn nhà mới."}, {"jp": "黒ずくめの服を着た男が、店の前をうろうろしている。", "vi": "Một người đàn ông mặc đồ đen đang lảng vảng trước cửa hàng."}, {"jp": "規則ずくめの寮生活に、入学早々うんざりしてしまった。", "vi": "Ngay khi bước vào đại học, tôi đã cảm thấy mệt mỏi vì phải sống trong ký túc xá với quá nhiều nội quy."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たら最後 / 〜が最後', 'V-た + ら最後 / V-た + が最後', 'N1', 'một lần... (không thể quay lại); nếu có ..., đó là kết thúc', 'Kết quả là xấu hoặc không thể đảo ngược và được tuyên bố một cách chắc chắn. 〜が最後 mang tính văn chương hơn một chút.', '[{"jp": "この子は一度泣き出したら最後、何をしても一時間は泣きやまない。", "vi": "Một khi đứa trẻ này bắt đầu khóc, dù tôi có làm gì đi nữa, nó sẽ không ngừng khóc suốt một tiếng đồng hồ."}, {"jp": "あの人に秘密を話したが最後、翌日には社内中に知れ渡っているだろう。", "vi": "Sau khi bạn nói cho người đó biết bí mật của mình, có thể ngày hôm sau nó sẽ được cả công ty biết đến."}, {"jp": "この契約書に一度判を押したら最後、後から取り消すことはできない。", "vi": "Hợp đồng này một khi đã được ký kết thì sau này không thể hủy bỏ được."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てからというもの', 'V-て + からというもの', 'N1', 'kể từ đó', 'Nhấn mạnh một sự thay đổi lâu dài, rõ rệt bắt đầu từ sự kiện đó; nhiều cảm xúc hơn so với 〜て以来 trung lập.', '[{"jp": "犬を飼い始めてからというもの、父は毎朝六時に起きるようになった。", "vi": "Kể từ khi chúng tôi có một con chó, bố tôi bắt đầu thức dậy lúc 6 giờ sáng mỗi ngày."}, {"jp": "彼女は留学から戻ってからというもの、見違えるほど積極的になった。", "vi": "Kể từ khi đi du học về, cô trở nên năng động đến khó tin."}, {"jp": "スマートフォンを手にしてからというもの、紙の本をほとんど読まなくなった。", "vi": "Từ khi có điện thoại thông minh, tôi gần như không còn đọc sách giấy nữa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てやまない', 'V-て + やまない', 'N1', 'không bao giờ ngừng; trân trọng; sâu sắc (hy vọng, tôn trọng, yêu thương)', 'Dùng với các động từ chỉ cảm giác như 願う, 祈る, 愛する, 尊敬する, 期待する. Điển hình của các bài phát biểu, thư từ và văn bản trang trọng.', '[{"jp": "皆様のご健康とご多幸を心より願ってやみません。", "vi": "Tôi chân thành chúc mọi người sức khỏe và hạnh phúc."}, {"jp": "恩師は、私が今も尊敬してやまない人物だ。", "vi": "Người cố vấn của tôi là người mà tôi vẫn rất kính trọng."}, {"jp": "この作家は、生涯故郷の海を愛してやまなかったという。", "vi": "Người ta nói rằng nhà văn này đã yêu quê hương, biển cả, suốt cuộc đời."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜と相まって', 'N + と相まって / N + も相まって', 'N1', 'Cùng kết hợp với... tạo nên...', 'Hai yếu tố củng cố lẫn nhau để tạo ra hiệu ứng mạnh mẽ hơn. Ngoài ra còn có AとBが相まって và 〜も相まって.', '[{"jp": "色づいた紅葉が澄んだ秋空と相まって、息をのむような景色をつくり出していた。", "vi": "Màu sắc thay đổi của lá mùa thu kết hợp với bầu trời mùa thu trong trẻo đã tạo nên một khung cảnh ngoạn mục."}, {"jp": "円安に規制緩和も相まって、訪日客の数は過去最高を記録した。", "vi": "Số lượng du khách đến Nhật Bản đã đạt mức cao nhất mọi thời đại do đồng Yên yếu và việc bãi bỏ quy định."}, {"jp": "誠実な人柄と確かな技術が相まって、彼の店は地元で厚い信頼を得ている。", "vi": "Nhờ tính cách chân thành và kỹ năng đáng tin cậy, cửa hàng của anh đã nhận được sự tin tưởng của cộng đồng địa phương."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ともなると / 〜ともなれば', 'N / V-る(thể từ điển) + ともなると / N / V-る(thể từ điển) + ともなれば', 'N1', 'khi nói đến; một lần (một mức độ hoặc giai đoạn nhất định) đạt được', 'Danh từ đánh dấu một địa vị, thời gian hoặc số lượng cao đáng kể; phần còn lại nêu rõ những gì tự nhiên đi kèm với nó.', '[{"jp": "大企業の社長ともなると、分刻みのスケジュールで動かなければならない。", "vi": "Khi trở thành chủ tịch của một công ty lớn, bạn phải làm việc theo lịch trình từng phút một."}, {"jp": "十二月ともなれば、この辺りの山はすっかり雪に覆われる。", "vi": "Đến tháng 12, những ngọn núi xung quanh đây hoàn toàn bị tuyết bao phủ."}, {"jp": "子どもが三人ともなると、毎月の食費だけでも相当な額になる。", "vi": "Khi bạn có ba đứa con, chỉ riêng chi phí ăn uống hàng tháng đã có thể tăng lên một số tiền đáng kể."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ならでは', 'N + ならではの + N / N + ならではだ', 'N1', 'duy nhất; điều đó chỉ ... có thể cung cấp', 'Hầu như luôn luôn khen ngợi. Văn học AならではBない có nghĩa là ''chỉ A mới có thể B''.', '[{"jp": "港町ならではの新鮮な魚介料理を、心ゆくまで味わった。", "vi": "Chúng tôi rất thích thú với những món hải sản tươi sống chỉ có thể tìm thấy ở một thị trấn cảng."}, {"jp": "細部まで行き届いたこの仕上がりは、熟練の職人ならではだ。", "vi": "Sự chú ý đến từng chi tiết này là kết quả của một nghệ nhân lành nghề."}, {"jp": "子どもならではの自由な発想に、大人たちは驚かされた。", "vi": "Người lớn ngạc nhiên trước lối suy nghĩ tự do mà chỉ trẻ em mới có được."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜べく', 'V-る(thể từ điển) + べく (する → すべく)', 'N1', 'để ; với mục đích', 'Phong cách viết trang trọng; する thường trở thành すべく. Mệnh đề chính không thể là một yêu cầu hoặc mệnh lệnh.', '[{"jp": "同社は海外市場に進出すべく、現地に新たな拠点を設けた。", "vi": "Công ty đã thành lập một cơ sở mới tại địa phương để mở rộng ra thị trường nước ngoài."}, {"jp": "彼は医師になるべく、働きながら夜間の予備校に通っている。", "vi": "Anh ấy đang làm việc và theo học trường dự bị ban đêm với hy vọng trở thành bác sĩ."}, {"jp": "被災地の復興を支援すべく、全国から多くのボランティアが集まった。", "vi": "Nhiều tình nguyện viên từ khắp nơi trên đất nước đã tập trung để hỗ trợ tái thiết các khu vực bị thiên tai."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜(よ)うものなら', 'V(thể ý chí) + ものなら', 'N1', 'nếu ai đó làm (điều gì đó khủng khiếp sẽ xảy ra)', 'Phóng đại sự nguy hiểm của một hành động. Đừng nhầm lẫn với 〜ものなら (N2), có dạng tiềm năng cho một điều ước không thể xảy ra: 行けるものなら行きたい.', '[{"jp": "父の前で母の料理に文句でも言おうものなら、大変なことになる。", "vi": "Nếu tôi thậm chí còn cố phàn nàn về việc mẹ nấu ăn trước mặt bố, tôi sẽ gặp rắc rối."}, {"jp": "この辺りは、少しでも雨が降ろうものなら、すぐに道路が冠水してしまう。", "vi": "Nếu trời mưa dù chỉ một chút ở khu vực này, đường sẽ ngập ngay lập tức."}, {"jp": "締め切りに一日でも遅れようものなら、二度と仕事をもらえなくなるだろう。", "vi": "Nếu bạn trễ thời hạn dù chỉ một ngày, bạn sẽ không bao giờ có được công việc khác."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に至る / 〜に至って / 〜に至っては', 'N / V-る(thể từ điển) + に至る / N / V-る(thể từ điển) + に至って / N + に至っては', 'N1', 'đạt được; dẫn đến ; chỉ khi nó đến; đối với (trường hợp cực đoan nhất)', 'に至る: đạt đến điểm (nghiêm trọng). に至って: chỉ một lần mọi việc đến mức đó. に至っては: giới thiệu ví dụ cực đoan nhất, thường là tiêu cực. Liên quan: 〜に至るまで ''xuống, thậm chí''.', '[{"jp": "小さな行き違いが、ついには両社の提携解消にまで至った。", "vi": "Một sự hiểu lầm nhỏ cuối cùng đã dẫn đến việc chấm dứt quan hệ đối tác giữa hai công ty."}, {"jp": "死者が出るに至って、市はようやく危険な交差点の改良に乗り出した。", "vi": "Chỉ sau khi xảy ra trường hợp tử vong, thành phố mới bắt đầu cải thiện nút giao thông nguy hiểm."}, {"jp": "最近の若者は新聞を読まないと言われるが、弟に至ってはテレビのニュースさえ見ない。", "vi": "Người ta nói giới trẻ ngày nay không đọc báo, nhưng em trai tôi thậm chí còn không xem thời sự trên TV."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を禁じ得ない', 'N + を禁じ得ない', 'N1', 'không thể không cảm thấy; không thể kìm nén (một cảm xúc)', 'Dùng với các danh từ chỉ cảm xúc như 怒り, 憤り, 同情, 驚き, 涙, 疑問. Chính thức; kỳ lạ đối với những cảm xúc tầm thường hàng ngày.', '[{"jp": "罪のない子どもたちが犠牲になったことに、深い憤りを禁じ得ない。", "vi": "Tôi không thể không cảm thấy phẫn nộ sâu sắc trước sự mất mát của những đứa trẻ vô tội."}, {"jp": "長年の苦労の末に夢をかなえた彼の姿に、涙を禁じ得なかった。", "vi": "Tôi không cầm được nước mắt khi chứng kiến ​​anh biến ước mơ của mình thành hiện thực sau nhiều năm làm việc chăm chỉ."}, {"jp": "当局の対応の遅さには、疑問を禁じ得ない。", "vi": "Người ta không thể không đặt câu hỏi về sự phản ứng chậm chạp của chính quyền."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を余儀なくされる', 'N + を余儀なくされる', 'N1', 'bị buộc phải ; không có lựa chọn nào khác ngoài việc', 'Danh từ này thường là danh từ suru chỉ một hành động không mong muốn (中止, 撤退, 変更, 入院). Chủ động 〜を余儀なくさせる có nghĩa là ''ép buộc (ai đó) phải''.', '[{"jp": "大型台風の接近により、多くの便が欠航を余儀なくされた。", "vi": "Nhiều chuyến bay buộc phải hủy do bão lớn đang đến gần."}, {"jp": "主力選手の相次ぐ負傷で、チームは戦術の大幅な変更を余儀なくされた。", "vi": "Do một loạt chấn thương của các cầu thủ chủ chốt, đội buộc phải thực hiện những thay đổi lớn về chiến thuật."}, {"jp": "住民たちは避難生活を余儀なくされ、今も仮設住宅で暮らしている。", "vi": "Người dân buộc phải sơ tán và vẫn đang sống trong những ngôi nhà tạm bợ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜あっての', 'N + あっての + N / N + あってのことだ', 'N1', '(chỉ) có thể vì; nợ mọi thứ', 'AあってのB: B chỉ tồn tại nhờ có A nên A là tất yếu. Thường bày tỏ lòng biết ơn.', '[{"jp": "お客様あっての商売ですから、どんな小さな声にも耳を傾けなければならない。", "vi": "Chúng ta kinh doanh vì khách hàng của mình nên chúng ta phải lắng nghe tiếng nói của họ, dù nhỏ đến đâu."}, {"jp": "今日の私があるのも、支えてくれた家族あってのことだ。", "vi": "Tôi có được như ngày hôm nay là nhờ gia đình đã ủng hộ tôi."}, {"jp": "健康あっての人生だ。体を壊すまで働いてはいけない。", "vi": "Cuộc sống là về sức khỏe. Đừng làm việc cho đến khi cơ thể bạn suy sụp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜いかんで / 〜いかんによらず', 'N (+ の) + いかんで / N (+ の) + いかんによらず', 'N1', 'tùy thuộc vào ; bất kể', 'Rất trang trọng (いかん = ''như thế nào, cái gì''). Các biến thể: 〜いかんによって / いかんでは (tùy theo); 〜いかんにかかわらず / いかんを問わず (bất kể).', '[{"jp": "来季の契約は、今シーズンの成績いかんで決まる。", "vi": "Hợp đồng ở mùa giải tới sẽ được xác định dựa trên thành tích ở mùa giải này."}, {"jp": "試験の結果いかんでは、留年もあり得る。", "vi": "Tùy thuộc vào kết quả của kỳ thi, có khả năng học sinh có thể học lại cùng năm đó."}, {"jp": "理由のいかんによらず、無断欠勤は認められない。", "vi": "Việc vắng mặt mà không được phép sẽ không được chấp nhận bất kể lý do."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜(よ)うが / 〜(よ)うと', 'V(thể ý chí) + が / V(thể ý chí) + と / A-い(bỏ い) + かろうが / A-な + だろうが / N + だろうが', 'N1', 'không có vấn đề gì (cái gì, như thế nào); ngay cả khi', 'Nhấn mạnh hơn 〜ても; thường đi kèm với các từ để hỏi (何を, どこへ, いくら) hoặc どんなに. Mệnh đề chính thể hiện kết quả không bị ảnh hưởng.', '[{"jp": "周りに何と言われようが、自分で決めた道を進むつもりだ。", "vi": "Dù mọi người có nói gì thì tôi vẫn sẽ đi theo con đường mà mình đã tự quyết định."}, {"jp": "どんなに忙しかろうと、彼は毎晩必ず子どもに絵本を読んでやる。", "vi": "Dù bận rộn đến đâu, anh vẫn luôn đọc truyện tranh cho con nghe mỗi tối."}, {"jp": "相手が上司だろうが、間違っていることははっきり指摘すべきだ。", "vi": "Ngay cả khi người kia là sếp của bạn, bạn cũng nên chỉ ra rõ ràng điều gì sai."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜(よ)うが〜まいが / 〜(よ)うと〜まいと', 'V(thể ý chí) + が + V-る(thể từ điển) + まいが / V(thể ý chí) + と + V-る(thể từ điển) + まいと', 'N1', 'có hay không; bất kể liệu', 'Động từ tương tự được lặp lại. Đối với động từ ichidan và する/来る, まい có thể gắn vào gốc nai: 認めまい, しまい (hoặc すまい), こまい.', '[{"jp": "君が賛成しようがしまいが、この計画はもう動き出している。", "vi": "Dù bạn có đồng ý hay không thì kế hoạch này vẫn đang được thực hiện."}, {"jp": "雨が降ろうと降るまいと、試合は予定どおり行われる。", "vi": "Dù trời mưa hay không, trận đấu vẫn diễn ra như dự kiến."}, {"jp": "本人が認めようが認めまいが、証拠は明らかだ。", "vi": "Dù anh ta có thừa nhận hay không thì bằng chứng vẫn rõ ràng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜(よ)うにも〜ない', 'V(thể ý chí) + にも + V-ない (potential of the same verb)', 'N1', 'muốn (làm) nhưng không thể; dù có cố gắng cũng không thể', 'Một số hoàn cảnh bên ngoài cản trở hành động dự định. Động từ thứ hai thường là thế âm của cùng một động từ, hoặc 〜ようがない.', '[{"jp": "財布を家に忘れてきたので、昼ご飯を買おうにも買えなかった。", "vi": "Tôi quên ví ở nhà nên không mua được bữa trưa."}, {"jp": "大雪で電車が止まってしまい、帰ろうにも帰れない。", "vi": "Tàu dừng do tuyết rơi dày nên tôi có muốn về nhà cũng không được."}, {"jp": "当時の記録がすべて失われており、確かめようにも確かめようがない。", "vi": "Tất cả hồ sơ từ thời điểm đó đã bị mất và không có cách nào để xác minh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かぎりだ', 'A-い / A-な + な + かぎりだ', 'N1', 'vô cùng; Tôi cảm thấy như vậy (cảm xúc)', 'Thể hiện cảm xúc mạnh mẽ của người nói bằng các tính từ cảm xúc (うれしい, 寂しい, 心細い, うらやましい, 残念な). Không sử dụng cho cảm xúc của người khác.', '[{"jp": "長年の夢だった自分の店をついに開くことができ、うれしいかぎりだ。", "vi": "Tôi rất vui khi cuối cùng cũng có thể mở được cửa hàng của riêng mình, đây là ước mơ của tôi trong nhiều năm."}, {"jp": "頼りにしていた先輩が来月で退職されるとは、心細いかぎりです。", "vi": "Thật đau buồn khi người đồng nghiệp cấp cao của tôi, người mà tôi tin cậy, sẽ nghỉ hưu vào tháng tới."}, {"jp": "若いのに三か国語を自在に操るなんて、うらやましいかぎりだ。", "vi": "Tôi rất ghen tị vì cậu ấy có thể nói được ba thứ tiếng một cách thoải mái như vậy dù còn rất trẻ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かたがた', 'N + かたがた', 'N1', 'đồng thời cũng ; một phần nhằm mục đích', 'Chính thức; thường đi kèm với お礼, ご挨拶, ご報告, お見舞い cộng với động từ thăm viếng (伺う, 訪ねる). So sánh 〜がてら thông thường và 〜かたわら (hoạt động dài hạn song song).', '[{"jp": "先日のお礼かたがた、ご挨拶に伺いたいと存じます。", "vi": "Tôi muốn gửi lời chào đến những người đã cảm ơn tôi ngày hôm trước."}, {"jp": "退院のご報告かたがた、入院中のお見舞いのお礼を申し上げます。", "vi": "Cảm ơn bạn đã báo cáo việc xuất viện và đã đến thăm chúng tôi trong thời gian bạn nằm viện."}, {"jp": "出張かたがた、久しぶりに恩師のお宅を訪ねた。", "vi": "Trong một chuyến công tác, lần đầu tiên tôi đã đến thăm nhà thầy."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かと思いきや', 'V(thể thông thường) / A-い / A-な / N + かと思いきや', 'N1', 'ngay khi người ta nghĩ...; trái với mong đợi', 'Kết quả trái ngược với những gì được mong đợi. Ngoài ra 〜と思いきや. Được tìm thấy trong bài viết và bài tiểu luận sống động hơn là trong bài phát biểu.', '[{"jp": "今年の冬は暖かいかと思いきや、二月に入って記録的な大雪に見舞われた。", "vi": "Tôi cứ tưởng mùa đông năm nay sẽ ấm áp nhưng vào tháng 2 chúng tôi đã phải hứng chịu một lượng tuyết kỷ lục."}, {"jp": "予約が取れないことで有名な店なので断られるかと思いきや、あっさり席が取れた。", "vi": "Tôi cứ tưởng mình sẽ bị từ chối vì nhà hàng nổi tiếng vì không thể đặt chỗ trước, nhưng tôi đã có thể dễ dàng có được chỗ ngồi."}, {"jp": "息子は宿題をしているのかと思いきや、机の下でゲームに夢中になっていた。", "vi": "Tôi tưởng con trai tôi đang làm bài tập về nhà nhưng nó lại đang mải mê chơi game dưới gầm bàn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜きらいがある', 'V-る(thể từ điển) / V-ない / N + の + きらいがある', 'N1', 'có xu hướng (xấu)', 'Luôn phê phán; phổ biến trong bình luận về thói quen hoặc thể chế của mọi người. So sánh 〜がち đàm thoại và 〜傾向がある trung tính.', '[{"jp": "彼は何事も自分一人で抱え込むきらいがある。", "vi": "Anh ấy có xu hướng giữ mọi thứ cho riêng mình."}, {"jp": "最近の報道は、視聴者の不安をいたずらにあおるきらいがある。", "vi": "Các bản tin gần đây có xu hướng gây lo lắng một cách không cần thiết cho người xem."}, {"jp": "この教授の論文は、結論を急ぎすぎるきらいがある。", "vi": "Bài viết của giáo sư này có xu hướng đưa ra những kết luận quá vội vàng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜極まる / 〜極まりない', 'A-な + 極まる / A-な + 極まりない', 'N1', 'vô cùng; hoàn toàn', 'Cả hai đều có nghĩa giống nhau; 極まりない ngày nay phổ biến hơn. Chủ yếu đi kèm với tính từ na phủ định (失礼, 危険, 不愉快, 退屈). 感極まる ''vượt qua cảm xúc'' là một cụm từ cố định.', '[{"jp": "公共の場で大声で電話をするなんて、迷惑極まりない。", "vi": "Thật khó chịu khi gọi điện thoại ồn ào ở nơi công cộng."}, {"jp": "雨の夜に無灯火で自転車に乗るのは、危険極まりない行為だ。", "vi": "Đi xe đạp không đèn vào đêm mưa là cực kỳ nguy hiểm."}, {"jp": "被害者を嘲笑するような彼の発言は、不謹慎極まる。", "vi": "Những bình luận nhạo báng nạn nhân của anh ta là vô cùng thiếu tôn trọng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜の極み', 'N + の極み', 'N1', 'chiều cao của; tối đa', 'Phổ biến với 光栄, 感激, 痛恨, ぜいたく, 疲労. So sánh 〜の至り, vốn được giới hạn ở một vài cụm từ cố định về cảm xúc của chính người nói.', '[{"jp": "決勝戦であのような凡ミスをしたことは、まさに痛恨の極みだ。", "vi": "Việc mắc phải một sai lầm đơn giản như vậy trong trận đấu cuối cùng thực sự là một điều vô cùng đáng tiếc."}, {"jp": "徹夜が三日続き、チームの全員が疲労の極みに達していた。", "vi": "Sau khi thức suốt đêm ba ngày, mọi người trong đội đều kiệt sức."}, {"jp": "一泊百万円のスイートとは、まさにぜいたくの極みだ。", "vi": "Một căn phòng có giá 1 triệu yên mỗi đêm là sự sang trọng bậc nhất."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ごとき / 〜ごとく', 'N + の + ごとく / V(thể thông thường) + (が) + ごとく / N + (の) + ごとき + N', 'N1', 'thích; BẰNG; (sau một người) sở thích của', 'Văn học tương đương với 〜ように / 〜ような. ごとき ngay sau khi một người tỏ ra khinh thường (お前ごとき) hoặc, đối với bản thân, sự khiêm tốn (私ごとき).', '[{"jp": "彼女は何事もなかったかのごとく、静かに微笑んでいた。", "vi": "Cô ấy chỉ cười nhẹ nhàng như không có chuyện gì xảy ra."}, {"jp": "前述のごとく、本研究の対象は二十代の社会人に限定している。", "vi": "Như đã đề cập ở trên, đối tượng của nghiên cứu này chỉ giới hạn ở những người trưởng thành đang đi làm ở độ tuổi 20."}, {"jp": "私ごとき若輩者が、このような大役を務めてよいのでしょうか。", "vi": "Liệu một người trẻ như tôi có nên đóng vai trò quan trọng như vậy không?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜こととて', 'V(thể thông thường) / A-な + な / N + の + こととて', 'N1', 'bởi vì ; vì (như một lời bào chữa hoặc lời xin lỗi)', 'Cổ hủ và trang trọng, chủ yếu là trong lời xin lỗi hoặc yêu cầu sự hiểu biết. Thường dùng với ぬ (知らぬこととて ''vì tôi không biết'').', '[{"jp": "何分にも不慣れなこととて、至らぬ点があればご容赦ください。", "vi": "Xin hãy tha thứ cho tôi nếu có bất kỳ sai sót nào vì tôi không quen với điều này."}, {"jp": "子どものしたこととて、今回ばかりは大目に見てやってください。", "vi": "Hãy bỏ qua những gì con bạn đã làm lần này."}, {"jp": "急なこととて、十分なおもてなしもできず失礼いたしました。", "vi": "Tôi xin lỗi vì không thể cung cấp đủ lòng hiếu khách cho bạn do sự cố bất ngờ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことなしに', 'V-る(thể từ điển) + ことなしに', 'N1', 'không có (làm)', 'Thường theo sau là điều không thể xảy ra (“không có A thì B không thể xảy ra”). Gần với 〜ことなく (N2), nghĩa đơn giản là “không làm gì”.', '[{"jp": "基礎を固めることなしに、応用力は身につかない。", "vi": "Bạn không thể có được các kỹ năng ứng dụng nếu không củng cố những kiến ​​thức cơ bản."}, {"jp": "彼は誰にも相談することなしに、会社を辞めてしまった。", "vi": "Anh ấy rời công ty mà không hỏi ý kiến ​​ai."}, {"jp": "痛みを伴うことなしに、この改革を成し遂げることはできない。", "vi": "Cuộc cải cách này không thể thực hiện được nếu không có đau đớn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜始末だ', 'V-る(thể từ điển) + 始末だ / この + 始末だ', 'N1', 'kết thúc (ở trạng thái tồi tệ); (sự việc) đã đến mức này', 'Một kết cục tồi tệ sau một loạt sự kiện, được kể lại với vẻ bực tức. Thường đi kèm với とうとう, ついには, 挙げ句の果てに.', '[{"jp": "弟は遊んでばかりいて、とうとう単位が足りずに留年する始末だ。", "vi": "Em trai tôi chỉ chơi đùa và cuối cùng phải lưu lại một lớp vì không có đủ tín chỉ."}, {"jp": "何度注意しても聞かず、ついには客の前で居眠りをする始末だった。", "vi": "Dù tôi có cảnh cáo bao nhiêu lần thì anh ấy vẫn không nghe và cuối cùng ngủ gục trước mặt khách."}, {"jp": "あれだけ準備は万全だと言っていたのに、この始末だ。", "vi": "Mặc dù tôi đã nói rằng tôi đã chuẩn bị đầy đủ nhưng mọi chuyện lại kết thúc như thế này."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ずじまい', 'V-ない(bỏ ない) + ずじまい (する → せずじまい)', 'N1', 'cuối cùng không bao giờ làm; chưa bao giờ đến gần', 'Tiếc nuối vì một hành động dự định đã không bao giờ xảy ra trước khi cơ hội trôi qua. Thông thường là 〜ずじまいだった / 〜ずじまいになった.', '[{"jp": "旅行中は雨続きで、楽しみにしていた山には登らずじまいだった。", "vi": "Trời tiếp tục mưa trong suốt chuyến đi nên tôi không thể leo được ngọn núi mà mình mong đợi."}, {"jp": "忙しさに追われ、結局恩師にお礼を言わずじまいになってしまった。", "vi": "Tôi bận quá nên không cảm ơn được thầy."}, {"jp": "彼女の本当の気持ちは、とうとう聞けずじまいだった。", "vi": "Cuối cùng, tôi không thể nghe được cảm xúc thật sự của cô ấy."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ずにはおかない / 〜ないではおかない', 'V-ない(bỏ ない) + ずにはおかない (する → せずにはおかない) / V-ない + ではおかない', 'N1', 'chắc chắn sẽ (làm); không thể thất bại (gây ra phản ứng)', 'Hai cách sử dụng: quyết tâm kiên quyết, hoặc điều gì đó chắc chắn gây ra cảm giác hoặc phản ứng. So sánh 〜ずにはいられない (N2), sự thôi thúc không thể cưỡng lại của bản thân.', '[{"jp": "彼女の力強い歌声は、聴く者の心を揺さぶらずにはおかない。", "vi": "Giọng hát nội lực của cô không khỏi làm lay động trái tim người nghe."}, {"jp": "今度という今度は、真相を突き止めずにはおかないぞ。", "vi": "Lần này tôi phải tìm ra sự thật."}, {"jp": "政府の今回の決定は、国民の反発を招かずにはおかないだろう。", "vi": "Quyết định của chính phủ có thể sẽ gây ra phản ứng dữ dội từ công chúng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ずにはすまない / 〜ないではすまない', 'V-ない(bỏ ない) + ずにはすまない (する → せずにはすまない) / V-ない + ではすまない', 'N1', 'phải (làm); sẽ không thoát khỏi nếu không (làm)', 'Nghĩa vụ xuất phát từ các chuẩn mực xã hội hoặc hoàn cảnh chứ không phải mong muốn cá nhân. 〜ずには済まされない là một biến thể mạnh hơn.', '[{"jp": "大切な花瓶を割ってしまったのだから、弁償せずにはすまないだろう。", "vi": "Vì đã làm vỡ một chiếc bình quý giá nên anh không còn cách nào khác ngoài việc đền bù."}, {"jp": "これほどの不祥事となれば、社長が責任を取らずにはすまない。", "vi": "Khi một vụ bê bối tầm cỡ này xảy ra, tổng thống không thể không chịu trách nhiệm."}, {"jp": "取引先に迷惑をかけた以上、直接謝りに行かないではすまない。", "vi": "Vì bạn đã gây rắc rối cho đối tác kinh doanh của mình nên không cần phải xin lỗi trực tiếp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜そばから', 'V-る(thể từ điển) / V-た + そばから', 'N1', 'ngay khi (và lặp đi lặp lại)', 'Một mô hình lặp đi lặp lại trong đó hành động thứ hai hủy bỏ hành động đầu tiên, thường gây thất vọng. Không giống như 〜や否や hay 〜なり, nó không được sử dụng cho một sự kiện diễn ra một lần.', '[{"jp": "片付けるそばから、子どもたちがおもちゃを散らかしていく。", "vi": "Khi tôi đang dọn dẹp, bọn trẻ bắt đầu vứt đồ chơi của chúng xuống."}, {"jp": "新しい単語は、覚えたそばから忘れてしまう。", "vi": "Tôi quên những từ mới ngay khi tôi học chúng."}, {"jp": "母がクッキーを焼くそばから、弟がつまみ食いしてしまう。", "vi": "Trong khi mẹ tôi nướng bánh quy, em trai tôi lại ăn vặt chúng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たりとも', 'N (一 + counter) + たりとも', 'N1', 'thậm chí không (một); không một ai', 'Gắn vào 一 + bộ đếm (一円, 一日, 一人, 一瞬) và theo sau là một câu phủ định hoặc cấm đoán. Ngoài ra 何人たりとも ''không có ai cả''.', '[{"jp": "税金を一円たりとも無駄にしてはならない。", "vi": "Không một đồng tiền thuế nào bị lãng phí."}, {"jp": "手術中は、一瞬たりとも気を抜くことができない。", "vi": "Trong quá trình phẫu thuật, bạn không thể thư giãn dù chỉ một giây."}, {"jp": "故郷で待つ家族のことを、一日たりとも忘れたことはない。", "vi": "Tôi chưa bao giờ quên dù chỉ một ngày gia đình đang chờ tôi ở quê nhà."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜だに', 'V-る(thể từ điển) + だに / N + だに', 'N1', 'thậm chí (chỉ); thậm chí không', 'Cổ xưa; tồn tại chủ yếu trong các cụm từ cố định: 想像するだに / 考えるだに (''chỉ nghĩ về nó thôi''), 微動だにしない, 想像だにしない /夢想だにしない (''thậm chí không bao giờ tưởng tượng được'').', '[{"jp": "あの事故の瞬間は、思い出すだに身震いがする。", "vi": "Tôi rùng mình khi nhớ lại khoảnh khắc xảy ra tai nạn đó."}, {"jp": "衛兵は一時間、微動だにせず立ち続けた。", "vi": "Người bảo vệ đứng bất động trong một giờ."}, {"jp": "自分の書いた小説が映画化されるとは、想像だにしなかった。", "vi": "Tôi chưa bao giờ tưởng tượng rằng cuốn tiểu thuyết tôi viết sẽ được dựng thành phim."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜たる', 'N + たる + N / N + たるもの', 'N1', 'như (một ở vị trí của); thích hợp', 'Nhấn mạnh các nhiệm vụ hoặc phẩm giá được mong đợi ở một vai trò. 〜たる者 / 〜たるもの được theo sau bởi những gì một người như vậy nên (không) làm.', '[{"jp": "教師たる者、生徒の前で模範を示さなければならない。", "vi": "Là giáo viên, bạn phải làm gương trước mặt học sinh."}, {"jp": "一国の首相たる人物が、このような軽率な発言をするとは嘆かわしい。", "vi": "Thật đáng trách khi một người là thủ tướng của một nước lại có thể phát biểu thiếu suy nghĩ như vậy."}, {"jp": "王者たる風格が、彼の立ち姿から漂っていた。", "vi": "Khí chất của một vị vua tỏa ra từ tư thế của ông."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜つ〜つ', 'V-ます(bỏ ます) + つ + V-ます(bỏ ます) + つ', 'N1', '(làm) A và B luân phiên nhau; qua lại', 'Chỉ trong các cụm từ có động từ trái nghĩa hoặc cặp chủ động/thụ động: 行きつ戻りつ, 持ちつ持たれつ, 抜きつ抜かれつ, 浮きつ沈みつ.', '[{"jp": "近所の人たちとは、持ちつ持たれつの関係でやってきた。", "vi": "Tôi đến sống với hàng xóm của mình thông qua mối quan hệ một đối một."}, {"jp": "彼は決心がつかず、店の前を行きつ戻りつしていた。", "vi": "Không thể quyết định được, anh đi đi lại lại trước cửa hàng."}, {"jp": "ゴール直前まで、二台の車は抜きつ抜かれつの接戦を繰り広げた。", "vi": "Hai chiếc xe đã giằng co cho đến ngay trước vạch đích."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜であれ / 〜であれ〜であれ', 'N + であれ / Question word + であれ / N + であれ + N + であれ', 'N1', 'bất cứ điều gì (nó là); bất cứ ai; dù là A hay B', 'Chữ viết tương đương với 〜でも / 〜だろうと. 〜であろうと và 〜であろうが là những biến thể gần giống nhau.', '[{"jp": "理由が何であれ、暴力は決して許されない。", "vi": "Bất kể lý do là gì, bạo lực sẽ không bao giờ được dung thứ."}, {"jp": "相手が誰であれ、礼儀をわきまえて接するべきだ。", "vi": "Dù người kia là ai thì bạn cũng nên đối xử lịch sự với họ."}, {"jp": "正社員であれアルバイトであれ、安全研修は全員が受けなければならない。", "vi": "Tất cả nhân viên, dù làm việc toàn thời gian hay bán thời gian, đều phải trải qua đào tạo về an toàn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てしかるべきだ', 'V-て + しかるべきだ / A-い-ku + て + しかるべきだ / A-な + であって + しかるべきだ', 'N1', 'nên ; nó sẽ chỉ là điều tự nhiên', 'Nói rõ điều gì là đúng đắn, thường ở dạng thụ động và thường hàm ý chỉ trích rằng điều đó đã không xảy ra. Tính từ しかるべき cũng có nghĩa là ''thích hợp''.', '[{"jp": "これだけの損害を出したのだから、経営陣は責任を問われてしかるべきだ。", "vi": "Ban quản lý phải chịu trách nhiệm về việc gây ra thiệt hại đó."}, {"jp": "長年会社に貢献してきた彼女は、もっと評価されてしかるべきだ。", "vi": "Cô ấy xứng đáng được ghi nhận nhiều hơn vì cô ấy đã đóng góp cho công ty trong nhiều năm."}, {"jp": "子どもの安全にかかわる問題なのだから、もっと早く対策が講じられてしかるべきだった。", "vi": "Vì đây là vấn đề an toàn cho trẻ em nên các biện pháp đối phó đáng lẽ phải được thực hiện sớm hơn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ではあるまいし', 'N + ではあるまいし / V-る(thể từ điển) + の + ではあるまいし', 'N1', 'nó không phải như thể (một người); vì (một) không phải', 'Tiếp theo là một bản án, lời khuyên hoặc mệnh lệnh. Mặc dù là まい trang trọng nhưng nó vẫn phổ biến trong lời nói, đặc biệt là 〜じゃあるまいし.', '[{"jp": "子どもではあるまいし、自分のことくらい自分で決めなさい。", "vi": "Bạn không phải là một đứa trẻ, vì vậy bạn nên đưa ra quyết định của riêng mình."}, {"jp": "一生会えなくなるわけではあるまいし、そんなに泣かないで。", "vi": "Không phải là anh sẽ không thể gặp em mãi mãi nên xin em đừng khóc nhiều như vậy nhé."}, {"jp": "神様じゃあるまいし、未来のことなんか分かるわけがないよ。", "vi": "Anh ấy không phải là Chúa, và anh ấy không thể nào biết được điều gì về tương lai."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜手前', 'V(thể thông thường) / N + の + 手前', 'N1', 'vì (xem xét nó trông như thế nào đối với người khác); không được xem xét cho', 'Bởi vì những gì một người đã nói hoặc vị trí của một người trước mặt người khác, người ta cảm thấy buộc phải hành động theo một cách nhất định. Thường theo sau là 〜わけにはいかない hoặc 〜しかない.', '[{"jp": "部下の手前、上司の私が弱音を吐くことはできなかった。", "vi": "Là cấp trên, tôi không thể phàn nàn trước mặt cấp dưới của mình."}, {"jp": "必ず合格すると宣言した手前、今さら受験をやめるとは言えない。", "vi": "Tôi không thể nói rằng tôi sẽ ngừng tham gia kỳ thi ngay bây giờ, mặc dù tôi đã tuyên bố rằng tôi chắc chắn sẽ vượt qua."}, {"jp": "子どもたちに約束を守れと言っている手前、親が約束を破るわけにはいかない。", "vi": "Trong khi cha mẹ đang bảo con cái hãy giữ lời hứa, họ không thể thất hứa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てもさしつかえない', 'V-て + もさしつかえない / A-い-ku + て + もさしつかえない / A-な + でもさしつかえない / N + でもさしつかえない', 'N1', 'không sao đâu; không có vấn đề gì nếu', 'Một 〜てもいい / 〜ても構わない trang trọng hơn, phổ biến trong kinh doanh, thông báo và hướng dẫn chính thức. Thường được viết 差し支えない.', '[{"jp": "書類は鉛筆で記入してもさしつかえありません。", "vi": "Bạn có thể điền vào các tài liệu bằng bút chì."}, {"jp": "急ぎの件でなければ、お返事は来週になってもさしつかえない。", "vi": "Nếu đó không phải là vấn đề khẩn cấp, bạn có thể trả lời vào tuần sau."}, {"jp": "応募資格は特にありませんので、未経験の方でもさしつかえありません。", "vi": "Không có bằng cấp cụ thể để nộp đơn, vì vậy những người không có kinh nghiệm đều được chào đón."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とあって', 'V(thể thông thường) / A-い / A-な / N + とあって', 'N1', 'bởi vì (của một tình huống đặc biệt); như nó vốn có', 'Nguyên nhân là một tình huống đặc biệt, đáng chú ý và mệnh đề chính tường thuật kết quả tự nhiên, được quan sát thấy của nó. Phổ biến trong tin tức; không được dùng cho mong muốn hoặc yêu cầu của chính người nói.', '[{"jp": "三連休の初日とあって、高速道路はどこも大渋滞だった。", "vi": "Vì đây là ngày đầu tiên của kỳ nghỉ cuối tuần kéo dài ba ngày nên giao thông trên tất cả các tuyến đường cao tốc đều bị ùn tắc nghiêm trọng."}, {"jp": "人気俳優が来店するとあって、店の前には早朝から長い行列ができた。", "vi": "Vì một diễn viên nổi tiếng đang ghé thăm cửa hàng nên hàng dài người đã xếp hàng trước cửa hàng từ sáng sớm."}, {"jp": "十年ぶりの再会とあって、二人は夜遅くまで語り合った。", "vi": "Vì đây là lần đoàn tụ đầu tiên sau mười năm nên cả hai đã trò chuyện đến khuya."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とあれば', 'V(thể thông thường) / N + とあれば', 'N1', 'nếu nó (cho); nếu (trường hợp đặc biệt như vậy) là như vậy', 'Một điều kiện đặc biệt mà theo đó một người sẽ có một ngoại lệ hoặc làm điều gì đó khó khăn. Thường xuyên 〜のためとあれば.', '[{"jp": "子どもの命を救うためとあれば、どんな犠牲も惜しまない。", "vi": "Tôi sẽ không tiếc hy sinh để cứu mạng sống của một đứa trẻ."}, {"jp": "社長直々の頼みとあれば、断るわけにはいかない。", "vi": "Nếu nó đến trực tiếp từ tổng thống, tôi không thể từ chối."}, {"jp": "好きな作家のサイン会とあれば、多少遠くても行かずにはいられない。", "vi": "Nếu có một buổi ký tặng của tác giả tôi yêu thích, tôi sẽ không thể không đi, dù có hơi xa một chút."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜といい〜といい', 'N + といい + N + といい', 'N1', 'cả A và B; về mặt A cũng như B', 'Chọn ra hai khía cạnh làm bằng chứng cho đánh giá tổng thể, tích cực hoặc tiêu cực. Không giống như 〜も〜も thông thường, nó mang ý nghĩa phán đoán của người nói.', '[{"jp": "この旅館は、料理といい接客といい、申し分ない。", "vi": "Nhà trọ này là nơi hoàn hảo cho thức ăn và dịch vụ khách hàng tốt."}, {"jp": "色といい形といい、この器は私の好みにぴったりだ。", "vi": "Chiếc bát này rất phù hợp với sở thích của tôi, cả về màu sắc lẫn hình dáng."}, {"jp": "兄といい弟といい、あの家の息子たちはどうしてこうも時間にルーズなのだろう。", "vi": "Tôi thắc mắc tại sao những đứa con trai của gia đình đó, một anh trai và một em trai, lại buông thả thời gian đến vậy."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜といったところだ', 'N / V-る(thể từ điển) + といったところだ', 'N1', 'nhiều nhất; Về; nhiều hay ít', 'Ước tính sơ bộ, khiêm tốn: số lượng hoặc mức độ không lớn. Thường đi kèm với せいぜい hoặc まあ. Ngoài ra 〜というところだ.', '[{"jp": "私の料理の腕前は、せいぜいカレーが作れるといったところだ。", "vi": "Kỹ năng nấu ăn của tôi chỉ giới hạn ở việc nấu cà ri."}, {"jp": "通勤時間は、ドアからドアまで三十分といったところです。", "vi": "Thời gian di chuyển từ nhà đến nhà khoảng 30 phút."}, {"jp": "今年の売り上げは、ほぼ昨年並みといったところだ。", "vi": "Doanh số bán hàng năm nay cũng gần bằng năm ngoái."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜といえども', 'V(thể thông thường) / A-い / A-な / N + といえども', 'N1', 'mặc dù ; thậm chí (ai đó thích)', 'Phiên bản chính thức của 〜といっても / 〜であっても: ngay cả người có địa vị đó cũng không được miễn. Thường đi kèm với いかなる hoặc たとえ.', '[{"jp": "子どもといえども、一人の人間として尊重されなければならない。", "vi": "Ngay cả trẻ em cũng phải được tôn trọng với tư cách cá nhân."}, {"jp": "いかなる権力者といえども、法の上に立つことは許されない。", "vi": "Dù bạn có mạnh mẽ đến đâu, bạn cũng không thể đứng trên luật pháp."}, {"jp": "経験豊かなベテランといえども、この天候での登山は危険だ。", "vi": "Ngay cả đối với những người leo núi có kinh nghiệm, việc leo núi trong thời tiết này rất nguy hiểm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜といったらない', 'A-い / A-な / N + といったらない', 'N1', 'không thể diễn tả được; vô cùng; ngoài lời nói', 'Hoạt động cho cả cảm giác tích cực và tiêu cực. Hình thức thông thường: 〜ったらない, và 〜といったらありゃしない (chỉ phủ định).', '[{"jp": "決勝戦で一点差で負けたときの悔しさといったらなかった。", "vi": "Tôi không thể diễn tả được cảm giác thất vọng của mình khi để thua một điểm trong trận chung kết."}, {"jp": "新しい部屋から見る夜景の美しさといったらない。", "vi": "Không gì có thể sánh bằng vẻ đẹp của cảnh đêm nhìn từ căn phòng mới của tôi."}, {"jp": "あの人の話は同じことの繰り返しで、退屈といったらない。", "vi": "Câu chuyện của người đó lặp đi lặp lại cùng một điều nên không hề nhàm chán chút nào."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ときたら', 'N + ときたら', 'N1', 'khi nói đến; về (khiếu nại)', 'Giới thiệu một người hoặc vật quen thuộc mà người nói đã chán ngán; những gì tiếp theo là một lời phàn nàn. Đàm thoại.', '[{"jp": "うちの夫ときたら、休みの日は一日中ソファでごろごろしている。", "vi": "Chồng tôi dành những ngày nghỉ nằm trên ghế cả ngày."}, {"jp": "最近のテレビ番組ときたら、どの局も似たような内容ばかりだ。", "vi": "Khi nói đến các chương trình truyền hình ngày nay, chúng đều có nội dung tương tự nhau."}, {"jp": "このパソコンときたら、肝心なときに限って固まってしまう。", "vi": "Máy tính này chỉ đóng băng vào những thời điểm quan trọng."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜としたところで / 〜にしたところで', 'V(thể thông thường) / N + としたところで / N + にしたところで', 'N1', 'ngay cả khi; thậm chí giả sử; ngay cả đối với (ai đó)', 'Giống như 〜としても / 〜にしても, nhưng nhấn mạnh rằng kết quả sẽ không thay đổi. Bình thường: 〜としたって / 〜にしたって.', '[{"jp": "今から急いだとしたところで、最終電車には間に合わないだろう。", "vi": "Cho dù bây giờ tôi có vội đi nữa thì tôi cũng sẽ không thể bắt kịp chuyến tàu cuối cùng."}, {"jp": "部長にしたところで、この問題の解決策を持っているわけではない。", "vi": "Ngay cả khi bạn bổ nhiệm anh ấy làm quản lý, anh ấy cũng không có giải pháp cho vấn đề này."}, {"jp": "仮に予算が倍になったとしたところで、人手が足りなければ計画は進まない。", "vi": "Ngay cả khi ngân sách tăng gấp đôi, kế hoạch sẽ không thể tiến hành nếu không đủ nhân lực."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とは', 'V(thể thông thường) / A-い / A-な / N + とは', 'N1', '(nghĩ) rằng...!; Tôi ngạc nhiên đó', 'Có thể kết thúc câu, không để lại phản ứng, hoặc theo sau là 思わなかった, 驚いた, v.v. Khác với định nghĩa 〜とは (''X có nghĩa là ...'').', '[{"jp": "あの真面目な彼が、会社の金に手をつけていたとは。", "vi": "Thật khó để tin rằng một người đàn ông nghiêm túc như vậy lại quản lý tiền của công ty."}, {"jp": "十年ぶりに訪れた故郷が、これほど様変わりしているとは思いもしなかった。", "vi": "Tôi không bao giờ ngờ rằng quê hương, nơi tôi đến thăm lần đầu tiên sau mười năm, lại khác đến thế."}, {"jp": "初めて出場した大会でいきなり優勝するとは、本人も驚いているに違いない。", "vi": "Chắc hẳn anh ấy rất bất ngờ khi bất ngờ giành chiến thắng trong giải đấu lần đầu tiên tham gia."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とばかりに', 'Mệnh đề + とばかりに', 'N1', 'như muốn nói', 'Mô tả thái độ hoặc cử chỉ của người khác dường như muốn nói điều gì đó mà không cần lời nói; không được sử dụng về bản thân. So sánh 〜んばかり (gần đạt đến trạng thái cực đoan).', '[{"jp": "店員は「早く帰れ」とばかりに、私たちのテーブルを片付け始めた。", "vi": "Người phục vụ bắt đầu dọn bàn và bảo chúng tôi về nhà sớm."}, {"jp": "相手のミスを見て、彼はここぞとばかりに攻め込んだ。", "vi": "Nhận thấy sai lầm của đối thủ, anh ta tấn công bằng toàn bộ sức lực của mình."}, {"jp": "息子は待ってましたとばかりに、誕生日プレゼントの包みを開けた。", "vi": "Con trai tôi mở quà sinh nhật như thể nó đã chờ đợi từ lâu."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ともなく / 〜ともなしに', 'V-る(thể từ điển) + ともなく / V-る(thể từ điển) + ともなしに / Question word + (particle) + ともなく', 'N1', 'vô nghĩa; nhàn rỗi; (với từ để hỏi) không có gì cụ thể', 'Động từ tương tự thường được lặp lại (見るともなく見る). Với các từ để hỏi: どこからともなく ''đặc biệt là từ hư không'', 誰からともなく ''ai đó hay ai đó''.', '[{"jp": "電車の中で、隣の二人の会話を聞くともなく聞いていた。", "vi": "Trên tàu, tôi đang nghe cuộc trò chuyện giữa hai người bên cạnh mà không thực sự chú ý."}, {"jp": "窓の外を見るともなしに眺めていると、雪がちらつき始めた。", "vi": "Khi tôi nhìn ra ngoài cửa sổ, tuyết bắt đầu rơi."}, {"jp": "どこからともなく、焼き魚のいい匂いが漂ってきた。", "vi": "Mùi cá nướng không biết từ đâu bay ra."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ないまでも', 'V-ない + までも', 'N1', 'ngay cả khi không (ở mức độ đó), ít nhất', 'Phần đầu nêu tên một mức độ cao chưa đạt được; thứ hai là mức độ thấp hơn, có thể chấp nhận được, thường kèm theo せめて, 少なくとも hoặc lời khuyên.', '[{"jp": "毎日とは言わないまでも、週に一度くらいは実家に電話しなさい。", "vi": "Gọi cho bố mẹ bạn ít nhất một lần một tuần, nếu không nói là hàng ngày."}, {"jp": "優勝はできないまでも、せめて決勝までは勝ち進みたい。", "vi": "Dù không thể thắng nhưng ít nhất tôi cũng muốn lọt vào trận chung kết."}, {"jp": "完璧には理解できないまでも、大まかな流れはつかんでおくべきだ。", "vi": "Ngay cả khi bạn không hiểu nó hoàn toàn, bạn cũng nên có ý tưởng chung về quy trình."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ないものでもない', 'V-ない + ものでもない', 'N1', 'điều đó không phải là không thể; có thể (trong một số điều kiện)', 'Một cách vòng vo, có phần miễn cưỡng để thừa nhận một khả năng. Tương tự như 〜ないことはない (N3) nhưng cứng hơn.', '[{"jp": "条件次第では、その仕事を引き受けないものでもない。", "vi": "Tùy theo điều kiện, tôi sẽ không nhận công việc đó."}, {"jp": "今から全力で走れば、終電に間に合わないものでもない。", "vi": "Nếu bạn chạy nhanh nhất có thể kể từ bây giờ, bạn sẽ không bỏ lỡ chuyến tàu cuối cùng."}, {"jp": "彼の言い分も分からないものでもないが、やはり規則は規則だ。", "vi": "Không phải là tôi không hiểu anh ấy đang nói gì, nhưng quy tắc vẫn là quy tắc."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ながらに / 〜ながらの', 'N + ながらに / N + ながらの + N / V-ます(bỏ ます) + ながらに', 'N1', 'như (nó đã vậy); trong khi còn lại; kể từ (sinh ra)', 'Giới hạn trong việc thiết lập các biểu thức: 昔ながら, 涙ながら, 生まれながら, いつもながら, いながらにして (''không rời khỏi chỗ của mình'').', '[{"jp": "この町には、昔ながらの手作りの和菓子屋が今も残っている。", "vi": "Trong thị trấn này vẫn còn một số cửa hàng bánh kẹo thủ công kiểu Nhật cổ điển."}, {"jp": "被害者の母親は、涙ながらに事件当日の様子を語った。", "vi": "Mẹ nạn nhân rơi nước mắt kể lại chuyện xảy ra vào ngày xảy ra vụ việc."}, {"jp": "彼女は生まれながらに優れた音感を持っていた。", "vi": "Cô ấy sinh ra đã có khả năng cảm nhận cao độ tuyệt vời."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜なくして(は)', 'N + なくして(は)', 'N1', 'không có (thứ gì đó thiết yếu), (không thể)', 'Tiếp theo là tiêu cực hoặc không thể; nhấn mạnh rằng danh từ là không thể thiếu. Nhấn mạnh và văn chương hơn 〜なしに(は).', '[{"jp": "地域住民の理解なくして、この計画の成功はあり得ない。", "vi": "Kế hoạch này không thể thành công nếu không có sự hiểu biết của người dân địa phương."}, {"jp": "失敗なくしては、本当の成長は得られない。", "vi": "Không có thất bại thì không thể đạt được sự tăng trưởng thực sự."}, {"jp": "多くの支援者の協力なくしては、この映画は完成しなかっただろう。", "vi": "Bộ phim này sẽ không thể hoàn thành nếu không có sự hợp tác của nhiều người ủng hộ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜なしに(は)', 'N + なしに(は)', 'N1', 'không có', 'なしに đơn giản có nghĩa là ''không có''; なしには được theo sau bởi âm (''không thể ... không có''). Hội thoại thường sử dụng 〜なしで.', '[{"jp": "彼は何の連絡もなしに、三日間会社を休んだ。", "vi": "Anh ấy đã vắng mặt ở nơi làm việc ba ngày mà không có bất kỳ thông báo nào."}, {"jp": "事前の許可なしには、この区域に立ち入ることはできません。", "vi": "Không ai có thể vào khu vực này mà không có sự cho phép trước."}, {"jp": "この話は、涙なしには聞けない。", "vi": "Tôi không thể nghe câu chuyện này mà không khóc."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ならいざしらず / 〜はいざしらず', 'N + ならいざしらず / N + はいざしらず / V(thể thông thường) + (の) + ならいざしらず', 'N1', 'nó có thể khác đối với ..., nhưng; Tôi không biết về..., nhưng', 'Trường hợp đầu tiên có thể được miễn hoặc không xác định được; trường hợp thực tế được xét xử nghiêm khắc hơn. Gần giống với 〜ならまだしも, nhưng mang tính văn chương hơn.', '[{"jp": "子どもならいざしらず、大人がこんな簡単な漢字も読めないとは情けない。", "vi": "Thật thảm hại khi người lớn thậm chí còn không thể đọc được những chữ kanji đơn giản như vậy, chứ đừng nói đến trẻ em."}, {"jp": "昔はいざしらず、今の時代に手書きの履歴書にこだわる必要はないだろう。", "vi": "Trong thế giới ngày nay, không cần thiết phải nhấn mạnh vào những bản lý lịch viết tay như trước đây."}, {"jp": "素人ならいざしらず、プロの料理人が塩と砂糖を間違えるなんて。", "vi": "Một người nghiệp dư sẽ không bao giờ biết, nhưng một đầu bếp chuyên nghiệp sẽ nhầm muối với đường."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ならまだしも', 'N + ならまだしも / V(thể thông thường) + (の) + ならまだしも', 'N1', 'nếu là ..., thì đó sẽ là một chuyện (nhưng)', 'Trường hợp đầu tiên có thể chấp nhận được; tình hình thực tế còn tồi tệ hơn. Mang tính trò chuyện nhiều hơn 〜ならいざしらず. Biến thể: 〜はまだしも.', '[{"jp": "一度ならまだしも、同じミスを三度も繰り返すのは問題だ。", "vi": "Làm một lần thì không sao, nhưng nếu bạn mắc cùng một lỗi ba lần thì sẽ thành vấn đề."}, {"jp": "遅刻するならまだしも、連絡もせずに休むのは社会人として失格だ。", "vi": "Nếu bạn đến muộn thì không sao, nhưng bạn sẽ bị loại khỏi tư cách thành viên của xã hội nếu bạn nghỉ làm mà không báo cho tôi."}, {"jp": "冗談で言うならまだしも、本気でそう思っているのなら問題だ。", "vi": "Nếu bạn nói đùa thì không sao, nhưng nếu bạn thực sự có ý đó thì đó là một vấn đề."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜なり', 'V-る(thể từ điển) + なり', 'N1', 'ngay khi ; khoảnh khắc', 'Cả hai hành động đều có cùng chủ đề (thường là ngôi thứ ba) và hành động thứ hai thường bất ngờ. Không dành cho hành động hoặc kế hoạch tương lai của chính người nói. Khác với 〜なり〜なり và 〜なりに.', '[{"jp": "娘は学校から帰ってくるなり、自分の部屋に閉じこもってしまった。", "vi": "Con gái tôi vừa đi học về là nhốt mình trong phòng."}, {"jp": "彼は受話器を取るなり、大声で怒鳴り始めた。", "vi": "Ngay khi nhấc điện thoại lên, anh ấy bắt đầu hét lên."}, {"jp": "父は一口食べるなり、「懐かしい味だ」とつぶやいた。", "vi": "Cha tôi vừa cắn một miếng, ông lẩm bẩm: “Nó có vị hoài cổ”."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜なり〜なり', 'N + なり + N + なり / V-る(thể từ điển) + なり + V-る(thể từ điển) + なり', 'N1', 'A hoặc B; A hoặc B hoặc bất cứ điều gì', 'Đưa ra các lựa chọn mẫu và thường được theo sau bởi một gợi ý, yêu cầu hoặc mệnh lệnh chứ không phải một sự kiện trong quá khứ. Một 〜なり có thể có nghĩa là ''hoặc cái gì đó'' (お茶なり).', '[{"jp": "分からないことがあれば、先生に聞くなり辞書で調べるなりしなさい。", "vi": "Nếu bạn không hiểu điều gì đó, hãy hỏi giáo viên hoặc tra từ điển."}, {"jp": "週末は、映画なり買い物なり、好きなことをして過ごすといい。", "vi": "Dành những ngày cuối tuần để làm bất cứ điều gì bạn thích, như đi xem phim hoặc mua sắm."}, {"jp": "結果が出たら、電話なりメールなりで知らせてください。", "vi": "Khi có kết quả, vui lòng cho tôi biết qua điện thoại hoặc email."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜なりに / 〜なりの', 'N + なりに / N + なりの + N / A-い + なりに / V(thể thông thường) + なりに', 'N1', 'theo cách riêng của mình; trong chừng mực (giới hạn của một người) cho phép', 'Chấp nhận một giới hạn (tuổi, khả năng, kích thước) và nói rằng điều gì đó đã được thực hiện hoặc có giá trị trong giới hạn đó. Có thể nghe có vẻ trịch thượng nếu dùng về cấp trên.', '[{"jp": "子どもは子どもなりに、親のことを心配しているものだ。", "vi": "Con cái, theo cách riêng của chúng, lo lắng cho cha mẹ."}, {"jp": "自分なりに努力したつもりだが、結果は思わしくなかった。", "vi": "Tôi đã cố gắng hết sức nhưng kết quả lại không như tôi mong đợi."}, {"jp": "狭い部屋には狭いなりの良さがある。", "vi": "Một căn phòng nhỏ có lợi thế của nó."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜には当たらない', 'V-る(thể từ điển) + には当たらない / N + には当たらない', 'N1', 'không cần phải làm vậy; nó không có giá trị (ngạc nhiên, v.v.)', 'Dùng với các động từ phản ứng: 驚く, 責める, 非難する, 心配する, 悲しむ, 賞賛する. Tình hình không đảm bảo cho phản ứng đó.', '[{"jp": "彼の実力を考えれば、今回の優勝は驚くには当たらない。", "vi": "Xét về khả năng của anh thì chiến thắng này không có gì bất ngờ."}, {"jp": "新人のうちは誰でも失敗するものだから、それほど責めるには当たらない。", "vi": "Tất cả tân binh đều mắc sai lầm nên tôi không thể trách họ được."}, {"jp": "多少の遅れは想定内であり、心配するには当たらない。", "vi": "Một số sự chậm trễ có thể xảy ra và không phải là nguyên nhân gây lo ngại."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にあって', 'N + にあって(は / も)', 'N1', 'trong (một tình huống hoặc vị trí); tại (một thời điểm)', 'Một 〜で / 〜において trang trọng nhấn mạnh việc đang ở trong một tình huống đặc biệt. にあっても = ''đồng đều''; にあっては = ''ở (vị trí như vậy)''.', '[{"jp": "物価が上がり続ける状況にあって、家計の見直しは避けられない。", "vi": "Khi giá cả tiếp tục tăng, việc xem xét lại tài chính hộ gia đình là điều không thể tránh khỏi."}, {"jp": "彼女は逆境にあっても、決して笑顔を絶やさなかった。", "vi": "Ngay cả khi đối mặt với nghịch cảnh, cô vẫn không ngừng mỉm cười."}, {"jp": "責任ある立場にあっては、軽率な言動は慎むべきだ。", "vi": "Nếu đang ở vị trí có trách nhiệm, bạn nên kiềm chế những lời nói và hành động hấp tấp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に難くない', 'V-る(thể từ điển) + に難くない / N + に難くない', 'N1', 'không khó để (tưởng tượng, hiểu)', 'Giới hạn trong một vài từ: 想像, 理解, 察する, 予想. Phong cách viết chính thức.', '[{"jp": "突然家族を失った遺族の悲しみは、想像に難くない。", "vi": "Không khó để hình dung nỗi đau buồn của những gia đình có tang quyến đột ngột mất đi người thân."}, {"jp": "当時の彼がどれほど追い詰められていたかは、察するに難くない。", "vi": "Không khó để tưởng tượng lúc đó anh ấy đã bị dồn vào chân tường như thế nào."}, {"jp": "この条件で工事を強行すれば、事故が起きることは予想に難くない。", "vi": "Nếu buộc phải thi công trong những điều kiện này thì không khó để dự đoán tai nạn sẽ xảy ra."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にして', 'N + にして', 'N1', 'chỉ (tại/với); thậm chí cho ; vừa là A vừa là B', 'Cách sử dụng chính: đã đạt đến một giai đoạn, thường là 〜にして初めて (''chỉ tại/với''); ''ngay cả đối với (ai đó đặc biệt)'' (名人にしてなお解けない); và AにしてB ''cả A và B''.', '[{"jp": "彼女は四十歳にして、初めて小説を書き上げた。", "vi": "Cô hoàn thành cuốn tiểu thuyết đầu tiên của mình ở tuổi bốn mươi."}, {"jp": "このような精密な作業は、熟練の職人にしてはじめて可能になる。", "vi": "Công việc chính xác như vậy chỉ có thể được thực hiện bởi những người thợ lành nghề."}, {"jp": "彼は医師にして作家でもあり、多方面で活躍している。", "vi": "Ông là bác sĩ, nhà văn và hoạt động trong nhiều lĩnh vực."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に即して', 'N + に即して / N + に即した + N', 'N1', 'phù hợp với; dựa trên (sự kiện, điều kiện thực tế)', 'Danh từ điển hình: 事実, 実情, 現実, 実態, 状況. Với luật lệ, 〜に則して hoặc 〜に則って được sử dụng.', '[{"jp": "規則を機械的に当てはめるのではなく、実情に即して判断すべきだ。", "vi": "Thay vì áp dụng các quy định một cách máy móc, các quyết định nên được đưa ra dựa trên tình hình thực tế."}, {"jp": "本書は、実際の職場の場面に即した会話例を数多く取り上げている。", "vi": "Cuốn sách này chứa nhiều ví dụ về các cuộc hội thoại dựa trên các tình huống thực tế tại nơi làm việc."}, {"jp": "事実に即して報道することが、記者の最低限の責任である。", "vi": "Báo cáo đúng sự thật là trách nhiệm tối thiểu của người báo cáo."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に堪える / 〜に堪えない', 'V-る(thể từ điển) + に堪える / N + に堪える / V-る(thể từ điển) + に堪えない / N + に堪えない', 'N1', 'có giá trị (làm); không thể chịu nổi (nhìn, nghe); (cảm nhận) sâu sắc', 'に堪える: ''đáng (đọc, nhìn thấy)''. Động từ + に堪えない: ''quá khủng khiếp để (nhìn, nghe)''. Danh từ cảm xúc + に堪えない (感謝, 遺憾): ''cảm nhận sâu sắc'', trong cách nói trang trọng.', '[{"jp": "この作品は、大人の鑑賞にも十分堪える完成度の高いアニメだ。", "vi": "Tác phẩm này là một anime rất hoàn chỉnh mà người lớn cũng có thể yêu thích."}, {"jp": "被災地の惨状は、見るに堪えないものだった。", "vi": "Sự tàn phá trong khu vực thảm họa là không thể chịu đựng được khi chứng kiến."}, {"jp": "皆様から温かいご支援をいただき、感謝に堪えません。", "vi": "Tôi không thể cảm ơn đủ vì sự hỗ trợ nồng nhiệt mà chúng tôi đã nhận được từ mọi người."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に足る', 'V-る(thể từ điển) + に足る + N / N + に足る + N', 'N1', 'đáng ; đủ để', 'Hầu hết đứng trước danh từ (信頼に足る人物). Câu phủ định 取るに足らない (''tầm thường'') là một cụm từ phổ biến.', '[{"jp": "彼は、部下からも取引先からも信頼に足る人物だと評価されている。", "vi": "Ông được cả cấp dưới và đối tác kinh doanh đánh giá là người đáng tin cậy."}, {"jp": "残念ながら、その主張を裏付けるに足る証拠は見つかっていない。", "vi": "Thật không may, không có bằng chứng đầy đủ nào được tìm thấy để hỗ trợ cho tuyên bố đó."}, {"jp": "取るに足らないうわさなど、気にする必要はない。", "vi": "Không cần phải lo lắng về những tin đồn tầm thường."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にとどまらず', 'N / V(thể thông thường) + にとどまらず', 'N1', 'không giới hạn; không dừng lại ở; vượt xa hơn', 'Nhấn mạnh rằng điều gì đó lan rộng ra ngoài phạm vi hoặc khu vực dự kiến. Gần với 〜に限らず (N2) nhưng có cảm giác mở rộng mạnh mẽ hơn.', '[{"jp": "感染症の影響は一国にとどまらず、世界経済全体に及んだ。", "vi": "Tác động của dịch bệnh không chỉ giới hạn ở một quốc gia mà ảnh hưởng đến toàn bộ nền kinh tế toàn cầu."}, {"jp": "この運動は一時的なブームにとどまらず、社会の意識を大きく変えた。", "vi": "Phong trào này không chỉ là một sự bùng nổ nhất thời; nó đã thay đổi đáng kể ý thức của xã hội."}, {"jp": "彼の研究は、学問の世界にとどまらず、産業界からも注目を集めている。", "vi": "Nghiên cứu của ông đã thu hút sự chú ý không chỉ từ giới học thuật mà còn từ giới công nghiệp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にひきかえ', 'N + にひきかえ / V(thể thông thường) + の + にひきかえ', 'N1', 'trái ngược với ; không giống', 'Đối chiếu hai điều trái ngược nhau với sự đánh giá của người nói (một tốt, một xấu). Chủ quan hơn 〜に対して.', '[{"jp": "しっかり者の姉にひきかえ、妹はのんびり屋でいつも忘れ物ばかりしている。", "vi": "Trái ngược với chị gái là người đáng tin cậy, cô em gái lại thoải mái hơn và luôn quên mọi chuyện."}, {"jp": "去年の猛暑にひきかえ、今年の夏はずいぶん過ごしやすい。", "vi": "Trái ngược với cái nóng gay gắt năm ngoái, mùa hè năm nay dễ chịu hơn rất nhiều."}, {"jp": "兄が勉強熱心なのにひきかえ、弟は漫画ばかり読んでいる。", "vi": "Trong khi người anh rất ham học thì người em chỉ đọc truyện tranh."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にもまして', 'N + にもまして / Question word + にもまして', 'N1', 'thậm chí còn hơn thế nữa; trên hết', 'Thường là 以前にもまして, 例年にもまして. Với từ để hỏi (何にもまして, 誰にもまして) nó có nghĩa là ''hơn bất cứ thứ gì/bất cứ ai''.', '[{"jp": "今年の夏は、例年にもまして暑さが厳しい。", "vi": "Mùa hè năm nay nóng hơn thường lệ."}, {"jp": "合格の知らせは、何にもましてうれしかった。", "vi": "Tôi còn hơn cả hạnh phúc khi biết rằng mình đã vượt qua kỳ thi."}, {"jp": "前回にもまして、今回の選挙は投票率の低さが目立った。", "vi": "Tỷ lệ cử tri đi bỏ phiếu trong cuộc bầu cử này thấp hơn đáng kể so với các cuộc bầu cử trước."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜の至り', 'N + の至り', 'N1', 'tối đa; chiều cao của (trong cụm từ đã đặt)', 'Chủ yếu là trong các cụm từ cố định: 光栄の至り, 恐縮の至り, 感激の至り, và 若気の至り (''tuổi trẻ điên rồ''). Được sử dụng trong các bài phát biểu và thư từ trang trọng.', '[{"jp": "このような席でご挨拶させていただけるとは、光栄の至りでございます。", "vi": "Thật vinh dự cho tôi khi được nói chuyện với bạn ở vị trí này."}, {"jp": "学生時代に派手な髪型をしていたのは、若気の至りだった。", "vi": "Kiểu tóc lòe loẹt thời sinh viên của anh là kết quả của tinh thần trẻ trung."}, {"jp": "皆様にご迷惑をおかけし、誠に恐縮の至りです。", "vi": "Chúng tôi chân thành xin lỗi vì bất kỳ sự bất tiện nào gây ra."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜のみならず', 'N / V(thể thông thường) / A-い + のみならず / A-な + である + のみならず / N + である + のみならず', 'N1', 'không chỉ ... mà còn', 'Văn viết trang trọng tương đương với 〜だけでなく / 〜ばかりでなく. Cũng có thể mở câu: のみならず、…', '[{"jp": "この問題は日本のみならず、多くの先進国が抱える課題である。", "vi": "Vấn đề này không chỉ Nhật Bản mà nhiều nước phát triển cũng phải đối mặt."}, {"jp": "彼女は優れた研究者であるのみならず、学生の指導にも熱心だ。", "vi": "Cô không chỉ là một nhà nghiên cứu xuất sắc mà còn rất tâm huyết trong việc giảng dạy học sinh."}, {"jp": "震災は建物を破壊したのみならず、住民の暮らしそのものを奪った。", "vi": "Trận động đất không chỉ phá hủy các tòa nhà mà còn tước đi sinh kế của người dân."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜はおろか', 'N + はおろか', 'N1', 'huống chi ; chưa kể', 'AはおろかBも / さえ / まで: B thậm chí còn là trường hợp cơ bản hơn; thường là về những sự thật tiêu cực hoặc đáng ngạc nhiên. Không giống như 〜どころか, không được dùng với mệnh lệnh hoặc lời chúc.', '[{"jp": "足を骨折してしまい、走ることはおろか、歩くことさえままならない。", "vi": "Anh ấy bị gãy chân và không thể đi được chứ đừng nói đến việc chạy."}, {"jp": "祖父は海外はおろか、東京にも行ったことがない。", "vi": "Ông tôi chưa bao giờ đến Tokyo chứ đừng nói đến nước ngoài."}, {"jp": "給料日前で、外食はおろか、コンビニの弁当を買う余裕もない。", "vi": "Ngay trước ngày lãnh lương, và tôi không đủ khả năng để mua hộp cơm trưa ở cửa hàng tiện lợi chứ đừng nói đến việc đi ăn ngoài."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ばこそ', 'V-ば + こそ / A-い(bỏ い) + ければこそ / A-な + であればこそ / N + であればこそ', 'N1', 'chính xác là vì; chỉ vì', 'Nhấn mạnh một lý do tích cực hoặc có ý tốt, thường là để giải thích điều gì đó có thể bị hiểu lầm. Văn chương hơn 〜からこそ.', '[{"jp": "君の将来を思えばこそ、厳しいことを言うのだ。", "vi": "Chỉ khi nghĩ đến tương lai của em, tôi mới nói ra những lời cay nghiệt như vậy."}, {"jp": "健康であればこそ、好きな仕事にも打ち込める。", "vi": "Nếu có sức khỏe, bạn có thể cống hiến hết mình cho công việc mình yêu thích."}, {"jp": "信頼していればこそ、この大役を彼女に任せたのです。", "vi": "Chính vì tin tưởng cô ấy nên tôi mới giao cho cô ấy vai trò quan trọng này."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ばそれまでだ', 'V-ば + それまでだ', 'N1', 'nếu..., thế là xong; tất cả sẽ chẳng là gì nếu', 'Hai cách sử dụng: mọi nỗ lực sẽ bị lãng phí nếu X xảy ra; hoặc 〜と言ってしまえばそれまでだ, ''nói X kết thúc cuộc thảo luận (nhưng ...)''. Thường đi kèm với 〜てしまえば.', '[{"jp": "どんなに高価な機械でも、壊れてしまえばそれまでだ。", "vi": "Máy có đắt đến đâu mà hỏng thì thôi."}, {"jp": "いくら準備をしても、本番で緊張して何も言えなければそれまでだ。", "vi": "Cho dù bạn có chuẩn bị bao nhiêu đi chăng nữa, nếu bạn quá lo lắng để nói bất cứ điều gì trong buổi biểu diễn thực sự thì chỉ vậy thôi."}, {"jp": "運が悪かったと言ってしまえばそれまでだが、防げた事故だったのではないか。", "vi": "Tôi có thể đi xa hơn khi nói rằng đó là điều không may mắn, nhưng tôi nghĩ tai nạn có thể đã được ngăn chặn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜べからず / 〜べからざる', 'V-る(thể từ điển) + べからず / V-る(thể từ điển) + べからざる + N (する → すべからず)', 'N1', 'không được; không (trên biển báo); (trước danh từ) không được', 'Cổ xưa; chủ yếu là về các dấu hiệu, các quy tắc và các cụm từ cố định. べからざる trước danh từ xuất hiện trong 欠くべからざる (''không thể thiếu'') và 許すべからざる (''không thể tha thứ'').', '[{"jp": "境内の池のほとりには、「魚にえさを与えるべからず」と書かれた立て札がある。", "vi": "Có một tấm biển bên ao trong khuôn viên chùa ghi rằng, ''''Không được cho cá ăn.''''"}, {"jp": "彼の発言は、公職にある者として許すべからざるものだ。", "vi": "Những bình luận của ông là không thể chấp nhận được đối với bất cứ ai nắm giữ một cơ quan công quyền."}, {"jp": "水は人間の生活にとって欠くべからざるものである。", "vi": "Nước rất cần thiết cho cuộc sống con người."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜べくもない', 'V-る(thể từ điển) + べくもない (する → すべくもない)', 'N1', 'không thể được; không có cách nào để', 'Phổ biến với 望む, 知る, 比べる (cũng là 比ぶべくもない cổ điển). Văn học; sự không thể đến từ hoàn cảnh.', '[{"jp": "プロの演奏と私の演奏とでは、比べるべくもない。", "vi": "Không có sự so sánh giữa hiệu suất của một chuyên gia và hiệu suất của tôi."}, {"jp": "都心の一等地に家を買うなど、今の収入では望むべくもない。", "vi": "Với thu nhập hiện tại của mình, tôi không thể hy vọng mua được một căn nhà ở vị trí đắc địa trung tâm thành phố."}, {"jp": "当事者が全員亡くなった今となっては、事故の真相は知るべくもない。", "vi": "Bây giờ tất cả những người liên quan đã qua đời, không cách nào biết được sự thật đằng sau vụ tai nạn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜まじき', 'N + に + あるまじき + N / V-る(thể từ điển) + まじき + N', 'N1', 'Không thể chấp nhận được ở vị thế...', 'Chủ yếu là 〜にあるまじき / 〜としてあるまじき + 行為, 発言, 態度: hành vi không xứng đáng với vai trò. Mạnh mẽ quan trọng và chính thức.', '[{"jp": "生徒に暴言を吐くなど、教育者にあるまじき行為だ。", "vi": "Việc giáo viên xúc phạm học sinh bằng lời nói là điều không nên làm."}, {"jp": "賄賂を受け取るとは、政治家としてあるまじきことである。", "vi": "Nhận hối lộ là điều không một chính trị gia nào nên làm."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜までもない', 'V-る(thể từ điển) + までもない', 'N1', 'không cần thiết; không cần phải (đi xa đến mức)', 'Vấn đề quá rõ ràng hoặc quá nhỏ để cần hành động. 言うまでもなく (''không cần phải nói'') là một cụm từ phổ biến.', '[{"jp": "言うまでもないが、試験中の私語は禁止だ。", "vi": "Không cần phải nói, việc nói chuyện riêng trong kỳ thi bị cấm."}, {"jp": "この程度の傷なら、わざわざ病院へ行くまでもない。", "vi": "Với vết thương ở mức độ này, không cần phải đến bệnh viện."}, {"jp": "彼女の実力は、改めて説明するまでもないだろう。", "vi": "Không cần phải giải thích lại khả năng của cô ấy nữa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜までだ / 〜までのことだ', 'V-る(thể từ điển) + までだ / V-た + までだ / V-る(thể từ điển) + までのことだ', 'N1', '(Tôi sẽ) chỉ (làm); Tôi chỉ (đã)', 'Với V-る(thể từ điển): bình tĩnh quyết tâm thực hiện lựa chọn duy nhất còn lại. Với V-た: ''Tôi chỉ làm X, không làm gì hơn'', biện minh cho hành động của một người.', '[{"jp": "電車が動かないなら、歩いて帰るまでだ。", "vi": "Nếu tàu không di chuyển thì tôi sẽ phải đi bộ về nhà."}, {"jp": "今回だめでも、また来年挑戦するまでのことだ。", "vi": "Ngay cả khi lần này nó không hiệu quả, điều đó có nghĩa là tôi có thể thử lại vào năm sau."}, {"jp": "別に怒っているわけではない。事実を言ったまでだ。", "vi": "Không phải là tôi đang tức giận. Tôi chỉ nói sự thật thôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜まみれ', 'N + まみれ', 'N1', 'bao phủ trong; bôi bằng', 'Có cái gì đó (bùn, máu, mồ hôi, dầu, bụi, nợ nần) dính đầy khắp nơi. So sánh だらけ (nhiều thứ, thậm chí sai sót) và ずくめ (hoàn toàn có thể tích cực).', '[{"jp": "子どもたちは泥まみれになって、日が暮れるまで遊んでいた。", "vi": "Bọn trẻ được bao phủ bởi bùn và chơi cho đến khi mặt trời lặn."}, {"jp": "救助隊員は汗まみれになりながら、がれきの中を捜索し続けた。", "vi": "Các nhân viên cứu hộ ướt đẫm mồ hôi khi tiếp tục tìm kiếm trong đống đổ nát."}, {"jp": "彼は事業に失敗して以来、借金まみれの生活を送っている。", "vi": "Kể từ khi công việc kinh doanh thất bại, anh phải sống một cuộc sống đầy nợ nần."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜めく', 'N + めく / N + めいた + N', 'N1', 'có dấu hiệu; trở nên giống như; -ish', 'Giới hạn ở một số danh từ nhất định: 春めく, 秋めく, 謎めく, 皮肉めく, 冗談めく, 言い訳めく. Văn chương hơn 〜らしい / 〜っぽい.', '[{"jp": "三月に入り、日差しもだいぶ春めいてきた。", "vi": "Bây giờ là tháng ba, nắng bắt đầu như mùa xuân."}, {"jp": "彼女は謎めいた微笑みを浮かべて、何も答えなかった。", "vi": "Cô mỉm cười bí ẩn và không trả lời."}, {"jp": "先輩の皮肉めいた言い方が、どうも気になった。", "vi": "Cách nói mỉa mai của tiền bối đã thu hút sự chú ý của tôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜もさることながら', 'N + もさることながら', 'N1', 'không chỉ ... mà còn (thậm chí nhiều hơn nữa); ... sang một bên', 'Thừa nhận A, sau đó nhấn mạnh B là quan trọng hơn hoặc đáng chú ý hơn. Thông thường đánh giá tích cực.', '[{"jp": "この店は、料理の味もさることながら、器の美しさにも心を奪われる。", "vi": "Đến nhà hàng này, bạn sẽ bị hớp hồn không chỉ bởi hương vị món ăn mà còn bởi vẻ đẹp của các món ăn."}, {"jp": "彼の成功は、才能もさることながら、人一倍の努力によるものだ。", "vi": "Thành công của anh không chỉ nhờ tài năng mà còn nhờ sự chăm chỉ."}, {"jp": "この本は内容もさることながら、装丁の美しさが話題を呼んだ。", "vi": "Cuốn sách này thu hút sự chú ý không chỉ vì nội dung mà còn vì bìa đẹp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ものを', 'V(thể thông thường) / A-い / A-な + な + ものを', 'N1', 'nếu chỉ (..., nhưng); mặc dù (tiếc nuối hoặc trách móc)', 'Hối tiếc, không hài lòng hoặc trách móc vì mọi việc đã không diễn ra như lẽ ra phải có. Thường đi kèm với 〜ば / 〜たら; có thể kết thúc câu: 言ってくれればよかったものを.', '[{"jp": "一言相談してくれれば手伝ったものを、どうして一人で抱え込んだのか。", "vi": "Tại sao tôi phải giải quyết một việc mà lẽ ra tôi có thể giúp được nếu tôi xin lời khuyên?"}, {"jp": "すぐに病院へ行けば軽く済んだものを、我慢したせいで入院する羽目になった。", "vi": "Nếu đến bệnh viện ngay thì có lẽ tôi đã khỏi bệnh, nhưng vì kìm nén nên cuối cùng tôi phải nhập viện."}, {"jp": "黙っていればいいものを、彼は余計なことを言って話をこじらせた。", "vi": "Đáng lẽ tôi nên im lặng nhưng anh ấy lại nói những điều không cần thiết khiến cuộc trò chuyện trở nên phức tạp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜や否や', 'V-る(thể từ điển) + や否や / V-る(thể từ điển) + や', 'N1', 'ngay khi ; khoảnh khắc; không sớm hơn ... hơn', 'Được viết nhiều nhất trong nhóm ''ngay sau''; chỉ sự thật trong quá khứ, không phải ý định hoặc mệnh lệnh. Cũng được rút gọn thành 〜や. So sánh 〜なり (cùng chủ đề) và 〜そばから (lặp lại).', '[{"jp": "首相が会見場に姿を現すや否や、一斉にカメラのフラッシュがたかれた。", "vi": "Ngay khi thủ tướng xuất hiện tại cuộc họp báo, đèn flash của máy ảnh đồng loạt bắn ra."}, {"jp": "新製品は発売されるや否や、たちまち品切れになった。", "vi": "Sản phẩm mới vừa ra mắt đã nhanh chóng cháy hàng."}, {"jp": "終業のベルが鳴るや、生徒たちは教室を飛び出していった。", "vi": "Ngay khi tiếng chuông cuối cùng vang lên, học sinh ùa ra khỏi lớp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ゆえ(に)', 'N + (の) + ゆえ(に) / V(thể thông thường) + (が) + ゆえ(に) / A-い + (が) + ゆえ(に) / A-な + である + がゆえに', 'N1', 'vì ; bởi vì; Vì vậy', 'Trang trọng viết ''bởi vì''; 〜がゆえに mang tính nhấn mạnh và 〜ゆえの + Danh từ bổ nghĩa cho danh từ. Khi bắt đầu câu, ゆえに có nghĩa là ''do đó'' (logic, toán học).', '[{"jp": "若さゆえの無謀な挑戦だったが、今ではいい思い出だ。", "vi": "Đó là một thử thách liều lĩnh do tuổi trẻ của tôi, nhưng bây giờ tôi có những kỷ niệm đẹp về nó."}, {"jp": "彼は正直すぎるがゆえに、損をすることも多い。", "vi": "Vì quá trung thực nên thường xuyên bị thua lỗ."}, {"jp": "資源が乏しいがゆえに、この国は技術開発に力を注いできた。", "vi": "Do thiếu nguồn lực nên đất nước này đã tập trung vào phát triển công nghệ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をおいて', 'N + をおいて(ほかに)〜ない', 'N1', 'khác hơn ; ngoài (không có ai/không có gì khác)', 'Ca ngợi điều gì đó là sự lựa chọn khả thi duy nhất; theo sau là âm (いない, ない). Không liên quan đến 置いて ''bỏ lại phía sau''.', '[{"jp": "この難しい手術を任せられるのは、彼をおいてほかにいない。", "vi": "Không có ai khác ngoài anh ấy có thể được giao phó cuộc phẫu thuật khó khăn này."}, {"jp": "次の大会を開くなら、この町をおいてふさわしい場所はない。", "vi": "Nếu chúng tôi tổ chức giải đấu tiếp theo, không có nơi nào tốt hơn thị trấn này."}, {"jp": "今をおいて、改革を断行する機会はないだろう。", "vi": "Sẽ không có cơ hội để thực hiện cải cách bây giờ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を皮切りに', 'N + を皮切りに / V(thể thông thường) + の + を皮切りに', 'N1', 'bắt đầu bằng ; bắt đầu bằng (tiếp theo là một chuỗi)', 'Đánh dấu sự kiện đầu tiên trong một chuỗi các sự kiện tương tự được mở rộng hoặc lan rộng. Ngoài ra còn có 〜を皮切りとして.', '[{"jp": "バンドは来月の東京公演を皮切りに、全国二十か所を回るツアーを行う。", "vi": "Ban nhạc sẽ lưu diễn tới 20 địa điểm trên khắp đất nước, bắt đầu bằng buổi biểu diễn ở Tokyo vào tháng tới."}, {"jp": "彼女の発言を皮切りに、会議ではさまざまな不満が噴き出した。", "vi": "Nhận xét của cô đã làm dấy lên nhiều lời phàn nàn tại cuộc họp."}, {"jp": "この店は、駅前への出店を皮切りに、市内で次々と支店を増やしていった。", "vi": "Cửa hàng này bắt đầu bằng việc mở một cửa hàng trước nhà ga, sau đó mở hết chi nhánh này đến chi nhánh khác trong thành phố."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を機に', 'N + を機に / V(thể thông thường) + の + を機に', 'N1', 'tận dụng cơ hội; với (một sự kiện) là một bước ngoặt', 'Trang trọng hơn 〜をきっかけに (N2), thường dùng để chỉ một bước ngoặt quan trọng. Ngoài ra 〜を機として.', '[{"jp": "還暦を機に、父は長年勤めた会社を退職した。", "vi": "Vào sinh nhật lần thứ 60 của ông, bố tôi nghỉ hưu ở công ty mà ông đã làm việc nhiều năm."}, {"jp": "子どもが生まれたのを機に、郊外の一戸建てに引っ越した。", "vi": "Sau khi sinh con, tôi chuyển đến một căn nhà biệt lập ở ngoại ô."}, {"jp": "今回の事故を機に、社内の安全管理体制が全面的に見直された。", "vi": "Sau vụ tai nạn này, hệ thống quản lý an toàn của công ty đã được xem xét lại toàn bộ."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を限りに', 'N + を限りに', 'N1', 'kể từ (và không còn nữa); lần cuối cùng; ở đầu (giọng của một người)', 'Đánh dấu điểm cuối cùng trước khi điều gì đó kết thúc (本日を限りに, 今回を限りに). 声を限りに ''to nhất có thể'' là một cụm từ cố định.', '[{"jp": "本日を限りに、当店は四十年の歴史に幕を下ろします。", "vi": "Kể từ hôm nay, cửa hàng của chúng tôi sẽ kết thúc lịch sử 40 năm của mình."}, {"jp": "彼はこの試合を限りに、現役を引退すると発表した。", "vi": "Anh tuyên bố sẽ nghỉ hưu sau trận đấu này."}, {"jp": "遭難者は声を限りに助けを求めたが、誰にも届かなかった。", "vi": "Nạn nhân hét to kêu cứu nhưng không ai đến được."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をもって', 'N + をもって', 'N1', 'với ; bằng cách; kể từ (một thời điểm)', 'Hai cách sử dụng: phương tiện (書面をもって, 実力をもって) và một điểm kết thúc trang trọng (本日をもって). 〜をもちまして thường dùng trong các thông báo; 〜をもってすれば = ''với ..., (bất cứ điều gì đều có thể)''.', '[{"jp": "以上をもちまして、本日の説明会を終了いたします。", "vi": "Với điều này, chúng tôi kết thúc phiên họp giao ban ngày hôm nay."}, {"jp": "選考の結果は、後日書面をもってお知らせいたします。", "vi": "Kết quả lựa chọn sẽ được thông báo bằng văn bản sau đó."}, {"jp": "彼はその圧倒的な実力をもって、並み居る強豪を次々と打ち破った。", "vi": "Với khả năng áp đảo của mình, anh đã lần lượt đánh bại nhiều đối thủ mạnh nhất."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をものともせず', 'N + をものともせず(に)', 'N1', 'bất chấp ; không nản lòng bởi', 'Mô tả ngưỡng mộ về người khác vượt qua khó khăn; không được sử dụng về bản thân. So sánh 〜をよそに (không quan tâm đến sự quan tâm của người khác, thường chỉ trích).', '[{"jp": "選手たちは激しい雨をものともせず、最後まで全力で戦い抜いた。", "vi": "Các cầu thủ bất chấp cơn mưa lớn và chiến đấu hết mình cho đến phút cuối cùng."}, {"jp": "彼女は周囲の反対をものともせず、単身で海外へ渡った。", "vi": "Bất chấp sự phản đối của những người xung quanh, cô vẫn tự mình ra nước ngoài."}, {"jp": "救助隊は余震の危険をものともせずに、倒壊した建物に入っていった。", "vi": "Đội cứu hộ tiến vào tòa nhà bị sập bất chấp nguy cơ xảy ra dư chấn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をよそに', 'N + をよそに', 'N1', 'phớt lờ; không chú ý đến; không biết gì về', 'Danh từ thường là cảm xúc hoặc phản ứng của người khác (心配, 期待, 反対, 批判) mà chủ ngữ bỏ qua; thường phê bình nhẹ nhàng.', '[{"jp": "親の心配をよそに、息子は連日夜遅くまで遊び歩いている。", "vi": "Bất chấp sự lo lắng của cha mẹ, con trai anh vẫn chơi đùa hàng ngày cho đến tận đêm khuya."}, {"jp": "住民の反対をよそに、高層マンションの建設が始まった。", "vi": "Việc xây dựng chung cư cao tầng được bắt đầu bất chấp sự phản đối của người dân."}, {"jp": "世間の騒ぎをよそに、当の本人はのんびりと釣りを楽しんでいた。", "vi": "Bất chấp sự hỗn loạn trên thế giới, người đàn ông được đề cập vẫn thư giãn và thích câu cá."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜んがため(に)', 'V-ない(bỏ ない) + んがため(に) (する → せんがため)', 'N1', 'để ; vì (quyết tâm mạnh mẽ)', 'Cổ xưa và nhấn mạnh, thể hiện quyết tâm mạnh mẽ; không phải vì những mục tiêu tầm thường. 〜んがための + Danh từ bổ nghĩa cho danh từ.', '[{"jp": "彼は夢をかなえんがため、全財産をなげうって留学した。", "vi": "Để biến ước mơ thành hiện thực, anh đã từ bỏ toàn bộ tài sản của mình để đi du học."}, {"jp": "勝たんがための卑劣な手段は、スポーツマンシップに反する。", "vi": "Những phương pháp hèn hạ để giành chiến thắng là trái với tinh thần thể thao."}, {"jp": "真実を明らかにせんがために、記者たちは危険を顧みず取材を続けた。", "vi": "Để khám phá sự thật, các phóng viên tiếp tục đưa tin, bất chấp rủi ro."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜んばかり', 'V-ない(bỏ ない) + んばかり (する → せんばかり)', 'N1', 'như thể sắp; gần như (đến mức)', 'Một trạng thái cực đoan đến mức dường như có điều gì đó sắp xảy ra nhưng thực tế không phải vậy. Các dạng: 〜んばかりに, 〜んばかりだ, 〜んばかりの + Danh từ. 言わんばかり trùng với 〜とばかりに.', '[{"jp": "優勝が決まった瞬間、スタジアムは割れんばかりの拍手に包まれた。", "vi": "Giây phút quyết định chiến thắng, cả sân vận động tràn ngập tiếng vỗ tay như sấm."}, {"jp": "彼女は今にも泣き出さんばかりの顔で、事情を説明した。", "vi": "Cô ấy trông như sắp bật khóc khi giải thích tình hình."}, {"jp": "課長は「君のせいだ」と言わんばかりに、私をにらみつけた。", "vi": "Người quản lý trừng mắt nhìn tôi như muốn nói: \"Đó là lỗi của anh.\""}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜うえは', 'V-る(thể từ điển) / V-た + うえは', 'N1', 'bây giờ đó; vì (người ta phải)', 'Giống như 〜以上(は) và 〜からには (N2) nhưng cứng hơn; nửa sau thể hiện quyết tâm, nghĩa vụ hoặc lời khuyên. Cũng được viết 上は.', '[{"jp": "引き受けたうえは、最後まで責任を持ってやり遂げるつもりだ。", "vi": "Đã nhận công việc, tôi dự định sẽ chịu trách nhiệm và theo đuổi nó đến cùng."}, {"jp": "契約を結んだうえは、条件は必ず守っていただきます。", "vi": "Khi đã ký hợp đồng, bạn phải tuân thủ các điều khoản."}, {"jp": "こうなったうえは、正直にすべてを話すしかない。", "vi": "Bây giờ chuyện này đã xảy ra, tôi không còn cách nào khác ngoài việc thành thật kể cho bạn nghe mọi chuyện."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('ただ〜のみ', 'ただ + N + のみ / ただ + V-る(thể từ điển) + のみ', 'N1', 'chỉ; chỉ; không có gì ngoài', 'Phiên bản trang trọng của ただ〜だけ. Thường kết thúc câu bằng 〜のみだ (''tất cả những gì một người có thể làm là ...''). riêng のみ cũng có nghĩa là ''chỉ'' trong văn viết.', '[{"jp": "今はただ、手術の成功を祈るのみだ。", "vi": "Tất cả những gì tôi có thể làm bây giờ là cầu nguyện cho ca phẫu thuật thành công."}, {"jp": "やるべきことはすべてやった。あとはただ結果を待つのみだ。", "vi": "Tôi đã làm tất cả những gì tôi phải làm. Bây giờ chúng ta chỉ cần chờ kết quả."}, {"jp": "この洞窟に入ることを許されたのは、ただ調査隊の隊員のみであった。", "vi": "Chỉ có thành viên của nhóm nghiên cứu mới được phép vào hang động này."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜だの〜だの', 'N / V(thể thông thường) / A-い / A-な + だの + ... + だの', 'N1', 'những thứ như A và B (danh sách phàn nàn)', 'Liệt kê các ví dụ với sự khó chịu hoặc không tán thành, thường theo sau là と(言う). So sánh 〜やら〜やら trung tính (N2) và 〜とか〜とか.', '[{"jp": "息子は、野菜は苦いだの肉は硬いだのと文句ばかり言って、なかなか食べない。", "vi": "Con trai tôi ăn không nhiều, kêu rau đắng, thịt dai."}, {"jp": "部屋の中は、古い雑誌だの壊れた家電だので足の踏み場もない。", "vi": "Bên trong phòng là những cuốn tạp chí cũ và đồ gia dụng hỏng nên không còn nơi nào để bước."}, {"jp": "彼女は、疲れただの眠いだのと言って、なかなか宿題を始めない。", "vi": "Cô ấy nói rằng cô ấy chỉ mệt mỏi, buồn ngủ và gặp khó khăn khi bắt đầu làm bài tập về nhà."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜てはばからない', 'V-て + はばからない', 'N1', 'không ngần ngại; công khai (nói, tuyên bố)', 'Với động từ nói (言う, 公言する, 断言する); thường ám chỉ sự táo bạo là quá mức. Thông thường là về người thứ ba.', '[{"jp": "彼は自分こそが業界一の技術者だと公言してはばからない。", "vi": "Anh tự hào tuyên bố mình là kỹ sư giỏi nhất trong ngành."}, {"jp": "その評論家は、現政権の政策を失敗だと断言してはばからない。", "vi": "Những người chỉ trích đó không ngại tuyên bố các chính sách của chính quyền hiện tại là thất bại."}, {"jp": "監督は、このチームは必ず優勝すると言ってはばからなかった。", "vi": "Huấn luyện viên không ngại nói rằng đội bóng này nhất định sẽ giành chức vô địch."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ともあろう', 'N + ともあろう + N', 'N1', 'của mọi người; ai đó (có địa vị như vậy) như', 'Danh từ là một vai trò hoặc tổ chức được tôn trọng; câu phê phán hành vi không xứng đáng với nó. Thông thường là 〜ともあろう者が / 人が.', '[{"jp": "警察官ともあろう者が、飲酒運転で捕まるとは。", "vi": "Tôi chưa bao giờ nghĩ rằng một người có thể được coi là cảnh sát lại bị bắt vì lái xe khi say rượu."}, {"jp": "一流ホテルともあろうものが、こんな初歩的なミスをするなんて信じられない。", "vi": "Tôi không thể tin được rằng nơi được cho là khách sạn hạng nhất lại mắc phải một sai lầm cơ bản như vậy."}, {"jp": "大臣ともあろう人が、記者の質問から逃げるべきではない。", "vi": "Một người có thể được coi là bộ trưởng không nên trốn tránh câu hỏi của phóng viên."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にかこつけて', 'N + にかこつけて', 'N1', 'sử dụng (cái gì đó) như một cái cớ hoặc cái cớ', 'Lý do đã nêu là cái cớ cho điều người đó thực sự muốn làm. Gần 〜を口実に.', '[{"jp": "彼は出張にかこつけて、地方の温泉を巡っているらしい。", "vi": "Có vẻ như anh ta đang đến thăm suối nước nóng địa phương dưới vỏ bọc là một chuyến công tác."}, {"jp": "体調不良にかこつけて、面倒な会議を欠席した。", "vi": "Tôi giả vờ không khỏe và vắng mặt trong một cuộc họp rắc rối."}, {"jp": "子どもの誕生日にかこつけて、自分が食べたかったケーキを買ってきた。", "vi": "Tôi đã mua một chiếc bánh mà tôi muốn ăn nhân dịp sinh nhật của con tôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に言わせれば', 'N + に言わせれば / N + に言わせると', 'N1', 'nếu bạn hỏi (ai đó); theo ý kiến của (ai đó)', 'Đưa ra quan điểm cá nhân, có quan điểm mạnh mẽ và có thể khác với quan điểm của người khác. Không giống như 〜によれば trung lập, nó nhấn mạnh quan điểm của cá nhân.', '[{"jp": "祖母に言わせれば、最近の若者は我慢が足りないそうだ。", "vi": "Theo bà tôi, giới trẻ ngày nay thiếu kiên nhẫn."}, {"jp": "専門家に言わせれば、この程度の揺れで建物が倒れることはまずないという。", "vi": "Các chuyên gia cho rằng rất khó có khả năng một tòa nhà sẽ sụp đổ do trận động đất ở cường độ này."}, {"jp": "私に言わせれば、あの映画は評判ほど面白くない。", "vi": "Nếu bạn hỏi tôi thì bộ phim đó không thú vị như người ta đồn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にかまけて', 'N + にかまけて', 'N1', 'quá bận rộn (để quan tâm đến những việc khác)', 'Kết quả là mệnh đề chính nêu tên một điều gì đó bị bỏ quên; thường tự phê bình hoặc viện cớ.', '[{"jp": "仕事にかまけて、家族と過ごす時間をおろそかにしてしまった。", "vi": "Tôi quá bận rộn với công việc đến nỗi không dành thời gian cho gia đình."}, {"jp": "新しいゲームにかまけて、試験勉強がまったく進んでいない。", "vi": "Tôi quá bận chơi các trò chơi mới đến nỗi không đạt được tiến bộ nào trong việc ôn thi."}, {"jp": "育児にかまけて、自分の健康診断を何年も受けていなかった。", "vi": "Tôi đã không đi khám sức khỏe trong nhiều năm vì bận nuôi con."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かいもなく', 'V-た + かいもなく / N + の + かいもなく', 'N1', 'bất chấp (nỗ lực); vô ích', 'Nỗ lực đã không được đền đáp. Từ tích cực 〜かいがあって có nghĩa là ''nỗ lực đó thật xứng đáng''. Cũng được viết 甲斐もなく.', '[{"jp": "家族の懸命な看病のかいもなく、祖父は静かに息を引き取った。", "vi": "Ông nội tôi đã ra đi thanh thản mà không có sự giúp đỡ của gia đình."}, {"jp": "必死に練習したかいもなく、一回戦で敗退してしまった。", "vi": "Dù luyện tập chăm chỉ nhưng tôi đã bị loại ngay từ vòng đầu tiên."}, {"jp": "早起きして並んだかいもなく、目当ての限定品は目の前で売り切れた。", "vi": "Tôi dậy sớm và không phải xếp hàng chờ mua món đồ phiên bản giới hạn mà mình đang tìm kiếm, và nó đã bán hết ngay trước mắt tôi."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜きっての', 'N + きっての + N', 'N1', 'nhất là... ở; tốt nhất trong', 'Danh từ chỉ một nhóm hoặc một địa điểm (社内, 町内, 学校, 業界, 国内). Được sử dụng để khen ngợi, thường là của một người hoặc một tổ chức.', '[{"jp": "彼女は社内きっての切れ者として知られている。", "vi": "Cô được biết đến là một trong những người thông minh nhất trong công ty."}, {"jp": "この旅館は、温泉街きっての老舗だ。", "vi": "Nhà trọ này là một trong những nhà trọ lâu đời nhất ở thị trấn suối nước nóng."}, {"jp": "学年きっての秀才と言われた兄も、社会に出てからは苦労している。", "vi": "Ngay cả anh trai của anh, người được cho là học sinh tài năng nhất lớp, cũng gặp khó khăn kể từ khi gia nhập lực lượng lao động."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ずとも', 'V-ない(bỏ ない) + ずとも (する → せずとも)', 'N1', 'thậm chí không có; mà không cần phải', 'Phiên bản văn học của 〜なくても. 〜ずともよい có nghĩa là ''không cần''.', '[{"jp": "わざわざ言わずとも、彼なら状況を察してくれるだろう。", "vi": "Dù bạn không nói gì thì anh ấy cũng sẽ hiểu được tình hình."}, {"jp": "これくらいの距離なら、車を使わずとも歩いて行ける。", "vi": "Bạn có thể đi bộ quãng đường này mà không cần sử dụng ô tô."}, {"jp": "急がずとも、会議にはまだ十分間に合いますよ。", "vi": "Ngay cả khi bạn không nhanh lên, bạn vẫn còn nhiều thời gian cho cuộc họp."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とはいえ', 'V(thể thông thường) / A-い / A-な / N + とはいえ', 'N1', 'mặc dù ; mặc dù; điều đó đã nói', 'Thừa nhận một sự thật, sau đó nói rằng kết quả mong đợi không hoàn toàn như vậy. Có thể mở một câu (''điều đó đã nói''). Trang trọng hơn 〜といっても.', '[{"jp": "春とはいえ、朝晩はまだ冷え込む。", "vi": "Dù đang là mùa xuân nhưng buổi sáng và buổi tối vẫn lạnh."}, {"jp": "締め切りまで一か月あるとはいえ、そろそろ準備を始めたほうがいい。", "vi": "Mặc dù còn một tháng nữa là đến hạn chót nhưng tốt hơn hết bạn nên bắt đầu chuẩn bị ngay từ bây giờ."}, {"jp": "景気は回復傾向にある。とはいえ、中小企業の経営は依然として厳しい。", "vi": "Nền kinh tế đang có xu hướng phục hồi. Tuy nhiên, việc quản lý doanh nghiệp vừa và nhỏ còn gặp nhiều khó khăn."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜べくして', 'V-る(thể từ điển) + べくして + V-た (same verb)', 'N1', 'điều chắc chắn sẽ xảy ra; tất yếu', 'Động từ tương tự được lặp lại (起こるべくして起こる); kết quả là hệ quả tự nhiên của hoàn cảnh.', '[{"jp": "安全点検を怠っていたのだから、あの事故は起こるべくして起こったと言える。", "vi": "Vì việc kiểm tra an toàn đã bị bỏ qua nên có thể nói rằng vụ tai nạn đã xảy ra."}, {"jp": "誰よりも練習を重ねてきた彼女は、勝つべくして勝ったのだ。", "vi": "Cô ấy đã luyện tập nhiều hơn bất kỳ ai khác và cô ấy thắng vì muốn thắng."}, {"jp": "もともと無理のある計画だったので、失敗すべくして失敗した。", "vi": "Đó là một kế hoạch bất khả thi ngay từ đầu nên nó đã được định sẵn là sẽ thất bại, nhưng nó đã thất bại."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜じみる / 〜じみた', 'N + じみる / N + じみた + N', 'N1', 'hơi ; có vẻ như (theo cách xấu); -ish', 'Sắc thái tiêu cực: 子どもじみた, 年寄りじみた, 説教じみた, 芝居じみた. So sánh 〜めく trung tính và 〜っぽい thông thường. Với 汗 hoặc 油 nó có nghĩa là ''vết bẩn''.', '[{"jp": "いい大人が、そんな子どもじみた言い訳をするものではない。", "vi": "Một người lớn tốt sẽ không bao giờ đưa ra những lời bào chữa trẻ con như vậy."}, {"jp": "彼の話はどこか説教じみていて、素直に聞く気になれない。", "vi": "Có điều gì đó trong câu chuyện của anh ấy nghe giống như một bài giảng, và tôi không muốn nghe nó."}, {"jp": "彼はまだ二十代なのに、年寄りじみたことばかり言う。", "vi": "Dù chỉ mới đôi mươi nhưng anh ấy luôn nói những điều nghe như một ông già."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ぐるみ', 'N + ぐるみ', 'N1', 'bao gồm tất cả; toàn bộ (nhóm) cùng nhau', 'Hoạt động với một số danh từ hạn chế: 家族, 町, 地域, 会社, 組織, 身ぐるみ. 会社ぐるみ / 組織ぐるみ thường mô tả hành vi sai trái có tổ chức.', '[{"jp": "隣の家とは、家族ぐるみで付き合っている。", "vi": "Hàng xóm sống với nhau như một gia đình."}, {"jp": "この地域では、町ぐるみで子どもたちの登下校を見守っている。", "vi": "Tại khu vực này, toàn thị trấn trông chừng trẻ em đi học."}, {"jp": "調査の結果、会社ぐるみの不正であったことが明らかになった。", "vi": "Kết quả điều tra cho thấy đây là một hành vi gian lận trên toàn công ty."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜にもほどがある', 'N / A-な / A-い / V-る(thể từ điển) + にもほどがある', 'N1', 'có giới hạn; quá... (vượt quá mức có thể chấp nhận được)', 'Chỉ trích mạnh mẽ hoặc phẫn nộ rằng điều gì đó đã đi quá xa. Trò chuyện và cảm xúc.', '[{"jp": "約束の時間に二時間も遅れてくるなんて、非常識にもほどがある。", "vi": "Trễ hai giờ so với thời gian đã hẹn là điều quá điên rồ."}, {"jp": "初対面の人に年収を聞くなんて、失礼にもほどがある。", "vi": "Sẽ cực kỳ thô lỗ khi hỏi thu nhập hàng năm của ai đó khi bạn gặp họ lần đầu tiên."}, {"jp": "冗談にもほどがある。そんな話、誰が信じるものか。", "vi": "Nói đùa cũng có lý. Ai sẽ tin một câu chuyện như vậy?"}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜をいいことに', 'N + をいいことに / V(thể thông thường) + の + をいいことに', 'N1', 'lợi dụng (không công bằng); sử dụng (một tình huống) làm giấy phép để', 'Quan trọng: ai đó lợi dụng tình huống để làm điều gì đó không đúng đắn. Với cách ''nắm bắt cơ hội'' một cách trung lập, hãy sử dụng 〜を機に hoặc 〜をきっかけに.', '[{"jp": "親が留守なのをいいことに、息子は友達を呼んで夜通し騒いでいた。", "vi": "Lợi dụng lúc bố mẹ đi vắng, con trai anh gọi bạn bè đến gây ồn ào cả đêm."}, {"jp": "上司が何も言わないのをいいことに、彼は毎日のように遅刻してくる。", "vi": "Hầu như ngày nào anh cũng đến muộn, lợi dụng việc sếp không nói gì."}, {"jp": "高齢者の知識不足をいいことに、業者は高額な契約を結ばせていた。", "vi": "Lợi dụng sự thiếu hiểu biết của người cao tuổi, các doanh nghiệp ép họ ký những hợp đồng đắt giá."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜に則って', 'N + に則って / N + に則った + N', 'N1', 'theo (quy tắc, luật lệ, truyền thống)', 'Danh từ là chuẩn mực hoặc hình mẫu: 法律, 規則, 伝統, しきたり, 手順. So sánh 〜に即して, dùng với sự kiện và điều kiện thực tế.', '[{"jp": "大会は、国際ルールに則って公正に運営される。", "vi": "Giải đấu sẽ được vận hành công bằng theo đúng luật lệ quốc tế."}, {"jp": "二人の結婚式は、古くからのしきたりに則って神社で執り行われた。", "vi": "Đám cưới của họ được tổ chức tại một ngôi đền theo phong tục cổ xưa."}, {"jp": "本件については、社内規定に則った処分が下される予定だ。", "vi": "Về vấn đề này, công ty sẽ xử lý kỷ luật theo quy định của công ty."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜かれ〜かれ', 'A-い(bỏ い) + かれ + A-い(bỏ い) + かれ', 'N1', 'dù là A hay B; A hoặc B giống nhau (cặp cố định)', 'Một dạng tính từ cổ điển chỉ tồn tại khi có các cặp đối lập cố định: 遅かれ早かれ, 多かれ少なかれ, 良かれあしかれ. Không hiệu quả.', '[{"jp": "遅かれ早かれ、この秘密はみんなに知られることになるだろう。", "vi": "Sớm hay muộn, bí mật này sẽ bị mọi người biết đến."}, {"jp": "多かれ少なかれ、誰にでも人に言えない悩みはあるものだ。", "vi": "Ít nhiều ai cũng có những lo lắng không thể kể với ai."}, {"jp": "良かれあしかれ、あの人の一言が会社の方向を決めてきた。", "vi": "Dù tốt hay xấu thì lời nói của người đó đã quyết định hướng đi của công ty."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ことこの上ない', 'A-い + ことこの上ない / A-な + な + ことこの上ない', 'N1', 'vô cùng; không gì có thể hơn thế nữa', 'Một cách viết cứng nhắc để nói ''cực kỳ''. Ngoài ra この上ない + Danh từ (この上ない喜び ''niềm vui lớn nhất''). Gần 〜極まりない.', '[{"jp": "深夜の山道を一人で運転するのは、心細いことこの上ない。", "vi": "Lái xe một mình trên đường núi vào đêm khuya có thể cực kỳ căng thẳng."}, {"jp": "彼の説明は回りくどく、分かりにくいことこの上ない。", "vi": "Lời giải thích của anh ấy vòng vo và khó hiểu."}, {"jp": "会議中に何度も携帯電話が鳴り、迷惑なことこの上なかった。", "vi": "Điện thoại di động của tôi reo nhiều lần trong cuộc họp, điều này thật khó chịu."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜とみえる / 〜とみえて', 'V(thể thông thường) / A-い / A-な / N + とみえる / V(thể thông thường) / A-い / A-な / N + とみえて', 'N1', 'có vẻ như (đánh giá từ bằng chứng); rõ ràng', 'Một suy luận từ những gì người ta quan sát được; với 〜とみえて, bằng chứng quan sát được sẽ theo sau. Văn chương hơn 〜らしい / 〜ようだ. Cũng được viết là と見える.', '[{"jp": "息子はよほど疲れていたとみえて、夕食も食べずに眠ってしまった。", "vi": "Con trai tôi có vẻ rất mệt mỏi và ngủ quên khi chưa ăn tối."}, {"jp": "隣の家は留守とみえて、何度チャイムを鳴らしても返事がない。", "vi": "Nhà hàng xóm hình như đi vắng, bấm chuông bao nhiêu lần cũng không có phản hồi."}, {"jp": "彼はこの結果にかなり満足しているとみえる。", "vi": "Anh có vẻ khá hài lòng với kết quả này."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜を踏まえて', 'N + を踏まえて / N + を踏まえた + N', 'N1', 'dựa vào; có tính đến; trong ánh sáng của', 'Phổ biến trong kinh doanh và văn bản chính thức. Không giống như 〜に基づいて (N2), theo sát cơ sở, nó có nghĩa là dựa trên hoặc phản ánh điều gì đó.', '[{"jp": "アンケートの結果を踏まえて、来年度のサービス内容を見直すことにした。", "vi": "Dựa trên kết quả khảo sát, chúng tôi quyết định xem xét nội dung dịch vụ cho năm tới."}, {"jp": "過去の失敗を踏まえたうえで、新たな計画を立てるべきだ。", "vi": "Những kế hoạch mới nên được thực hiện dựa trên những thất bại trong quá khứ."}, {"jp": "委員会は現地調査の結果を踏まえ、報告書をまとめた。", "vi": "Ủy ban đã biên soạn một báo cáo dựa trên kết quả khảo sát thực địa."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('〜ないとも限らない', 'V-ない + とも限らない', 'N1', 'điều đó không phải là không thể; có khả năng đó', 'Cảnh báo về một khả năng nhỏ nhưng có thật, thường là không mong muốn và thường kèm theo biện pháp phòng ngừa. Khác với 〜とは限らない (''không nhất thiết'').', '[{"jp": "途中で渋滞に巻き込まれないとも限らないから、早めに出発しよう。", "vi": "Không có gì đảm bảo rằng bạn sẽ không bị kẹt xe trên đường đi, vì vậy hãy cố gắng về sớm."}, {"jp": "誰が聞いていないとも限らないので、ここで仕事の話はやめておこう。", "vi": "Không có gì đảm bảo rằng không có ai lắng nghe, vì vậy chúng ta hãy ngừng nói về công việc ở đây."}, {"jp": "大きな地震がいつ起きないとも限らない。日頃から備えておくことが大切だ。", "vi": "Không có gì đảm bảo rằng một trận động đất lớn sẽ xảy ra bất cứ lúc nào. Điều quan trọng là phải chuẩn bị hàng ngày."}]'::jsonb, true, false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0);
